// "Umumiy kimyo" (General chemistry) lessons: Part 1, six chapters. Opened with the header button or #kimyo,
// a topic with #kimyo/<id>. Text is original; each block may carry a visual drawn by chem-visuals.js.
window.PT_CHEM = {"parts":[{"title":{"uz":"Birinchi qism","en":"Part one","ru":"Часть первая"},"chapters":[{"title":{"uz":"1-bob. Kimyoning asosiy tushuncha va qonunlari","en":"Chapter 1. Basic concepts and laws of chemistry","ru":"Глава 1. Основные понятия и законы химии"},"topics":[{"id":"lab","num":0,"icon":"🥽","uz":{"title":"Laboratoriyada xavfsizlik va jihozlar","intro":"Kimyo xonasi — kashfiyotlar maskani, lekin u yerda har bir harakat o'ylab qilinadi. Bu darsda xavfsiz ishlash qoidalari, shtativ va spirt lampasi bilan tanishamiz hamda alanga qanday tuzilganini bilib olamiz.","blocks":[{"h":"Ishni boshlashdan oldin","p":"Laboratoriyaga xalat kiyib kiriladi, sochlar yig'iladi, stol ustida faqat ish uchun kerakli narsalar qoladi. Tajriba tartibini oldindan o'qib chiqing va asboblar to'g'ri yig'ilganiga ishonch hosil qilmaguncha ishni boshlamang. Har bir tajriba maxsus daftarga yozib boriladi.","items":["Daftarga: sana, ish raqami va mavzusi, maqsadi","Kerakli asboblar va ularning chizmasi","Nima qilingani va nima kuzatilgani","Reaksiya tenglamalari va xulosa"]},{"h":"Asosiy xavfsizlik qoidalari","p":"Ko'pchilik baxtsiz hodisalar shoshilish va e'tiborsizlikdan kelib chiqadi: suyuqlik qattiq qizib idishdan otilib chiqadi yoki modda noto'g'ri ishlatiladi. Quyidagi qoidalar o'zingizni ham, sinfdoshlaringizni ham asraydi.","items":["Moddalarni tatib ko'rmang, qo'l bilan ushlamang; hidni faqat kaft bilan o'zingizga yelpib bilib oling","Qizdirilayotgan probirka og'zini hech kimga qaratmang va idish ustiga engashmang","Kislota yoki ishqor bilan ishlaganda himoya ko'zoynagi taqing","Kislotani suyultirishda kislotani suvga ingichka oqim bilan quying, aksincha emas","Kuchli kislota va ishqorni og'iz bilan pipetkaga tortmang","Yonuvchi moddalarni olovdan uzoqda saqlang; yong'in chiqsa, manbani o'chirib, qum seping yoki yopqich yoping","Ish tugagach gaz, suv va elektrni o'chiring, idishlarni yuvib, joyni tozalang"]},{"h":"Laboratoriya jihozlari","p":"Kimyoviy idishlar issiqqa chidamli maxsus shishadan yasaladi. Probirka kichik tajribalar uchun, kimyoviy stakan va kolbalar suyuqlik bilan ishlash uchun, voronka quyish va filtrlash uchun, chinni kosacha bug'latish uchun ishlatiladi. O'lchov silindri va menzurka suyuqlik hajmini o'lchaydi.","visual":{"type":"diagram","kind":"lab"}},{"h":"Laboratoriya shtativi","p":"Shtativ og'ir taglik va unga burab mahkamlangan tik o'zakdan iborat. O'zakka vintli qisqichlar yordamida halqa, tutqich (lapka) va boshqa moslamalar istalgan balandlikda o'rnatiladi. Probirka va kolba tutqichga yengil qisiladi — qattiq siqilsa, shisha sinadi.","items":["Halqa — kolba yoki chinni kosachani ushlab turadi","Halqa ustidagi to'r — stakan va yassi tubli kolbani bir tekis qizdirish uchun","Tutqich — probirka va sovitkichni qisib turadi","Suv yoki qum hammomi — bir xil haroratda qizdirish uchun"]},{"h":"Spirt lampasi va alanga tuzilishi","p":"Spirt lampasi spirt solinadigan idish, pilik o'tkazilgan metall nay-disk va qalpoqchadan iborat. Idish yarmigacha voronka orqali to'ldiriladi, lampa gugurt bilan yoqiladi va faqat qalpoqcha yopib o'chiriladi. Alanganing pastki qorong'i qismi eng sovuq, o'rta yorug' qismi issiq, yuqori xira qismi esa eng issiq.","items":["Lampani boshqa yonib turgan lampadan yoqmang","Hech qachon puflab o'chirmang — qalpoqcha bilan yoping","Probirkani alanganing yuqori qismida qizdiring, pilikka tegizmang","Ishlatilmayotgan lampa doim qalpoqcha bilan yopiq turadi"],"visual":{"type":"diagram","kind":"flame"}},{"h":"Esda tuting","items":["Laboratoriyada hech narsani tatib ko'rmaymiz va qo'l bilan ushlamaymiz","Qizdirilayotgan idish og'zi odamlardan teskari tomonga qaraydi","Spirt lampasi faqat qalpoqcha bilan o'chiriladi","Alanganing eng issiq joyi — uning yuqori qismi"]}],"quiz":[{"q":"Spirt lampasini qanday o'chirish to'g'ri?","options":["Puflab","Qalpoqchasini yopib","Ustiga suv sepib","Boshqa lampa bilan"],"correct":1,"explain":"Qalpoqcha havoni to'sadi va alanga xavfsiz so'nadi, puflash esa olovni tarqatishi mumkin."},{"q":"Probirkani alanganing qaysi qismida qizdirish kerak?","options":["Pilik yonidagi pastki qismida","O'rta yorug' qismida","Yuqori, eng issiq qismida","Alanga yonida, unga tegizmasdan"],"correct":2,"explain":"Alanganing yuqori qismi eng issiq bo'lgani uchun qizdirish shu yerda tez va bir tekis boradi."},{"q":"Kislotani suyultirishda nima qilinadi?","options":["Kislota suvga oz-ozdan quyiladi","Suv kislotaga tez quyiladi","Ikkalasi bir vaqtda qizdiriladi","Kislota pipetkaga og'iz bilan tortiladi"],"correct":0,"explain":"Kislota suvga quyilganda ajralgan issiqlik ko'p suvga tarqaladi va sachrash bo'lmaydi."}]},"en":{"title":"Lab safety and equipment","intro":"The chemistry room is a place for discoveries, but every move there is made with care. In this lesson we learn the safety rules, get to know the lab stand and the spirit lamp, and find out how a flame is built.","blocks":[{"h":"Before you start","p":"Wear a lab coat, tie back long hair and keep only what you need on the bench. Read the procedure in advance and do not begin until you are sure the apparatus is assembled correctly. Every experiment is recorded in a special notebook.","items":["In the notebook: date, number and title of the work, its aim","Equipment needed and a sketch of the set-up","What was done and what was observed","Reaction equations and conclusion"]},{"h":"Key safety rules","p":"Most accidents come from hurry and carelessness: a liquid overheats and spurts out, or a substance is handled the wrong way. These rules protect both you and your classmates.","items":["Never taste or touch chemicals; to smell, waft the vapour towards you with your hand","Never point a heated test tube at anyone and never lean over a reacting vessel","Wear safety goggles when working with acids or alkalis","To dilute an acid, pour the acid into water in a thin stream, never the reverse","Never suck strong acids or alkalis into a pipette by mouth","Keep flammable substances away from flames; if a fire starts, shut off its source and cover it with sand or a fire blanket","When finished, turn off gas, water and electricity, wash the glassware and tidy up"]},{"h":"Laboratory equipment","p":"Chemical glassware is made of special heat-resistant glass. Test tubes are for small experiments, beakers and flasks for working with liquids, funnels for pouring and filtering, and porcelain dishes for evaporation. Measuring cylinders measure liquid volumes.","visual":{"type":"diagram","kind":"lab"}},{"h":"The lab stand","p":"A stand has a heavy base with an upright rod screwed into it. Rings, clamps and other holders are fixed to the rod at any height with screw bosses. Test tubes and flasks are clamped gently — squeezing too hard cracks the glass.","items":["Ring — holds a round flask or a porcelain dish","Wire gauze on the ring — for heating beakers and flat-bottomed flasks evenly","Clamp — grips a test tube or a condenser","Water or sand bath — for heating at a steady temperature"]},{"h":"The spirit lamp and the flame","p":"A spirit lamp consists of a reservoir for alcohol, a metal tube-disc holding the wick, and a cap. It is filled to about half through a funnel, lit with a match and put out only by covering it with the cap. The dark inner zone of the flame is the coolest, the bright middle zone is hot, and the faint upper zone is the hottest.","items":["Never light one lamp from another burning lamp","Never blow it out — cover it with the cap","Heat a test tube in the upper part of the flame without touching the wick","Keep an unused lamp capped at all times"],"visual":{"type":"diagram","kind":"flame"}},{"h":"Remember","items":["In the lab we never taste or touch chemicals","The mouth of a heated vessel always points away from people","A spirit lamp is put out only with its cap","The hottest part of the flame is its upper zone"]}],"quiz":[{"q":"What is the correct way to put out a spirit lamp?","options":["Blow on it","Cover it with its cap","Sprinkle water on it","Use another lamp"],"correct":1,"explain":"The cap cuts off air so the flame dies safely, while blowing can spread the fire."},{"q":"In which part of the flame should a test tube be heated?","options":["The lower zone near the wick","The bright middle zone","The upper, hottest zone","Beside the flame without touching it"],"correct":2,"explain":"The upper zone is the hottest, so heating there is fast and even."},{"q":"How is an acid diluted?","options":["The acid is poured into water little by little","Water is poured quickly into the acid","Both are heated together","The acid is sucked into a pipette by mouth"],"correct":0,"explain":"When acid goes into water, the heat released spreads through a lot of water and nothing splashes."}]},"ru":{"title":"Безопасность и оборудование лаборатории","intro":"Кабинет химии — место открытий, но каждое действие в нём продумано. На этом уроке мы изучим правила безопасной работы, познакомимся со штативом и спиртовкой и узнаем, как устроено пламя.","blocks":[{"h":"Перед началом работы","p":"В лабораторию входят в халате, длинные волосы собирают, на столе оставляют только нужное для работы. Заранее прочитайте порядок опыта и не начинайте, пока не убедитесь, что прибор собран правильно. Каждый опыт записывают в специальную тетрадь.","items":["В тетради: дата, номер и тема работы, её цель","Нужное оборудование и рисунок прибора","Что сделано и что наблюдалось","Уравнения реакций и вывод"]},{"h":"Главные правила безопасности","p":"Большинство несчастных случаев происходит из-за спешки и невнимательности: перегретая жидкость выбрасывается из сосуда или вещество используют неправильно. Эти правила берегут и вас, и ваших одноклассников.","items":["Не пробуйте вещества на вкус и не трогайте руками; запах определяйте, направляя пары к себе ладонью","Не направляйте нагреваемую пробирку на людей и не наклоняйтесь над сосудом","При работе с кислотами и щелочами надевайте защитные очки","При разбавлении кислоту льют в воду тонкой струйкой, а не наоборот","Не набирайте крепкие кислоты и щёлочи в пипетку ртом","Держите горючие вещества вдали от огня; при пожаре выключите источник и засыпьте песком или накройте покрывалом","После работы перекройте газ, воду и электричество, вымойте посуду и уберите место"]},{"h":"Лабораторное оборудование","p":"Химическую посуду делают из особого термостойкого стекла. Пробирки нужны для небольших опытов, стаканы и колбы — для работы с жидкостями, воронки — для переливания и фильтрования, фарфоровые чашки — для выпаривания. Мерные цилиндры и мензурки измеряют объём жидкости.","visual":{"type":"diagram","kind":"lab"}},{"h":"Лабораторный штатив","p":"Штатив состоит из тяжёлого основания и ввинченного в него вертикального стержня. На стержне с помощью муфт с винтами закрепляют кольца, лапки и другие держатели на любой высоте. Пробирки и колбы зажимают в лапке слегка — при сильном сжатии стекло трескается.","items":["Кольцо — держит круглодонную колбу или фарфоровую чашку","Сетка на кольце — для равномерного нагрева стаканов и плоскодонных колб","Лапка — зажимает пробирку или холодильник","Водяная или песчаная баня — для нагрева при постоянной температуре"]},{"h":"Спиртовка и строение пламени","p":"Спиртовка состоит из резервуара для спирта, металлической трубки-диска с фитилём и колпачка. Её заполняют примерно наполовину через воронку, зажигают спичкой и гасят только колпачком. Тёмная внутренняя зона пламени самая холодная, яркая средняя — горячая, а бледная верхняя — самая горячая.","items":["Не зажигайте спиртовку от другой горящей спиртовки","Никогда не задувайте — накройте колпачком","Нагревайте пробирку в верхней части пламени, не касаясь фитиля","Неработающая спиртовка всегда закрыта колпачком"],"visual":{"type":"diagram","kind":"flame"}},{"h":"Запомните","items":["В лаборатории вещества не пробуют на вкус и не трогают руками","Отверстие нагреваемого сосуда направлено от людей","Спиртовку гасят только колпачком","Самая горячая часть пламени — верхняя"]}],"quiz":[{"q":"Как правильно погасить спиртовку?","options":["Задуть","Накрыть колпачком","Побрызгать водой","Другой спиртовкой"],"correct":1,"explain":"Колпачок перекрывает доступ воздуха, и пламя безопасно гаснет, а задувание может разнести огонь."},{"q":"В какой части пламени нагревают пробирку?","options":["В нижней зоне у фитиля","В яркой средней зоне","В верхней, самой горячей зоне","Рядом с пламенем, не касаясь его"],"correct":2,"explain":"Верхняя зона самая горячая, поэтому нагрев там быстрый и равномерный."},{"q":"Как разбавляют кислоту?","options":["Кислоту понемногу льют в воду","Воду быстро льют в кислоту","Нагревают обе жидкости вместе","Набирают кислоту в пипетку ртом"],"correct":0,"explain":"Когда кислоту льют в воду, выделившееся тепло распределяется в большом объёме воды и брызг нет."}]}},{"id":"t01","num":1,"icon":"⚗️","uz":{"title":"Kimyo fani, uning vazifalari va tarixi","intro":"Nonning qizarishi, temirning zanglashi, gazning yonishi — bularning hammasi kimyo. Bu darsda kimyo nimani o'rganishini, qanday vazifalarni hal qilishini va qanday olimlar uni rivojlantirganini bilib olamiz.","blocks":[{"h":"Kimyo nimani o'rganadi?","p":"Kimyo — moddalarni, ularning xossalarini va bir moddaning boshqasiga aylanishini o'rganadigan fan. Atrofimizdagi havo, suv, tuproq, o'simliklar, kiyim va buyumlar — barchasi moddalardan iborat. Hozir 118 ta kimyoviy element ma'lum, son-sanoqsiz moddalar shu elementlarning turli birikmalaridir.","items":["Tabiiy moddalar: suv, tuz, neft, paxta tolasi","Sintetik moddalar: polietilen, plastmassa, kapron, neylon, ko'p dorilar"]},{"h":"Kimyoning vazifalari","p":"Kimyogarlar moddalarning fizik va kimyoviy xossalarini o'rganadi, ulardan foydalanish yo'llarini topadi va tabiatda yo'q yangi moddalarni yaratadi. Dori-darmon, o'g'it, qurilish materiallari, avtomobil qismlari, kiyim-kechak ishlab chiqarishning asosida kimyo yotadi. Masalan, tabiiy gaz yonganda issiqlik ajraladi va undan uylarni isitishda foydalanamiz.","formula":"CH₄ + 2O₂ → CO₂ + 2H₂O","visual":{"type":"reaction","id":"ch4_o2"}},{"h":"Kimyo tarixidan","p":"Odamlar qadimdan bo'yoq, sopol, metall va dori tayyorlashda kimyoviy o'zgarishlardan foydalangan. XVII–XIX asrlarda kimyo haqiqiy fanga aylandi: tajriba va o'lchovlar asosiy dalil bo'ldi.","items":["G. Shtal — flogiston nazariyasi (keyinchalik rad etilgan)","M. Lomonosov — moddaning zarrachalardan tuzilishi haqidagi g'oyalar","A. Lavuazye — yonish va oksidlanishning to'g'ri izohi","J. Dalton — atom nazariyasi asoslari","D. Mendeleyev — 1869-yilda elementlar davriy jadvali","A. Butlerov — organik moddalarning tuzilish nazariyasi"]},{"h":"Markaziy Osiyo va O'zbekiston olimlarining hissasi","p":"O'rta asrlarda Sharq olimlari kimyoviy bilimlarni tajribaga tayangan holda rivojlantirdilar. Ular haydash, kristallash, bug'latish kabi usullarni tasvirlab, moddalarni tizimga solishga harakat qildilar. Bugungi O'zbekiston kimyogarlari esa o'simlik moddalari, paxta sellulozasi va polimerlar kimyosida xalqaro tan olingan ishlar qilgan.","items":["Jobir ibn Hayyon — haydash, kristallash kabi laboratoriya amallarini tasvirlagan","Abu Bakr ar-Roziy — moddalarni kelib chiqishiga ko'ra guruhlagan, laboratoriya asboblarini bayon qilgan","Abu Rayhon Beruniy — ko'plab metall va minerallarning zichligini aniq o'lchagan","Abu Ali ibn Sino — dorivor moddalarni sodda va murakkablarga ajratib tavsiflagan","Ahmad al-Farg'oniy, Abu Nasr Forobiy — tabiat va olam tuzilishi haqida asarlar yozgan","O. Sodiqov — g'o'za moddalarini o'rgangan, Bioorganik kimyo institutiga asos solgan","S. Yunusov — o'simliklardagi alkaloidlarni tadqiq qilgan, O'simlik moddalari kimyosi institutini tashkil etgan","H. Usmonov — paxta sellulozasi va polimerlar kimyosi bo'yicha maktab yaratgan","N. Parpiyev, Sh. Solihov, N. Yusupbekov va boshqalar — koordinatsion birikmalar, oqsillar, kimyoviy texnologiya sohalarida"]},{"h":"Bugungi O'zbekistonda kimyo","p":"Mamlakatimizda neft va gaz konlari asosida kimyo sanoati rivojlangan: yoqilg'i, plastmassa, o'g'itlar ishlab chiqariladi. Avtomobil va texnikaning ko'plab qismlari ham sintetik materiallardan tayyorlanadi. Fanlar akademiyasining institutlari va universitetlar kimyoning turli yo'nalishlarida tadqiqot olib boradi."},{"h":"Esda tuting","items":["Kimyo moddalar, ularning xossalari va o'zgarishlarini o'rganadi","Hozir 118 ta kimyoviy element ma'lum","1869-yilda Mendeleyev elementlar davriy jadvalini yaratgan","Markaziy Osiyo olimlari kimyo tarixiga katta hissa qo'shgan"]}],"quiz":[{"q":"Kimyo nimani o'rganadi?","options":["Faqat tirik organizmlarni","Moddalar, ularning xossalari va o'zgarishlarini","Faqat jismlarning harakatini","Yer yuzasining shaklini"],"correct":1,"explain":"Kimyoning asosiy ob'ekti — moddalar va ularning bir-biriga aylanishi."},{"q":"Elementlar davriy jadvalini kim yaratgan?","options":["J. Dalton","A. Lavuazye","D. Mendeleyev","A. Butlerov"],"correct":2,"explain":"Davriy jadval 1869-yilda D. Mendeleyev tomonidan tuzilgan."},{"q":"Qaysi olim ko'plab metall va minerallarning zichligini aniq o'lchagan?","options":["Abu Rayhon Beruniy","G. Shtal","J. Dalton","M. Lomonosov"],"correct":0,"explain":"Beruniy turli metall va qimmatbaho toshlarning zichligini o'z davri uchun juda aniq aniqlagan."}]},"en":{"title":"Chemistry as a science, its tasks and history","intro":"Bread turning golden, iron rusting, gas burning — all of this is chemistry. In this lesson we find out what chemistry studies, what problems it solves and which scientists built it up.","blocks":[{"h":"What does chemistry study?","p":"Chemistry is the science of substances, their properties and how one substance changes into another. The air, water, soil, plants, clothes and objects around us are all made of substances. Today 118 chemical elements are known, and countless substances are different combinations of them.","items":["Natural substances: water, salt, oil, cotton fibre","Synthetic substances: polyethylene, plastics, nylon and other fibres, many medicines"]},{"h":"The tasks of chemistry","p":"Chemists study the physical and chemical properties of substances, find ways to use them and create new substances that do not exist in nature. Medicines, fertilisers, building materials, car parts and clothing all depend on chemistry. For example, natural gas releases heat when it burns, and we use it to heat our homes.","formula":"CH₄ + 2O₂ → CO₂ + 2H₂O","visual":{"type":"reaction","id":"ch4_o2"}},{"h":"A short history","p":"Since ancient times people used chemical changes to make dyes, pottery, metals and medicines. In the 17th–19th centuries chemistry became a true science, where experiments and measurements became the main evidence.","items":["G. Stahl — the phlogiston theory (later rejected)","M. Lomonosov — ideas that matter is made of tiny particles","A. Lavoisier — the correct explanation of burning and oxidation","J. Dalton — the foundations of atomic theory","D. Mendeleev — the periodic table of the elements, 1869","A. Butlerov — the theory of the structure of organic compounds"]},{"h":"Scientists of Central Asia and Uzbekistan","p":"In the Middle Ages scholars of the East developed chemical knowledge based on experiment. They described methods such as distillation, crystallisation and evaporation and tried to classify substances. Modern chemists of Uzbekistan have done internationally recognised work on plant substances, cotton cellulose and polymers.","items":["Jabir ibn Hayyan — described lab operations such as distillation and crystallisation","Abu Bakr ar-Razi — grouped substances by origin and described laboratory apparatus","Abu Rayhan Beruni — accurately measured the densities of many metals and minerals","Abu Ali ibn Sina — described medicinal substances, dividing them into simple and compound ones","Ahmad al-Fargani, Abu Nasr al-Farabi — wrote works on nature and the structure of the world","O. Sodiqov — studied substances of the cotton plant, founded the Institute of Bioorganic Chemistry","S. Yunusov — researched plant alkaloids, founded the Institute of the Chemistry of Plant Substances","H. Usmonov — created a school of cotton cellulose and polymer chemistry","N. Parpiyev, Sh. Solihov, N. Yusupbekov and others — coordination compounds, proteins, chemical engineering"]},{"h":"Chemistry in Uzbekistan today","p":"The country's chemical industry has grown on the basis of its oil and gas fields, producing fuels, plastics and fertilisers. Many parts of cars and machines are made from synthetic materials. Institutes of the Academy of Sciences and universities carry out research in many branches of chemistry."},{"h":"Remember","items":["Chemistry studies substances, their properties and their changes","118 chemical elements are known today","Mendeleev created the periodic table in 1869","Scholars of Central Asia made a major contribution to the history of chemistry"]}],"quiz":[{"q":"What does chemistry study?","options":["Only living organisms","Substances, their properties and changes","Only the motion of bodies","The shape of the Earth's surface"],"correct":1,"explain":"The main subject of chemistry is substances and how they turn into one another."},{"q":"Who created the periodic table of the elements?","options":["J. Dalton","A. Lavoisier","D. Mendeleev","A. Butlerov"],"correct":2,"explain":"The periodic table was drawn up by D. Mendeleev in 1869."},{"q":"Which scholar accurately measured the densities of many metals and minerals?","options":["Abu Rayhan Beruni","G. Stahl","J. Dalton","M. Lomonosov"],"correct":0,"explain":"Beruni determined the densities of metals and gemstones very precisely for his time."}]},"ru":{"title":"Химия как наука, её задачи и история","intro":"Румяная корочка хлеба, ржавчина на железе, горящий газ — всё это химия. На этом уроке узнаем, что изучает химия, какие задачи решает и какие учёные её развивали.","blocks":[{"h":"Что изучает химия?","p":"Химия — наука о веществах, их свойствах и превращениях одних веществ в другие. Воздух, вода, почва, растения, одежда и предметы вокруг нас состоят из веществ. Сейчас известно 118 химических элементов, а бесчисленные вещества — это их различные сочетания.","items":["Природные вещества: вода, соль, нефть, хлопковое волокно","Синтетические вещества: полиэтилен, пластмассы, капрон, нейлон, многие лекарства"]},{"h":"Задачи химии","p":"Химики изучают физические и химические свойства веществ, находят способы их применения и создают новые вещества, которых нет в природе. Производство лекарств, удобрений, стройматериалов, деталей машин и одежды основано на химии. Например, природный газ при горении выделяет тепло, которым мы отапливаем дома.","formula":"CH₄ + 2O₂ → CO₂ + 2H₂O","visual":{"type":"reaction","id":"ch4_o2"}},{"h":"Из истории химии","p":"С древних времён люди использовали химические превращения, чтобы получать краски, керамику, металлы и лекарства. В XVII–XIX веках химия стала настоящей наукой, где главным доказательством стали опыт и измерение.","items":["Г. Шталь — теория флогистона (позже отвергнута)","М. Ломоносов — идеи о строении вещества из мельчайших частиц","А. Лавуазье — верное объяснение горения и окисления","Дж. Дальтон — основы атомной теории","Д. Менделеев — периодическая таблица элементов, 1869 год","А. Бутлеров — теория строения органических веществ"]},{"h":"Вклад учёных Центральной Азии и Узбекистана","p":"В Средние века учёные Востока развивали химические знания, опираясь на опыт. Они описывали перегонку, кристаллизацию, выпаривание и старались систематизировать вещества. Современные химики Узбекистана получили международное признание за работы по химии растительных веществ, хлопковой целлюлозы и полимеров.","items":["Джабир ибн Хайян — описал перегонку, кристаллизацию и другие лабораторные операции","Абу Бакр ар-Рази — сгруппировал вещества по происхождению, описал лабораторные приборы","Абу Райхан Беруни — точно измерил плотности многих металлов и минералов","Абу Али ибн Сина — описал лекарственные вещества, разделив их на простые и сложные","Ахмад аль-Фаргани, Абу Наср аль-Фараби — писали труды о природе и устройстве мира","О. Садыков — изучал вещества хлопчатника, основал Институт биоорганической химии","С. Юнусов — исследовал алкалоиды растений, основал Институт химии растительных веществ","Х. Усманов — создал школу химии хлопковой целлюлозы и полимеров","Н. Парпиев, Ш. Салихов, Н. Юсупбеков и другие — координационные соединения, белки, химическая технология"]},{"h":"Химия в современном Узбекистане","p":"На основе нефтяных и газовых месторождений в стране выросла химическая промышленность: выпускают топливо, пластмассы, удобрения. Многие детали автомобилей и техники делают из синтетических материалов. Институты Академии наук и университеты ведут исследования в разных областях химии."},{"h":"Запомните","items":["Химия изучает вещества, их свойства и превращения","Сейчас известно 118 химических элементов","Менделеев создал периодическую таблицу в 1869 году","Учёные Центральной Азии внесли большой вклад в историю химии"]}],"quiz":[{"q":"Что изучает химия?","options":["Только живые организмы","Вещества, их свойства и превращения","Только движение тел","Форму поверхности Земли"],"correct":1,"explain":"Главный предмет химии — вещества и их превращения друг в друга."},{"q":"Кто создал периодическую таблицу элементов?","options":["Дж. Дальтон","А. Лавуазье","Д. Менделеев","А. Бутлеров"],"correct":2,"explain":"Периодическую таблицу составил Д. Менделеев в 1869 году."},{"q":"Какой учёный точно измерил плотности многих металлов и минералов?","options":["Абу Райхан Беруни","Г. Шталь","Дж. Дальтон","М. Ломоносов"],"correct":0,"explain":"Беруни определил плотности металлов и драгоценных камней очень точно для своего времени."}]}},{"id":"t02","num":2,"icon":"🔍","uz":{"title":"Modda va uning xossalari","intro":"Qoshiq, stakan va mix — bular jismlar; ular nimadan yasalgan bo'lsa, o'sha moddadir. Moddalarni bir-biridan qanday ajratamiz? Javob — ularning xossalarida.","blocks":[{"h":"Jism va modda","p":"Jism — atrofimizdagi har qanday buyum yoki narsa: kitob, qalam, kolba, Quyosh. Modda — jism nimadan tashkil topganini bildiradi. Bir xil jism turli moddalardan (qoshiq — temir, aluminiy yoki kumushdan), bir xil moddadan esa turli jismlar (shishadan stakan, kolba, probirka) yasalishi mumkin.","table":{"head":["Jism","Modda"],"rows":[["Mix","Temir"],["Stakan","Shisha"],["Sim","Mis"],["Muz bo'lagi","Suv"]]}},{"h":"Moddaning xossalari","p":"Xossa — moddani boshqalardan ajratib turadigan belgi. Ba'zi xossalarni sezgi a'zolarimiz bilan bilamiz, ba'zilarini esa asboblar yordamida o'lchaymiz.","items":["Agregat holati: qattiq, suyuq yoki gaz","Rangi va yaltiroqligi","Hidi (ta'mi faqat oziq-ovqatda; laboratoriyada hech narsa tatib ko'rilmaydi!)","Zichligi","Suyuqlanish va qaynash harorati","Suvda eruvchanligi, issiqlik va elektr o'tkazuvchanligi"]},{"h":"Moddalarni xossalari bo'yicha farqlash","p":"Oq kukunlar — shakar, osh tuzi va bo'r — bir-biriga o'xshaydi. Ularni suvga solsak, bo'r erimaydi, shakar va tuz esa eriydi. Rangsiz suyuqliklarni hidi, zichligi yoki qaynash harorati bilan ajratish mumkin: spirtning o'tkir hidi bor, suv esa hidsiz.","table":{"head":["Modda","Zichlik, g/ml","Qaynash harorati, °C"],"rows":[["Suv","1,00","100"],["Etil spirt","0,79","78"],["Sulfat kislota (konsentrlangan)","1,84","≈ 338"]]}},{"h":"Xossalar harorat bilan bog'liq","p":"Bir modda turli sharoitda turli holatda bo'lishi mumkin: suv sovuqda muz, xona haroratida suyuqlik, qaynaganda bug'. Shuning uchun xossa aytilganda sharoit ham ko'rsatiladi. Zarrachalar qanday joylashgani holatni belgilaydi.","visual":{"type":"particles"}},{"h":"Hayotdagi misol","p":"Mis elektr tokini yaxshi o'tkazgani uchun undan simlar yasaladi. Aluminiy yengil va zanglamaydi — u samolyot va idishlar uchun qulay. Moddaning qayerda ishlatilishi uning xossalariga bog'liq."},{"h":"Esda tuting","items":["Jismlar moddalardan tashkil topgan","Har bir modda o'ziga xos xossalar to'plamiga ega","Rang, hid, zichlik, qaynash harorati, eruvchanlik — moddaning xossalari","Moddaning ishlatilishi uning xossalariga bog'liq"]}],"quiz":[{"q":"Quyidagilardan qaysi biri modda?","options":["Qoshiq","Mix","Kumush","Kolba"],"correct":2,"explain":"Kumush — modda, qolganlari esa moddalardan yasalgan jismlar."},{"q":"Shakar va bo'r kukunini qanday oson ajratish mumkin?","options":["Rangiga qarab","Suvga solib","Og'irligiga qarab","Magnit bilan"],"correct":1,"explain":"Shakar suvda eriydi, bo'r esa erimaydi."},{"q":"Etil spirt qaysi xossasi bilan suvdan farq qiladi?","options":["O'tkir hidi va pastroq qaynash harorati bilan","Rangi bilan","Qattiq holatda bo'lishi bilan","Magnitga tortilishi bilan"],"correct":0,"explain":"Spirtning hidi bor va u taxminan 78 °C da, suv esa 100 °C da qaynaydi."}]},"en":{"title":"Substances and their properties","intro":"A spoon, a glass and a nail are objects; what they are made of is a substance. How do we tell substances apart? The answer lies in their properties.","blocks":[{"h":"Objects and substances","p":"An object (a physical body) is any item around us: a book, a pencil, a flask, the Sun. A substance is what an object is made of. The same kind of object can be made of different substances (a spoon of iron, aluminium or silver), and one substance can form different objects (glass makes beakers, flasks and test tubes).","table":{"head":["Object","Substance"],"rows":[["Nail","Iron"],["Drinking glass","Glass"],["Wire","Copper"],["Ice cube","Water"]]}},{"h":"Properties of substances","p":"A property is a feature that distinguishes a substance from others. Some properties we notice with our senses, others we measure with instruments.","items":["State: solid, liquid or gas","Colour and lustre","Smell (taste only for food; in the lab nothing is ever tasted!)","Density","Melting and boiling points","Solubility in water, conduction of heat and electricity"]},{"h":"Telling substances apart","p":"White powders — sugar, table salt and chalk — look alike. In water, chalk does not dissolve while sugar and salt do. Colourless liquids can be told apart by smell, density or boiling point: alcohol has a sharp smell, water has none.","table":{"head":["Substance","Density, g/mL","Boiling point, °C"],"rows":[["Water","1.00","100"],["Ethanol","0.79","78"],["Sulfuric acid (concentrated)","1.84","≈ 338"]]}},{"h":"Properties depend on temperature","p":"One substance can exist in different states under different conditions: water is ice in the cold, liquid at room temperature and steam when boiling. That is why conditions are stated together with a property. The arrangement of particles determines the state.","visual":{"type":"particles"}},{"h":"A real-life example","p":"Copper conducts electricity well, so it is used for wires. Aluminium is light and does not rust, which makes it good for aircraft and cookware. Where a substance is used depends on its properties."},{"h":"Remember","items":["Objects are made of substances","Every substance has its own set of properties","Colour, smell, density, boiling point and solubility are properties of a substance","How a substance is used depends on its properties"]}],"quiz":[{"q":"Which of these is a substance?","options":["A spoon","A nail","Silver","A flask"],"correct":2,"explain":"Silver is a substance; the others are objects made of substances."},{"q":"How can sugar and chalk powder be told apart easily?","options":["By colour","By putting them in water","By weight","With a magnet"],"correct":1,"explain":"Sugar dissolves in water, chalk does not."},{"q":"Which property distinguishes ethanol from water?","options":["Its sharp smell and lower boiling point","Its colour","Being solid","Being attracted to a magnet"],"correct":0,"explain":"Ethanol has a smell and boils at about 78 °C, water at 100 °C."}]},"ru":{"title":"Вещество и его свойства","intro":"Ложка, стакан и гвоздь — это тела, а то, из чего они сделаны, — вещества. Как отличить одно вещество от другого? Ответ — в их свойствах.","blocks":[{"h":"Тело и вещество","p":"Тело — любой предмет вокруг нас: книга, карандаш, колба, Солнце. Вещество — то, из чего состоит тело. Одинаковые тела можно сделать из разных веществ (ложку — из железа, алюминия или серебра), а из одного вещества — разные тела (из стекла — стаканы, колбы, пробирки).","table":{"head":["Тело","Вещество"],"rows":[["Гвоздь","Железо"],["Стакан","Стекло"],["Провод","Медь"],["Кубик льда","Вода"]]}},{"h":"Свойства веществ","p":"Свойство — признак, по которому вещество отличается от других. Одни свойства мы замечаем органами чувств, другие измеряем приборами.","items":["Агрегатное состояние: твёрдое, жидкое или газообразное","Цвет и блеск","Запах (вкус — только у пищи; в лаборатории ничего не пробуют!)","Плотность","Температуры плавления и кипения","Растворимость в воде, тепло- и электропроводность"]},{"h":"Как различить вещества","p":"Белые порошки — сахар, поваренная соль и мел — похожи. В воде мел не растворяется, а сахар и соль растворяются. Бесцветные жидкости различают по запаху, плотности или температуре кипения: у спирта резкий запах, вода запаха не имеет.","table":{"head":["Вещество","Плотность, г/мл","Температура кипения, °C"],"rows":[["Вода","1,00","100"],["Этиловый спирт","0,79","78"],["Серная кислота (конц.)","1,84","≈ 338"]]}},{"h":"Свойства зависят от температуры","p":"Одно вещество в разных условиях бывает в разных состояниях: вода на холоде — лёд, при комнатной температуре — жидкость, при кипении — пар. Поэтому, называя свойство, указывают и условия. Состояние определяется тем, как расположены частицы.","visual":{"type":"particles"}},{"h":"Пример из жизни","p":"Медь хорошо проводит электрический ток, поэтому из неё делают провода. Алюминий лёгкий и не ржавеет — он удобен для самолётов и посуды. Применение вещества зависит от его свойств."},{"h":"Запомните","items":["Тела состоят из веществ","У каждого вещества свой набор свойств","Цвет, запах, плотность, температура кипения, растворимость — свойства вещества","Применение вещества зависит от его свойств"]}],"quiz":[{"q":"Что из перечисленного — вещество?","options":["Ложка","Гвоздь","Серебро","Колба"],"correct":2,"explain":"Серебро — вещество, остальное — тела, сделанные из веществ."},{"q":"Как легко различить порошки сахара и мела?","options":["По цвету","Поместив их в воду","По весу","Магнитом"],"correct":1,"explain":"Сахар растворяется в воде, а мел — нет."},{"q":"Каким свойством этиловый спирт отличается от воды?","options":["Резким запахом и более низкой температурой кипения","Цветом","Твёрдым состоянием","Притяжением к магниту"],"correct":0,"explain":"У спирта есть запах, и он кипит примерно при 78 °C, а вода — при 100 °C."}]}},{"id":"t03","num":3,"icon":"⚛️","uz":{"title":"Atom-molekular ta'limot. Kimyoviy element va belgi","intro":"Atirni xonaning bir burchagida ochsangiz, hidi tez orada butun xonaga tarqaladi. Buni faqat moddalar juda mayda, doim harakatlanuvchi zarrachalardan iboratligi bilan tushuntirish mumkin.","blocks":[{"h":"G'oyadan nazariyagacha","p":"Qadimgi yunon faylasuflari olam bo'linmas mayda zarrachalardan — atomlardan (yunoncha «atomos» — bo'linmas) iborat, degan fikrni aytgan. Sharq mutafakkirlari ham hodisalar sababini ko'zga ko'rinmas zarrachalarda ko'rgan. Lomonosov, Dalton, Avogadro ishlaridan so'ng 1860-yilda Karlsruedagi xalqaro kongressda atom va molekula tushunchalari aniq ta'riflandi."},{"h":"Ta'limotning asosiy qoidalari","items":["Ko'p moddalar molekulalardan tuzilgan; molekula — modda kimyoviy xossalarini saqlovchi eng kichik zarracha","Molekulalar atomlardan tashkil topgan","Atomlar ham murakkab: ular proton, neytron va elektronlardan iborat","Atom va molekulalar to'xtovsiz harakatda bo'ladi, ular orasida tortishish va itarilish kuchlari bor","Bir moddaning molekulalari bir xil, turli moddalarniki esa turlicha"],"visual":{"type":"molecule3d","mol":"H2O"}},{"h":"Zarrachalar mavjudligining dalillari","p":"1827-yilda R. Broun mikroskopda suvdagi mayda gulchang zarrachalarining tinimsiz tartibsiz harakatini kuzatdi — ularni suv molekulalari turtib turadi. Diffuziya — bir modda zarrachalarining boshqa modda zarrachalari orasiga o'z-o'zidan tarqalishi. Qizdirilganda jismlarning kengayishi ham zarrachalar orasidagi masofa o'zgarishi bilan izohlanadi. Bugun esa elektron mikroskopda alohida atomlarni suratga olish mumkin.","items":["Broun harakati","Hidning havoda tarqalishi (diffuziya)","Qandning suvda o'z-o'zidan erib tarqalishi","Jismlarning issiqda kengayib, sovuqda torayishi"]},{"h":"Molekula atomlardan iborat","p":"Suvga elektr toki o'tkazilsa, u ikki gazga parchalanadi: bir trubkada vodorod, ikkinchisida kislorod yig'iladi, vodorod hajmi kisloroddan ikki marta ko'p. Demak, suv molekulasi yanada kichik zarrachalar — vodorod va kislorod atomlaridan tuzilgan. Kimyoviy reaksiyada molekulalar o'zgaradi, atomlar esa saqlanib qoladi.","formula":"2H₂O → 2H₂ + O₂","visual":{"type":"diagram","kind":"electrolysis"}},{"h":"Kimyoviy element va kimyoviy belgi","p":"Kimyoviy element — atomlarning muayyan turi. Hozir 118 ta element ma'lum. 1813-yilda J. Berselius har bir elementni lotincha nomining bosh harfi yoki bosh harfi va yana bir harfi bilan belgilashni taklif qildi. Kimyoviy belgi elementni ham, uning bitta atomini ham bildiradi.","table":{"head":["Element","Lotincha nomi","Belgisi"],"rows":[["Vodorod","Hydrogenium","H"],["Kislorod","Oxygenium","O"],["Temir","Ferrum","Fe"],["Mis","Cuprum","Cu"],["Simob","Hydrargyrum","Hg"],["Natriy","Natrium","Na"]]}},{"h":"Esda tuting","items":["Molekula — modda kimyoviy xossalarini saqlovchi eng kichik zarracha","Atom va molekulalar doimo harakatda; buni Broun harakati va diffuziya isbotlaydi","Kimyoviy element — atomlarning muayyan turi","Kimyoviy belgi elementni va uning bitta atomini bildiradi"]}],"quiz":[{"q":"Diffuziya nima?","options":["Moddaning qizdirilganda erishi","Bir modda zarrachalarining boshqasi orasiga o'z-o'zidan tarqalishi","Atomning parchalanishi","Suyuqlikning muzlashi"],"correct":1,"explain":"Diffuziya zarrachalar harakati tufayli o'z-o'zidan sodir bo'ladi."},{"q":"Simobning kimyoviy belgisi qaysi?","options":["Si","S","Sm","Hg"],"correct":3,"explain":"Belgi lotincha Hydrargyrum nomidan olingan."},{"q":"Suv elektr toki bilan parchalanganda qaysi gaz hajmi ko'proq bo'ladi?","options":["Vodorod, ikki marta ko'p","Kislorod, ikki marta ko'p","Ikkalasi teng","Faqat bug' hosil bo'ladi"],"correct":0,"explain":"Suv molekulasida vodorod atomlari kislorodnikidan ikki marta ko'p, shuning uchun vodorod hajmi ham ikki baravar."}]},"en":{"title":"Atomic-molecular theory. Chemical elements and symbols","intro":"Open a bottle of perfume in one corner of a room, and soon the scent fills the whole room. This can only be explained if substances are made of tiny particles that are always moving.","blocks":[{"h":"From an idea to a theory","p":"Ancient Greek philosophers suggested that the world is made of tiny indivisible particles — atoms (Greek atomos, indivisible). Thinkers of the East also looked for the causes of events in invisible particles. After the work of Lomonosov, Dalton and Avogadro, the international congress in Karlsruhe in 1860 gave clear definitions of the atom and the molecule."},{"h":"Main points of the theory","items":["Many substances are made of molecules; a molecule is the smallest particle that keeps the chemical properties of a substance","Molecules are made of atoms","Atoms are complex too: they consist of protons, neutrons and electrons","Atoms and molecules are in constant motion, with forces of attraction and repulsion between them","Molecules of one substance are identical; molecules of different substances differ"],"visual":{"type":"molecule3d","mol":"H2O"}},{"h":"Evidence that particles exist","p":"In 1827 R. Brown saw under a microscope that tiny pollen grains in water jiggle endlessly and randomly — water molecules keep hitting them. Diffusion is the spontaneous spreading of particles of one substance among those of another. Expansion on heating is explained by a change in the distance between particles. Today single atoms can even be imaged with an electron microscope.","items":["Brownian motion","Smells spreading through air (diffusion)","Sugar dissolving and spreading through water on its own","Bodies expanding when hot and contracting when cold"]},{"h":"Molecules are made of atoms","p":"When an electric current passes through water, it splits into two gases: hydrogen collects in one tube and oxygen in the other, with twice as much hydrogen by volume. So a water molecule is built from even smaller particles — hydrogen and oxygen atoms. In a chemical reaction molecules change, but atoms are kept.","formula":"2H₂O → 2H₂ + O₂","visual":{"type":"diagram","kind":"electrolysis"}},{"h":"Chemical elements and symbols","p":"A chemical element is a particular kind of atom. 118 elements are known today. In 1813 J. Berzelius proposed writing each element as the first letter of its Latin name, or the first letter plus one more. A chemical symbol stands both for the element and for one atom of it.","table":{"head":["Element","Latin name","Symbol"],"rows":[["Hydrogen","Hydrogenium","H"],["Oxygen","Oxygenium","O"],["Iron","Ferrum","Fe"],["Copper","Cuprum","Cu"],["Mercury","Hydrargyrum","Hg"],["Sodium","Natrium","Na"]]}},{"h":"Remember","items":["A molecule is the smallest particle that keeps a substance's chemical properties","Atoms and molecules are always moving, as Brownian motion and diffusion show","A chemical element is a particular kind of atom","A chemical symbol stands for an element and for one atom of it"]}],"quiz":[{"q":"What is diffusion?","options":["A substance melting when heated","The spontaneous spreading of one substance's particles among another's","An atom breaking apart","A liquid freezing"],"correct":1,"explain":"Diffusion happens by itself because particles are moving."},{"q":"What is the chemical symbol of mercury?","options":["Si","S","Sm","Hg"],"correct":3,"explain":"The symbol comes from its Latin name, Hydrargyrum."},{"q":"When water is split by electric current, which gas has the larger volume?","options":["Hydrogen, twice as much","Oxygen, twice as much","Both are equal","Only steam forms"],"correct":0,"explain":"A water molecule has twice as many hydrogen atoms as oxygen atoms, so hydrogen's volume is double."}]},"ru":{"title":"Атомно-молекулярное учение. Химический элемент и знак","intro":"Откройте флакон духов в одном углу комнаты — и вскоре запах заполнит всю комнату. Объяснить это можно только тем, что вещества состоят из крошечных, постоянно движущихся частиц.","blocks":[{"h":"От идеи к теории","p":"Древнегреческие философы предположили, что мир состоит из мельчайших неделимых частиц — атомов (греч. «атомос» — неделимый). Мыслители Востока тоже видели причину явлений в невидимых частицах. После работ Ломоносова, Дальтона и Авогадро на международном съезде химиков в Карлсруэ в 1860 году были приняты чёткие определения атома и молекулы."},{"h":"Основные положения учения","items":["Многие вещества состоят из молекул; молекула — наименьшая частица, сохраняющая химические свойства вещества","Молекулы состоят из атомов","Атомы тоже сложны: они состоят из протонов, нейтронов и электронов","Атомы и молекулы непрерывно движутся, между ними действуют силы притяжения и отталкивания","Молекулы одного вещества одинаковы, разных веществ — различны"],"visual":{"type":"molecule3d","mol":"H2O"}},{"h":"Доказательства существования частиц","p":"В 1827 году Р. Броун увидел в микроскоп, что мелкие частицы пыльцы в воде непрерывно и беспорядочно движутся — их толкают молекулы воды. Диффузия — самопроизвольное проникновение частиц одного вещества между частицами другого. Расширение тел при нагревании объясняется изменением расстояний между частицами. Сегодня отдельные атомы можно даже сфотографировать в электронный микроскоп.","items":["Броуновское движение","Распространение запаха в воздухе (диффузия)","Самопроизвольное растворение и распределение сахара в воде","Расширение тел при нагревании и сжатие при охлаждении"]},{"h":"Молекулы состоят из атомов","p":"Если пропустить через воду электрический ток, она разлагается на два газа: в одной трубке собирается водород, в другой — кислород, причём водорода по объёму вдвое больше. Значит, молекула воды построена из ещё более мелких частиц — атомов водорода и кислорода. В химической реакции молекулы изменяются, а атомы сохраняются.","formula":"2H₂O → 2H₂ + O₂","visual":{"type":"diagram","kind":"electrolysis"}},{"h":"Химический элемент и химический знак","p":"Химический элемент — определённый вид атомов. Сейчас известно 118 элементов. В 1813 году Й. Берцелиус предложил обозначать элемент первой буквой его латинского названия или первой и ещё одной буквой. Химический знак обозначает и элемент, и один его атом.","table":{"head":["Элемент","Латинское название","Знак"],"rows":[["Водород","Hydrogenium","H"],["Кислород","Oxygenium","O"],["Железо","Ferrum","Fe"],["Медь","Cuprum","Cu"],["Ртуть","Hydrargyrum","Hg"],["Натрий","Natrium","Na"]]}},{"h":"Запомните","items":["Молекула — наименьшая частица, сохраняющая химические свойства вещества","Атомы и молекулы постоянно движутся — это доказывают броуновское движение и диффузия","Химический элемент — определённый вид атомов","Химический знак обозначает элемент и один его атом"]}],"quiz":[{"q":"Что такое диффузия?","options":["Плавление вещества при нагревании","Самопроизвольное проникновение частиц одного вещества между частицами другого","Распад атома","Замерзание жидкости"],"correct":1,"explain":"Диффузия идёт сама собой благодаря движению частиц."},{"q":"Какой химический знак у ртути?","options":["Si","S","Sm","Hg"],"correct":3,"explain":"Знак происходит от латинского названия Hydrargyrum."},{"q":"При разложении воды током какого газа получается больше по объёму?","options":["Водорода, вдвое больше","Кислорода, вдвое больше","Поровну","Образуется только пар"],"correct":0,"explain":"В молекуле воды атомов водорода вдвое больше, чем кислорода, поэтому и объём водорода вдвое больше."}]}},{"id":"t04","num":4,"icon":"⚖️","uz":{"title":"Atomlarning o'lchami. Nisbiy va absolut atom massa","intro":"Atom shunchalik kichikki, bir qator qilib terilgan 10 million atom atigi 1 mm ni egallaydi. Bunday mitti zarrachalarning massasini qanday ifodalaymiz?","blocks":[{"h":"Atom qanchalik kichik?","p":"Atomlarning diametri taxminan 10⁻¹⁰ m ga teng. Bu kattalik ilgari angstrem (Å) bilan o'lchangan, hozir esa nanometr (nm) ko'proq ishlatiladi.","formula":"1 Å = 10⁻¹⁰ m = 0,1 nm;  1 nm = 10⁻⁹ m","visual":{"type":"atom3d","el":"C"}},{"h":"Absolut atom massa","p":"Absolut massa — atomning haqiqiy massasi, u kilogramm yoki grammda ifodalanadi. Bu sonlar juda kichik: masalan, vodorod atomining massasi 1,67·10⁻²⁷ kg, uglerod atominiki 19,93·10⁻²⁷ kg. Bunday sonlar bilan hisoblash noqulay, shuning uchun kimyoda boshqa kattalik ishlatiladi."},{"h":"Massa atom birligi","p":"Taqqoslash uchun o'lchov sifatida uglerod-12 atomi massasining 1/12 qismi olingan. Bu massa atom birligi (m.a.b.) deyiladi.","formula":"1 m.a.b. = 19,93·10⁻²⁷ kg : 12 = 1,66·10⁻²⁷ kg = 1,66·10⁻²⁴ g"},{"h":"Nisbiy atom massa (Ar)","p":"Nisbiy atom massa — atom massasi massa atom birligidan necha marta katta ekanini ko'rsatadigan son. Uning birligi yo'q («r» — inglizcha relative, nisbiy). Ar qiymatlari davriy jadvalda berilgan.","formula":"Ar = m(atom) : 1 m.a.b.","items":["Misol: natriy atomining absolut massasi 38,18·10⁻²⁷ kg","1-qadam: Ar(Na) = 38,18·10⁻²⁷ : 1,66·10⁻²⁷","2-qadam: Ar(Na) = 23","Teskari masala: m(S) = 32 · 1,66·10⁻²⁷ kg = 53,12·10⁻²⁷ kg"]},{"h":"Ba'zi elementlarning nisbiy atom massalari","table":{"head":["Element","Ar"],"rows":[["H","1"],["C","12"],["N","14"],["O","16"],["Na","23"],["S","32"],["Cl","35,5"],["Ca","40"],["Fe","56"],["Cu","64"]]}},{"h":"Esda tuting","items":["Atom diametri taxminan 10⁻¹⁰ m (0,1 nm)","Absolut massa — atomning haqiqiy massasi kg yoki g da","1 m.a.b. = 1,66·10⁻²⁷ kg","Nisbiy atom massa birliksiz son va u davriy jadvalda beriladi"]}],"quiz":[{"q":"Massa atom birligi nimaga teng?","options":["Vodorod atomi massasiga","Uglerod-12 atomi massasining 1/12 qismiga","Kislorod atomi massasining 1/16 qismiga","1 grammga"],"correct":1,"explain":"1 m.a.b. uglerod-12 atomi massasining o'n ikkidan biri, ya'ni 1,66·10⁻²⁷ kg."},{"q":"Atomning massasi 26,56·10⁻²⁷ kg. Uning nisbiy atom massasi qancha?","options":["12","14","32","16"],"correct":3,"explain":"26,56·10⁻²⁷ : 1,66·10⁻²⁷ = 16, bu kislorod."},{"q":"Nisbiy atom massaning o'lchov birligi qanday?","options":["Birligi yo'q","kg","g","nm"],"correct":0,"explain":"Ar — ikki massaning nisbati, shuning uchun birliksiz son."}]},"en":{"title":"Size of atoms. Relative and absolute atomic mass","intro":"Atoms are so small that 10 million of them lined up in a row would span only 1 mm. How do we express the mass of such tiny particles?","blocks":[{"h":"How small is an atom?","p":"The diameter of an atom is about 10⁻¹⁰ m. This size used to be given in ångströms (Å); today the nanometre (nm) is used more often.","formula":"1 Å = 10⁻¹⁰ m = 0.1 nm;  1 nm = 10⁻⁹ m","visual":{"type":"atom3d","el":"C"}},{"h":"Absolute atomic mass","p":"The absolute mass is the real mass of an atom, given in kilograms or grams. These numbers are tiny: a hydrogen atom has a mass of 1.67×10⁻²⁷ kg and a carbon atom 19.93×10⁻²⁷ kg. Calculating with such numbers is awkward, so chemistry uses another quantity."},{"h":"The atomic mass unit","p":"As a standard for comparison, 1/12 of the mass of a carbon-12 atom was chosen. It is called the atomic mass unit (u).","formula":"1 u = 19.93×10⁻²⁷ kg ÷ 12 = 1.66×10⁻²⁷ kg = 1.66×10⁻²⁴ g"},{"h":"Relative atomic mass (Ar)","p":"Relative atomic mass is a number showing how many times an atom's mass is greater than one atomic mass unit. It has no unit (r stands for relative). Ar values are given in the periodic table.","formula":"Ar = m(atom) ÷ 1 u","items":["Example: the absolute mass of a sodium atom is 38.18×10⁻²⁷ kg","Step 1: Ar(Na) = 38.18×10⁻²⁷ ÷ 1.66×10⁻²⁷","Step 2: Ar(Na) = 23","Reverse problem: m(S) = 32 × 1.66×10⁻²⁷ kg = 53.12×10⁻²⁷ kg"]},{"h":"Relative atomic masses of some elements","table":{"head":["Element","Ar"],"rows":[["H","1"],["C","12"],["N","14"],["O","16"],["Na","23"],["S","32"],["Cl","35.5"],["Ca","40"],["Fe","56"],["Cu","64"]]}},{"h":"Remember","items":["An atom's diameter is about 10⁻¹⁰ m (0.1 nm)","Absolute mass is the real mass of an atom in kg or g","1 u = 1.66×10⁻²⁷ kg","Relative atomic mass is a unitless number given in the periodic table"]}],"quiz":[{"q":"What is one atomic mass unit equal to?","options":["The mass of a hydrogen atom","1/12 of the mass of a carbon-12 atom","1/16 of the mass of an oxygen atom","1 gram"],"correct":1,"explain":"1 u is one twelfth of the mass of a carbon-12 atom, 1.66×10⁻²⁷ kg."},{"q":"An atom has a mass of 26.56×10⁻²⁷ kg. What is its relative atomic mass?","options":["12","14","32","16"],"correct":3,"explain":"26.56×10⁻²⁷ ÷ 1.66×10⁻²⁷ = 16, which is oxygen."},{"q":"What is the unit of relative atomic mass?","options":["It has no unit","kg","g","nm"],"correct":0,"explain":"Ar is a ratio of two masses, so it is a unitless number."}]},"ru":{"title":"Размеры атомов. Относительная и абсолютная атомная масса","intro":"Атомы так малы, что 10 миллионов атомов, выложенных в ряд, займут всего 1 мм. Как выразить массу таких крошечных частиц?","blocks":[{"h":"Насколько мал атом?","p":"Диаметр атома составляет около 10⁻¹⁰ м. Раньше эту величину выражали в ангстремах (Å), сейчас чаще используют нанометры (нм).","formula":"1 Å = 10⁻¹⁰ м = 0,1 нм;  1 нм = 10⁻⁹ м","visual":{"type":"atom3d","el":"C"}},{"h":"Абсолютная атомная масса","p":"Абсолютная масса — истинная масса атома в килограммах или граммах. Эти числа очень малы: масса атома водорода 1,67·10⁻²⁷ кг, атома углерода 19,93·10⁻²⁷ кг. Считать с такими числами неудобно, поэтому в химии используют другую величину."},{"h":"Атомная единица массы","p":"За эталон сравнения взята 1/12 часть массы атома углерода-12. Она называется атомной единицей массы (а. е. м.).","formula":"1 а. е. м. = 19,93·10⁻²⁷ кг : 12 = 1,66·10⁻²⁷ кг = 1,66·10⁻²⁴ г"},{"h":"Относительная атомная масса (Ar)","p":"Относительная атомная масса — число, показывающее, во сколько раз масса атома больше атомной единицы массы. Единиц измерения у неё нет (r — от англ. relative, относительный). Значения Ar приведены в периодической таблице.","formula":"Ar = m(атома) : 1 а. е. м.","items":["Пример: абсолютная масса атома натрия 38,18·10⁻²⁷ кг","Шаг 1: Ar(Na) = 38,18·10⁻²⁷ : 1,66·10⁻²⁷","Шаг 2: Ar(Na) = 23","Обратная задача: m(S) = 32 · 1,66·10⁻²⁷ кг = 53,12·10⁻²⁷ кг"]},{"h":"Относительные атомные массы некоторых элементов","table":{"head":["Элемент","Ar"],"rows":[["H","1"],["C","12"],["N","14"],["O","16"],["Na","23"],["S","32"],["Cl","35,5"],["Ca","40"],["Fe","56"],["Cu","64"]]}},{"h":"Запомните","items":["Диаметр атома — около 10⁻¹⁰ м (0,1 нм)","Абсолютная масса — истинная масса атома в кг или г","1 а. е. м. = 1,66·10⁻²⁷ кг","Относительная атомная масса — безразмерное число из периодической таблицы"]}],"quiz":[{"q":"Чему равна атомная единица массы?","options":["Массе атома водорода","1/12 массы атома углерода-12","1/16 массы атома кислорода","1 грамму"],"correct":1,"explain":"1 а. е. м. — двенадцатая часть массы атома углерода-12, то есть 1,66·10⁻²⁷ кг."},{"q":"Масса атома 26,56·10⁻²⁷ кг. Какова его относительная атомная масса?","options":["12","14","32","16"],"correct":3,"explain":"26,56·10⁻²⁷ : 1,66·10⁻²⁷ = 16 — это кислород."},{"q":"В каких единицах выражают относительную атомную массу?","options":["Единиц нет","кг","г","нм"],"correct":0,"explain":"Ar — отношение двух масс, поэтому это безразмерное число."}]}},{"id":"t05","num":5,"icon":"🧱","uz":{"title":"Kimyoviy modda — atom va molekulalar uyushmasi","intro":"Olamdagi son-sanoqsiz moddalar atigi 118 ta elementdan qurilgan. Ammo bu «g'ishtlar» turlicha birlashadi: biri molekula hosil qiladi, boshqasi ulkan kristall panjara quradi.","blocks":[{"h":"Elementlar tabiatda","p":"Elementlar tabiatda bir xil tarqalmagan. Yer po'stining asosiy qismi bir nechta elementdan — kislorod, kremniy, aluminiy, temir va kalsiydan iborat. Inson tanasi asosan kislorod, uglerod, vodorod va yana bir necha elementdan tuzilgan, ba'zi elementlar esa faqat laboratoriyada olinadi.","visual":{"type":"chart","kind":"crust"}},{"h":"Birikma o'z elementlariga o'xshamaydi","p":"Suvni parchalab vodorod va kislorod olish mumkin. Lekin suvning xossalari bu ikki gazning xossalaridan butunlay farq qiladi. Ikki yoki undan ortiq turli moddaga parchalanadigan modda kimyoviy birikma deyiladi.","table":{"head":["Xossa (20 °C)","Suv","Vodorod","Kislorod"],"rows":[["Holati","suyuq","gaz","gaz"],["Qaynash harorati, °C","100","−253","−183"],["Yonishi","yonmaydi","yonadi","yonishga yordam beradi"]]}},{"h":"Molekular tuzilishli moddalar","p":"Bunday moddalar bir xil molekulalardan iborat, shuning uchun tarkibi doimiy. Gazlar odatda molekular tuzilishga ega. Qattiq holatdagi ba'zi moddalarning kristallarida ham molekulalar joylashgan: muz, «quruq muz» (CO₂), yod, naftalin. Molekulalar bir-biri bilan kuchsiz tortishgani uchun bu moddalar oson suyuqlanadi yoki bug'lanadi.","visual":{"type":"molecule3d","mol":"CO2"}},{"h":"Nomolekular tuzilishli moddalar","p":"Ko'pchilik qattiq moddalarning kristall panjarasi tugunlarida molekulalar emas, atomlar yoki ionlar joylashgan. Ular o'zaro kuchli bog'langani uchun bunday moddalar odatda qattiq va qiyin suyuqlanadi.","items":["Tugunlarda atomlar — juda qattiq, yuqori haroratda suyuqlanadi (olmos)","Tugunlarda ionlar — qiyin suyuqlanadi, uchuvchan emas (osh tuzi NaCl)","Tugunlarda metall atomlari va ionlari, orasida erkin elektronlar — yaltiroqlik, egiluvchanlik, issiqlik va elektr o'tkazuvchanlik (metallar)"],"visual":{"type":"molecule3d","mol":"NaCl"}},{"h":"Esda tuting","items":["Barcha moddalar kimyoviy elementlardan tashkil topgan","Birikmaning xossalari uni hosil qilgan elementlarnikidan farq qiladi","Molekular moddalar oson suyuqlanadi va uchuvchan bo'ladi","Nomolekular moddalarda tugunlarda atomlar yoki ionlar turadi, ular qiyin suyuqlanadi"]}],"quiz":[{"q":"Qaysi modda molekular tuzilishga ega?","options":["Olmos","Osh tuzi","Muz","Temir"],"correct":2,"explain":"Muz kristallarining tugunlarida suv molekulalari joylashgan."},{"q":"Metallarning elektr tokini o'tkazishiga nima sabab?","options":["Erkin elektronlar","Molekulalarning kuchsiz bog'lanishi","Kristallning yo'qligi","Ionlarning yo'qligi"],"correct":0,"explain":"Metall kristallida atomlar orasida erkin harakatlanuvchi elektronlar bor."},{"q":"Kimyoviy birikma nima?","options":["Faqat bir xil atomlardan iborat modda","Ikki va undan ortiq turli moddaga parchalanadigan modda","Ikki moddaning oddiy aralashmasi","Faqat gaz holatidagi modda"],"correct":1,"explain":"Masalan, suv vodorod va kislorodga parchalanadi, demak u birikma."}]},"en":{"title":"A substance as an association of atoms and molecules","intro":"The countless substances of the world are built from just 118 elements. But these building blocks join up in different ways: some form molecules, others build huge crystal lattices.","blocks":[{"h":"Elements in nature","p":"Elements are not spread evenly in nature. Most of the Earth's crust is made of a few elements — oxygen, silicon, aluminium, iron and calcium. The human body consists mainly of oxygen, carbon, hydrogen and a few other elements, while some elements are made only in laboratories.","visual":{"type":"chart","kind":"crust"}},{"h":"A compound is unlike its elements","p":"Water can be split into hydrogen and oxygen. Yet the properties of water are completely different from those of the two gases. A substance that can be broken down into two or more different substances is called a chemical compound.","table":{"head":["Property (20 °C)","Water","Hydrogen","Oxygen"],"rows":[["State","liquid","gas","gas"],["Boiling point, °C","100","−253","−183"],["Burning","does not burn","burns","supports burning"]]}},{"h":"Molecular substances","p":"These substances consist of identical molecules, so their composition is constant. Gases usually have a molecular structure. Some solids also have molecules in their crystals: ice, dry ice (CO₂), iodine, naphthalene. Because the molecules attract each other only weakly, such substances melt or evaporate easily.","visual":{"type":"molecule3d","mol":"CO2"}},{"h":"Non-molecular substances","p":"In most solids the points of the crystal lattice hold not molecules but atoms or ions. They are strongly bonded, so such substances are usually hard and difficult to melt.","items":["Atoms at the lattice points — very hard, high melting point (diamond)","Ions at the lattice points — hard to melt, not volatile (table salt NaCl)","Metal atoms and ions with free electrons between them — lustre, malleability, conduction of heat and electricity (metals)"],"visual":{"type":"molecule3d","mol":"NaCl"}},{"h":"Remember","items":["All substances are made of chemical elements","A compound's properties differ from those of the elements that form it","Molecular substances melt easily and are volatile","Non-molecular substances have atoms or ions at lattice points and are hard to melt"]}],"quiz":[{"q":"Which substance has a molecular structure?","options":["Diamond","Table salt","Ice","Iron"],"correct":2,"explain":"Water molecules sit at the lattice points of an ice crystal."},{"q":"Why do metals conduct electricity?","options":["Free electrons","Weakly bonded molecules","Lack of a crystal","Lack of ions"],"correct":0,"explain":"In a metal crystal there are electrons that move freely between the atoms."},{"q":"What is a chemical compound?","options":["A substance made of only one kind of atom","A substance that breaks down into two or more different substances","A simple mixture of two substances","A substance that is only a gas"],"correct":1,"explain":"For example, water breaks down into hydrogen and oxygen, so it is a compound."}]},"ru":{"title":"Химическое вещество — объединение атомов и молекул","intro":"Бесчисленные вещества мира построены всего из 118 элементов. Но эти «кирпичики» соединяются по-разному: одни образуют молекулы, другие — огромные кристаллические решётки.","blocks":[{"h":"Элементы в природе","p":"Элементы распространены в природе неравномерно. Основная часть земной коры состоит из нескольких элементов — кислорода, кремния, алюминия, железа и кальция. Тело человека состоит главным образом из кислорода, углерода, водорода и ещё нескольких элементов, а некоторые элементы получают только в лабораториях.","visual":{"type":"chart","kind":"crust"}},{"h":"Соединение не похоже на свои элементы","p":"Воду можно разложить на водород и кислород. Но свойства воды совсем не похожи на свойства этих газов. Вещество, которое разлагается на два или более разных вещества, называется химическим соединением.","table":{"head":["Свойство (20 °C)","Вода","Водород","Кислород"],"rows":[["Состояние","жидкость","газ","газ"],["Температура кипения, °C","100","−253","−183"],["Горение","не горит","горит","поддерживает горение"]]}},{"h":"Вещества молекулярного строения","p":"Такие вещества состоят из одинаковых молекул, поэтому их состав постоянен. Газы обычно имеют молекулярное строение. Молекулы находятся и в кристаллах некоторых твёрдых веществ: лёд, «сухой лёд» (CO₂), иод, нафталин. Молекулы слабо притягиваются друг к другу, поэтому такие вещества легко плавятся или испаряются.","visual":{"type":"molecule3d","mol":"CO2"}},{"h":"Вещества немолекулярного строения","p":"У большинства твёрдых веществ в узлах кристаллической решётки находятся не молекулы, а атомы или ионы. Они прочно связаны, поэтому такие вещества обычно твёрдые и тугоплавкие.","items":["Атомы в узлах — очень твёрдые, высокая температура плавления (алмаз)","Ионы в узлах — тугоплавкие, нелетучие (поваренная соль NaCl)","Атомы и ионы металла со свободными электронами между ними — блеск, пластичность, тепло- и электропроводность (металлы)"],"visual":{"type":"molecule3d","mol":"NaCl"}},{"h":"Запомните","items":["Все вещества состоят из химических элементов","Свойства соединения отличаются от свойств образующих его элементов","Молекулярные вещества легкоплавки и летучи","В немолекулярных веществах в узлах находятся атомы или ионы, они тугоплавки"]}],"quiz":[{"q":"Какое вещество имеет молекулярное строение?","options":["Алмаз","Поваренная соль","Лёд","Железо"],"correct":2,"explain":"В узлах кристалла льда находятся молекулы воды."},{"q":"Почему металлы проводят электрический ток?","options":["Из-за свободных электронов","Из-за слабой связи молекул","Из-за отсутствия кристалла","Из-за отсутствия ионов"],"correct":0,"explain":"В кристалле металла между атомами свободно движутся электроны."},{"q":"Что такое химическое соединение?","options":["Вещество из атомов одного вида","Вещество, разлагающееся на два или более разных вещества","Простая смесь двух веществ","Вещество, существующее только в виде газа"],"correct":1,"explain":"Например, вода разлагается на водород и кислород, значит, это соединение."}]}},{"id":"t06","num":6,"icon":"🧪","uz":{"title":"Sof modda va aralashma","intro":"Choy, sut, asal, havo, dengiz suvi — bularning hech biri sof modda emas. Aralashmalar qanday bo'ladi va ulardan toza moddani qanday ajratib olamiz?","blocks":[{"h":"Sof modda va aralashma","p":"Sof modda butun hajmi bo'yicha bir xil tarkib va doimiy xossalarga ega: distillangan suv, mis sim, kislorod. Aralashma ikki yoki undan ortiq moddadan iborat, tarkibi o'zgaruvchan va uni fizik usullar bilan qismlarga ajratish mumkin. Tabiatda sof moddalar deyarli uchramaydi: hatto buloq suvida ham erigan tuzlar va gazlar bor.","items":["Sof moddalar: distillangan suv, mis, kislorod, shakar","Aralashmalar: havo, sut, asal, o'simlik moyi, yodlangan osh tuzi"]},{"h":"Gomogen va geterogen aralashmalar","p":"Gomogen aralashmada qismlarni hatto mikroskopda ham ko'rib bo'lmaydi, masalan tuzning suvdagi eritmasi. Uning xossalari tarkibiga bog'liq: suvda tuz qancha ko'p bo'lsa, u 0 °C dan shuncha past haroratda muzlaydi. Geterogen aralashmada qismlar ko'z yoki mikroskop bilan ko'rinadi: loyqa suv, qum va temir qipig'i.","table":{"head":["Belgi","Gomogen","Geterogen"],"rows":[["Qismlar ko'rinadimi?","yo'q","ha"],["Misol","tuzli suv, havo","loyqa suv, qum va tuz"],["Ajratish usuli","bug'latish, distillash","tindirish, filtrlash, magnit"]]}},{"h":"Geterogen aralashmalarni ajratish","p":"Har bir usul moddalardagi biror xossa farqiga asoslanadi: zichlik, zarracha kattaligi yoki magnitga tortilish.","items":["Tindirish — og'ir zarrachalar cho'kadi, keyin suyuqlik ehtiyotlik bilan quyib olinadi (dekantatsiya)","Ajratish voronkasi — bir-birida erimaydigan suyuqliklarni (suv va moy) ajratadi","Filtrlash — filtr qog'oz qattiq zarrachalarni ushlab qoladi, tiniq filtrat o'tadi","Magnit — temir qipig'ini oltingugurt yoki qumdan ajratadi"],"visual":{"type":"diagram","kind":"filtration"}},{"h":"Gomogen aralashmalarni ajratish","p":"Bug'latishda erituvchi uchib ketadi va erigan qattiq modda qoladi — dengiz suvidan tuz shunday olinadi. Distillash (haydash) suyuqliklarning qaynash harorati farqiga asoslangan: avval oson qaynaydigan suyuqlik bug'lanadi, uning bug'i sovitkichda yana suyuqlikka aylanadi. Xromatografiya esa rangli moddalarni (masalan, siyoh tarkibini) ajratishga yordam beradi.","visual":{"type":"diagram","kind":"distillation"}},{"h":"Amaliy ish: ifloslangan osh tuzini tozalash","p":"Bu ishda bir nechta usul ketma-ket qo'llanadi: tuz suvda eriydi, qum va tuproq esa erimaydi.","items":["1. Taxminan 20 ml distillangan suvga tayoqcha bilan aralashtirib iflos tuzni oz-ozdan soling, tuz erimay qolsa to'xtating","2. Kvadrat filtr qog'ozni to'rtga buklab, voronkaga mos qirqing va konus qilib yoying; filtr cheti voronka chetidan biroz pastda tursin","3. Loyqa eritmani tayoqcha bo'ylab filtrga asta quying; o'tgan tiniq suyuqlik — filtrat","4. Filtratni chinni kosachada shtativ halqasida qizdiring va sachramasligi uchun aralashtirib turing","5. Kristallar paydo bo'lishi bilan qizdirishni to'xtating va toza tuzni ko'zdan kechiring","6. Hisobotga mavzu, jihozlar, bosqichlar, chizma va xulosani yozing"]},{"h":"Esda tuting","items":["Sof modda doimiy tarkib va xossalarga ega, aralashmaning tarkibi o'zgaruvchan","Gomogen aralashmada qismlar ko'rinmaydi, geterogenda ko'rinadi","Tindirish, filtrlash, magnit — geterogen aralashmalar uchun","Bug'latish, distillash — gomogen aralashmalar uchun"]}],"quiz":[{"q":"Qaysi biri sof modda?","options":["Sut","Havo","Distillangan suv","Asal"],"correct":2,"explain":"Distillangan suvda boshqa moddalar deyarli yo'q, qolganlari aralashmalar."},{"q":"Temir qipig'i va oltingugurt aralashmasini qanday ajratish qulay?","options":["Magnit bilan","Distillash bilan","Bug'latish bilan","Xromatografiya bilan"],"correct":0,"explain":"Temir magnitga tortiladi, oltingugurt esa tortilmaydi."},{"q":"Filtrlashdan keyin qog'ozdan o'tgan tiniq suyuqlik nima deyiladi?","options":["Cho'kma","Distillat","Suspenziya","Filtrat"],"correct":3,"explain":"Filtrdan o'tgan tiniq suyuqlik filtrat deb ataladi."}]},"en":{"title":"Pure substances and mixtures","intro":"Tea, milk, honey, air, sea water — none of these is a pure substance. What are mixtures like, and how do we get a pure substance out of them?","blocks":[{"h":"Pure substances and mixtures","p":"A pure substance has the same composition throughout and constant properties: distilled water, copper wire, oxygen. A mixture consists of two or more substances, its composition can vary, and it can be separated by physical methods. Pure substances hardly occur in nature: even spring water contains dissolved salts and gases.","items":["Pure substances: distilled water, copper, oxygen, sugar","Mixtures: air, milk, honey, vegetable oil, iodised salt"]},{"h":"Homogeneous and heterogeneous mixtures","p":"In a homogeneous mixture the parts cannot be seen even under a microscope, for example salt dissolved in water. Its properties depend on its composition: the more salt in the water, the further below 0 °C it freezes. In a heterogeneous mixture the parts can be seen by eye or under a microscope: muddy water, sand with iron filings.","table":{"head":["Feature","Homogeneous","Heterogeneous"],"rows":[["Parts visible?","no","yes"],["Example","salt water, air","muddy water, sand and salt"],["Separated by","evaporation, distillation","settling, filtration, magnet"]]}},{"h":"Separating heterogeneous mixtures","p":"Each method relies on a difference in some property: density, particle size or attraction to a magnet.","items":["Settling — heavy particles sink, then the liquid is carefully poured off (decanting)","Separating funnel — separates liquids that do not mix (water and oil)","Filtration — filter paper holds back solid particles while the clear filtrate passes through","Magnet — pulls iron filings out of sulfur or sand"],"visual":{"type":"diagram","kind":"filtration"}},{"h":"Separating homogeneous mixtures","p":"In evaporation the solvent leaves and the dissolved solid stays behind — this is how salt is obtained from sea water. Distillation uses different boiling points: the liquid that boils more easily evaporates first, and its vapour turns back into liquid in a condenser. Chromatography helps separate coloured substances, for example the dyes in ink.","visual":{"type":"diagram","kind":"distillation"}},{"h":"Practical work: purifying contaminated table salt","p":"Several methods are used one after another here: salt dissolves in water, while sand and soil do not.","items":["1. Add dirty salt bit by bit to about 20 mL of distilled water while stirring with a glass rod; stop when salt no longer dissolves","2. Fold a square of filter paper into four, trim it to fit the funnel and open it into a cone; its edge should sit a little below the rim of the funnel","3. Pour the cloudy solution slowly onto the filter along the glass rod; the clear liquid that passes through is the filtrate","4. Heat the filtrate in a porcelain dish on the stand ring, stirring so it does not spatter","5. Stop heating as soon as crystals appear, then examine the clean salt","6. Write a report: title, equipment, steps, a sketch and the conclusion"]},{"h":"Remember","items":["A pure substance has constant composition and properties; a mixture's composition varies","Parts of a homogeneous mixture are invisible, those of a heterogeneous one are visible","Settling, filtration and magnets work for heterogeneous mixtures","Evaporation and distillation work for homogeneous mixtures"]}],"quiz":[{"q":"Which of these is a pure substance?","options":["Milk","Air","Distilled water","Honey"],"correct":2,"explain":"Distilled water contains almost nothing else; the others are mixtures."},{"q":"How is a mixture of iron filings and sulfur best separated?","options":["With a magnet","By distillation","By evaporation","By chromatography"],"correct":0,"explain":"Iron is attracted to a magnet, sulfur is not."},{"q":"What is the clear liquid that passes through filter paper called?","options":["Precipitate","Distillate","Suspension","Filtrate"],"correct":3,"explain":"The clear liquid that passes through a filter is called the filtrate."}]},"ru":{"title":"Чистые вещества и смеси","intro":"Чай, молоко, мёд, воздух, морская вода — ничто из этого не является чистым веществом. Какими бывают смеси и как выделить из них чистое вещество?","blocks":[{"h":"Чистое вещество и смесь","p":"Чистое вещество во всём объёме имеет одинаковый состав и постоянные свойства: дистиллированная вода, медная проволока, кислород. Смесь состоит из двух или более веществ, её состав может меняться, и её можно разделить физическими способами. Чистые вещества в природе почти не встречаются: даже в родниковой воде есть растворённые соли и газы.","items":["Чистые вещества: дистиллированная вода, медь, кислород, сахар","Смеси: воздух, молоко, мёд, растительное масло, йодированная соль"]},{"h":"Однородные и неоднородные смеси","p":"В однородной (гомогенной) смеси части не видны даже в микроскоп, например раствор соли в воде. Её свойства зависят от состава: чем больше соли в воде, тем ниже 0 °C она замерзает. В неоднородной (гетерогенной) смеси части видны глазом или в микроскоп: мутная вода, песок с железными опилками.","table":{"head":["Признак","Гомогенная","Гетерогенная"],"rows":[["Видны ли части?","нет","да"],["Пример","солёная вода, воздух","мутная вода, песок с солью"],["Способ разделения","выпаривание, дистилляция","отстаивание, фильтрование, магнит"]]}},{"h":"Разделение неоднородных смесей","p":"Каждый способ основан на различии в каком-либо свойстве: плотности, размере частиц или притяжении к магниту.","items":["Отстаивание — тяжёлые частицы оседают, затем жидкость осторожно сливают (декантация)","Делительная воронка — разделяет несмешивающиеся жидкости (вода и масло)","Фильтрование — фильтровальная бумага задерживает твёрдые частицы, прозрачный фильтрат проходит","Магнит — извлекает железные опилки из смеси с серой или песком"],"visual":{"type":"diagram","kind":"filtration"}},{"h":"Разделение однородных смесей","p":"При выпаривании растворитель улетучивается, а растворённое твёрдое вещество остаётся — так получают соль из морской воды. Дистилляция (перегонка) основана на разных температурах кипения: сначала испаряется легкокипящая жидкость, а её пар в холодильнике снова превращается в жидкость. Хроматография помогает разделить окрашенные вещества, например красители чернил.","visual":{"type":"diagram","kind":"distillation"}},{"h":"Практическая работа: очистка загрязнённой поваренной соли","p":"Здесь последовательно применяют несколько способов: соль растворяется в воде, а песок и почва — нет.","items":["1. В примерно 20 мл дистиллированной воды понемногу добавляйте загрязнённую соль, перемешивая палочкой; остановитесь, когда соль перестанет растворяться","2. Сложите квадратный фильтр вчетверо, обрежьте по размеру воронки и разверните конусом; край фильтра должен быть чуть ниже края воронки","3. Медленно лейте мутный раствор на фильтр по стеклянной палочке; прошедшая прозрачная жидкость — фильтрат","4. Нагревайте фильтрат в фарфоровой чашке на кольце штатива, помешивая, чтобы не разбрызгивался","5. Как только появятся кристаллы, прекратите нагрев и рассмотрите чистую соль","6. Составьте отчёт: тема, оборудование, этапы, рисунок и вывод"]},{"h":"Запомните","items":["Чистое вещество имеет постоянный состав и свойства, состав смеси переменный","В гомогенной смеси части не видны, в гетерогенной — видны","Отстаивание, фильтрование, магнит — для неоднородных смесей","Выпаривание и дистилляция — для однородных смесей"]}],"quiz":[{"q":"Что из перечисленного — чистое вещество?","options":["Молоко","Воздух","Дистиллированная вода","Мёд"],"correct":2,"explain":"В дистиллированной воде почти нет примесей, остальное — смеси."},{"q":"Как удобнее разделить смесь железных опилок и серы?","options":["Магнитом","Дистилляцией","Выпариванием","Хроматографией"],"correct":0,"explain":"Железо притягивается магнитом, а сера — нет."},{"q":"Как называется прозрачная жидкость, прошедшая через фильтр?","options":["Осадок","Дистиллят","Суспензия","Фильтрат"],"correct":3,"explain":"Прозрачная жидкость, прошедшая через фильтр, называется фильтратом."}]}},{"id":"t07","num":7,"icon":"💎","uz":{"title":"Oddiy va murakkab moddalar","intro":"Olmos va qalam grafiti bir-biriga umuman o'xshamaydi, lekin ikkalasi ham faqat uglerod atomlaridan iborat. Bu darsda moddalar qanday guruhlanishini va bitta element qanday qilib bir nechta modda hosil qilishini bilib olamiz.","blocks":[{"h":"Oddiy va murakkab moddalar","p":"Bir xil element atomlaridan tuzilgan moddalar oddiy moddalar deyiladi: vodorod H₂, kislorod O₂, temir Fe, oltingugurt S, mis Cu. Turli element atomlaridan tuzilgan moddalar murakkab moddalar (birikmalar) deyiladi: suv H₂O, osh tuzi NaCl, karbonat angidrid CO₂, shakar. Murakkab moddalar soni bir necha milliondan oshadi.","visual":{"type":"diagram","kind":"classification"}},{"h":"Murakkab moddalar sinflari","p":"Murakkab moddalar tarkibi va xossalariga ko'ra sinflarga ajratiladi. Ular bilan keyingi mavzularda batafsil tanishamiz.","table":{"head":["Sinf","Misol"],"rows":[["Oksidlar","H₂O, CO₂"],["Asoslar","NaOH"],["Kislotalar","H₂SO₄"],["Tuzlar","NaCl, CaCO₃"]]}},{"h":"Allotropiya","p":"Bir element atomlaridan bir nechta oddiy modda hosil bo'lishi allotropiya deyiladi. Allotropik shakllar molekuladagi atomlar soni yoki atomlarning bog'lanish tartibi bilan farq qiladi. Masalan, kislorod elementi ikki oddiy modda — kislorod O₂ va ozon O₃ ni hosil qiladi.","items":["Uglerod: olmos, grafit, karbin, fulleren","Kislorod: kislorod O₂ va ozon O₃","Fosfor: oq, qizil va qora fosfor","Oltingugurt: rombik va plastik oltingugurt"],"visual":{"type":"molecule3d","mol":"O3"}},{"h":"Element va oddiy modda — bir narsa emas","p":"Olmos — eng qattiq tabiiy modda, grafit esa yumshoq va qog'ozda iz qoldiradi. Shunga qaramay, ikkalasi kislorodda yonganda bir xil gaz — karbonat angidrid hosil qiladi. Demak, ular bitta element — ugleroddan tashkil topgan turli oddiy moddalardir.","formula":"C + O₂ → CO₂","visual":{"type":"reaction","id":"c_o2"}},{"h":"Analiz va sintez","p":"Moddani tarkibiy qismlarga ajratib, tarkibini o'rganish analiz deyiladi; oddiyroq moddalardan yangi modda olish esa sintez deyiladi. Suvning tok bilan parchalanishi — analizga, vodorodning kislorodda yonib suv hosil qilishi esa sintezga misol.","items":["Sifat analizi — modda qanday qismlardan iboratligini aniqlaydi","Miqdoriy analiz — har bir qism qancha ekanini aniqlaydi"],"formula":"2H₂ + O₂ → 2H₂O"},{"h":"Esda tuting","items":["Oddiy modda bir xil element atomlaridan, murakkab modda turli element atomlaridan tuzilgan","Bir elementning bir nechta oddiy modda hosil qilishi — allotropiya","Olmos va grafit — uglerodning allotropik shakllari","Analiz — moddani parchalab o'rganish, sintez — yangi modda hosil qilish"]}],"quiz":[{"q":"Quyidagilardan qaysi biri murakkab modda?","options":["Kislorod","Temir","Karbonat angidrid","Oltingugurt"],"correct":2,"explain":"CO₂ ikki xil element — uglerod va kislorod atomlaridan tuzilgan."},{"q":"Kislorod va ozon bir-biriga nisbatan nima?","options":["Bitta elementning allotropik shakllari","Ikki xil element","Aralashma va sof modda","Oksid va kislota"],"correct":0,"explain":"O₂ va O₃ — bitta element, kislorodning turli oddiy moddalari."},{"q":"Oddiy moddalardan yangi murakkab modda olish nima deyiladi?","options":["Analiz","Sintez","Distillash","Filtrlash"],"correct":1,"explain":"Sintez — moddani boshqa moddalardan hosil qilish jarayoni."}]},"en":{"title":"Simple and complex substances","intro":"Diamond and pencil graphite look nothing alike, yet both are made only of carbon atoms. In this lesson we see how substances are grouped and how one element can form several substances.","blocks":[{"h":"Simple and complex substances","p":"Substances made of atoms of a single element are called simple substances: hydrogen H₂, oxygen O₂, iron Fe, sulfur S, copper Cu. Substances made of atoms of different elements are called complex substances (compounds): water H₂O, table salt NaCl, carbon dioxide CO₂, sugar. There are several million complex substances.","visual":{"type":"diagram","kind":"classification"}},{"h":"Classes of complex substances","p":"Complex substances are divided into classes by their composition and properties. We will study them in detail in later topics.","table":{"head":["Class","Example"],"rows":[["Oxides","H₂O, CO₂"],["Bases","NaOH"],["Acids","H₂SO₄"],["Salts","NaCl, CaCO₃"]]}},{"h":"Allotropy","p":"When one element forms several simple substances, this is called allotropy. Allotropes differ in the number of atoms in the molecule or in the way the atoms are bonded. For example, the element oxygen forms two simple substances — oxygen O₂ and ozone O₃.","items":["Carbon: diamond, graphite, carbyne, fullerene","Oxygen: oxygen O₂ and ozone O₃","Phosphorus: white, red and black phosphorus","Sulfur: rhombic and plastic sulfur"],"visual":{"type":"molecule3d","mol":"O3"}},{"h":"An element is not the same as a simple substance","p":"Diamond is the hardest natural substance, while graphite is soft and leaves a mark on paper. Even so, both burn in oxygen to give the same gas — carbon dioxide. So they are different simple substances made of one element, carbon.","formula":"C + O₂ → CO₂","visual":{"type":"reaction","id":"c_o2"}},{"h":"Analysis and synthesis","p":"Breaking a substance down to study its composition is called analysis; making a new substance from simpler ones is called synthesis. Splitting water with electric current is an example of analysis, and hydrogen burning in oxygen to form water is an example of synthesis.","items":["Qualitative analysis — finds out which parts a substance consists of","Quantitative analysis — finds out how much of each part there is"],"formula":"2H₂ + O₂ → 2H₂O"},{"h":"Remember","items":["A simple substance is made of atoms of one element, a complex substance of atoms of different elements","One element forming several simple substances is allotropy","Diamond and graphite are allotropes of carbon","Analysis breaks a substance down to study it; synthesis makes a new substance"]}],"quiz":[{"q":"Which of these is a complex substance?","options":["Oxygen","Iron","Carbon dioxide","Sulfur"],"correct":2,"explain":"CO₂ is made of atoms of two different elements, carbon and oxygen."},{"q":"What are oxygen and ozone to each other?","options":["Allotropes of one element","Two different elements","A mixture and a pure substance","An oxide and an acid"],"correct":0,"explain":"O₂ and O₃ are different simple substances of the same element, oxygen."},{"q":"What is making a new complex substance from simple ones called?","options":["Analysis","Synthesis","Distillation","Filtration"],"correct":1,"explain":"Synthesis is the process of making a substance from other substances."}]},"ru":{"title":"Простые и сложные вещества","intro":"Алмаз и графит из карандаша совсем не похожи, но оба состоят только из атомов углерода. На этом уроке узнаем, как классифицируют вещества и как один элемент образует несколько веществ.","blocks":[{"h":"Простые и сложные вещества","p":"Вещества, состоящие из атомов одного элемента, называются простыми: водород H₂, кислород O₂, железо Fe, сера S, медь Cu. Вещества, состоящие из атомов разных элементов, называются сложными (соединениями): вода H₂O, поваренная соль NaCl, углекислый газ CO₂, сахар. Сложных веществ известно несколько миллионов.","visual":{"type":"diagram","kind":"classification"}},{"h":"Классы сложных веществ","p":"Сложные вещества делят на классы по составу и свойствам. Подробно мы изучим их в следующих темах.","table":{"head":["Класс","Пример"],"rows":[["Оксиды","H₂O, CO₂"],["Основания","NaOH"],["Кислоты","H₂SO₄"],["Соли","NaCl, CaCO₃"]]}},{"h":"Аллотропия","p":"Образование одним элементом нескольких простых веществ называется аллотропией. Аллотропные модификации различаются числом атомов в молекуле или порядком связи атомов. Например, элемент кислород образует два простых вещества — кислород O₂ и озон O₃.","items":["Углерод: алмаз, графит, карбин, фуллерен","Кислород: кислород O₂ и озон O₃","Фосфор: белый, красный и чёрный фосфор","Сера: ромбическая и пластическая сера"],"visual":{"type":"molecule3d","mol":"O3"}},{"h":"Элемент и простое вещество — не одно и то же","p":"Алмаз — самое твёрдое природное вещество, а графит мягкий и оставляет след на бумаге. И всё же оба при горении в кислороде дают один и тот же газ — углекислый. Значит, это разные простые вещества одного элемента — углерода.","formula":"C + O₂ → CO₂","visual":{"type":"reaction","id":"c_o2"}},{"h":"Анализ и синтез","p":"Разложение вещества для изучения его состава называется анализом, а получение нового вещества из более простых — синтезом. Разложение воды электрическим током — пример анализа, а горение водорода в кислороде с образованием воды — пример синтеза.","items":["Качественный анализ — устанавливает, из каких частей состоит вещество","Количественный анализ — устанавливает, сколько каждой части"],"formula":"2H₂ + O₂ → 2H₂O"},{"h":"Запомните","items":["Простое вещество состоит из атомов одного элемента, сложное — из атомов разных элементов","Образование одним элементом нескольких простых веществ — аллотропия","Алмаз и графит — аллотропные модификации углерода","Анализ — разложение вещества для изучения, синтез — получение нового вещества"]}],"quiz":[{"q":"Какое из веществ сложное?","options":["Кислород","Железо","Углекислый газ","Сера"],"correct":2,"explain":"CO₂ состоит из атомов двух разных элементов — углерода и кислорода."},{"q":"Кем приходятся друг другу кислород и озон?","options":["Аллотропные модификации одного элемента","Два разных элемента","Смесь и чистое вещество","Оксид и кислота"],"correct":0,"explain":"O₂ и O₃ — разные простые вещества одного элемента, кислорода."},{"q":"Как называется получение нового сложного вещества из простых?","options":["Анализ","Синтез","Дистилляция","Фильтрование"],"correct":1,"explain":"Синтез — процесс получения вещества из других веществ."}]}},{"id":"t08","num":8,"icon":"🧊","uz":{"title":"Moddaning agregat holatlari","intro":"Stakandagi suv, undagi muz bo'lagi va choynakdan chiqayotgan bug' — bularning hammasi bitta modda. Farq faqat zarrachalarning qanday joylashgani va qanchalik erkin harakatlanishida. Keling, moddaning uch holatini zarrachalar ko'zi bilan ko'rib chiqamiz.","blocks":[{"h":"Uch asosiy holat","p":"Moddalar odatda qattiq, suyuq yoki gaz holatida uchraydi: temir mix — qattiq, sut — suyuq, karbonat angidrid — gaz. Bitta moddaning o'zi sharoitga qarab turli holatda bo'lishi mumkin. Masalan, suv muz, suyuq suv va bug' ko'rinishida uchraydi. Quyidagi animatsiyada har bir holatdagi zarrachalar harakatini kuzating.","visual":{"type":"particles"}},{"h":"Zarrachalar nima qiladi?","p":"Har qanday modda doimo harakatdagi mayda zarrachalardan — atom va molekulalardan tuzilgan. Moddaning holatini zarrachalar orasidagi masofa va ularning bir-birini tortish kuchi belgilaydi.","table":{"head":["Belgi","Qattiq","Suyuq","Gaz"],"rows":[["Shakli","O'zgarmas","Idish shaklini oladi","Idish shaklini oladi"],["Hajmi","O'zgarmas","O'zgarmas","Butun idishni to'ldiradi"],["Zarrachalar orasidagi masofa","Juda kichik","Kichik","Juda katta"],["Zarrachalar harakati","Joyida tebranadi","Bir-biri ustidan sirpanadi","Tez va tartibsiz uchadi"],["Siqiluvchanlik","Deyarli siqilmaydi","Deyarli siqilmaydi","Oson siqiladi"]]}},{"h":"Holatlar orasidagi o'tishlar","p":"Qizdirilganda zarrachalar tezroq harakatlanadi va modda bir holatdan boshqasiga o'tadi; sovitilganda teskari jarayon boradi. Bu o'tishlarda modda o'zgarmaydi — faqat uning holati o'zgaradi.","items":["Suyuqlanish (erish): qattiq → suyuq, masalan, muzning erishi","Bug'lanish va qaynash: suyuq → gaz","Kondensatsiya: gaz → suyuq, masalan, sovuq oynada tomchilar paydo bo'lishi","Qotish (muzlash): suyuq → qattiq","Sublimatsiya: qattiq → gaz, suyuq holatni chetlab o'tib; masalan, yod kristallari yoki «quruq muz»"],"visual":{"type":"diagram","kind":"states"}},{"h":"Hayotdan misollar","p":"Yuvilgan kir quriganda undagi suv bug'lanib ketadi. Qishda deraza oynasida qirov paydo bo'ladi: havodagi suv bug'i to'g'ridan-to'g'ri qattiq holatga o'tadi. Suyultirilgan gaz ballonlarida gaz katta bosim ostida suyuq holatda saqlanadi, chunki gazni siqib, hajmini ancha kichraytirish mumkin."},{"h":"Esda tuting","items":["Modda qattiq, suyuq va gaz holatida bo'lishi mumkin","Qattiq jism shakli va hajmini saqlaydi, suyuqlik faqat hajmini saqlaydi, gaz esa hech birini saqlamaydi","Gazda zarrachalar orasidagi masofa eng katta, shuning uchun gaz oson siqiladi","Holat o'zgarganda yangi modda hosil bo'lmaydi"]}],"quiz":[{"q":"Qaysi holatda modda o'z shaklini ham, hajmini ham saqlaydi?","options":["Gaz","Suyuqlik","Qattiq","Hech qaysisida"],"correct":2,"explain":"Qattiq jismda zarrachalar qat'iy joylashgan, shuning uchun shakl ham, hajm ham saqlanadi."},{"q":"Quyidagilardan qaysi biri eng oson siqiladi?","options":["Temir","Suv","Havo","Muz"],"correct":2,"explain":"Gaz zarrachalari orasida bo'shliq katta, shuning uchun havo oson siqiladi."},{"q":"Muzning erishi qanday o'tish deb ataladi?","options":["Kondensatsiya","Suyuqlanish","Sublimatsiya","Qotish"],"correct":1,"explain":"Qattiq holatdan suyuq holatga o'tish suyuqlanish deyiladi."}]},"en":{"title":"States of matter","intro":"Water in a glass, an ice cube floating in it and steam rising from a kettle are all the same substance. The only difference is how the particles are arranged and how freely they move. Let us look at the three states of matter through the eyes of the particles.","blocks":[{"h":"Three main states","p":"Substances are usually found as solids, liquids or gases: an iron nail is solid, milk is liquid and carbon dioxide is a gas. The same substance can exist in different states depending on conditions. Water, for example, occurs as ice, liquid water and vapour. Watch how the particles move in each state in the animation below.","visual":{"type":"particles"}},{"h":"What are the particles doing?","p":"Every substance is made of tiny particles, atoms and molecules, that are always moving. The state of a substance depends on the distance between its particles and on how strongly they attract each other.","table":{"head":["Feature","Solid","Liquid","Gas"],"rows":[["Shape","Fixed","Takes the shape of the container","Takes the shape of the container"],["Volume","Fixed","Fixed","Fills the whole container"],["Distance between particles","Very small","Small","Very large"],["Particle motion","Vibrate in place","Slide past each other","Fly fast and randomly"],["Compressibility","Almost incompressible","Almost incompressible","Easily compressed"]]}},{"h":"Changes between states","p":"When heated, particles move faster and the substance can pass from one state to another; when cooled, the reverse happens. In these changes the substance itself stays the same — only its state changes.","items":["Melting: solid → liquid, for example ice melting","Evaporation and boiling: liquid → gas","Condensation: gas → liquid, for example droplets forming on a cold window","Freezing (solidification): liquid → solid","Sublimation: solid → gas, skipping the liquid state; for example iodine crystals or dry ice"],"visual":{"type":"diagram","kind":"states"}},{"h":"Examples from everyday life","p":"When washed clothes dry, the water in them evaporates. In winter, frost forms on window glass: water vapour from the air turns directly into a solid. In liquefied gas cylinders the gas is kept as a liquid under high pressure, because a gas can be squeezed into a much smaller volume."},{"h":"Remember","items":["A substance can be solid, liquid or gas","A solid keeps its shape and volume, a liquid keeps only its volume, a gas keeps neither","In a gas the particles are farthest apart, so gases are easy to compress","A change of state does not produce a new substance"]}],"quiz":[{"q":"In which state does a substance keep both its shape and its volume?","options":["Gas","Liquid","Solid","None of them"],"correct":2,"explain":"In a solid the particles hold fixed positions, so both shape and volume are kept."},{"q":"Which of these is the easiest to compress?","options":["Iron","Water","Air","Ice"],"correct":2,"explain":"Gas particles have a lot of empty space between them, so air is easily compressed."},{"q":"What is the melting of ice called?","options":["Condensation","Melting","Sublimation","Freezing"],"correct":1,"explain":"The change from solid to liquid is called melting."}]},"ru":{"title":"Агрегатные состояния вещества","intro":"Вода в стакане, плавающий в ней кубик льда и пар над чайником — всё это одно и то же вещество. Разница лишь в том, как расположены частицы и насколько свободно они движутся. Рассмотрим три состояния вещества глазами частиц.","blocks":[{"h":"Три основных состояния","p":"Вещества обычно встречаются в твёрдом, жидком или газообразном состоянии: железный гвоздь — твёрдый, молоко — жидкое, углекислый газ — газ. Одно и то же вещество в зависимости от условий может находиться в разных состояниях. Например, вода бывает льдом, жидкой водой и паром. Посмотрите в анимации, как движутся частицы в каждом состоянии.","visual":{"type":"particles"}},{"h":"Что делают частицы?","p":"Любое вещество состоит из мельчайших, постоянно движущихся частиц — атомов и молекул. Состояние вещества определяется расстоянием между частицами и силой их взаимного притяжения.","table":{"head":["Признак","Твёрдое","Жидкое","Газ"],"rows":[["Форма","Постоянная","Принимает форму сосуда","Принимает форму сосуда"],["Объём","Постоянный","Постоянный","Заполняет весь сосуд"],["Расстояние между частицами","Очень малое","Малое","Очень большое"],["Движение частиц","Колеблются на месте","Скользят друг относительно друга","Быстро и хаотично летают"],["Сжимаемость","Почти не сжимается","Почти не сжимается","Легко сжимается"]]}},{"h":"Переходы между состояниями","p":"При нагревании частицы движутся быстрее, и вещество может перейти из одного состояния в другое; при охлаждении идёт обратный процесс. При таких переходах само вещество не меняется — меняется только его состояние.","items":["Плавление: твёрдое → жидкое, например таяние льда","Испарение и кипение: жидкое → газ","Конденсация: газ → жидкое, например капли на холодном стекле","Отвердевание (замерзание): жидкое → твёрдое","Возгонка (сублимация): твёрдое → газ, минуя жидкое состояние; например кристаллы иода или «сухой лёд»"],"visual":{"type":"diagram","kind":"states"}},{"h":"Примеры из жизни","p":"Когда сохнет выстиранное бельё, вода из него испаряется. Зимой на оконном стекле появляется иней: водяной пар из воздуха сразу переходит в твёрдое состояние. В баллонах со сжиженным газом газ хранится в жидком виде под большим давлением, ведь газ можно сжать до гораздо меньшего объёма."},{"h":"Запомните","items":["Вещество может быть твёрдым, жидким или газообразным","Твёрдое тело сохраняет форму и объём, жидкость — только объём, газ — ни то, ни другое","В газе частицы дальше всего друг от друга, поэтому газы легко сжимаются","При смене агрегатного состояния новое вещество не образуется"]}],"quiz":[{"q":"В каком состоянии вещество сохраняет и форму, и объём?","options":["Газ","Жидкость","Твёрдое","Ни в каком"],"correct":2,"explain":"В твёрдом теле частицы занимают постоянные места, поэтому сохраняются и форма, и объём."},{"q":"Что из перечисленного сжимается легче всего?","options":["Железо","Вода","Воздух","Лёд"],"correct":2,"explain":"Между частицами газа много пустого пространства, поэтому воздух легко сжимается."},{"q":"Как называется таяние льда?","options":["Конденсация","Плавление","Возгонка","Отвердевание"],"correct":1,"explain":"Переход из твёрдого состояния в жидкое называется плавлением."}]}},{"id":"t09","num":9,"icon":"🔣","uz":{"title":"Kimyoviy formula. Valentlik. Indekslar","intro":"Kimyogarlar moddalarni uzun so'zlar bilan emas, qisqa formulalar bilan yozadi. H₂O yozuvi bir qarashda suv nimadan va qanday nisbatda tuzilganini aytib beradi. Bu darsda formulani «o'qish» va uni o'zingiz tuzishni o'rganasiz.","blocks":[{"h":"Kimyoviy formula nima?","p":"Kimyoviy formula — moddaning tarkibini element belgilari va raqamlar yordamida qisqa yozish usuli. Formula uchta narsani bildiradi: modda qaysi elementlardan iborat (sifat tarkibi), bitta molekulada har bir elementdan nechta atom bor (miqdor tarkibi) va shu moddaning bitta molekulasi.","items":["CO₂ — uglerod va kisloroddan tuzilgan","Bitta molekulada 1 ta C va 2 ta O atomi bor","CO₂ yozuvi karbonat angidridning bitta molekulasini bildiradi"],"visual":{"type":"molecule3d","mol":"CO2"}},{"h":"Indeks va koeffitsient","p":"Element belgisining pastki o'ng tomonidagi kichik raqam indeks deyiladi: u bitta molekuladagi shu element atomlari sonini ko'rsatadi. Formula oldidagi katta raqam koeffitsient deyiladi va nechta molekula yoki atom olinganini bildiradi. Indeks yoki koeffitsient 1 ga teng bo'lsa, u yozilmaydi.","items":["3H — uchta alohida vodorod atomi","H₂ — ikki atomli bitta vodorod molekulasi","4NH₃ — to'rtta ammiak molekulasi, har birida 1 ta N va 3 ta H atomi","2CO₂ — jami 2 ta C va 4 ta O atomi"]},{"h":"Valentlik","p":"Valentlik — element atomining boshqa atomlarning ma'lum sonini biriktirib olish xususiyati. Vodorod atomi hech qachon bittadan ortiq atomni biriktirmaydi, shuning uchun uning valentligi I deb olinadi va o'lchov birligi bo'lib xizmat qiladi. Ammiakda azot uchta vodorodni biriktirgani uchun III valentli. Valentlik rim raqami bilan yoziladi, masalan, Fe(III).","items":["Doimiy valentlik: H, Na, K — I; O, Ca, Mg, Zn — II; Al — III","O'zgaruvchan valentlik: Fe — II yoki III (FeO, Fe₂O₃)","Cu — I yoki II (Cu₂O, CuO)","S — II, IV yoki VI (H₂S, SO₂, SO₃)"],"visual":{"type":"molecule3d","mol":"NH3"}},{"h":"Valentlik bo'yicha formula tuzish","p":"Ikki elementdan tuzilgan (binar) birikmada bir element valentligining atomlar soniga ko'paytmasi ikkinchi elementnikiga teng bo'ladi. Bu qoida yordamida formulani tuzish mumkin.","formula":"a · x = b · y   (a, b — valentliklar; x, y — indekslar)","items":["Masala: alyuminiy (III) va kislorod (II) birikmasining formulasini tuzing","1) Valentliklarning eng kichik umumiy karralisi: EKUK(3; 2) = 6","2) Al indeksi: 6 : 3 = 2; O indeksi: 6 : 2 = 3","3) Formula: Al₂O₃","Tekshiruv: III · 2 = II · 3 = 6"]},{"h":"Formuladan valentlikni topish","p":"Bir elementning valentligi ma'lum bo'lsa, ikkinchisini formuladan hisoblab topish mumkin. Grafik formulada har bir valentlik bitta chiziqcha bilan ko'rsatiladi: H–O–H, O=C=O.","items":["Masala: N₂O₅ dagi azot valentligini toping","1) Kislorod: II · 5 = 10","2) Bu 10 birlik 2 ta azot atomiga taqsimlanadi: 10 : 2 = 5","Javob: azot V valentli"]},{"h":"Esda tuting","items":["Indeks — molekuladagi atomlar soni, koeffitsient — molekulalar yoki atomlar soni","Vodorodning valentligi doimo I, kislorodniki odatda II","Binar birikmada: valentlik × indeks ikkala element uchun teng","Ba'zi elementlar o'zgaruvchan valentlikka ega: Fe, Cu, S"]}],"quiz":[{"q":"3H₂O yozuvidagi 3 raqami nima?","options":["Indeks","Koeffitsient","Valentlik","Atom massasi"],"correct":1,"explain":"Formula oldidagi raqam koeffitsient bo'lib, molekulalar sonini ko'rsatadi."},{"q":"SO₃ da oltingugurtning valentligi nechaga teng?","options":["II","IV","VI","III"],"correct":2,"explain":"Kislorod: II · 3 = 6, bu bitta S atomiga to'g'ri keladi, demak S — VI valentli."},{"q":"Kalsiy (II) va xlor (I) birikmasining to'g'ri formulasi qaysi?","options":["CaCl₂","CaCl","Ca₂Cl","CaCl₃"],"correct":0,"explain":"II · 1 = I · 2, shuning uchun bitta Ca atomiga ikkita Cl atomi to'g'ri keladi."}]},"en":{"title":"Chemical formula. Valence. Subscripts","intro":"Chemists write substances not with long words but with short formulas. The record H₂O tells you at a glance what water is made of and in what ratio. In this lesson you will learn to read a formula and to build one yourself.","blocks":[{"h":"What is a chemical formula?","p":"A chemical formula is a short way of writing the composition of a substance using element symbols and numbers. A formula tells us three things: which elements the substance contains (qualitative composition), how many atoms of each element are in one molecule (quantitative composition), and it stands for one molecule of the substance.","items":["CO₂ is made of carbon and oxygen","One molecule contains 1 C atom and 2 O atoms","The record CO₂ stands for one molecule of carbon dioxide"],"visual":{"type":"molecule3d","mol":"CO2"}},{"h":"Subscripts and coefficients","p":"The small number at the lower right of an element symbol is called a subscript (index): it shows how many atoms of that element are in one molecule. The large number in front of a formula is called a coefficient and shows how many molecules or atoms are taken. A subscript or coefficient equal to 1 is not written.","items":["3H — three separate hydrogen atoms","H₂ — one diatomic hydrogen molecule","4NH₃ — four ammonia molecules, each with 1 N atom and 3 H atoms","2CO₂ — 2 C atoms and 4 O atoms in total"]},{"h":"Valence","p":"Valence is the ability of an atom of an element to bond with a definite number of other atoms. A hydrogen atom never bonds with more than one atom, so its valence is taken as I and serves as the unit of measurement. In ammonia nitrogen holds three hydrogen atoms, so it has valence III. Valence is written with Roman numerals, for example Fe(III).","items":["Constant valence: H, Na, K — I; O, Ca, Mg, Zn — II; Al — III","Variable valence: Fe — II or III (FeO, Fe₂O₃)","Cu — I or II (Cu₂O, CuO)","S — II, IV or VI (H₂S, SO₂, SO₃)"],"visual":{"type":"molecule3d","mol":"NH3"}},{"h":"Writing a formula from valences","p":"In a compound of two elements (a binary compound), the valence of one element multiplied by its number of atoms equals the same product for the other element. This rule lets us build the formula.","formula":"a · x = b · y   (a, b — valences; x, y — subscripts)","items":["Problem: write the formula of the compound of aluminium (III) and oxygen (II)","1) Least common multiple of the valences: LCM(3, 2) = 6","2) Subscript of Al: 6 ÷ 3 = 2; subscript of O: 6 ÷ 2 = 3","3) Formula: Al₂O₃","Check: III · 2 = II · 3 = 6"]},{"h":"Finding valence from a formula","p":"If the valence of one element is known, the valence of the other can be calculated from the formula. In a structural (graphic) formula each unit of valence is shown as one dash: H–O–H, O=C=O.","items":["Problem: find the valence of nitrogen in N₂O₅","1) Oxygen: II · 5 = 10","2) These 10 units are shared by 2 nitrogen atoms: 10 ÷ 2 = 5","Answer: nitrogen has valence V"]},{"h":"Remember","items":["A subscript is the number of atoms in a molecule; a coefficient is the number of molecules or atoms","Hydrogen always has valence I, oxygen usually II","In a binary compound valence × subscript is the same for both elements","Some elements have variable valence: Fe, Cu, S"]}],"quiz":[{"q":"What is the number 3 in 3H₂O?","options":["A subscript","A coefficient","A valence","An atomic mass"],"correct":1,"explain":"A number in front of a formula is a coefficient and shows the number of molecules."},{"q":"What is the valence of sulfur in SO₃?","options":["II","IV","VI","III"],"correct":2,"explain":"Oxygen gives II · 3 = 6 for a single S atom, so sulfur has valence VI."},{"q":"Which is the correct formula of the compound of calcium (II) and chlorine (I)?","options":["CaCl₂","CaCl","Ca₂Cl","CaCl₃"],"correct":0,"explain":"II · 1 = I · 2, so one Ca atom combines with two Cl atoms."}]},"ru":{"title":"Химическая формула. Валентность. Индексы","intro":"Химики записывают вещества не длинными словами, а короткими формулами. Запись H₂O сразу говорит, из чего состоит вода и в каком соотношении. На этом уроке вы научитесь «читать» формулу и составлять её самостоятельно.","blocks":[{"h":"Что такое химическая формула?","p":"Химическая формула — краткая запись состава вещества с помощью символов элементов и чисел. Формула сообщает три вещи: из каких элементов состоит вещество (качественный состав), сколько атомов каждого элемента входит в одну молекулу (количественный состав), и обозначает одну молекулу этого вещества.","items":["CO₂ состоит из углерода и кислорода","В одной молекуле 1 атом C и 2 атома O","Запись CO₂ обозначает одну молекулу углекислого газа"],"visual":{"type":"molecule3d","mol":"CO2"}},{"h":"Индекс и коэффициент","p":"Маленькая цифра справа внизу от символа элемента называется индексом: она показывает число атомов этого элемента в одной молекуле. Большая цифра перед формулой называется коэффициентом и показывает, сколько взято молекул или атомов. Индекс или коэффициент, равный 1, не пишется.","items":["3H — три отдельных атома водорода","H₂ — одна двухатомная молекула водорода","4NH₃ — четыре молекулы аммиака, в каждой 1 атом N и 3 атома H","2CO₂ — всего 2 атома C и 4 атома O"]},{"h":"Валентность","p":"Валентность — способность атома элемента присоединять определённое число других атомов. Атом водорода никогда не присоединяет больше одного атома, поэтому его валентность принята за I и служит единицей измерения. В аммиаке азот удерживает три атома водорода, значит, он трёхвалентен. Валентность обозначают римскими цифрами, например Fe(III).","items":["Постоянная валентность: H, Na, K — I; O, Ca, Mg, Zn — II; Al — III","Переменная валентность: Fe — II или III (FeO, Fe₂O₃)","Cu — I или II (Cu₂O, CuO)","S — II, IV или VI (H₂S, SO₂, SO₃)"],"visual":{"type":"molecule3d","mol":"NH3"}},{"h":"Составление формулы по валентности","p":"В соединении из двух элементов (бинарном) произведение валентности одного элемента на число его атомов равно такому же произведению для второго элемента. По этому правилу можно составить формулу.","formula":"a · x = b · y   (a, b — валентности; x, y — индексы)","items":["Задача: составьте формулу соединения алюминия (III) с кислородом (II)","1) Наименьшее общее кратное валентностей: НОК(3; 2) = 6","2) Индекс Al: 6 : 3 = 2; индекс O: 6 : 2 = 3","3) Формула: Al₂O₃","Проверка: III · 2 = II · 3 = 6"]},{"h":"Определение валентности по формуле","p":"Если известна валентность одного элемента, валентность другого можно вычислить по формуле. В графической формуле каждая единица валентности изображается одной чёрточкой: H–O–H, O=C=O.","items":["Задача: определите валентность азота в N₂O₅","1) Кислород: II · 5 = 10","2) Эти 10 единиц делятся на 2 атома азота: 10 : 2 = 5","Ответ: азот пятивалентен (V)"]},{"h":"Запомните","items":["Индекс — число атомов в молекуле, коэффициент — число молекул или атомов","Водород всегда одновалентен, кислород обычно двухвалентен","В бинарном соединении произведение валентности на индекс одинаково для обоих элементов","У некоторых элементов валентность переменная: Fe, Cu, S"]}],"quiz":[{"q":"Что означает цифра 3 в записи 3H₂O?","options":["Индекс","Коэффициент","Валентность","Атомная масса"],"correct":1,"explain":"Число перед формулой — коэффициент, он показывает число молекул."},{"q":"Чему равна валентность серы в SO₃?","options":["II","IV","VI","III"],"correct":2,"explain":"Кислород даёт II · 3 = 6 на один атом S, значит, сера шестивалентна."},{"q":"Какова правильная формула соединения кальция (II) с хлором (I)?","options":["CaCl₂","CaCl","Ca₂Cl","CaCl₃"],"correct":0,"explain":"II · 1 = I · 2, поэтому на один атом Ca приходится два атома Cl."}]}},{"id":"t10","num":10,"icon":"🔬","uz":{"title":"Molekulalar o'lchami va massasi. Mol va molar massa","intro":"Bir tomchi suvda shunchalik ko'p molekula borki, ularni sanash uchun butun insoniyatga millionlab yillar kerak bo'lardi. Kimyogarlar bu muammoni oddiy yo'l bilan hal qilgan: zarrachalarni katta «to'plamlar» — mollar bilan sanashadi. Bu dars kimyodagi barcha hisoblarning asosidir.","blocks":[{"h":"Molekulalar qanchalik kichik?","p":"Ko'pchilik molekulalarning o'lchami nanometrning ulushlaridan bir necha nanometrgacha boradi (1 nm = 10⁻⁹ m). Bitta suv molekulasining massasi taxminan 3·10⁻²³ g ga teng. Bunday kichik sonlar bilan hisoblash noqulay, shuning uchun kimyoda nisbiy massalardan foydalaniladi."},{"h":"Nisbiy molekular massa (Mr)","p":"Nisbiy molekular massa molekula massasi uglerod-12 atomi massasining 1/12 qismidan necha marta katta ekanini ko'rsatadi. Bu birliksiz son bo'lib, molekuladagi barcha atomlarning nisbiy atom massalari yig'indisiga teng. Molekulaning haqiqiy (absolut) massasini topish uchun Mr ni 1,66·10⁻²⁴ g ga ko'paytirish kifoya.","formula":"Mr = Ar(1-element) · x + Ar(2-element) · y + ...","items":["Mr(CO₂) = 12 + 2 · 16 = 44","Mr(H₂SO₄) = 2 · 1 + 32 + 4 · 16 = 98","Mr(CaCO₃) = 40 + 12 + 3 · 16 = 100","Absolut massa: m(CO₂) = 44 · 1,66·10⁻²⁴ g ≈ 7,3·10⁻²³ g"],"visual":{"type":"calc","kind":"molar"}},{"h":"Mol — modda miqdori birligi","p":"Tuxum o'nlab, qog'oz esa pachkalab sanaladi. Kimyoda ham zarrachalar to'plam bilan sanaladi va bu to'plam mol deb ataladi. 1 mol — 12 g uglerod-12 da nechta atom bo'lsa, shuncha zarracha (atom, molekula yoki ion) tutgan modda miqdori. Modda miqdori n harfi bilan belgilanadi va mol larda o'lchanadi."},{"h":"Avogadro doimiysi","p":"Har qanday moddaning 1 molida bir xil son — 6,02·10²³ ta zarracha bo'ladi. Bu son Avogadro doimiysi deyiladi va N_A bilan belgilanadi.","formula":"N = n · N_A,   N_A = 6,02·10²³ mol⁻¹","items":["1 mol suvda 6,02·10²³ ta H₂O molekulasi bor","0,5 mol temirda 3,01·10²³ ta Fe atomi bor","2 mol kislorodda 1,204·10²⁴ ta O₂ molekulasi bor"]},{"h":"Molar massa","p":"Molar massa M — 1 mol moddaning massasi, u g/mol da o'lchanadi. Uning son qiymati nisbiy molekular massaga teng: Mr(H₂O) = 18 bo'lsa, M(H₂O) = 18 g/mol.","formula":"M = m / n,   n = m / M","items":["Masala: 88 g CO₂ da necha mol va nechta molekula bor?","1) M(CO₂) = 44 g/mol","2) n = 88 : 44 = 2 mol","3) N = 2 · 6,02·10²³ = 1,204·10²⁴ ta molekula"],"visual":{"type":"calc","kind":"mole"}},{"h":"Esda tuting","items":["Mr — molekuladagi atomlar nisbiy massalarining yig'indisi","1 mol istalgan moddada 6,02·10²³ ta zarracha bor","Molar massaning son qiymati Mr ga teng, birligi g/mol","Asosiy bog'lanishlar: n = m / M va N = n · N_A"]}],"quiz":[{"q":"Mr(NaOH) nechaga teng?","options":["39","40","41","24"],"correct":1,"explain":"23 + 16 + 1 = 40."},{"q":"1 mol istalgan moddada nechta zarracha bor?","options":["6,02·10²³","22,4","1,66·10⁻²⁴","12"],"correct":0,"explain":"Bu son Avogadro doimiysi deb ataladi."},{"q":"36 g suv necha mol bo'ladi?","options":["1 mol","3 mol","2 mol","0,5 mol"],"correct":2,"explain":"n = 36 : 18 = 2 mol."}]},"en":{"title":"Size and mass of molecules. The mole and molar mass","intro":"A single drop of water contains so many molecules that all of humanity would need millions of years to count them. Chemists solved this problem in a simple way: they count particles in large packs called moles. This lesson is the basis of every calculation in chemistry.","blocks":[{"h":"How small are molecules?","p":"Most molecules are from a fraction of a nanometre to a few nanometres in size (1 nm = 10⁻⁹ m). One water molecule has a mass of about 3×10⁻²³ g. Such tiny numbers are inconvenient to work with, so chemistry uses relative masses."},{"h":"Relative molecular mass (Mr)","p":"Relative molecular mass shows how many times the mass of a molecule is greater than 1/12 of the mass of a carbon-12 atom. It is a number without units and equals the sum of the relative atomic masses of all atoms in the molecule. To find the actual (absolute) mass of a molecule, simply multiply Mr by 1.66×10⁻²⁴ g.","formula":"Mr = Ar(element 1) · x + Ar(element 2) · y + ...","items":["Mr(CO₂) = 12 + 2 · 16 = 44","Mr(H₂SO₄) = 2 · 1 + 32 + 4 · 16 = 98","Mr(CaCO₃) = 40 + 12 + 3 · 16 = 100","Absolute mass: m(CO₂) = 44 × 1.66×10⁻²⁴ g ≈ 7.3×10⁻²³ g"],"visual":{"type":"calc","kind":"molar"}},{"h":"The mole — the unit of amount of substance","p":"Eggs are counted by the dozen and paper by the ream. In chemistry particles are also counted in packs, and this pack is called the mole. 1 mole is the amount of substance that contains as many particles (atoms, molecules or ions) as there are atoms in 12 g of carbon-12. Amount of substance is written as n and measured in moles (mol)."},{"h":"The Avogadro constant","p":"One mole of any substance contains the same number of particles: 6.02×10²³. This number is called the Avogadro constant and is written N_A.","formula":"N = n · N_A,   N_A = 6.02×10²³ mol⁻¹","items":["1 mol of water contains 6.02×10²³ H₂O molecules","0.5 mol of iron contains 3.01×10²³ Fe atoms","2 mol of oxygen contains 1.204×10²⁴ O₂ molecules"]},{"h":"Molar mass","p":"Molar mass M is the mass of 1 mole of a substance, measured in g/mol. Its numerical value equals the relative molecular mass: if Mr(H₂O) = 18, then M(H₂O) = 18 g/mol.","formula":"M = m / n,   n = m / M","items":["Problem: how many moles and how many molecules are in 88 g of CO₂?","1) M(CO₂) = 44 g/mol","2) n = 88 ÷ 44 = 2 mol","3) N = 2 × 6.02×10²³ = 1.204×10²⁴ molecules"],"visual":{"type":"calc","kind":"mole"}},{"h":"Remember","items":["Mr is the sum of the relative masses of the atoms in a molecule","1 mole of any substance contains 6.02×10²³ particles","Molar mass has the same number as Mr, with the unit g/mol","Key relations: n = m / M and N = n · N_A"]}],"quiz":[{"q":"What is Mr(NaOH)?","options":["39","40","41","24"],"correct":1,"explain":"23 + 16 + 1 = 40."},{"q":"How many particles are in 1 mole of any substance?","options":["6.02×10²³","22.4","1.66×10⁻²⁴","12"],"correct":0,"explain":"This number is called the Avogadro constant."},{"q":"How many moles are in 36 g of water?","options":["1 mol","3 mol","2 mol","0.5 mol"],"correct":2,"explain":"n = 36 ÷ 18 = 2 mol."}]},"ru":{"title":"Размер и масса молекул. Моль и молярная масса","intro":"В одной капле воды столько молекул, что всему человечеству пришлось бы считать их миллионы лет. Химики решили эту задачу просто: они считают частицы большими «пачками» — молями. Этот урок — основа всех расчётов в химии.","blocks":[{"h":"Насколько малы молекулы?","p":"Размеры большинства молекул — от долей нанометра до нескольких нанометров (1 нм = 10⁻⁹ м). Масса одной молекулы воды — около 3·10⁻²³ г. С такими крошечными числами неудобно работать, поэтому в химии пользуются относительными массами."},{"h":"Относительная молекулярная масса (Mr)","p":"Относительная молекулярная масса показывает, во сколько раз масса молекулы больше 1/12 массы атома углерода-12. Это безразмерное число, равное сумме относительных атомных масс всех атомов молекулы. Чтобы найти истинную (абсолютную) массу молекулы, достаточно умножить Mr на 1,66·10⁻²⁴ г.","formula":"Mr = Ar(1-го элемента) · x + Ar(2-го элемента) · y + ...","items":["Mr(CO₂) = 12 + 2 · 16 = 44","Mr(H₂SO₄) = 2 · 1 + 32 + 4 · 16 = 98","Mr(CaCO₃) = 40 + 12 + 3 · 16 = 100","Абсолютная масса: m(CO₂) = 44 · 1,66·10⁻²⁴ г ≈ 7,3·10⁻²³ г"],"visual":{"type":"calc","kind":"molar"}},{"h":"Моль — единица количества вещества","p":"Яйца считают десятками, бумагу — пачками. В химии частицы тоже считают «пачками», и такая пачка называется молем. 1 моль — это количество вещества, содержащее столько частиц (атомов, молекул или ионов), сколько атомов в 12 г углерода-12. Количество вещества обозначают буквой n и измеряют в молях."},{"h":"Постоянная Авогадро","p":"В 1 моль любого вещества содержится одно и то же число частиц — 6,02·10²³. Это число называется постоянной Авогадро и обозначается N_A.","formula":"N = n · N_A,   N_A = 6,02·10²³ моль⁻¹","items":["В 1 моль воды 6,02·10²³ молекул H₂O","В 0,5 моль железа 3,01·10²³ атомов Fe","В 2 моль кислорода 1,204·10²⁴ молекул O₂"]},{"h":"Молярная масса","p":"Молярная масса M — это масса 1 моль вещества, она измеряется в г/моль. Численно она равна относительной молекулярной массе: если Mr(H₂O) = 18, то M(H₂O) = 18 г/моль.","formula":"M = m / n,   n = m / M","items":["Задача: сколько моль и сколько молекул в 88 г CO₂?","1) M(CO₂) = 44 г/моль","2) n = 88 : 44 = 2 моль","3) N = 2 · 6,02·10²³ = 1,204·10²⁴ молекул"],"visual":{"type":"calc","kind":"mole"}},{"h":"Запомните","items":["Mr — сумма относительных масс атомов в молекуле","В 1 моль любого вещества 6,02·10²³ частиц","Молярная масса численно равна Mr и измеряется в г/моль","Главные связи: n = m / M и N = n · N_A"]}],"quiz":[{"q":"Чему равна Mr(NaOH)?","options":["39","40","41","24"],"correct":1,"explain":"23 + 16 + 1 = 40."},{"q":"Сколько частиц содержится в 1 моль любого вещества?","options":["6,02·10²³","22,4","1,66·10⁻²⁴","12"],"correct":0,"explain":"Это число называется постоянной Авогадро."},{"q":"Сколько моль составляют 36 г воды?","options":["1 моль","3 моль","2 моль","0,5 моль"],"correct":2,"explain":"n = 36 : 18 = 2 моль."}]}},{"id":"t11","num":11,"icon":"🔥","uz":{"title":"Moddalarning xossalari: fizik va kimyoviy o'zgarishlar","intro":"Qor eriydi, non qizarib pishadi, velosiped zanjiri zanglaydi — atrofimizda hamma narsa o'zgarib turadi. Lekin bu o'zgarishlarning bir qismida modda o'zi bo'lib qoladi, boshqasida esa butunlay yangi modda paydo bo'ladi. Ularni qanday farqlashni o'rganamiz.","blocks":[{"h":"Hodisa nima?","p":"Tabiatdagi har qanday o'zgarish hodisa deyiladi: qorning erishi, choydagi shakarning erib ketishi, gugurtning yonishi. Kimyoda hodisalar ikki katta guruhga bo'linadi: fizik va kimyoviy hodisalar."},{"h":"Fizik hodisalar","p":"Fizik hodisada moddaning shakli, o'lchami, joylashuvi yoki agregat holati o'zgaradi, lekin modda o'zi bo'lib qolaveradi — yangi modda hosil bo'lmaydi.","items":["Shishaning sinishi — bo'laklar baribir shisha","Suvning muzlashi yoki qaynashi","Osh tuzining suvda erishi — suv bug'latilsa, tuz qaytib chiqadi","Simning egilishi, yog'ochning arralanishi"]},{"h":"Kimyoviy hodisalar","p":"Kimyoviy hodisada bir modda yangi xossalarga ega bo'lgan boshqa moddaga aylanadi. Bunday hodisalar kimyoviy reaksiyalar deb ataladi. Masalan, temir kukuni oltingugurt bilan qizdirilsa, na temir, na oltingugurt qoladi — o'rniga yangi xossali qora modda — temir (II) sulfid hosil bo'ladi.","formula":"Fe + S → FeS","items":["Temirning zanglashi","Sutning achishi","Yog'och va tabiiy gazning yonishi","Ovqatning kuyib qorayishi"],"visual":{"type":"reaction","id":"fe_s"}},{"h":"Reaksiya alomatlari","p":"Kimyoviy o'zgarish ro'y berganini quyidagi belgilardan bilish mumkin. Bitta belgi har doim ham ishonchli dalil emas, lekin bir nechtasi birga kuzatilsa, yangi modda hosil bo'lgani aniq.","items":["Rang o'zgarishi","Yangi hid paydo bo'lishi","Gaz pufakchalari ajralishi","Cho'kma tushishi","Issiqlik yoki yorug'lik chiqishi yoki yutilishi"]},{"h":"Fizik va kimyoviy xossalar","p":"Fizik xossalar — moddani o'zgartirmasdan aniqlanadigan belgilar: rangi, hidi, zichligi, suyuqlanish va qaynash harorati. Kimyoviy xossa — moddaning boshqa moddalar bilan qanday ta'sirlashishi, masalan, yonuvchanligi yoki zanglashi. Ko'pincha ikkala hodisa birga kuzatiladi: gaz plitasida qozondagi suv qaynaydi (fizik), plitadagi gaz esa yonadi (kimyoviy)."},{"h":"Esda tuting","items":["Fizik hodisada yangi modda hosil bo'lmaydi","Kimyoviy hodisada (reaksiyada) yangi xossali modda hosil bo'ladi","Reaksiya alomatlari: rang, hid, gaz, cho'kma, issiqlik yoki yorug'lik","Fizik va kimyoviy xossalar birgalikda moddani tavsiflaydi"]}],"quiz":[{"q":"Qaysi biri kimyoviy hodisa?","options":["Muzning erishi","Shishaning sinishi","Temirning zanglashi","Shakarning choyda erishi"],"correct":2,"explain":"Zanglashda temir boshqa modda — zangga aylanadi."},{"q":"Fizik hodisaning asosiy belgisi qaysi?","options":["Yangi modda hosil bo'ladi","Yangi modda hosil bo'lmaydi","Doim gaz ajraladi","Doim cho'kma tushadi"],"correct":1,"explain":"Fizik hodisada modda o'zgarmaydi, faqat uning shakli yoki holati o'zgaradi."},{"q":"Qaysi biri moddaning kimyoviy xossasi?","options":["Yonuvchanligi","Rangi","Zichligi","Qaynash harorati"],"correct":0,"explain":"Yonuvchanlik modda boshqa modda (kislorod) bilan reaksiyaga kirishganda namoyon bo'ladi."}]},"en":{"title":"Properties of substances: physical and chemical changes","intro":"Snow melts, bread turns golden in the oven, a bicycle chain rusts — everything around us keeps changing. In some of these changes the substance stays the same, while in others a completely new substance appears. Let us learn how to tell them apart.","blocks":[{"h":"What is a phenomenon?","p":"Any change in nature is called a phenomenon: snow melting, sugar dissolving in tea, a match burning. In chemistry, phenomena are divided into two large groups: physical and chemical."},{"h":"Physical changes","p":"In a physical change the shape, size, position or state of a substance changes, but the substance itself stays the same — no new substance is formed.","items":["Breaking glass — the pieces are still glass","Water freezing or boiling","Table salt dissolving in water — if the water is evaporated, the salt comes back","Bending a wire, sawing wood"]},{"h":"Chemical changes","p":"In a chemical change one substance turns into another substance with new properties. Such changes are called chemical reactions. For example, when iron powder is heated with sulfur, neither iron nor sulfur remains — instead a new black substance with new properties, iron(II) sulfide, forms.","formula":"Fe + S → FeS","items":["Rusting of iron","Souring of milk","Burning of wood and natural gas","Food blackening when it burns"],"visual":{"type":"reaction","id":"fe_s"}},{"h":"Signs of a reaction","p":"You can tell that a chemical change has taken place from the signs below. A single sign is not always reliable proof, but when several appear together, a new substance has clearly formed.","items":["A change of colour","A new smell","Gas bubbles given off","A precipitate forming","Heat or light given off or absorbed"]},{"h":"Physical and chemical properties","p":"Physical properties are features measured without changing the substance: colour, smell, density, melting and boiling points. A chemical property describes how a substance reacts with other substances, for example whether it burns or rusts. Often both kinds of change happen together: on a gas stove the water in a pot boils (physical) while the gas burns (chemical)."},{"h":"Remember","items":["In a physical change no new substance is formed","In a chemical change (reaction) a substance with new properties is formed","Signs of a reaction: colour, smell, gas, precipitate, heat or light","Physical and chemical properties together describe a substance"]}],"quiz":[{"q":"Which of these is a chemical change?","options":["Ice melting","Glass breaking","Iron rusting","Sugar dissolving in tea"],"correct":2,"explain":"When iron rusts it turns into a different substance — rust."},{"q":"What is the main sign of a physical change?","options":["A new substance forms","No new substance forms","A gas is always released","A precipitate always forms"],"correct":1,"explain":"In a physical change the substance stays the same; only its shape or state changes."},{"q":"Which of these is a chemical property of a substance?","options":["Flammability","Colour","Density","Boiling point"],"correct":0,"explain":"Flammability shows up only when the substance reacts with another substance (oxygen)."}]},"ru":{"title":"Свойства веществ: физические и химические явления","intro":"Тает снег, румянится хлеб в духовке, ржавеет велосипедная цепь — всё вокруг постоянно меняется. Но в одних изменениях вещество остаётся прежним, а в других появляется совершенно новое вещество. Научимся их различать.","blocks":[{"h":"Что такое явление?","p":"Любое изменение в природе называется явлением: таяние снега, растворение сахара в чае, горение спички. В химии явления делят на две большие группы: физические и химические."},{"h":"Физические явления","p":"При физическом явлении меняются форма, размер, положение или агрегатное состояние вещества, но само вещество остаётся прежним — новое вещество не образуется.","items":["Разбилось стекло — осколки всё равно стекло","Замерзание или кипение воды","Растворение поваренной соли в воде — если воду выпарить, соль вернётся","Сгибание проволоки, распиливание дерева"]},{"h":"Химические явления","p":"При химическом явлении одно вещество превращается в другое, с новыми свойствами. Такие явления называют химическими реакциями. Например, если нагреть железный порошок с серой, не останется ни железа, ни серы — образуется новое чёрное вещество с иными свойствами — сульфид железа(II).","formula":"Fe + S → FeS","items":["Ржавление железа","Скисание молока","Горение дерева и природного газа","Подгорание пищи"],"visual":{"type":"reaction","id":"fe_s"}},{"h":"Признаки реакции","p":"О том, что произошло химическое превращение, можно судить по признакам ниже. Один признак не всегда надёжное доказательство, но если наблюдаются сразу несколько, новое вещество точно образовалось.","items":["Изменение цвета","Появление нового запаха","Выделение пузырьков газа","Выпадение осадка","Выделение или поглощение теплоты или света"]},{"h":"Физические и химические свойства","p":"Физические свойства — признаки, которые определяют, не изменяя вещество: цвет, запах, плотность, температуры плавления и кипения. Химическое свойство описывает, как вещество взаимодействует с другими веществами, например горит ли оно или ржавеет. Часто оба явления идут вместе: на газовой плите вода в кастрюле кипит (физическое), а газ горит (химическое)."},{"h":"Запомните","items":["При физическом явлении новое вещество не образуется","При химическом явлении (реакции) образуется вещество с новыми свойствами","Признаки реакции: цвет, запах, газ, осадок, теплота или свет","Физические и химические свойства вместе характеризуют вещество"]}],"quiz":[{"q":"Какое из явлений химическое?","options":["Таяние льда","Разбивание стекла","Ржавление железа","Растворение сахара в чае"],"correct":2,"explain":"При ржавлении железо превращается в другое вещество — ржавчину."},{"q":"Каков главный признак физического явления?","options":["Образуется новое вещество","Новое вещество не образуется","Всегда выделяется газ","Всегда выпадает осадок"],"correct":1,"explain":"При физическом явлении вещество не меняется, меняется лишь его форма или состояние."},{"q":"Что из перечисленного — химическое свойство вещества?","options":["Горючесть","Цвет","Плотность","Температура кипения"],"correct":0,"explain":"Горючесть проявляется, только когда вещество реагирует с другим веществом (кислородом)."}]}},{"id":"t12","num":12,"icon":"⚗️","uz":{"title":"Kimyoviy reaksiyalarning sodir bo'lishi. Kimyoviy tenglamalar. Koeffitsientlar","intro":"Gugurt qutisida yonmasdan yotadi, lekin qutiga ishqalansa, darhol alangalanadi. Demak, reaksiya boshlanishi uchun ma'lum shartlar kerak. Bu darsda o'sha shartlarni va reaksiyani formulalar tilida — tenglama bilan yozishni o'rganamiz.","blocks":[{"h":"Reaksiya qachon boshlanadi?","p":"Moddalarning bir joyda turishi har doim ham reaksiya uchun yetarli emas. Reaksiya boshlanishi va tez borishi uchun quyidagi shartlar muhim. Masalan, yog'och g'o'la sekin yonadi, mayda qipiq esa lov etib yonib ketadi.","items":["Zarrachalar to'qnashishi kerak, ya'ni moddalar bir-biriga tegib turishi lozim","Qattiq moddalarni maydalash yoki kukun qilish tegish yuzasini oshiradi","Moddalarni eritma holida olish reaksiyani tezlashtiradi","Ko'p reaksiyalar uchun qizdirish kerak: yonish kabi ba'zilarini faqat boshlab berish kifoya, ba'zilari esa to'xtovsiz qizdirishni talab qiladi"]},{"h":"Kimyoviy tenglama","p":"Kimyoviy tenglama — reaksiyaning kimyoviy formulalar yordamidagi qisqa yozuvi. Chap tomonga reaksiyaga kirishuvchi moddalar (reagentlar), o'ng tomonga hosil bo'ladigan moddalar (mahsulotlar) yoziladi. Ular orasiga strelka yoki tenglik belgisi qo'yiladi, bir tomondagi moddalar esa «+» bilan ajratiladi.","formula":"reagentlar → mahsulotlar"},{"h":"Nega koeffitsient kerak?","p":"Reaksiyada atomlar yo'qolmaydi va yangidan paydo bo'lmaydi — ular faqat qayta guruhlanadi. Shuning uchun har bir element atomlari soni tenglamaning ikkala tomonida teng bo'lishi kerak. Tenglashtirish uchun formulalar oldiga koeffitsientlar qo'yiladi. Indekslarni o'zgartirish mumkin emas, chunki bu butunlay boshqa moddani bildiradi.","formula":"2H₂ + O₂ → 2H₂O","visual":{"type":"reaction","id":"h2_o2"}},{"h":"Bosqichma-bosqich tenglashtirish","p":"Alyuminiyning kislorodda yonishini tenglashtiramiz.","items":["1) Sxema: Al + O₂ → Al₂O₃","2) Kislorod: chapda 2 ta, o'ngda 3 ta. EKUK(2; 3) = 6, shuning uchun O₂ oldiga 3, Al₂O₃ oldiga 2 qo'yamiz","3) Alyuminiy: o'ngda 2 · 2 = 4 ta, chapda 1 ta — Al oldiga 4 qo'yamiz","4) Natija: 4Al + 3O₂ → 2Al₂O₃","Tekshiruv: Al 4 = 4, O 6 = 6"]},{"h":"Yana bir misol: metanning yonishi","p":"Uydagi gaz plitasida yonadigan tabiiy gazning asosiy qismi metandir. U yonganda karbonat angidrid va suv hosil bo'ladi. Ikkala tomonda ham 1 ta C, 4 ta H va 4 ta O atomi bor.","formula":"CH₄ + 2O₂ → CO₂ + 2H₂O","visual":{"type":"reaction","id":"ch4_o2"}},{"h":"Esda tuting","items":["Reaksiya uchun zarrachalar to'qnashishi, ko'pincha qizdirish ham kerak","Tenglamada chapda reagentlar, o'ngda mahsulotlar yoziladi","Koeffitsientlar atomlar sonini tenglashtiradi, indekslar esa o'zgarmaydi","Tenglashtirilgan tenglamada har bir element atomlari soni ikkala tomonda teng"]}],"quiz":[{"q":"Tenglamadagi koeffitsient nimani ko'rsatadi?","options":["Molekuladagi atomlar sonini","Molekulalar yoki atomlar sonini","Element valentligini","Moddaning massasini"],"correct":1,"explain":"Formula oldidagi koeffitsient olinayotgan molekulalar yoki atomlar sonini bildiradi."},{"q":"Kalsiyning kislorodda yonish tenglamasi qaysi biri to'g'ri tenglashtirilgan?","options":["Ca + O₂ → CaO₂","Ca + O₂ → 2CaO","2Ca + O₂ → 2CaO","Ca + O → CaO"],"correct":2,"explain":"Chapda va o'ngda 2 ta Ca va 2 ta O atomi bor."},{"q":"Reaksiyani tezlashtirish uchun qattiq moddani nima qilish kerak?","options":["Katta bo'lak holida olish","Maydalab kukun qilish","Sovitish","Idishni yopib qo'yish"],"correct":1,"explain":"Maydalanganda moddalarning tegish yuzasi ortadi va zarrachalar tez-tez to'qnashadi."}]},"en":{"title":"How chemical reactions happen. Chemical equations. Coefficients","intro":"A match can lie in its box without burning, yet it bursts into flame as soon as it is struck. So a reaction needs certain conditions to start. In this lesson we look at those conditions and learn to write a reaction in the language of formulas — as an equation.","blocks":[{"h":"When does a reaction start?","p":"Simply placing substances together is not always enough for a reaction. The conditions below matter for a reaction to start and run quickly. For example, a log burns slowly, while fine sawdust flares up at once.","items":["Particles must collide, so the substances have to be in contact","Grinding a solid or turning it into powder increases the contact surface","Using substances as solutions speeds up the reaction","Many reactions need heating: some, like burning, only need to be started, while others need constant heating"]},{"h":"The chemical equation","p":"A chemical equation is a short record of a reaction written with chemical formulas. The reacting substances (reactants) are written on the left and the substances formed (products) on the right. An arrow or an equals sign is placed between them, and substances on the same side are separated by «+».","formula":"reactants → products"},{"h":"Why do we need coefficients?","p":"In a reaction atoms do not disappear or appear from nowhere — they are only regrouped. So the number of atoms of each element must be the same on both sides of the equation. To balance it, coefficients are placed in front of the formulas. Subscripts must never be changed, because that would describe a completely different substance.","formula":"2H₂ + O₂ → 2H₂O","visual":{"type":"reaction","id":"h2_o2"}},{"h":"Balancing step by step","p":"Let us balance the burning of aluminium in oxygen.","items":["1) Scheme: Al + O₂ → Al₂O₃","2) Oxygen: 2 on the left, 3 on the right. LCM(2, 3) = 6, so put 3 in front of O₂ and 2 in front of Al₂O₃","3) Aluminium: 2 × 2 = 4 on the right, 1 on the left — put 4 in front of Al","4) Result: 4Al + 3O₂ → 2Al₂O₃","Check: Al 4 = 4, O 6 = 6"]},{"h":"One more example: burning methane","p":"Methane is the main part of the natural gas that burns on a kitchen stove. When it burns, carbon dioxide and water are formed. Both sides contain 1 C atom, 4 H atoms and 4 O atoms.","formula":"CH₄ + 2O₂ → CO₂ + 2H₂O","visual":{"type":"reaction","id":"ch4_o2"}},{"h":"Remember","items":["A reaction needs colliding particles and often heating","Reactants are written on the left of the equation, products on the right","Coefficients balance the numbers of atoms; subscripts stay unchanged","In a balanced equation each element has the same number of atoms on both sides"]}],"quiz":[{"q":"What does a coefficient in an equation show?","options":["The number of atoms in a molecule","The number of molecules or atoms","The valence of an element","The mass of a substance"],"correct":1,"explain":"A coefficient in front of a formula gives the number of molecules or atoms taken."},{"q":"Which equation for calcium burning in oxygen is correctly balanced?","options":["Ca + O₂ → CaO₂","Ca + O₂ → 2CaO","2Ca + O₂ → 2CaO","Ca + O → CaO"],"correct":2,"explain":"Both sides have 2 Ca atoms and 2 O atoms."},{"q":"What should be done to a solid to speed up its reaction?","options":["Use it as one large lump","Grind it into powder","Cool it","Close the vessel"],"correct":1,"explain":"Grinding increases the contact surface, so particles collide more often."}]},"ru":{"title":"Протекание химических реакций. Химические уравнения. Коэффициенты","intro":"Спичка может лежать в коробке и не гореть, но вспыхивает, как только ею чиркнут. Значит, для начала реакции нужны определённые условия. На этом уроке разберём эти условия и научимся записывать реакцию на языке формул — уравнением.","blocks":[{"h":"Когда начинается реакция?","p":"Того, что вещества находятся рядом, не всегда достаточно для реакции. Чтобы реакция началась и шла быстро, важны условия ниже. Например, полено горит медленно, а мелкие опилки вспыхивают мгновенно.","items":["Частицы должны сталкиваться, то есть вещества должны соприкасаться","Измельчение твёрдого вещества в порошок увеличивает поверхность соприкосновения","Использование растворов ускоряет реакцию","Многим реакциям нужно нагревание: одни, как горение, достаточно лишь начать, другие требуют постоянного нагревания"]},{"h":"Химическое уравнение","p":"Химическое уравнение — краткая запись реакции с помощью химических формул. Слева пишут вступающие в реакцию вещества (реагенты), справа — образующиеся вещества (продукты). Между ними ставят стрелку или знак равенства, а вещества одной стороны разделяют знаком «+».","formula":"реагенты → продукты"},{"h":"Зачем нужны коэффициенты?","p":"В реакции атомы не исчезают и не появляются из ничего — они лишь перегруппировываются. Поэтому число атомов каждого элемента в обеих частях уравнения должно быть одинаковым. Для уравнивания перед формулами ставят коэффициенты. Индексы менять нельзя: это означало бы совсем другое вещество.","formula":"2H₂ + O₂ → 2H₂O","visual":{"type":"reaction","id":"h2_o2"}},{"h":"Уравниваем по шагам","p":"Уравняем горение алюминия в кислороде.","items":["1) Схема: Al + O₂ → Al₂O₃","2) Кислород: слева 2, справа 3. НОК(2; 3) = 6, поэтому перед O₂ ставим 3, перед Al₂O₃ — 2","3) Алюминий: справа 2 · 2 = 4, слева 1 — перед Al ставим 4","4) Итог: 4Al + 3O₂ → 2Al₂O₃","Проверка: Al 4 = 4, O 6 = 6"]},{"h":"Ещё пример: горение метана","p":"Метан — основная часть природного газа, который горит на кухонной плите. При его горении образуются углекислый газ и вода. В обеих частях по 1 атому C, 4 атома H и 4 атома O.","formula":"CH₄ + 2O₂ → CO₂ + 2H₂O","visual":{"type":"reaction","id":"ch4_o2"}},{"h":"Запомните","items":["Для реакции нужны столкновения частиц, часто и нагревание","В уравнении слева пишут реагенты, справа — продукты","Коэффициенты уравнивают число атомов, индексы при этом не меняются","В уравненной реакции число атомов каждого элемента слева и справа одинаково"]}],"quiz":[{"q":"Что показывает коэффициент в уравнении?","options":["Число атомов в молекуле","Число молекул или атомов","Валентность элемента","Массу вещества"],"correct":1,"explain":"Коэффициент перед формулой показывает, сколько взято молекул или атомов."},{"q":"Какое уравнение горения кальция в кислороде уравнено верно?","options":["Ca + O₂ → CaO₂","Ca + O₂ → 2CaO","2Ca + O₂ → 2CaO","Ca + O → CaO"],"correct":2,"explain":"В обеих частях по 2 атома Ca и по 2 атома O."},{"q":"Что нужно сделать с твёрдым веществом, чтобы ускорить реакцию?","options":["Взять его одним большим куском","Измельчить в порошок","Охладить","Закрыть сосуд"],"correct":1,"explain":"При измельчении растёт поверхность соприкосновения, и частицы чаще сталкиваются."}]}},{"id":"t13","num":13,"icon":"🧩","uz":{"title":"Tarkibning doimiylik qonuni","intro":"Toshkentda tozalangan suv bilan Antarktida muzidan olingan suvni solishtirsak, ularning tarkibi bir xil bo'lib chiqadi. Bu tasodif emas — bu kimyoning asosiy qonunlaridan biri. Shu qonun tufayli har bir toza modda o'zining aniq formulasiga ega.","blocks":[{"h":"Qonunning mazmuni","p":"Har qanday toza modda qayerda va qanday usulda olinganidan qat'i nazar, bir xil sifat va miqdoriy tarkibga ega bo'ladi. Bu qonunni XVIII asr oxiri — XIX asr boshlarida fransuz kimyogari Jozef Prust ko'plab tajribalar asosida isbotlagan.","formula":"Toza modda tarkibi olinish usuliga bog'liq emas"},{"h":"Suv misolida","p":"Suvni daryodan olib tozalash, vodorodni kislorodda yondirish yoki boshqa reaksiyalar yordamida olish mumkin. Qaysi usul bo'lmasin, toza suvda vodorod va kislorodning massa nisbati doimo 1 : 8 ga teng.","items":["Mr(H₂O) = 2 · 1 + 16 = 18","ω(H) = 2 : 18 ≈ 0,111 yoki 11,1%","ω(O) = 16 : 18 ≈ 0,889 yoki 88,9%","m(H) : m(O) = 2 : 16 = 1 : 8"],"visual":{"type":"molecule3d","mol":"H2O"}},{"h":"Elementning massa ulushi","p":"Elementning massa ulushi ω u moddaning umumiy massasining qancha qismini tashkil etishini ko'rsatadi. U birlik ulushlarida yoki foizlarda ifodalanadi.","formula":"ω(E) = n · Ar(E) / Mr","items":["Masala: CaCO₃ dagi kalsiyning massa ulushini toping","1) Mr(CaCO₃) = 40 + 12 + 3 · 16 = 100","2) ω(Ca) = 1 · 40 : 100 = 0,4","Javob: 40%"]},{"h":"Bir xil elementlar — boshqa modda","p":"Vodorod peroksid H₂O₂ ham vodorod va kisloroddan tuzilgan, ammo miqdoriy tarkibi boshqacha. Shuning uchun u suvdan keskin farq qiladi: u yaralarni zararsizlantirish uchun ishlatiladigan faol modda. Tarkibdagi miqdoriy o'zgarish yangi sifatga olib keladi.","table":{"head":["Modda","ω(H)","ω(O)"],"rows":[["H₂O","11,1%","88,9%"],["H₂O₂","5,9%","94,1%"]]}},{"h":"Karrali nisbatlar","p":"Ikki element bir necha birikma hosil qilishi mumkin. Uglerod kislorod bilan CO va CO₂ hosil qiladi: 12 g uglerodga birinchisida 16 g, ikkinchisida 32 g kislorod to'g'ri keladi. Kislorod massalari 1 : 2 kabi kichik butun sonlar nisbatida — bu qonuniyatni ingliz olimi Jon Dalton aniqlagan."},{"h":"Esda tuting","items":["Toza moddaning tarkibi doimiy va olinish usuliga bog'liq emas","Suvda m(H) : m(O) = 1 : 8, ω(H) ≈ 11,1%","Massa ulushi: ω(E) = n · Ar(E) / Mr","Bir xil elementlardan, lekin boshqa nisbatda tuzilgan moddalar — boshqa moddalar"]}],"quiz":[{"q":"Tarkibning doimiylik qonuniga ko'ra nima to'g'ri?","options":["Toza modda tarkibi olinish usuliga bog'liq emas","Reaksiyada moddalar massasi o'zgarmaydi","Teng hajmdagi gazlarda molekulalar soni teng","Har qanday aralashmaning tarkibi doimiy"],"correct":0,"explain":"Qonun toza moddalar haqida: ular qanday olinmasin, tarkibi bir xil."},{"q":"Suvda vodorod va kislorodning massa nisbati qanday?","options":["1 : 16","2 : 1","1 : 8","1 : 2"],"correct":2,"explain":"2 g vodorodga 16 g kislorod to'g'ri keladi, ya'ni 1 : 8."},{"q":"MgO dagi magniyning massa ulushi qancha? (Ar(Mg) = 24)","options":["40%","60%","24%","50%"],"correct":1,"explain":"Mr(MgO) = 40, ω(Mg) = 24 : 40 = 0,6 yoki 60%."}]},"en":{"title":"The law of constant composition","intro":"If we compare purified water from Tashkent with water from Antarctic ice, their composition turns out to be the same. This is not a coincidence — it is one of the basic laws of chemistry. Thanks to this law every pure substance has its own definite formula.","blocks":[{"h":"What the law says","p":"Every pure substance has the same qualitative and quantitative composition, no matter where or how it was obtained. This law was proved with many experiments by the French chemist Joseph Proust around the turn of the 19th century.","formula":"The composition of a pure substance does not depend on how it was made"},{"h":"The example of water","p":"Water can be taken from a river and purified, made by burning hydrogen in oxygen, or obtained from other reactions. Whatever the method, in pure water the mass ratio of hydrogen to oxygen is always 1 : 8.","items":["Mr(H₂O) = 2 · 1 + 16 = 18","ω(H) = 2 ÷ 18 ≈ 0.111, or 11.1%","ω(O) = 16 ÷ 18 ≈ 0.889, or 88.9%","m(H) : m(O) = 2 : 16 = 1 : 8"],"visual":{"type":"molecule3d","mol":"H2O"}},{"h":"Mass fraction of an element","p":"The mass fraction ω of an element shows what part of the total mass of a substance it makes up. It is expressed as a decimal fraction or as a percentage.","formula":"ω(E) = n · Ar(E) / Mr","items":["Problem: find the mass fraction of calcium in CaCO₃","1) Mr(CaCO₃) = 40 + 12 + 3 · 16 = 100","2) ω(Ca) = 1 · 40 ÷ 100 = 0.4","Answer: 40%"]},{"h":"Same elements — a different substance","p":"Hydrogen peroxide H₂O₂ is also made of hydrogen and oxygen, but its quantitative composition is different. That is why it differs sharply from water: it is an active substance used to disinfect wounds. A change in quantitative composition leads to new properties.","table":{"head":["Substance","ω(H)","ω(O)"],"rows":[["H₂O","11.1%","88.9%"],["H₂O₂","5.9%","94.1%"]]}},{"h":"Multiple proportions","p":"Two elements can form several compounds. Carbon forms CO and CO₂ with oxygen: for 12 g of carbon, the first contains 16 g of oxygen and the second 32 g. The oxygen masses are in a ratio of small whole numbers, 1 : 2 — this regularity was found by the English scientist John Dalton."},{"h":"Remember","items":["The composition of a pure substance is constant and does not depend on how it was made","In water m(H) : m(O) = 1 : 8 and ω(H) ≈ 11.1%","Mass fraction: ω(E) = n · Ar(E) / Mr","Substances made of the same elements in different ratios are different substances"]}],"quiz":[{"q":"According to the law of constant composition, which statement is true?","options":["The composition of a pure substance does not depend on how it was made","The mass of substances does not change in a reaction","Equal volumes of gases contain equal numbers of molecules","Any mixture has a constant composition"],"correct":0,"explain":"The law is about pure substances: however they are made, their composition is the same."},{"q":"What is the mass ratio of hydrogen to oxygen in water?","options":["1 : 16","2 : 1","1 : 8","1 : 2"],"correct":2,"explain":"2 g of hydrogen corresponds to 16 g of oxygen, that is 1 : 8."},{"q":"What is the mass fraction of magnesium in MgO? (Ar(Mg) = 24)","options":["40%","60%","24%","50%"],"correct":1,"explain":"Mr(MgO) = 40, ω(Mg) = 24 ÷ 40 = 0.6, or 60%."}]},"ru":{"title":"Закон постоянства состава","intro":"Если сравнить очищенную воду из Ташкента и воду из антарктического льда, их состав окажется одинаковым. Это не случайность, а один из основных законов химии. Благодаря ему каждое чистое вещество имеет свою определённую формулу.","blocks":[{"h":"Суть закона","p":"Любое чистое вещество имеет одинаковый качественный и количественный состав независимо от того, где и каким способом оно получено. Этот закон на основе множества опытов доказал французский химик Жозеф Пруст на рубеже XVIII и XIX веков.","formula":"Состав чистого вещества не зависит от способа получения"},{"h":"На примере воды","p":"Воду можно взять из реки и очистить, получить сжиганием водорода в кислороде или с помощью других реакций. При любом способе в чистой воде массовое отношение водорода к кислороду всегда равно 1 : 8.","items":["Mr(H₂O) = 2 · 1 + 16 = 18","ω(H) = 2 : 18 ≈ 0,111, или 11,1%","ω(O) = 16 : 18 ≈ 0,889, или 88,9%","m(H) : m(O) = 2 : 16 = 1 : 8"],"visual":{"type":"molecule3d","mol":"H2O"}},{"h":"Массовая доля элемента","p":"Массовая доля элемента ω показывает, какую часть общей массы вещества он составляет. Её выражают в долях единицы или в процентах.","formula":"ω(Э) = n · Ar(Э) / Mr","items":["Задача: найдите массовую долю кальция в CaCO₃","1) Mr(CaCO₃) = 40 + 12 + 3 · 16 = 100","2) ω(Ca) = 1 · 40 : 100 = 0,4","Ответ: 40%"]},{"h":"Те же элементы — другое вещество","p":"Пероксид водорода H₂O₂ тоже состоит из водорода и кислорода, но его количественный состав иной. Поэтому он резко отличается от воды: это активное вещество, которым обеззараживают раны. Изменение количественного состава приводит к новым свойствам.","table":{"head":["Вещество","ω(H)","ω(O)"],"rows":[["H₂O","11,1%","88,9%"],["H₂O₂","5,9%","94,1%"]]}},{"h":"Кратные отношения","p":"Два элемента могут образовывать несколько соединений. Углерод с кислородом образует CO и CO₂: на 12 г углерода в первом приходится 16 г кислорода, во втором — 32 г. Массы кислорода относятся как небольшие целые числа, 1 : 2, — эту закономерность установил английский учёный Джон Дальтон."},{"h":"Запомните","items":["Состав чистого вещества постоянен и не зависит от способа получения","В воде m(H) : m(O) = 1 : 8, ω(H) ≈ 11,1%","Массовая доля: ω(Э) = n · Ar(Э) / Mr","Вещества из тех же элементов, но в другом соотношении, — это другие вещества"]}],"quiz":[{"q":"Какое утверждение соответствует закону постоянства состава?","options":["Состав чистого вещества не зависит от способа получения","Масса веществ в реакции не меняется","В равных объёмах газов одинаковое число молекул","Любая смесь имеет постоянный состав"],"correct":0,"explain":"Закон говорит о чистых веществах: как бы их ни получили, состав одинаков."},{"q":"Каково массовое отношение водорода к кислороду в воде?","options":["1 : 16","2 : 1","1 : 8","1 : 2"],"correct":2,"explain":"На 2 г водорода приходится 16 г кислорода, то есть 1 : 8."},{"q":"Чему равна массовая доля магния в MgO? (Ar(Mg) = 24)","options":["40%","60%","24%","50%"],"correct":1,"explain":"Mr(MgO) = 40, ω(Mg) = 24 : 40 = 0,6, или 60%."}]}},{"id":"t14","num":14,"icon":"⚖️","uz":{"title":"Massaning saqlanish qonuni","intro":"Gulxan yonib bo'lgach, o'rnida bir hovuch kul qoladi. Shunchalik ko'p yog'ochning massasi qayoqqa ketdi? Javob kimyoning eng muhim qonunlaridan birida: reaksiyada massa yo'qolmaydi ham, yo'qdan paydo ham bo'lmaydi.","blocks":[{"h":"Qonun ta'rifi","p":"Reaksiyaga kirishgan moddalarning umumiy massasi reaksiyada hosil bo'lgan moddalarning umumiy massasiga teng. Tarozida buni yaqqol ko'rish mumkin: yopiq idishdagi reaksiyadan oldin va keyin tarozi pallalari muvozanatda qoladi.","formula":"m(reagentlar) = m(mahsulotlar)","visual":{"type":"balance"}},{"h":"Qonun qanday kashf etilgan?","p":"XVIII asrda rus olimi Mixail Lomonosov va fransuz olimi Antuan Lavuaze moddalarni og'zi mahkam berkitilgan idishlarda qizdirib, reaksiyadan oldin va keyin tortib ko'rishgan. Idish yopiq bo'lsa, umumiy massa o'zgarmasligi aniqlandi. Lavuaze bu kuzatishni tabiatning umumiy qonuni sifatida ta'rifladi."},{"h":"Nega massa saqlanadi?","p":"Reaksiyada atomlar yo'qolmaydi, yangidan paydo bo'lmaydi va bir element atomi boshqa element atomiga aylanmaydi. Ular faqat yangi tartibda birikadi. Har bir atomning massasi o'zgarmagani va atomlar soni saqlangani uchun umumiy massa ham o'zgarmaydi. Shu sababli tenglamalarni koeffitsientlar bilan tenglashtiramiz."},{"h":"Hisob bilan tekshiramiz","p":"Magniyning yonish tenglamasi bo'yicha massalarni solishtiramiz (Ar(Mg) = 24).","formula":"2Mg + O₂ → 2MgO","items":["1) Chap tomon: 2 · 24 + 2 · 16 = 48 + 32 = 80","2) O'ng tomon: 2 · (24 + 16) = 80","3) 80 = 80 — massa saqlandi","Masala: 12 g uglerod 32 g kislorodda to'liq yonsa, 12 + 32 = 44 g CO₂ hosil bo'ladi"]},{"h":"Massa «yo'qolgandek» tuyulsa","p":"Ochiq havoda yog'och yonsa, kul yog'ochdan ancha yengil bo'ladi; temir mix zanglasa, aksincha, og'irlashadi. Bu qonunga zid emas. Birinchi holda gazsimon mahsulotlar (karbonat angidrid, suv bug'i) havoga chiqib ketadi, ikkinchisida havodagi kislorod va suv temirga birikadi. Barcha moddalar yopiq idishda tortilsa, massa o'zgarmaydi."},{"h":"Esda tuting","items":["Reagentlar massasi mahsulotlar massasiga teng","Reaksiyada atomlar soni va turi o'zgarmaydi","Qonunni Lomonosov va Lavuaze tajribada isbotlagan","Massa o'zgargandek tuyulsa, gazlar chiqib ketgan yoki havodan birikkan bo'ladi"]}],"quiz":[{"q":"Kimyoviy reaksiyada doimo nima o'zgarmay qoladi?","options":["Moddalarning rangi","Molekulalar soni","Moddalarning umumiy massasi","Agregat holati"],"correct":2,"explain":"Atomlar saqlangani uchun umumiy massa o'zgarmaydi; molekulalar soni esa o'zgarishi mumkin."},{"q":"28 g temir 16 g oltingugurt bilan to'liq reaksiyaga kirishdi. Necha gramm FeS hosil bo'ldi?","options":["44 g","12 g","28 g","16 g"],"correct":0,"explain":"Massaning saqlanish qonuniga ko'ra 28 + 16 = 44 g."},{"q":"Ochiq havoda yongan qog'oz kulining massasi nega kam bo'ladi?","options":["Massa yo'q bo'lib ketadi","Atomlar yo'qoladi","Gazsimon mahsulotlar havoga chiqib ketadi","Yonishda qonun bajarilmaydi"],"correct":2,"explain":"Hosil bo'lgan CO₂ va suv bug'i havoga uchib ketadi, shuning uchun ular tortilmaydi."}]},"en":{"title":"The law of conservation of mass","intro":"When a campfire burns out, only a handful of ash remains. Where did the mass of all that wood go? The answer lies in one of the most important laws of chemistry: in a reaction, mass neither disappears nor appears from nothing.","blocks":[{"h":"Statement of the law","p":"The total mass of the substances that react equals the total mass of the substances formed in the reaction. A balance shows this clearly: before and after a reaction in a closed vessel the pans stay level.","formula":"m(reactants) = m(products)","visual":{"type":"balance"}},{"h":"How the law was discovered","p":"In the 18th century the Russian scientist Mikhail Lomonosov and the French scientist Antoine Lavoisier heated substances in tightly sealed vessels and weighed them before and after the reaction. They found that, as long as the vessel was closed, the total mass did not change. Lavoisier stated this observation as a general law of nature."},{"h":"Why is mass conserved?","p":"In a reaction atoms do not disappear, do not appear from nowhere, and an atom of one element does not turn into an atom of another. They only join together in a new arrangement. Because the mass of each atom stays the same and the number of atoms is kept, the total mass does not change either. That is why we balance equations with coefficients."},{"h":"Checking with numbers","p":"Let us compare the masses in the equation for burning magnesium (Ar(Mg) = 24).","formula":"2Mg + O₂ → 2MgO","items":["1) Left side: 2 · 24 + 2 · 16 = 48 + 32 = 80","2) Right side: 2 · (24 + 16) = 80","3) 80 = 80 — mass is conserved","Problem: if 12 g of carbon burns completely in 32 g of oxygen, 12 + 32 = 44 g of CO₂ is formed"]},{"h":"When mass seems to «disappear»","p":"When wood burns in open air, the ash is much lighter than the wood; when an iron nail rusts, it becomes heavier instead. This does not break the law. In the first case gaseous products (carbon dioxide, water vapour) escape into the air; in the second, oxygen and water from the air combine with the iron. If all substances are weighed in a closed vessel, the mass does not change."},{"h":"Remember","items":["The mass of the reactants equals the mass of the products","The number and kinds of atoms do not change in a reaction","Lomonosov and Lavoisier proved the law by experiment","If mass seems to change, gases have escaped or have been taken from the air"]}],"quiz":[{"q":"What always stays the same in a chemical reaction?","options":["The colour of the substances","The number of molecules","The total mass of the substances","The state of matter"],"correct":2,"explain":"Atoms are conserved, so the total mass stays the same; the number of molecules can change."},{"q":"28 g of iron reacted completely with 16 g of sulfur. How many grams of FeS were formed?","options":["44 g","12 g","28 g","16 g"],"correct":0,"explain":"By the law of conservation of mass, 28 + 16 = 44 g."},{"q":"Why is the ash of paper burnt in open air lighter than the paper?","options":["Mass vanishes","Atoms disappear","Gaseous products escape into the air","The law does not hold for burning"],"correct":2,"explain":"The CO₂ and water vapour formed fly off into the air, so they are not weighed."}]},"ru":{"title":"Закон сохранения массы","intro":"Когда костёр догорает, от него остаётся лишь горстка золы. Куда делась масса всех этих дров? Ответ — в одном из важнейших законов химии: в реакции масса не исчезает и не возникает из ничего.","blocks":[{"h":"Формулировка закона","p":"Общая масса веществ, вступивших в реакцию, равна общей массе веществ, образовавшихся в результате реакции. Это наглядно видно на весах: до и после реакции в закрытом сосуде чаши остаются в равновесии.","formula":"m(реагентов) = m(продуктов)","visual":{"type":"balance"}},{"h":"Как был открыт закон","p":"В XVIII веке русский учёный Михаил Ломоносов и французский учёный Антуан Лавуазье нагревали вещества в плотно запаянных сосудах и взвешивали их до и после реакции. Оказалось, что если сосуд закрыт, общая масса не меняется. Лавуазье сформулировал это наблюдение как общий закон природы."},{"h":"Почему масса сохраняется?","p":"В реакции атомы не исчезают, не появляются из ничего, и атом одного элемента не превращается в атом другого. Они лишь соединяются в новом порядке. Поскольку масса каждого атома неизменна, а число атомов сохраняется, не меняется и общая масса. Именно поэтому уравнения уравнивают коэффициентами."},{"h":"Проверим расчётом","p":"Сравним массы в уравнении горения магния (Ar(Mg) = 24).","formula":"2Mg + O₂ → 2MgO","items":["1) Левая часть: 2 · 24 + 2 · 16 = 48 + 32 = 80","2) Правая часть: 2 · (24 + 16) = 80","3) 80 = 80 — масса сохранилась","Задача: если 12 г углерода полностью сгорают в 32 г кислорода, образуется 12 + 32 = 44 г CO₂"]},{"h":"Когда масса будто «исчезает»","p":"Когда дерево сгорает на открытом воздухе, зола гораздо легче дерева; а ржавеющий железный гвоздь, наоборот, тяжелеет. Это не противоречит закону. В первом случае газообразные продукты (углекислый газ, водяной пар) уходят в воздух, во втором — кислород и вода из воздуха присоединяются к железу. Если взвешивать все вещества в закрытом сосуде, масса не меняется."},{"h":"Запомните","items":["Масса реагентов равна массе продуктов","В реакции число и вид атомов не меняются","Закон опытным путём доказали Ломоносов и Лавуазье","Если кажется, что масса изменилась, значит, газы ушли или были поглощены из воздуха"]}],"quiz":[{"q":"Что всегда остаётся неизменным в химической реакции?","options":["Цвет веществ","Число молекул","Общая масса веществ","Агрегатное состояние"],"correct":2,"explain":"Атомы сохраняются, поэтому общая масса не меняется; число молекул может измениться."},{"q":"28 г железа полностью прореагировали с 16 г серы. Сколько граммов FeS образовалось?","options":["44 г","12 г","28 г","16 г"],"correct":0,"explain":"По закону сохранения массы 28 + 16 = 44 г."},{"q":"Почему зола бумаги, сгоревшей на воздухе, легче самой бумаги?","options":["Масса исчезает","Атомы пропадают","Газообразные продукты уходят в воздух","При горении закон не выполняется"],"correct":2,"explain":"Образовавшиеся CO₂ и водяной пар улетают в воздух, поэтому их не взвешивают."}]}},{"id":"t15","num":15,"icon":"🎈","uz":{"title":"Avogadro qonuni. Molar hajm","intro":"Bir xil hajmdagi ikkita sharni vodorod va karbonat angidrid bilan to'ldiraylik. Ulardan biri osmonga ko'tariladi, ikkinchisi yerga tushadi — ammo ikkala shardagi molekulalar soni bir xil! Bu ajoyib fakt Avogadro qonuni bilan tushuntiriladi.","blocks":[{"h":"Gaz hajmi nimaga bog'liq?","p":"Gazning hajmi harorat va bosimga qarab o'zgaradi: qizdirilgan shar kattalashadi, nasos bilan siqilgan havo kichik hajmga sig'adi. Gazda molekulalar orasidagi masofa molekulalarning o'z o'lchamidan juda katta. Shuning uchun gaz hajmini asosan molekulalar soni va ular orasidagi masofa belgilaydi, molekula o'lchami esa deyarli ahamiyatsiz."},{"h":"Avogadro qonuni","p":"1811-yilda italyan olimi Amedeo Avogadro quyidagi xulosaga keldi: bir xil harorat va bosimda teng hajmdagi har xil gazlarda molekulalar soni bir xil bo'ladi. Shu asosda u vodorod, kislorod, azot, xlor kabi oddiy gazlarning molekulalari ikki atomli (H₂, O₂, N₂, Cl₂) ekanini ko'rsatdi. Qonun faqat gazlarga taalluqli: suyuq va qattiq moddalarda hajm zarrachalar o'lchamiga ham bog'liq."},{"h":"Normal sharoit va molar hajm","p":"Normal sharoit (n.sh.) — 0 °C harorat va 101,3 kPa bosim. Avogadro qonuniga ko'ra, 1 mol istalgan gaz (6,02·10²³ ta molekula) bir xil sharoitda bir xil hajmni egallaydi. Normal sharoitda bu hajm 22,4 L ga teng va molar hajm (Vₘ) deb ataladi.","formula":"Vₘ = V / n = 22,4 L/mol (n.sh.)","visual":{"type":"calc","kind":"gas"}},{"h":"Asosiy formulalar","p":"Molar hajm yordamida gaz hajmi, modda miqdori, massasi va molekulalar soni o'zaro bog'lanadi.","items":["V = n · Vₘ — hajmni topish","n = V / Vₘ — modda miqdorini topish","V = m · Vₘ / M — massa ma'lum bo'lsa","N = (V / Vₘ) · N_A — molekulalar soni"]},{"h":"Ishlangan misol","p":"Xuddi shu 5,6 L hajmdagi vodorod ham 0,25 mol bo'ladi, lekin uning massasi atigi 0,5 g. Molekulalar soni bir xil, massalari esa har xil.","items":["Masala: 8 g kislorod (O₂) n.sh. da qancha hajmni egallaydi?","1) M(O₂) = 2 · 16 = 32 g/mol","2) n = 8 : 32 = 0,25 mol","3) V = 0,25 · 22,4 = 5,6 L","4) Molekulalar soni: N = 0,25 · 6,02·10²³ = 1,505·10²³"]},{"h":"Esda tuting","p":"Masalan, 1 mol suyuq suv atigi 18 mL ni egallaydi, bug' holida esa n.sh. ga keltirilgan holda 22,4 L — taxminan 1200 marta ko'p.","items":["Bir xil sharoitda teng hajmdagi gazlarda molekulalar soni teng","N.sh.: 0 °C va 101,3 kPa","N.sh. da 1 mol istalgan gaz 22,4 L hajmni egallaydi","Qonun faqat gazlar uchun o'rinli"]}],"quiz":[{"q":"N.sh. da 1 mol azot qancha hajmni egallaydi?","options":["11,2 L","22,4 L","44,8 L","1 L"],"correct":1,"explain":"N.sh. da istalgan gazning 1 moli 22,4 L ni egallaydi."},{"q":"44,8 L (n.sh.) karbonat angidrid necha mol bo'ladi?","options":["1 mol","0,5 mol","2 mol","4 mol"],"correct":2,"explain":"n = 44,8 : 22,4 = 2 mol."},{"q":"Avogadro qonuni qaysi moddalar uchun o'rinli?","options":["Gazlar uchun","Suyuqliklar uchun","Qattiq moddalar uchun","Barcha moddalar uchun bir xil"],"correct":0,"explain":"Faqat gazlarda molekulalar orasidagi masofa ularning o'lchamidan juda katta."}]},"en":{"title":"Avogadro's law. Molar volume","intro":"Let us fill two balloons of the same size, one with hydrogen and one with carbon dioxide. One rises into the sky and the other sinks to the floor — yet both contain the same number of molecules! This remarkable fact is explained by Avogadro's law.","blocks":[{"h":"What does the volume of a gas depend on?","p":"The volume of a gas changes with temperature and pressure: a heated balloon grows, and air squeezed by a pump fits into a small volume. In a gas the distance between molecules is far larger than the molecules themselves. So the volume of a gas is set mainly by the number of molecules and the distance between them, while the size of the molecules hardly matters."},{"h":"Avogadro's law","p":"In 1811 the Italian scientist Amedeo Avogadro concluded: at the same temperature and pressure, equal volumes of different gases contain the same number of molecules. On this basis he showed that the molecules of simple gases such as hydrogen, oxygen, nitrogen and chlorine are diatomic (H₂, O₂, N₂, Cl₂). The law applies only to gases: in liquids and solids the volume also depends on the size of the particles."},{"h":"Normal conditions and molar volume","p":"Normal conditions (n.c.) are a temperature of 0 °C and a pressure of 101.3 kPa. By Avogadro's law, 1 mole of any gas (6.02×10²³ molecules) occupies the same volume under the same conditions. Under normal conditions this volume is 22.4 L and is called the molar volume (Vₘ).","formula":"Vₘ = V / n = 22.4 L/mol (n.c.)","visual":{"type":"calc","kind":"gas"}},{"h":"Key formulas","p":"The molar volume links the volume, amount, mass and number of molecules of a gas.","items":["V = n · Vₘ — find the volume","n = V / Vₘ — find the amount of substance","V = m · Vₘ / M — when the mass is known","N = (V / Vₘ) · N_A — number of molecules"]},{"h":"Worked example","p":"The same 5.6 L of hydrogen is also 0.25 mol, but its mass is only 0.5 g. The number of molecules is the same, but the masses differ.","items":["Problem: what volume does 8 g of oxygen (O₂) occupy at n.c.?","1) M(O₂) = 2 · 16 = 32 g/mol","2) n = 8 ÷ 32 = 0.25 mol","3) V = 0.25 × 22.4 = 5.6 L","4) Number of molecules: N = 0.25 × 6.02×10²³ = 1.505×10²³"]},{"h":"Remember","p":"For example, 1 mol of liquid water takes up only 18 mL, while as vapour (recalculated to n.c.) it would take 22.4 L — about 1200 times more.","items":["Under the same conditions equal volumes of gases contain equal numbers of molecules","Normal conditions: 0 °C and 101.3 kPa","At n.c. 1 mole of any gas occupies 22.4 L","The law holds only for gases"]}],"quiz":[{"q":"What volume does 1 mol of nitrogen occupy at n.c.?","options":["11.2 L","22.4 L","44.8 L","1 L"],"correct":1,"explain":"At n.c. 1 mole of any gas occupies 22.4 L."},{"q":"How many moles are in 44.8 L (n.c.) of carbon dioxide?","options":["1 mol","0.5 mol","2 mol","4 mol"],"correct":2,"explain":"n = 44.8 ÷ 22.4 = 2 mol."},{"q":"For which substances is Avogadro's law valid?","options":["For gases","For liquids","For solids","Equally for all substances"],"correct":0,"explain":"Only in gases is the distance between molecules much larger than their size."}]},"ru":{"title":"Закон Авогадро. Молярный объём","intro":"Наполним два одинаковых шарика: один водородом, другой углекислым газом. Первый взлетит, второй опустится на пол — но число молекул в обоих одинаково! Этот удивительный факт объясняет закон Авогадро.","blocks":[{"h":"От чего зависит объём газа?","p":"Объём газа меняется с температурой и давлением: нагретый шарик раздувается, а сжатый насосом воздух помещается в малый объём. В газе расстояния между молекулами намного больше размеров самих молекул. Поэтому объём газа определяется в основном числом молекул и расстоянием между ними, а размер молекул почти не важен."},{"h":"Закон Авогадро","p":"В 1811 году итальянский учёный Амедео Авогадро пришёл к выводу: при одинаковых температуре и давлении в равных объёмах различных газов содержится одинаковое число молекул. На этой основе он показал, что молекулы простых газов — водорода, кислорода, азота, хлора — двухатомны (H₂, O₂, N₂, Cl₂). Закон относится только к газам: у жидкостей и твёрдых тел объём зависит и от размера частиц."},{"h":"Нормальные условия и молярный объём","p":"Нормальные условия (н. у.) — температура 0 °C и давление 101,3 кПа. По закону Авогадро 1 моль любого газа (6,02·10²³ молекул) при одинаковых условиях занимает одинаковый объём. При нормальных условиях он равен 22,4 л и называется молярным объёмом (Vₘ).","formula":"Vₘ = V / n = 22,4 л/моль (н. у.)","visual":{"type":"calc","kind":"gas"}},{"h":"Основные формулы","p":"Молярный объём связывает объём, количество вещества, массу и число молекул газа.","items":["V = n · Vₘ — найти объём","n = V / Vₘ — найти количество вещества","V = m · Vₘ / M — если известна масса","N = (V / Vₘ) · N_A — число молекул"]},{"h":"Разобранный пример","p":"Те же 5,6 л водорода — это тоже 0,25 моль, но их масса всего 0,5 г. Число молекул одинаковое, а массы разные.","items":["Задача: какой объём при н. у. занимают 8 г кислорода (O₂)?","1) M(O₂) = 2 · 16 = 32 г/моль","2) n = 8 : 32 = 0,25 моль","3) V = 0,25 · 22,4 = 5,6 л","4) Число молекул: N = 0,25 · 6,02·10²³ = 1,505·10²³"]},{"h":"Запомните","p":"Например, 1 моль жидкой воды занимает всего 18 мл, а в виде пара (в пересчёте на н. у.) — 22,4 л, примерно в 1200 раз больше.","items":["При одинаковых условиях в равных объёмах газов одинаковое число молекул","Нормальные условия: 0 °C и 101,3 кПа","При н. у. 1 моль любого газа занимает 22,4 л","Закон справедлив только для газов"]}],"quiz":[{"q":"Какой объём при н. у. занимает 1 моль азота?","options":["11,2 л","22,4 л","44,8 л","1 л"],"correct":1,"explain":"При н. у. 1 моль любого газа занимает 22,4 л."},{"q":"Сколько моль составляют 44,8 л (н. у.) углекислого газа?","options":["1 моль","0,5 моль","2 моль","4 моль"],"correct":2,"explain":"n = 44,8 : 22,4 = 2 моль."},{"q":"Для каких веществ справедлив закон Авогадро?","options":["Для газов","Для жидкостей","Для твёрдых веществ","Одинаково для всех веществ"],"correct":0,"explain":"Только в газах расстояния между молекулами намного больше их размеров."}]}},{"id":"t16","num":16,"icon":"💥","uz":{"title":"Kimyoviy reaksiya turlari. Kimyoviy energiya","intro":"Reaksiyalar juda ko'p, lekin ularning ko'pchiligi bir nechta oddiy «andoza»ga tushadi. Bu andozalarni bilsangiz, notanish reaksiyani ham tez tushunasiz. Shuningdek, reaksiyalarda energiya qanday ajralishi yoki yutilishini ko'rib chiqamiz.","blocks":[{"h":"Reaksiyalarning to'rt asosiy turi","p":"Reaksiyalarni boshlang'ich moddalar va mahsulotlar soni hamda tarkibiga qarab to'rt asosiy turga ajratish mumkin.","table":{"head":["Tur","Umumiy sxema","Misol"],"rows":[["Birikish","A + B → AB","CaO + H₂O → Ca(OH)₂"],["Parchalanish","AB → A + B","2H₂O → 2H₂ + O₂ (elektr toki ta'sirida)"],["O'rin olish","A + BC → AC + B","Zn + 2HCl → ZnCl₂ + H₂"],["Almashinish","AB + CD → AD + CB","NaOH + HCl → NaCl + H₂O"]]}},{"h":"Birikish va parchalanish","p":"Birikishda ikki yoki undan ortiq moddadan bitta yangi modda hosil bo'ladi: masalan, so'ndirilmagan ohak suv bilan reaksiyaga kirishib, so'ndirilgan ohakka aylanadi. Parchalanishda esa bitta murakkab moddadan ikki yoki undan ortiq modda hosil bo'ladi: ohaktosh kuchli qizdirilganda so'ndirilmagan ohak va karbonat angidridga ajraladi.","formula":"CaCO₃ → CaO + CO₂","visual":{"type":"reaction","id":"cao_h2o"}},{"h":"O'rin olish va almashinish","p":"O'rin olishda oddiy modda murakkab modda tarkibidagi bir elementning o'rnini egallaydi: rux xlorid kislotadan vodorodni siqib chiqaradi, temir esa mis (II) sulfat eritmasidan misni ajratib oladi. Almashinishda ikki murakkab modda o'z tarkibiy qismlarini almashtiradi; kislota va ishqorning neytrallanishi bunga yaxshi misol.","formula":"Fe + CuSO₄ → FeSO₄ + Cu","visual":{"type":"reaction","id":"zn_hcl"}},{"h":"Kimyoviy energiya","p":"Moddalardagi kimyoviy bog'larda energiya to'plangan. Reaksiyada eski bog'lar uziladi va yangilari hosil bo'ladi; ular energiyalarining farqi issiqlik, yorug'lik, elektr yoki mexanik ish ko'rinishida ajraladi yoki yutiladi. Reaksiyada ajralgan yoki yutilgan issiqlik miqdori Q bilan belgilanadi va kilojoullarda (kJ) o'lchanadi. Masalan, telefon batareyasida kimyoviy energiya elektr energiyasiga aylanadi."},{"h":"Ekzotermik va endotermik reaksiyalar","p":"Issiqlik chiqishi bilan boradigan reaksiyalar ekzotermik («ekzo» — tashqari), issiqlik yutilishi bilan boradiganlari esa endotermik («endo» — ichkari) reaksiyalar deyiladi. Issiqlik chiqsa, tenglamada «+Q», yutilsa «−Q» yoziladi.","items":["Ekzotermik: C + O₂ → CO₂ + 393 kJ (ko'mirning yonishi)","Endotermik: CaCO₃ → CaO + CO₂ − Q (to'xtovsiz qizdirishni talab qiladi)","Hayotda: gaz va ko'mirning yonishi issiqlik beradi; o'simliklardagi fotosintez esa quyosh energiyasini yutadi"]},{"h":"Esda tuting","items":["Asosiy turlar: birikish, parchalanish, o'rin olish, almashinish","O'rin olishda oddiy modda qatnashadi, almashinishda ikki murakkab modda","Reaksiyalarda energiya ajraladi (ekzotermik) yoki yutiladi (endotermik)","Issiqlik miqdori Q kilojoullarda o'lchanadi"]}],"quiz":[{"q":"S + O₂ → SO₂ reaksiyasi qaysi turga kiradi?","options":["Parchalanish","Birikish","O'rin olish","Almashinish"],"correct":1,"explain":"Ikki moddadan bitta yangi modda hosil bo'ldi."},{"q":"Mg + 2HCl → MgCl₂ + H₂ reaksiyasi qaysi turga kiradi?","options":["Birikish","Almashinish","O'rin olish","Parchalanish"],"correct":2,"explain":"Oddiy modda — magniy — kislotadagi vodorod o'rnini egalladi."},{"q":"Issiqlik yutilishi bilan boradigan reaksiya qanday ataladi?","options":["Endotermik","Ekzotermik","Birikish","Neytrallanish"],"correct":0,"explain":"«Endo» — ichkari: issiqlik tashqaridan ichkariga yutiladi."}]},"en":{"title":"Types of chemical reactions. Chemical energy","intro":"There are very many reactions, but most of them fit a few simple patterns. Once you know these patterns, you can quickly make sense of an unfamiliar reaction. We will also see how energy is released or absorbed in reactions.","blocks":[{"h":"Four main types of reactions","p":"Reactions can be sorted into four main types according to the number and composition of the starting substances and products.","table":{"head":["Type","General scheme","Example"],"rows":[["Combination","A + B → AB","CaO + H₂O → Ca(OH)₂"],["Decomposition","AB → A + B","2H₂O → 2H₂ + O₂ (by electric current)"],["Single displacement","A + BC → AC + B","Zn + 2HCl → ZnCl₂ + H₂"],["Exchange (double displacement)","AB + CD → AD + CB","NaOH + HCl → NaCl + H₂O"]]}},{"h":"Combination and decomposition","p":"In combination two or more substances form one new substance: for example, quicklime reacts with water and turns into slaked lime. In decomposition one complex substance breaks down into two or more substances: when limestone is strongly heated, it splits into quicklime and carbon dioxide.","formula":"CaCO₃ → CaO + CO₂","visual":{"type":"reaction","id":"cao_h2o"}},{"h":"Displacement and exchange","p":"In single displacement a simple substance takes the place of one element in a complex substance: zinc pushes hydrogen out of hydrochloric acid, and iron pulls copper out of copper(II) sulfate solution. In exchange two complex substances swap their parts; the neutralisation of an acid by an alkali is a good example.","formula":"Fe + CuSO₄ → FeSO₄ + Cu","visual":{"type":"reaction","id":"zn_hcl"}},{"h":"Chemical energy","p":"Energy is stored in the chemical bonds of substances. In a reaction old bonds break and new ones form; the difference in their energies is released or absorbed as heat, light, electricity or mechanical work. The amount of heat released or absorbed in a reaction is written Q and measured in kilojoules (kJ). For example, in a phone battery chemical energy is turned into electrical energy."},{"h":"Exothermic and endothermic reactions","p":"Reactions that release heat are called exothermic («exo» — outside), and reactions that absorb heat are called endothermic («endo» — inside). If heat is released, «+Q» is written in the equation; if it is absorbed, «−Q».","items":["Exothermic: C + O₂ → CO₂ + 393 kJ (burning coal)","Endothermic: CaCO₃ → CaO + CO₂ − Q (needs constant heating)","In life: burning gas and coal gives heat, while photosynthesis in plants absorbs the energy of sunlight"]},{"h":"Remember","items":["Main types: combination, decomposition, single displacement, exchange","Displacement involves a simple substance; exchange involves two complex substances","Reactions release energy (exothermic) or absorb it (endothermic)","The amount of heat Q is measured in kilojoules"]}],"quiz":[{"q":"Which type of reaction is S + O₂ → SO₂?","options":["Decomposition","Combination","Single displacement","Exchange"],"correct":1,"explain":"Two substances formed one new substance."},{"q":"Which type of reaction is Mg + 2HCl → MgCl₂ + H₂?","options":["Combination","Exchange","Single displacement","Decomposition"],"correct":2,"explain":"A simple substance, magnesium, took the place of hydrogen in the acid."},{"q":"What is a reaction that absorbs heat called?","options":["Endothermic","Exothermic","Combination","Neutralisation"],"correct":0,"explain":"«Endo» means inside: heat is taken in from the surroundings."}]},"ru":{"title":"Типы химических реакций. Химическая энергия","intro":"Реакций очень много, но большинство из них укладывается в несколько простых «шаблонов». Зная эти шаблоны, вы быстро разберётесь и в незнакомой реакции. Также посмотрим, как в реакциях выделяется или поглощается энергия.","blocks":[{"h":"Четыре основных типа реакций","p":"По числу и составу исходных веществ и продуктов реакции можно разделить на четыре основных типа.","table":{"head":["Тип","Общая схема","Пример"],"rows":[["Соединение","A + B → AB","CaO + H₂O → Ca(OH)₂"],["Разложение","AB → A + B","2H₂O → 2H₂ + O₂ (под действием тока)"],["Замещение","A + BC → AC + B","Zn + 2HCl → ZnCl₂ + H₂"],["Обмен","AB + CD → AD + CB","NaOH + HCl → NaCl + H₂O"]]}},{"h":"Соединение и разложение","p":"При соединении из двух или более веществ образуется одно новое вещество: например, негашёная известь реагирует с водой и превращается в гашёную. При разложении одно сложное вещество распадается на два или более веществ: при сильном нагревании известняк разлагается на негашёную известь и углекислый газ.","formula":"CaCO₃ → CaO + CO₂","visual":{"type":"reaction","id":"cao_h2o"}},{"h":"Замещение и обмен","p":"При замещении простое вещество занимает место одного из элементов в сложном веществе: цинк вытесняет водород из соляной кислоты, а железо вытесняет медь из раствора сульфата меди(II). При обмене два сложных вещества обмениваются составными частями; хороший пример — нейтрализация кислоты щёлочью.","formula":"Fe + CuSO₄ → FeSO₄ + Cu","visual":{"type":"reaction","id":"zn_hcl"}},{"h":"Химическая энергия","p":"В химических связях веществ запасена энергия. В реакции старые связи рвутся и образуются новые; разница их энергий выделяется или поглощается в виде теплоты, света, электричества или механической работы. Количество теплоты, выделившейся или поглощённой в реакции, обозначают Q и измеряют в килоджоулях (кДж). Например, в батарее телефона химическая энергия превращается в электрическую."},{"h":"Экзотермические и эндотермические реакции","p":"Реакции, идущие с выделением теплоты, называют экзотермическими («экзо» — наружу), а с поглощением теплоты — эндотермическими («эндо» — внутрь). Если теплота выделяется, в уравнении пишут «+Q», если поглощается — «−Q».","items":["Экзотермическая: C + O₂ → CO₂ + 393 кДж (горение угля)","Эндотермическая: CaCO₃ → CaO + CO₂ − Q (требует постоянного нагревания)","В жизни: горение газа и угля даёт тепло, а фотосинтез в растениях поглощает энергию солнечного света"]},{"h":"Запомните","items":["Основные типы: соединение, разложение, замещение, обмен","В замещении участвует простое вещество, в обмене — два сложных","В реакциях энергия выделяется (экзотермические) или поглощается (эндотермические)","Количество теплоты Q измеряют в килоджоулях"]}],"quiz":[{"q":"К какому типу относится реакция S + O₂ → SO₂?","options":["Разложение","Соединение","Замещение","Обмен"],"correct":1,"explain":"Из двух веществ образовалось одно новое."},{"q":"К какому типу относится реакция Mg + 2HCl → MgCl₂ + H₂?","options":["Соединение","Обмен","Замещение","Разложение"],"correct":2,"explain":"Простое вещество магний заняло место водорода в кислоте."},{"q":"Как называется реакция, идущая с поглощением теплоты?","options":["Эндотермическая","Экзотермическая","Соединение","Нейтрализация"],"correct":0,"explain":"«Эндо» — внутрь: теплота поглощается из окружающей среды."}]}},{"id":"t16p","num":16,"icon":"📝","uz":{"title":"Masalalar yechish: asosiy hisoblar","intro":"Formulalarni bilish yarim ish, ularni masalada qo'llay olish — qolgan yarmi. Bu darsda o'tilgan mavzular bo'yicha beshta masalani qadamma-qadam yechamiz. Har bir qadamni o'zingiz takrorlab ko'ring, so'ng testni bajaring.","blocks":[{"h":"Masala yechish tartibi","p":"Har qanday hisoblash masalasini bir xil reja asosida yechish qulay. Kerakli kattaliklar: n = m / M, N = n · N_A, V = n · Vₘ, ω = n · Ar / Mr.","items":["1) Shartni qisqa yozing: «Berilgan» va «Topish kerak»","2) Reaksiya bo'lsa, tenglamasini yozib, tenglashtiring","3) Kerakli molar massalarni hisoblang","4) Berilgan moddani molga o'tkazing va tenglama koeffitsientlari orqali boshqa moddaga bog'lang","5) Javobni birligi bilan yozing va mantiqan tekshiring"]},{"h":"1-masala: o'g'itdagi azot ulushi","p":"Karbamid CO(NH₂)₂ — keng tarqalgan azotli o'g'it. Undagi azotning massa ulushini toping.","formula":"ω(N) = 2 · Ar(N) / Mr","items":["1) Mr(CO(NH₂)₂) = 12 + 16 + 2 · (14 + 2 · 1) = 60","2) Bitta molekulada 2 ta azot atomi: 2 · 14 = 28","3) ω(N) = 28 : 60 ≈ 0,467","Javob: taxminan 46,7% azot"],"visual":{"type":"calc","kind":"molar"}},{"h":"2-masala: tarkibidan formulani topish","p":"Mis oksidida 80% mis va 20% kislorod bor. Uning formulasini toping.","items":["1) Formulani CuₓOᵧ deb belgilaymiz","2) Har bir foizni atom massasiga bo'lamiz: x = 80 : 64 = 1,25; y = 20 : 16 = 1,25","3) Nisbat: x : y = 1,25 : 1,25 = 1 : 1","4) Formula: CuO","Tekshiruv: Mr(CuO) = 80, ω(Cu) = 64 : 80 = 80%"]},{"h":"3-masala: molekula va atomlar soni","p":"9 g suvda nechta molekula va jami nechta atom bor?","items":["1) M(H₂O) = 18 g/mol","2) n = 9 : 18 = 0,5 mol","3) N(H₂O) = 0,5 · 6,02·10²³ = 3,01·10²³ ta molekula","4) Har bir molekulada 3 ta atom: 3 · 3,01·10²³ = 9,03·10²³ ta atom","Javob: 3,01·10²³ ta molekula, 9,03·10²³ ta atom"]},{"h":"4-masala: tenglama bo'yicha massa va hajm","p":"13 g rux xlorid kislota bilan to'liq reaksiyaga kirishdi. Necha gramm rux xlorid va n.sh. da necha litr vodorod hosil bo'ladi?","formula":"Zn + 2HCl → ZnCl₂ + H₂","items":["1) n(Zn) = 13 : 65 = 0,2 mol","2) Tenglamaga ko'ra n(ZnCl₂) = n(H₂) = n(Zn) = 0,2 mol","3) M(ZnCl₂) = 65 + 2 · 35,5 = 136 g/mol; m = 0,2 · 136 = 27,2 g","4) V(H₂) = 0,2 · 22,4 = 4,48 L","Tekshiruv: sarflangan HCl 0,4 · 36,5 = 14,6 g; 13 + 14,6 = 27,2 + 0,4 = 27,6 g — massa saqlandi"],"visual":{"type":"reaction","id":"zn_hcl"}},{"h":"5-masala: gazlar hajmi","p":"10 L metan to'liq yonishi uchun qancha hajm kislorod kerak va qancha hajm karbonat angidrid hosil bo'ladi? Hajmlar bir xil sharoitda o'lchangan.","formula":"CH₄ + 2O₂ → CO₂ + 2H₂O","items":["1) Avogadro qonuniga ko'ra gazlar hajmlari nisbati koeffitsientlar nisbatiga teng","2) V(CH₄) : V(O₂) : V(CO₂) = 1 : 2 : 1","3) V(O₂) = 2 · 10 = 20 L","4) V(CO₂) = 1 · 10 = 10 L","Javob: 20 L kislorod kerak, 10 L karbonat angidrid hosil bo'ladi"],"visual":{"type":"calc","kind":"gas"}}],"quiz":[{"q":"Mr(CuSO₄) nechaga teng?","options":["96","160","128","144"],"correct":1,"explain":"64 + 32 + 4 · 16 = 160."},{"q":"4 g NaOH necha mol bo'ladi?","options":["0,1 mol","1 mol","0,4 mol","10 mol"],"correct":0,"explain":"M(NaOH) = 40 g/mol, n = 4 : 40 = 0,1 mol."},{"q":"N.sh. da 11,2 L vodorodning massasi qancha?","options":["2 g","0,5 g","11,2 g","1 g"],"correct":3,"explain":"n = 11,2 : 22,4 = 0,5 mol, m = 0,5 · 2 = 1 g."}]},"en":{"title":"Problem solving: key calculations","intro":"Knowing the formulas is half the job; being able to use them in a problem is the other half. In this lesson we solve five problems on the topics covered so far, step by step. Repeat each step yourself, then try the quiz.","blocks":[{"h":"How to solve a problem","p":"It helps to solve every calculation problem with the same plan. Useful relations: n = m / M, N = n · N_A, V = n · Vₘ, ω = n · Ar / Mr.","items":["1) Write the condition briefly: «Given» and «Find»","2) If there is a reaction, write and balance its equation","3) Calculate the molar masses you need","4) Convert the given substance to moles and link it to the other substance through the coefficients","5) Write the answer with its unit and check that it makes sense"]},{"h":"Problem 1: nitrogen in a fertiliser","p":"Urea CO(NH₂)₂ is a widely used nitrogen fertiliser. Find the mass fraction of nitrogen in it.","formula":"ω(N) = 2 · Ar(N) / Mr","items":["1) Mr(CO(NH₂)₂) = 12 + 16 + 2 · (14 + 2 · 1) = 60","2) One molecule has 2 nitrogen atoms: 2 · 14 = 28","3) ω(N) = 28 ÷ 60 ≈ 0.467","Answer: about 46.7% nitrogen"],"visual":{"type":"calc","kind":"molar"}},{"h":"Problem 2: formula from composition","p":"A copper oxide contains 80% copper and 20% oxygen. Find its formula.","items":["1) Write the formula as CuₓOᵧ","2) Divide each percentage by the atomic mass: x = 80 ÷ 64 = 1.25; y = 20 ÷ 16 = 1.25","3) Ratio: x : y = 1.25 : 1.25 = 1 : 1","4) Formula: CuO","Check: Mr(CuO) = 80, ω(Cu) = 64 ÷ 80 = 80%"]},{"h":"Problem 3: number of molecules and atoms","p":"How many molecules and how many atoms in total are in 9 g of water?","items":["1) M(H₂O) = 18 g/mol","2) n = 9 ÷ 18 = 0.5 mol","3) N(H₂O) = 0.5 × 6.02×10²³ = 3.01×10²³ molecules","4) Each molecule has 3 atoms: 3 × 3.01×10²³ = 9.03×10²³ atoms","Answer: 3.01×10²³ molecules, 9.03×10²³ atoms"]},{"h":"Problem 4: mass and volume from an equation","p":"13 g of zinc reacted completely with hydrochloric acid. How many grams of zinc chloride and how many litres of hydrogen (n.c.) are formed?","formula":"Zn + 2HCl → ZnCl₂ + H₂","items":["1) n(Zn) = 13 ÷ 65 = 0.2 mol","2) From the equation n(ZnCl₂) = n(H₂) = n(Zn) = 0.2 mol","3) M(ZnCl₂) = 65 + 2 · 35.5 = 136 g/mol; m = 0.2 × 136 = 27.2 g","4) V(H₂) = 0.2 × 22.4 = 4.48 L","Check: HCl used is 0.4 × 36.5 = 14.6 g; 13 + 14.6 = 27.2 + 0.4 = 27.6 g — mass is conserved"],"visual":{"type":"reaction","id":"zn_hcl"}},{"h":"Problem 5: volumes of gases","p":"What volume of oxygen is needed to burn 10 L of methane completely, and what volume of carbon dioxide is formed? All volumes are measured under the same conditions.","formula":"CH₄ + 2O₂ → CO₂ + 2H₂O","items":["1) By Avogadro's law the ratio of gas volumes equals the ratio of coefficients","2) V(CH₄) : V(O₂) : V(CO₂) = 1 : 2 : 1","3) V(O₂) = 2 × 10 = 20 L","4) V(CO₂) = 1 × 10 = 10 L","Answer: 20 L of oxygen is needed and 10 L of carbon dioxide is formed"],"visual":{"type":"calc","kind":"gas"}}],"quiz":[{"q":"What is Mr(CuSO₄)?","options":["96","160","128","144"],"correct":1,"explain":"64 + 32 + 4 · 16 = 160."},{"q":"How many moles are in 4 g of NaOH?","options":["0.1 mol","1 mol","0.4 mol","10 mol"],"correct":0,"explain":"M(NaOH) = 40 g/mol, n = 4 ÷ 40 = 0.1 mol."},{"q":"What is the mass of 11.2 L of hydrogen at n.c.?","options":["2 g","0.5 g","11.2 g","1 g"],"correct":3,"explain":"n = 11.2 ÷ 22.4 = 0.5 mol, m = 0.5 × 2 = 1 g."}]},"ru":{"title":"Решение задач: основные расчёты","intro":"Знать формулы — половина дела, уметь применять их в задаче — вторая половина. На этом уроке мы по шагам решим пять задач по пройденным темам. Повторите каждый шаг самостоятельно, а затем пройдите тест.","blocks":[{"h":"Порядок решения задачи","p":"Любую расчётную задачу удобно решать по одному плану. Нужные соотношения: n = m / M, N = n · N_A, V = n · Vₘ, ω = n · Ar / Mr.","items":["1) Кратко запишите условие: «Дано» и «Найти»","2) Если есть реакция, запишите и уравняйте её уравнение","3) Вычислите нужные молярные массы","4) Переведите данное вещество в моли и свяжите с другим веществом через коэффициенты","5) Запишите ответ с единицами и проверьте его на здравый смысл"]},{"h":"Задача 1: азот в удобрении","p":"Карбамид CO(NH₂)₂ — широко распространённое азотное удобрение. Найдите массовую долю азота в нём.","formula":"ω(N) = 2 · Ar(N) / Mr","items":["1) Mr(CO(NH₂)₂) = 12 + 16 + 2 · (14 + 2 · 1) = 60","2) В одной молекуле 2 атома азота: 2 · 14 = 28","3) ω(N) = 28 : 60 ≈ 0,467","Ответ: около 46,7% азота"],"visual":{"type":"calc","kind":"molar"}},{"h":"Задача 2: формула по составу","p":"Оксид меди содержит 80% меди и 20% кислорода. Найдите его формулу.","items":["1) Обозначим формулу CuₓOᵧ","2) Делим каждый процент на атомную массу: x = 80 : 64 = 1,25; y = 20 : 16 = 1,25","3) Отношение: x : y = 1,25 : 1,25 = 1 : 1","4) Формула: CuO","Проверка: Mr(CuO) = 80, ω(Cu) = 64 : 80 = 80%"]},{"h":"Задача 3: число молекул и атомов","p":"Сколько молекул и сколько всего атомов содержится в 9 г воды?","items":["1) M(H₂O) = 18 г/моль","2) n = 9 : 18 = 0,5 моль","3) N(H₂O) = 0,5 · 6,02·10²³ = 3,01·10²³ молекул","4) В каждой молекуле 3 атома: 3 · 3,01·10²³ = 9,03·10²³ атомов","Ответ: 3,01·10²³ молекул, 9,03·10²³ атомов"]},{"h":"Задача 4: масса и объём по уравнению","p":"13 г цинка полностью прореагировали с соляной кислотой. Сколько граммов хлорида цинка и сколько литров водорода (н. у.) образуется?","formula":"Zn + 2HCl → ZnCl₂ + H₂","items":["1) n(Zn) = 13 : 65 = 0,2 моль","2) По уравнению n(ZnCl₂) = n(H₂) = n(Zn) = 0,2 моль","3) M(ZnCl₂) = 65 + 2 · 35,5 = 136 г/моль; m = 0,2 · 136 = 27,2 г","4) V(H₂) = 0,2 · 22,4 = 4,48 л","Проверка: израсходовано HCl 0,4 · 36,5 = 14,6 г; 13 + 14,6 = 27,2 + 0,4 = 27,6 г — масса сохранилась"],"visual":{"type":"reaction","id":"zn_hcl"}},{"h":"Задача 5: объёмы газов","p":"Какой объём кислорода нужен для полного сгорания 10 л метана и какой объём углекислого газа при этом образуется? Объёмы измерены при одинаковых условиях.","formula":"CH₄ + 2O₂ → CO₂ + 2H₂O","items":["1) По закону Авогадро объёмы газов относятся как коэффициенты","2) V(CH₄) : V(O₂) : V(CO₂) = 1 : 2 : 1","3) V(O₂) = 2 · 10 = 20 л","4) V(CO₂) = 1 · 10 = 10 л","Ответ: нужно 20 л кислорода, образуется 10 л углекислого газа"],"visual":{"type":"calc","kind":"gas"}}],"quiz":[{"q":"Чему равна Mr(CuSO₄)?","options":["96","160","128","144"],"correct":1,"explain":"64 + 32 + 4 · 16 = 160."},{"q":"Сколько моль составляют 4 г NaOH?","options":["0,1 моль","1 моль","0,4 моль","10 моль"],"correct":0,"explain":"M(NaOH) = 40 г/моль, n = 4 : 40 = 0,1 моль."},{"q":"Какова масса 11,2 л водорода при н. у.?","options":["2 г","0,5 г","11,2 г","1 г"],"correct":3,"explain":"n = 11,2 : 22,4 = 0,5 моль, m = 0,5 · 2 = 1 г."}]}}]},{"title":{"uz":"2-bob. Kislorod","en":"Chapter 2. Oxygen","ru":"Глава 2. Кислород"},"topics":[{"id":"t17","num":17,"icon":"🫁","uz":{"title":"Kislorod","intro":"Har bir nafas, har bir gulxan va hatto temirning zanglashi ham bitta element bilan bog'liq. Bu element kislorod bo'lib, u sayyoramizda eng keng tarqalgan elementdir. Keling, u bilan yaqindan tanishamiz.","blocks":[{"h":"Kislorod qayerda uchraydi","p":"Kislorod tabiatda ham erkin holda, ham birikmalar tarkibida uchraydi. Erkin kislorod (O₂) havoda bo'ladi, bog'langan kislorod esa suv, qum, tog' jinslari, minerallar va tirik organizmlar tarkibiga kiradi. Yer po'sti massasining deyarli yarmi kisloroddan iborat.","items":["Havoda: hajm bo'yicha taxminan 21% O₂","Suvda: suv massasining qariyb 89% i kislorod","Yer po'stida: massasining deyarli yarmi (qum SiO₂, ohaktosh CaCO₃, temir rudalari)","Tirik organizmlarda: oqsillar, uglevodlar, yog'lar tarkibida"],"visual":{"type":"chart","kind":"crust"}},{"h":"Kashf etilish tarixi","p":"XVIII asrning 70-yillarida shved kimyogari K. Sheele va ingliz olimi J. Pristli bir-biridan mustaqil ravishda kislorodni ajratib olishgan. Pristli simob oksidini qizdirib, sham alangasini juda yorqin qiladigan gaz olgan. Fransuz olimi A. Lavuazye bu gazning yonish va nafas olishdagi rolini tushuntirib, unga «oxygenium» (kislota hosil qiluvchi) nomini bergan, kimyoviy belgisi O shundan olingan."},{"h":"Kislorod atomi","p":"Kislorod davriy sistemada 8-o'rinda turadi: atom yadrosining zaryadi +8, atomida 8 ta elektron bor. Uning nisbiy atom massasi 16 ga teng. Birikmalarida kislorod asosan II valentli bo'ladi.","formula":"O: tartib raqami 8, Ar(O) = 16, valentligi II","visual":{"type":"atom3d","el":"O"}},{"h":"Element va oddiy modda","p":"«Kislorod» so'zi ikki ma'noda ishlatiladi. Suv yoki qum tarkibidagi kislorod haqida gapirganda biz elementni nazarda tutamiz. Nafas olinadigan gaz esa oddiy modda – ikki atomli O₂ molekulalaridan iborat.","items":["Element: H₂O, CO₂, CaCO₃ tarkibidagi O atomlari","Oddiy modda: O₂ gazi, Mr(O₂) = 2 · 16 = 32"]},{"h":"Namuna: suvdagi kislorodning massa ulushi","p":"Birikmadagi elementning massa ulushini topish uchun uning atomlari massasini butun molekula massasiga bo'lamiz.","formula":"ω(O) = Ar(O) · n / Mr(H₂O)","items":["Mr(H₂O) = 2 · 1 + 16 = 18","Kislorod atomlari massasi: 1 · 16 = 16","ω(O) = 16 / 18 ≈ 0,889","Javob: suv massasining taxminan 88,9% i kislorod"]},{"h":"Esda tuting","items":["Kislorod – Yer po'stida eng ko'p tarqalgan element","Belgisi O, Ar = 16, birikmalarda valentligi II","Erkin holdagi oddiy modda – O₂ (Mr = 32)","Kislorodni 1770-yillarda Sheele va Pristli kashf etgan, Lavuazye uni nomlagan"]}],"quiz":[{"q":"Kislorodning nisbiy atom massasi nechaga teng?","options":["8","16","32","12"],"correct":1,"explain":"Ar(O) = 16; 32 esa O₂ molekulasining massasi."},{"q":"Qaysi gapda kislorod oddiy modda sifatida tilga olingan?","options":["Qum tarkibida kislorod bor","Suv tarkibida kislorod bor","Baliqlar suvda erigan kislorod bilan nafas oladi","Shakar tarkibida kislorod bor"],"correct":2,"explain":"Baliqlar O₂ gazi bilan nafas oladi, qolganlarida esa element haqida gap boradi."},{"q":"Kislorod birikmalarida asosan qanday valentlik namoyon qiladi?","options":["I","III","IV","II"],"correct":3,"explain":"Kislorod birikmalarida odatda ikki valentli bo'ladi, masalan H₂O, CaO."}]},"en":{"title":"Oxygen","intro":"Every breath you take, every campfire and even a rusting nail depend on one element. That element is oxygen, the most widespread element on our planet. Let's get to know it.","blocks":[{"h":"Where oxygen is found","p":"In nature oxygen exists both as a free substance and inside compounds. Free oxygen (O₂) is part of the air, while bound oxygen is found in water, sand, rocks, minerals and living things. Almost half of the mass of the Earth's crust is oxygen.","items":["In air: about 21% O₂ by volume","In water: about 89% of the mass of water is oxygen","In the Earth's crust: almost half of its mass (sand SiO₂, limestone CaCO₃, iron ores)","In living organisms: in proteins, carbohydrates and fats"],"visual":{"type":"chart","kind":"crust"}},{"h":"How it was discovered","p":"In the 1770s the Swedish chemist C. Scheele and the English scientist J. Priestley obtained oxygen independently of each other. Priestley heated mercury oxide and collected a gas that made a candle flame burn very brightly. The French scientist A. Lavoisier explained the role of this gas in burning and breathing and named it 'oxygenium' (acid-former), which gives the symbol O."},{"h":"The oxygen atom","p":"Oxygen is number 8 in the periodic table: the nuclear charge is +8 and the atom has 8 electrons. Its relative atomic mass is 16. In its compounds oxygen is almost always divalent (valency II).","formula":"O: atomic number 8, Ar(O) = 16, valency II","visual":{"type":"atom3d","el":"O"}},{"h":"Element versus simple substance","p":"The word 'oxygen' is used in two senses. When we talk about the oxygen in water or sand, we mean the element. The gas we breathe is a simple substance made of two-atom O₂ molecules.","items":["Element: O atoms inside H₂O, CO₂, CaCO₃","Simple substance: O₂ gas, Mr(O₂) = 2 × 16 = 32"]},{"h":"Worked example: oxygen in water","p":"To find the mass fraction of an element in a compound, divide the mass of its atoms by the mass of the whole molecule.","formula":"ω(O) = Ar(O) · n / Mr(H₂O)","items":["Mr(H₂O) = 2 × 1 + 16 = 18","Mass of oxygen atoms: 1 × 16 = 16","ω(O) = 16 / 18 ≈ 0.889","Answer: about 88.9% of the mass of water is oxygen"]},{"h":"Remember","items":["Oxygen is the most abundant element in the Earth's crust","Symbol O, Ar = 16, valency II in compounds","The free simple substance is O₂ (Mr = 32)","Scheele and Priestley discovered oxygen in the 1770s; Lavoisier named it"]}],"quiz":[{"q":"What is the relative atomic mass of oxygen?","options":["8","16","32","12"],"correct":1,"explain":"Ar(O) = 16; 32 is the mass of the O₂ molecule."},{"q":"In which sentence is oxygen meant as a simple substance?","options":["Sand contains oxygen","Water contains oxygen","Fish breathe oxygen dissolved in water","Sugar contains oxygen"],"correct":2,"explain":"Fish breathe O₂ gas; the other sentences are about the element."},{"q":"What valency does oxygen usually show in compounds?","options":["I","III","IV","II"],"correct":3,"explain":"Oxygen is normally divalent in compounds, for example in H₂O and CaO."}]},"ru":{"title":"Кислород","intro":"Каждый вдох, каждый костёр и даже ржавеющий гвоздь связаны с одним элементом. Это кислород – самый распространённый элемент на нашей планете. Давайте познакомимся с ним поближе.","blocks":[{"h":"Где встречается кислород","p":"В природе кислород встречается и в свободном виде, и в составе соединений. Свободный кислород (O₂) входит в состав воздуха, а связанный – в состав воды, песка, горных пород, минералов и живых организмов. Почти половина массы земной коры приходится на кислород.","items":["В воздухе: около 21% O₂ по объёму","В воде: около 89% массы воды составляет кислород","В земной коре: почти половина массы (песок SiO₂, известняк CaCO₃, железные руды)","В живых организмах: в белках, углеводах и жирах"],"visual":{"type":"chart","kind":"crust"}},{"h":"История открытия","p":"В 1770-х годах шведский химик К. Шееле и английский учёный Дж. Пристли независимо друг от друга получили кислород. Пристли нагревал оксид ртути и собрал газ, в котором пламя свечи горело очень ярко. Французский учёный А. Лавуазье объяснил роль этого газа в горении и дыхании и назвал его «oxygenium» (рождающий кислоты) – отсюда символ O."},{"h":"Атом кислорода","p":"Кислород занимает 8-е место в периодической системе: заряд ядра +8, в атоме 8 электронов. Его относительная атомная масса равна 16. В соединениях кислород, как правило, двухвалентен.","formula":"O: порядковый номер 8, Ar(O) = 16, валентность II","visual":{"type":"atom3d","el":"O"}},{"h":"Элемент и простое вещество","p":"Слово «кислород» употребляется в двух смыслах. Говоря о кислороде в составе воды или песка, мы имеем в виду элемент. Газ, которым мы дышим, – это простое вещество из двухатомных молекул O₂.","items":["Элемент: атомы O в составе H₂O, CO₂, CaCO₃","Простое вещество: газ O₂, Mr(O₂) = 2 · 16 = 32"]},{"h":"Пример: кислород в воде","p":"Чтобы найти массовую долю элемента в соединении, массу его атомов делят на массу всей молекулы.","formula":"ω(O) = Ar(O) · n / Mr(H₂O)","items":["Mr(H₂O) = 2 · 1 + 16 = 18","Масса атомов кислорода: 1 · 16 = 16","ω(O) = 16 / 18 ≈ 0,889","Ответ: около 88,9% массы воды составляет кислород"]},{"h":"Запомните","items":["Кислород – самый распространённый элемент земной коры","Символ O, Ar = 16, в соединениях валентность II","Свободное простое вещество – O₂ (Mr = 32)","Кислород открыли Шееле и Пристли в 1770-х годах, название дал Лавуазье"]}],"quiz":[{"q":"Чему равна относительная атомная масса кислорода?","options":["8","16","32","12"],"correct":1,"explain":"Ar(O) = 16, а 32 – это масса молекулы O₂."},{"q":"В каком предложении речь идёт о кислороде как простом веществе?","options":["В песке есть кислород","В воде есть кислород","Рыбы дышат кислородом, растворённым в воде","В сахаре есть кислород"],"correct":2,"explain":"Рыбы дышат газом O₂, в остальных случаях речь об элементе."},{"q":"Какую валентность обычно проявляет кислород в соединениях?","options":["I","III","IV","II"],"correct":3,"explain":"В соединениях кислород обычно двухвалентен, например в H₂O и CaO."}]}},{"id":"t18","num":18,"icon":"🧪","uz":{"title":"Kislorod – oddiy modda. Olinishi","intro":"Kislorod elementi ikki xil oddiy modda hosil qiladi: biz nafas oladigan kislorod va o'tkir hidli ozon. Bu darsda ularning xossalarini va kislorodni laboratoriya hamda zavodda qanday olishni o'rganamiz. Oxirida kislorod olish bo'yicha amaliy ishni ham ko'rib chiqamiz.","blocks":[{"h":"Kislorodning fizik xossalari","p":"Bitta element bir necha oddiy modda hosil qilishi allotropiya deyiladi; kislorod uchun bular O₂ va O₃. Oddiy sharoitda O₂ – rangsiz, hidsiz va ta'msiz gaz, havodan biroz og'ir. U suvda kam eriydi, ammo shu oz miqdor ham baliqlarning nafas olishi uchun yetarli. Juda sovitilganda O₂ havorang suyuqlikka aylanadi va magnitga tortiladi.","table":{"head":["Xossa","Kislorod O₂","Ozon O₃"],"rows":[["Rangi","rangsiz (suyuqligi havorang)","och moviy"],["Hidi","hidsiz","o'tkir, o'ziga xos"],["Qaynash harorati","−183 °C","−112 °C"],["1 l massasi (n.sh.)","1,43 g","2,14 g"],["Suvda eruvchanligi","kam","O₂ dan ancha yaxshi"]]},"visual":{"type":"molecule3d","mol":"O2"}},{"h":"Ozon","p":"Kisloroddan elektr uchquni o'tkazilganda yoki chaqmoq chaqqanda ozon hosil bo'ladi; momaqaldiroqdan keyingi «yangi» hid shundan. Stratosferada ozon Quyoshning ultrabinafsha nurlari ta'sirida hosil bo'ladi va Yerdagi hayotni bu xavfli nurlardan himoya qiluvchi qatlam yaratadi. Ozon kuchli oksidlovchi: u bakteriyalarni o'ldiradi, shuning uchun suv va havoni zararsizlantirishda ishlatiladi, lekin ko'p miqdorda zaharli.","formula":"3O₂ → 2O₃ (elektr razryadi)","visual":{"type":"molecule3d","mol":"O3"}},{"h":"Laboratoriyada olinishi va katalizator","p":"Laboratoriyada kislorod tarkibida kislorod ko'p bo'lgan murakkab moddalarni parchalab olinadi. Vodorod peroksid parchalanishini qora kukun – marganes(IV) oksid MnO₂ keskin tezlashtiradi, o'zi esa sarflanmaydi. Reaksiyani tezlashtirib, o'zi o'zgarmay qoladigan moddalar katalizatorlar, bunday jarayon esa kataliz deyiladi.","items":["2H₂O₂ → 2H₂O + O₂ (katalizator MnO₂)","2KMnO₄ → K₂MnO₄ + MnO₂ + O₂ (qizdirilganda)","2KClO₃ → 2KCl + 3O₂ (qizdirilganda, MnO₂ ishtirokida)","2NaNO₃ → 2NaNO₂ + O₂ (qizdirilganda)"]},{"h":"Sanoatda olinishi","p":"Zavodlarda kislorod asosan havodan olinadi. Havo kuchli sovitilib suyuqlikka aylantiriladi, so'ng asta isitiladi: azot −196 °C da avval bug'lanib chiqadi, kislorod esa −183 °C gacha suyuq qoladi. Juda toza kislorod kerak bo'lsa, suvni elektr toki bilan parchalash (elektroliz) usuli qo'llanadi.","formula":"2H₂O → 2H₂ + O₂ (elektr toki)","visual":{"type":"diagram","kind":"electrolysis"}},{"h":"Amaliy ish: kislorod olish va xossalarini sinash","p":"Bu tajribada kislorod vodorod peroksiddan olinadi va uning yonishga yordam berishi tekshiriladi. Ishni himoya ko'zoynagida, o'qituvchi nazoratida bajaring.","items":["Probirka, gaz o'tkazuvchi nay va tiqindan asbob yig'ing va germetikligini tekshiring","Probirkaga uchdan bir qismigacha H₂O₂ eritmasi quyib, ozgina MnO₂ qo'shing va darhol tiqin bilan berkiting","Ajralayotgan gazni suv ostida (suvni siqib chiqarish usulida) yoki og'zi yuqoriga qaragan idishga yig'ing, chunki O₂ havodan og'ir","Cho'g'langan cho'pni idishga tushiring: u yana alangalanib ketadi – bu kislorodni aniqlash usuli","Cho'g'langan ko'mirni kislorodga tushiring, yonib bo'lgach ohakli suv qo'shib chayqating: suv loyqalanadi, demak CO₂ hosil bo'lgan"]},{"h":"Esda tuting","items":["Kislorod ikki allotropik shakl hosil qiladi: O₂ va O₃","O₂ – rangsiz, hidsiz, havodan biroz og'ir, suvda kam eriydigan gaz","Laboratoriyada O₂ H₂O₂, KMnO₄, KClO₃ ni parchalab, sanoatda esa suyuq havodan olinadi","Katalizator reaksiyani tezlashtiradi, lekin o'zi sarflanmaydi"]}],"quiz":[{"q":"Vodorod peroksid parchalanishida MnO₂ qanday vazifani bajaradi?","options":["Katalizator","Reaksiya mahsuloti","Erituvchi","Yoqilg'i"],"correct":0,"explain":"MnO₂ reaksiyani tezlashtiradi va o'zi sarflanmay qoladi."},{"q":"Idishda kislorod borligini qanday aniqlash mumkin?","options":["Ohakli suv loyqalanadi","Cho'g'langan cho'p alangalanib ketadi","Lakmus qizaradi","Gaz o'tkir hid chiqaradi"],"correct":1,"explain":"Kislorodda cho'g'langan cho'p yana yonib ketadi."},{"q":"Sanoatda kislorod asosan nimadan olinadi?","options":["Kaliy permanganatdan","Ozondan","Suyuq havodan","Vodorod peroksiddan"],"correct":2,"explain":"Suyuq havo bug'latilganda azot avval ajraladi, kislorod esa qoladi."}]},"en":{"title":"Oxygen as a simple substance. Preparation","intro":"The element oxygen forms two different simple substances: the oxygen we breathe and sharp-smelling ozone. In this lesson we study their properties and how oxygen is made in the laboratory and in industry. At the end we look at a practical experiment for obtaining oxygen.","blocks":[{"h":"Physical properties of oxygen","p":"When one element forms several simple substances, this is called allotropy; for oxygen these are O₂ and O₃. Under normal conditions O₂ is a colourless, odourless, tasteless gas that is slightly heavier than air. It dissolves poorly in water, but even this small amount is enough for fish to breathe. When strongly cooled, O₂ becomes a pale blue liquid that is attracted by a magnet.","table":{"head":["Property","Oxygen O₂","Ozone O₃"],"rows":[["Colour","colourless (pale blue liquid)","pale blue"],["Smell","none","sharp, characteristic"],["Boiling point","−183 °C","−112 °C"],["Mass of 1 L (STP)","1.43 g","2.14 g"],["Solubility in water","low","much higher than O₂"]]},"visual":{"type":"molecule3d","mol":"O2"}},{"h":"Ozone","p":"Ozone forms when an electric spark passes through oxygen or when lightning strikes; that is the 'fresh' smell after a thunderstorm. In the stratosphere ozone is produced by the Sun's ultraviolet rays and forms a layer that shields life on Earth from this dangerous radiation. Ozone is a strong oxidiser that kills bacteria, so it is used to disinfect water and air, but in large amounts it is poisonous.","formula":"3O₂ → 2O₃ (electric discharge)","visual":{"type":"molecule3d","mol":"O3"}},{"h":"Laboratory preparation and catalysts","p":"In the laboratory oxygen is obtained by decomposing compounds rich in oxygen. A black powder, manganese(IV) oxide MnO₂, greatly speeds up the decomposition of hydrogen peroxide and is not used up itself. Substances that speed up a reaction and remain unchanged are called catalysts, and such a process is called catalysis.","items":["2H₂O₂ → 2H₂O + O₂ (MnO₂ catalyst)","2KMnO₄ → K₂MnO₄ + MnO₂ + O₂ (on heating)","2KClO₃ → 2KCl + 3O₂ (on heating, with MnO₂)","2NaNO₃ → 2NaNO₂ + O₂ (on heating)"]},{"h":"Industrial production","p":"In industry oxygen is mainly obtained from air. Air is strongly cooled until it becomes liquid and is then slowly warmed: nitrogen boils off first at −196 °C, while oxygen stays liquid until −183 °C. When very pure oxygen is needed, water is split by electric current (electrolysis).","formula":"2H₂O → 2H₂ + O₂ (electric current)","visual":{"type":"diagram","kind":"electrolysis"}},{"h":"Practical work: obtaining oxygen and testing it","p":"In this experiment oxygen is produced from hydrogen peroxide and its ability to support burning is tested. Wear safety goggles and work under the teacher's supervision.","items":["Assemble a test tube, a stopper and a gas delivery tube, and check that the set-up is airtight","Fill the test tube one third with H₂O₂ solution, add a little MnO₂ and close it at once","Collect the gas over water (by displacing water) or in a vessel held mouth up, because O₂ is heavier than air","Put a glowing splint into the vessel: it bursts into flame, which is the test for oxygen","Lower glowing charcoal into oxygen; after it burns, add limewater and shake: the limewater turns milky, showing that CO₂ formed"]},{"h":"Remember","items":["Oxygen forms two allotropes: O₂ and O₃","O₂ is a colourless, odourless gas, slightly heavier than air and poorly soluble in water","In the lab O₂ is made by decomposing H₂O₂, KMnO₄ or KClO₃; in industry it comes from liquid air","A catalyst speeds up a reaction without being used up"]}],"quiz":[{"q":"What is the role of MnO₂ in the decomposition of hydrogen peroxide?","options":["Catalyst","Reaction product","Solvent","Fuel"],"correct":0,"explain":"MnO₂ speeds up the reaction and is not consumed."},{"q":"How can you show that a vessel contains oxygen?","options":["Limewater turns milky","A glowing splint bursts into flame","Litmus turns red","The gas has a sharp smell"],"correct":1,"explain":"A glowing splint relights in oxygen."},{"q":"What is the main industrial source of oxygen?","options":["Potassium permanganate","Ozone","Liquid air","Hydrogen peroxide"],"correct":2,"explain":"When liquid air warms up, nitrogen boils off first and oxygen remains."}]},"ru":{"title":"Кислород – простое вещество. Получение","intro":"Элемент кислород образует два разных простых вещества: кислород, которым мы дышим, и озон с резким запахом. На этом уроке мы изучим их свойства и узнаем, как кислород получают в лаборатории и на заводе. В конце разберём практическую работу по получению кислорода.","blocks":[{"h":"Физические свойства кислорода","p":"Способность одного элемента образовывать несколько простых веществ называется аллотропией; для кислорода это O₂ и O₃. При обычных условиях O₂ – бесцветный газ без запаха и вкуса, немного тяжелее воздуха. Он плохо растворяется в воде, но и этого количества хватает для дыхания рыб. При сильном охлаждении O₂ превращается в голубую жидкость, которая притягивается магнитом.","table":{"head":["Свойство","Кислород O₂","Озон O₃"],"rows":[["Цвет","бесцветный (жидкость голубая)","бледно-голубой"],["Запах","без запаха","резкий, характерный"],["Температура кипения","−183 °C","−112 °C"],["Масса 1 л (н. у.)","1,43 г","2,14 г"],["Растворимость в воде","малая","намного выше, чем у O₂"]]},"visual":{"type":"molecule3d","mol":"O2"}},{"h":"Озон","p":"Озон образуется, когда через кислород проходит электрическая искра или сверкает молния; отсюда «свежий» запах после грозы. В стратосфере озон возникает под действием ультрафиолетовых лучей Солнца и образует слой, защищающий жизнь на Земле от опасного излучения. Озон – сильный окислитель, убивающий бактерии, поэтому им обеззараживают воду и воздух, но в больших количествах он ядовит.","formula":"3O₂ → 2O₃ (электрический разряд)","visual":{"type":"molecule3d","mol":"O3"}},{"h":"Получение в лаборатории и катализаторы","p":"В лаборатории кислород получают разложением богатых кислородом сложных веществ. Чёрный порошок – оксид марганца(IV) MnO₂ – резко ускоряет разложение пероксида водорода и сам при этом не расходуется. Вещества, которые ускоряют реакцию и остаются неизменными, называются катализаторами, а такой процесс – катализом.","items":["2H₂O₂ → 2H₂O + O₂ (катализатор MnO₂)","2KMnO₄ → K₂MnO₄ + MnO₂ + O₂ (при нагревании)","2KClO₃ → 2KCl + 3O₂ (при нагревании, с MnO₂)","2NaNO₃ → 2NaNO₂ + O₂ (при нагревании)"]},{"h":"Получение в промышленности","p":"На заводах кислород получают в основном из воздуха. Воздух сильно охлаждают до жидкого состояния, а затем медленно нагревают: азот испаряется первым при −196 °C, а кислород остаётся жидким до −183 °C. Если нужен очень чистый кислород, воду разлагают электрическим током (электролиз).","formula":"2H₂O → 2H₂ + O₂ (электрический ток)","visual":{"type":"diagram","kind":"electrolysis"}},{"h":"Практическая работа: получение кислорода и изучение его свойств","p":"В этом опыте кислород получают из пероксида водорода и проверяют, как он поддерживает горение. Работайте в защитных очках под наблюдением учителя.","items":["Соберите прибор из пробирки, пробки и газоотводной трубки и проверьте его на герметичность","Налейте в пробирку на треть раствор H₂O₂, добавьте немного MnO₂ и сразу закройте пробкой","Собирайте газ под водой (вытеснением воды) или в сосуд, обращённый горлышком вверх, так как O₂ тяжелее воздуха","Внесите в сосуд тлеющую лучинку: она вспыхивает – так распознают кислород","Внесите в кислород раскалённый уголь, после сгорания добавьте известковую воду и встряхните: она мутнеет, значит, образовался CO₂"]},{"h":"Запомните","items":["Кислород образует две аллотропные формы: O₂ и O₃","O₂ – бесцветный газ без запаха, немного тяжелее воздуха, плохо растворим в воде","В лаборатории O₂ получают разложением H₂O₂, KMnO₄, KClO₃, в промышленности – из жидкого воздуха","Катализатор ускоряет реакцию, но сам не расходуется"]}],"quiz":[{"q":"Какую роль играет MnO₂ при разложении пероксида водорода?","options":["Катализатор","Продукт реакции","Растворитель","Топливо"],"correct":0,"explain":"MnO₂ ускоряет реакцию и сам не расходуется."},{"q":"Как доказать, что в сосуде находится кислород?","options":["Известковая вода мутнеет","Тлеющая лучинка вспыхивает","Лакмус краснеет","Газ имеет резкий запах"],"correct":1,"explain":"В кислороде тлеющая лучинка снова загорается."},{"q":"Из чего в основном получают кислород в промышленности?","options":["Из перманганата калия","Из озона","Из жидкого воздуха","Из пероксида водорода"],"correct":2,"explain":"При испарении жидкого воздуха сначала уходит азот, а кислород остаётся."}]}},{"id":"t19","num":19,"icon":"✨","uz":{"title":"Kislorodning kimyoviy xossalari. Ahamiyati va ishlatilishi","intro":"Kislorod juda faol metallmas: u ko'pchilik oddiy va murakkab moddalar bilan birikadi. Bunday reaksiyalarda oksidlar hosil bo'ladi va ko'pincha issiqlik va yorug'lik ajraladi. Kislorodsiz na nafas olish, na yonish, na zamonaviy sanoat bo'lardi.","blocks":[{"h":"Oksidlanish va oksidlar","p":"Moddaning kislorod bilan birikish reaksiyasi oksidlanish deyiladi. Ikki elementdan iborat bo'lib, ulardan biri kislorod bo'lgan murakkab moddalar oksidlar deb ataladi. Masalan, MgO, CO₂, SO₂, P₂O₅ – oksidlar.","formula":"Oddiy modda + O₂ → oksid"},{"h":"Metallar bilan reaksiyalar","p":"Kislorod oltin, platina va ularga o'xshash juda passiv metallardan tashqari deyarli barcha metallar bilan reaksiyaga kirishadi. Magniy ko'zni qamashtiradigan oq alanga bilan yonadi, temir sim esa kislorodda uchqunlar sochib yonadi.","items":["2Mg + O₂ → 2MgO (magniy oksid)","4Al + 3O₂ → 2Al₂O₃ (aluminiy oksid)","3Fe + 2O₂ → Fe₃O₄ (temir qo'sh oksidi, temir kuyindisi)","2Cu + O₂ → 2CuO (qizdirilganda qora mis(II) oksid)"]},{"h":"Metallmaslar va murakkab moddalar bilan reaksiyalar","p":"Ko'mir, oltingugurt, fosfor kabi metallmaslar ham kislorodda yonib oksidlar hosil qiladi; havodagiga qaraganda toza kislorodda ular ancha shiddatli yonadi. Murakkab moddalar yonganda esa ular tarkibidagi har bir elementning oksidi hosil bo'ladi.","items":["C + O₂ → CO₂ (ko'mir yonadi)","S + O₂ → SO₂ (ko'kimtir alanga, o'tkir hidli gaz)","4P + 5O₂ → 2P₂O₅ (oq tutun)","CH₄ + 2O₂ → CO₂ + 2H₂O","2H₂S + 3O₂ → 2SO₂ + 2H₂O"],"visual":{"type":"reaction","id":"c_o2"}},{"h":"Namuna: ko'mirni yoqish uchun qancha kislorod kerak","p":"6 g ko'mir (uglerod) to'liq yonishi uchun normal sharoitda qancha hajm kislorod kerakligini hisoblaymiz.","formula":"C + O₂ → CO₂","items":["n(C) = m / M = 6 g / 12 g/mol = 0,5 mol","Tenglamaga ko'ra n(O₂) = n(C) = 0,5 mol","V(O₂) = n · 22,4 l/mol = 0,5 · 22,4 = 11,2 l","Javob: 11,2 l kislorod"]},{"h":"Biologik ahamiyati va ishlatilishi","p":"Kislorod hayot uchun eng muhim elementlardan biri: inson tanasi massasining taxminan 65% i kisloroddan iborat. Tirik organizmlar nafas olganda kislorod yordamida oziq moddalarni oksidlab energiya oladi; o'lik qoldiqlarning chirishi ham kislorod ishtirokida boradi. Shu bilan birga kislorod texnikada keng qo'llanadi.","items":["Tibbiyotda: og'ir bemorlarga nafas berish uchun","Suv ostida, tog'da, kosmosda: nafas olish apparatlarida","Metallurgiyada: cho'yan va po'lat olishda","Metallarni kesish va payvandlashda yuqori harorat olish uchun","Raketa dvigatellarida yoqilg'ini oksidlovchi sifatida"]},{"h":"Esda tuting","items":["Moddaning kislorod bilan birikishi oksidlanish deyiladi","Oksid – biri kislorod bo'lgan ikki elementli birikma","Kislorod ko'pchilik metallar, metallmaslar va murakkab moddalar bilan reaksiyaga kirishadi","Nafas olish, chirish va yonish – kislorod ishtirokidagi jarayonlar"]}],"quiz":[{"q":"Fosfor kislorodda yonganda qaysi modda hosil bo'ladi?","options":["PO","P₂O₅","P₂O₃","PH₃"],"correct":1,"explain":"4P + 5O₂ → 2P₂O₅, bu oq tutun ko'rinishida ko'rinadi."},{"q":"Quyidagilardan qaysi biri oksid?","options":["KMnO₄","H₂SO₄","CaO","NaCl"],"correct":2,"explain":"CaO faqat ikki elementdan iborat va ulardan biri kislorod."},{"q":"12 g uglerod to'liq yonishi uchun n.sh. da necha litr O₂ kerak?","options":["22,4 l","11,2 l","44,8 l","5,6 l"],"correct":0,"explain":"12 g C = 1 mol, unga 1 mol O₂, ya'ni 22,4 l kerak."}]},"en":{"title":"Chemical properties of oxygen. Importance and uses","intro":"Oxygen is a very active non-metal that combines with most simple and complex substances. These reactions produce oxides and often release heat and light. Without oxygen there would be no breathing, no burning and no modern industry.","blocks":[{"h":"Oxidation and oxides","p":"A reaction in which a substance combines with oxygen is called oxidation. Compounds made of two elements, one of which is oxygen, are called oxides. For example, MgO, CO₂, SO₂ and P₂O₅ are oxides.","formula":"Simple substance + O₂ → oxide"},{"h":"Reactions with metals","p":"Oxygen reacts with almost all metals except gold, platinum and similar very unreactive metals. Magnesium burns with a dazzling white flame, and an iron wire burns in oxygen throwing out sparks.","items":["2Mg + O₂ → 2MgO (magnesium oxide)","4Al + 3O₂ → 2Al₂O₃ (aluminium oxide)","3Fe + 2O₂ → Fe₃O₄ (iron scale, a mixed oxide)","2Cu + O₂ → 2CuO (black copper(II) oxide on heating)"]},{"h":"Reactions with non-metals and compounds","p":"Non-metals such as carbon, sulfur and phosphorus also burn in oxygen to form oxides; in pure oxygen they burn much more fiercely than in air. When a compound burns, each of its elements forms an oxide.","items":["C + O₂ → CO₂ (charcoal burns)","S + O₂ → SO₂ (bluish flame, sharp-smelling gas)","4P + 5O₂ → 2P₂O₅ (white smoke)","CH₄ + 2O₂ → CO₂ + 2H₂O","2H₂S + 3O₂ → 2SO₂ + 2H₂O"],"visual":{"type":"reaction","id":"c_o2"}},{"h":"Worked example: oxygen needed to burn charcoal","p":"Let's calculate the volume of oxygen at STP needed to burn 6 g of carbon completely.","formula":"C + O₂ → CO₂","items":["n(C) = m / M = 6 g / 12 g/mol = 0.5 mol","From the equation n(O₂) = n(C) = 0.5 mol","V(O₂) = n × 22.4 L/mol = 0.5 × 22.4 = 11.2 L","Answer: 11.2 L of oxygen"]},{"h":"Biological importance and uses","p":"Oxygen is one of the most important elements for life: about 65% of the mass of the human body is oxygen. Living things use oxygen in respiration to oxidise food and release energy, and the decay of dead remains also needs oxygen. Oxygen is also widely used in technology.","items":["Medicine: helping seriously ill patients breathe","Under water, high in the mountains and in space: in breathing equipment","Metallurgy: making cast iron and steel","Cutting and welding metals with a very hot flame","Rocket engines: as the oxidiser for fuel"]},{"h":"Remember","items":["The combination of a substance with oxygen is called oxidation","An oxide is a two-element compound in which one element is oxygen","Oxygen reacts with most metals, non-metals and many compounds","Respiration, decay and burning are all processes involving oxygen"]}],"quiz":[{"q":"What forms when phosphorus burns in oxygen?","options":["PO","P₂O₅","P₂O₃","PH₃"],"correct":1,"explain":"4P + 5O₂ → 2P₂O₅, seen as white smoke."},{"q":"Which of these is an oxide?","options":["KMnO₄","H₂SO₄","CaO","NaCl"],"correct":2,"explain":"CaO consists of only two elements, one of which is oxygen."},{"q":"How many litres of O₂ (STP) are needed to burn 12 g of carbon completely?","options":["22.4 L","11.2 L","44.8 L","5.6 L"],"correct":0,"explain":"12 g of C is 1 mol, which needs 1 mol of O₂, i.e. 22.4 L."}]},"ru":{"title":"Химические свойства кислорода. Значение и применение","intro":"Кислород – очень активный неметалл, который соединяется с большинством простых и сложных веществ. В таких реакциях образуются оксиды и часто выделяются тепло и свет. Без кислорода не было бы ни дыхания, ни горения, ни современной промышленности.","blocks":[{"h":"Окисление и оксиды","p":"Реакция соединения вещества с кислородом называется окислением. Сложные вещества, состоящие из двух элементов, один из которых кислород, называются оксидами. Например, MgO, CO₂, SO₂, P₂O₅ – оксиды.","formula":"Простое вещество + O₂ → оксид"},{"h":"Реакции с металлами","p":"Кислород реагирует почти со всеми металлами, кроме золота, платины и подобных им очень малоактивных металлов. Магний горит ослепительно белым пламенем, а железная проволока сгорает в кислороде, разбрасывая искры.","items":["2Mg + O₂ → 2MgO (оксид магния)","4Al + 3O₂ → 2Al₂O₃ (оксид алюминия)","3Fe + 2O₂ → Fe₃O₄ (железная окалина, смешанный оксид)","2Cu + O₂ → 2CuO (чёрный оксид меди(II) при нагревании)"]},{"h":"Реакции с неметаллами и сложными веществами","p":"Неметаллы – уголь, сера, фосфор – тоже сгорают в кислороде с образованием оксидов; в чистом кислороде они горят гораздо энергичнее, чем на воздухе. При горении сложного вещества каждый его элемент образует оксид.","items":["C + O₂ → CO₂ (горит уголь)","S + O₂ → SO₂ (голубоватое пламя, газ с резким запахом)","4P + 5O₂ → 2P₂O₅ (белый дым)","CH₄ + 2O₂ → CO₂ + 2H₂O","2H₂S + 3O₂ → 2SO₂ + 2H₂O"],"visual":{"type":"reaction","id":"c_o2"}},{"h":"Пример: сколько кислорода нужно для сжигания угля","p":"Рассчитаем объём кислорода (н. у.), необходимый для полного сгорания 6 г углерода.","formula":"C + O₂ → CO₂","items":["n(C) = m / M = 6 г / 12 г/моль = 0,5 моль","По уравнению n(O₂) = n(C) = 0,5 моль","V(O₂) = n · 22,4 л/моль = 0,5 · 22,4 = 11,2 л","Ответ: 11,2 л кислорода"]},{"h":"Биологическое значение и применение","p":"Кислород – один из важнейших для жизни элементов: около 65% массы тела человека составляет кислород. При дыхании живые организмы с помощью кислорода окисляют питательные вещества и получают энергию; гниение остатков организмов тоже идёт с участием кислорода. Кроме того, кислород широко применяется в технике.","items":["В медицине: для дыхания тяжелобольных","Под водой, в горах и в космосе: в дыхательных аппаратах","В металлургии: при получении чугуна и стали","Для резки и сварки металлов очень горячим пламенем","В ракетных двигателях: как окислитель топлива"]},{"h":"Запомните","items":["Соединение вещества с кислородом называется окислением","Оксид – соединение двух элементов, одним из которых является кислород","Кислород реагирует с большинством металлов, неметаллов и многими сложными веществами","Дыхание, гниение и горение – процессы с участием кислорода"]}],"quiz":[{"q":"Что образуется при сгорании фосфора в кислороде?","options":["PO","P₂O₅","P₂O₃","PH₃"],"correct":1,"explain":"4P + 5O₂ → 2P₂O₅, он виден как белый дым."},{"q":"Какое из веществ является оксидом?","options":["KMnO₄","H₂SO₄","CaO","NaCl"],"correct":2,"explain":"CaO состоит только из двух элементов, один из которых кислород."},{"q":"Сколько литров O₂ (н. у.) нужно для полного сгорания 12 г углерода?","options":["22,4 л","11,2 л","44,8 л","5,6 л"],"correct":0,"explain":"12 г C – это 1 моль, ему нужен 1 моль O₂, то есть 22,4 л."}]}},{"id":"t20","num":20,"icon":"🌍","uz":{"title":"Kislorodning tabiatda aylanishi. Havo va uni muhofaza qilish","intro":"Har kuni milliardlab tirik mavjudotlar kislorod bilan nafas oladi, lekin havodagi kislorod tugab qolmaydi. Buning sababi – tabiatdagi kislorod aylanishi. Bu darsda havo nimalardan iboratligini va uni qanday toza saqlash mumkinligini bilib olamiz.","blocks":[{"h":"Kislorod Yerning qayerlarida bor","p":"Kislorod Yerning barcha qobiqlarida bor: litosferada (tog' jinslari va minerallarda), gidrosferada (suvda), atmosferada (O₂ gazi) va biosferada (tirik organizmlarda). Eng ko'p kislorod litosferada, lekin u yerdagi kislorod aylanishda juda sekin ishtirok etadi. Kislorod almashinuvi asosan havo, suv va tirik organizmlar orasida boradi."},{"h":"Kislorodning aylanishi","p":"Yashil o'simliklar quyosh nuri ta'sirida karbonat angidrid va suvdan organik moddalar hosil qilib, havoga kislorod chiqaradi – bu fotosintez. Nafas olish, chirish va yonishda esa kislorod sarflanadi va yana CO₂ hamda suv hosil bo'ladi. Bu ikki qarama-qarshi jarayon havodagi kislorod miqdorini deyarli o'zgarmas saqlaydi.","formula":"6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ (fotosintez, yorug'lik)","items":["Nafas olish: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O","Chirish va yonish ham kislorodni sarflab, CO₂ qaytaradi","Ohaktoshlar (CaCO₃) orqali kislorodning bir qismi uzoq vaqt litosferada saqlanadi"],"visual":{"type":"diagram","kind":"oxygen_cycle"}},{"h":"Havoning tarkibi","p":"Havo – gazlarning tabiiy aralashmasi. Azot, kislorod va inert gazlar havoning doimiy qismlari bo'lib, ularning ulushi hamma joyda deyarli bir xil. Karbonat angidrid, suv bug'i va chang miqdori esa joy va sharoitga qarab o'zgaradi. Normal sharoitda 1 l havoning massasi taxminan 1,29 g.","table":{"head":["Gaz","Hajmiy ulushi, %"],"rows":[["Azot N₂","≈ 78"],["Kislorod O₂","≈ 21"],["Argon Ar","≈ 0,93"],["Karbonat angidrid CO₂","≈ 0,04"],["Boshqa gazlar (Ne, He, Kr, Xe, H₂)","juda oz"]]},"visual":{"type":"chart","kind":"air"}},{"h":"Namuna: sinf xonasidagi kislorod","p":"Uzunligi 8 m, eni 6 m va balandligi 3 m bo'lgan sinf xonasida qancha kislorod borligini hisoblaymiz.","items":["Xona hajmi: V = 8 · 6 · 3 = 144 m³","Kislorodning hajmiy ulushi ≈ 21% = 0,21","V(O₂) = 144 · 0,21 ≈ 30 m³","Javob: xonada taxminan 30 m³ kislorod bor, shuning uchun xonani muntazam shamollatish kerak"]},{"h":"Havoni ifloslanishdan saqlash","p":"Avtomobillar, zavodlar, issiqlik elektr stansiyalari va chiqindilarni yoqish havoga is gazi CO, oltingugurt dioksidi SO₂, azot oksidlari va chang chiqaradi. Bu moddalar nafas yo'llariga zarar beradi va kislotali yomg'irlarga sabab bo'ladi. Havoni toza saqlash har birimizning vazifamiz.","items":["Zavod mo'rilariga tozalovchi filtrlar o'rnatish","Chiqindisiz texnologiyalar va toza energiya manbalaridan foydalanish","Daraxt ekish va o'rmonlarni asrash","Jamoat transporti, velosipeddan ko'proq foydalanish, chiqindilarni yoqmaslik"]},{"h":"Esda tuting","items":["Kislorod aylanishi fotosintez hamda nafas olish, chirish va yonish jarayonlariga asoslangan","Havo – aralashma: ≈78% N₂, ≈21% O₂, ≈1% Ar va boshqa gazlar","Havoning doimiy qismlari: azot, kislorod, inert gazlar","Havoni ifloslanishdan saqlash – butun insoniyatning vazifasi"]}],"quiz":[{"q":"Havodagi kislorod zaxirasini qaysi jarayon to'ldirib turadi?","options":["Nafas olish","Yonish","Chirish","Fotosintez"],"correct":3,"explain":"Fotosintezda yashil o'simliklar havoga O₂ chiqaradi."},{"q":"Havoda hajm bo'yicha eng ko'p bo'lgan gaz qaysi?","options":["Azot","Kislorod","Argon","Karbonat angidrid"],"correct":0,"explain":"Havoning taxminan 78% i azotdan iborat."},{"q":"Quyidagilardan qaysi biri havoning o'zgaruvchan tarkibiy qismi?","options":["Azot","Argon","Suv bug'i","Kislorod"],"correct":2,"explain":"Suv bug'i miqdori ob-havo va joyga qarab o'zgaradi."}]},"en":{"title":"The oxygen cycle. Air and its protection","intro":"Every day billions of living things breathe oxygen, yet the oxygen in the air never runs out. The reason is the oxygen cycle in nature. In this lesson we find out what air is made of and how we can keep it clean.","blocks":[{"h":"Where oxygen is on Earth","p":"Oxygen is present in all of the Earth's shells: the lithosphere (rocks and minerals), the hydrosphere (water), the atmosphere (O₂ gas) and the biosphere (living things). Most oxygen is in the lithosphere, but that oxygen takes part in the cycle very slowly. Oxygen exchange mainly happens between air, water and living organisms."},{"h":"The oxygen cycle","p":"Using sunlight, green plants make organic substances from carbon dioxide and water and release oxygen into the air; this is photosynthesis. Respiration, decay and burning use up oxygen and produce CO₂ and water again. These two opposite processes keep the amount of oxygen in the air almost constant.","formula":"6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ (photosynthesis, light)","items":["Respiration: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O","Decay and burning also consume oxygen and return CO₂","Part of the oxygen is stored for a long time in the lithosphere in limestone (CaCO₃)"],"visual":{"type":"diagram","kind":"oxygen_cycle"}},{"h":"Composition of air","p":"Air is a natural mixture of gases. Nitrogen, oxygen and the noble gases are constant components whose proportions are almost the same everywhere. The amounts of carbon dioxide, water vapour and dust vary with place and conditions. At STP, 1 L of air has a mass of about 1.29 g.","table":{"head":["Gas","Volume fraction, %"],"rows":[["Nitrogen N₂","≈ 78"],["Oxygen O₂","≈ 21"],["Argon Ar","≈ 0.93"],["Carbon dioxide CO₂","≈ 0.04"],["Other gases (Ne, He, Kr, Xe, H₂)","tiny amounts"]]},"visual":{"type":"chart","kind":"air"}},{"h":"Worked example: oxygen in a classroom","p":"Let's estimate how much oxygen there is in a classroom 8 m long, 6 m wide and 3 m high.","items":["Room volume: V = 8 × 6 × 3 = 144 m³","Volume fraction of oxygen ≈ 21% = 0.21","V(O₂) = 144 × 0.21 ≈ 30 m³","Answer: about 30 m³ of oxygen, which is why rooms need regular airing"]},{"h":"Protecting air from pollution","p":"Cars, factories, thermal power stations and burning rubbish release carbon monoxide CO, sulfur dioxide SO₂, nitrogen oxides and dust into the air. These substances harm the lungs and cause acid rain. Keeping the air clean is everyone's responsibility.","items":["Fitting cleaning filters to factory chimneys","Using waste-free technologies and clean energy sources","Planting trees and protecting forests","Using public transport and bicycles more, and not burning rubbish"]},{"h":"Remember","items":["The oxygen cycle is based on photosynthesis on one side and respiration, decay and burning on the other","Air is a mixture: ≈78% N₂, ≈21% O₂, ≈1% Ar and other gases","Constant components of air: nitrogen, oxygen, noble gases","Protecting the air from pollution is a task for all of humanity"]}],"quiz":[{"q":"Which process replenishes the oxygen in the air?","options":["Respiration","Burning","Decay","Photosynthesis"],"correct":3,"explain":"In photosynthesis green plants release O₂ into the air."},{"q":"Which gas makes up the largest part of air by volume?","options":["Nitrogen","Oxygen","Argon","Carbon dioxide"],"correct":0,"explain":"About 78% of air is nitrogen."},{"q":"Which of these is a variable component of air?","options":["Nitrogen","Argon","Water vapour","Oxygen"],"correct":2,"explain":"The amount of water vapour depends on weather and place."}]},"ru":{"title":"Круговорот кислорода. Воздух и его охрана","intro":"Каждый день миллиарды живых существ дышат кислородом, но кислород в воздухе не кончается. Причина – круговорот кислорода в природе. На этом уроке мы узнаем, из чего состоит воздух и как сохранить его чистым.","blocks":[{"h":"Где находится кислород на Земле","p":"Кислород есть во всех оболочках Земли: в литосфере (горные породы и минералы), гидросфере (вода), атмосфере (газ O₂) и биосфере (живые организмы). Больше всего кислорода в литосфере, но он участвует в круговороте очень медленно. Обмен кислородом идёт в основном между воздухом, водой и живыми организмами."},{"h":"Круговорот кислорода","p":"Зелёные растения на свету образуют органические вещества из углекислого газа и воды и выделяют в воздух кислород – это фотосинтез. При дыхании, гниении и горении кислород расходуется и снова образуются CO₂ и вода. Эти два противоположных процесса поддерживают содержание кислорода в воздухе почти постоянным.","formula":"6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ (фотосинтез, свет)","items":["Дыхание: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O","Гниение и горение тоже расходуют кислород и возвращают CO₂","Часть кислорода надолго сохраняется в литосфере в составе известняков (CaCO₃)"],"visual":{"type":"diagram","kind":"oxygen_cycle"}},{"h":"Состав воздуха","p":"Воздух – природная смесь газов. Азот, кислород и благородные газы – постоянные составные части, их доля почти везде одинакова. Количество углекислого газа, водяного пара и пыли меняется в зависимости от места и условий. При н. у. 1 л воздуха имеет массу около 1,29 г.","table":{"head":["Газ","Объёмная доля, %"],"rows":[["Азот N₂","≈ 78"],["Кислород O₂","≈ 21"],["Аргон Ar","≈ 0,93"],["Углекислый газ CO₂","≈ 0,04"],["Другие газы (Ne, He, Kr, Xe, H₂)","очень мало"]]},"visual":{"type":"chart","kind":"air"}},{"h":"Пример: кислород в классе","p":"Оценим, сколько кислорода в классе длиной 8 м, шириной 6 м и высотой 3 м.","items":["Объём комнаты: V = 8 · 6 · 3 = 144 м³","Объёмная доля кислорода ≈ 21% = 0,21","V(O₂) = 144 · 0,21 ≈ 30 м³","Ответ: около 30 м³ кислорода, поэтому класс нужно регулярно проветривать"]},{"h":"Охрана воздуха от загрязнения","p":"Автомобили, заводы, тепловые электростанции и сжигание мусора выбрасывают в воздух угарный газ CO, сернистый газ SO₂, оксиды азота и пыль. Эти вещества вредят органам дыхания и вызывают кислотные дожди. Беречь чистоту воздуха – обязанность каждого.","items":["Устанавливать очистные фильтры на заводских трубах","Применять безотходные технологии и чистые источники энергии","Сажать деревья и беречь леса","Чаще пользоваться общественным транспортом и велосипедом, не сжигать мусор"]},{"h":"Запомните","items":["Круговорот кислорода основан на фотосинтезе, с одной стороны, и дыхании, гниении и горении – с другой","Воздух – смесь: ≈78% N₂, ≈21% O₂, ≈1% Ar и другие газы","Постоянные составные части воздуха: азот, кислород, благородные газы","Защита воздуха от загрязнения – задача всего человечества"]}],"quiz":[{"q":"Какой процесс пополняет запасы кислорода в воздухе?","options":["Дыхание","Горение","Гниение","Фотосинтез"],"correct":3,"explain":"При фотосинтезе зелёные растения выделяют в воздух O₂."},{"q":"Какого газа в воздухе больше всего по объёму?","options":["Азота","Кислорода","Аргона","Углекислого газа"],"correct":0,"explain":"Около 78% воздуха составляет азот."},{"q":"Что из перечисленного – переменная составная часть воздуха?","options":["Азот","Аргон","Водяной пар","Кислород"],"correct":2,"explain":"Количество водяного пара зависит от погоды и места."}]}},{"id":"t21","num":21,"icon":"🔥","uz":{"title":"Yonish. Yoqilg'ining turlari","intro":"Olov – insoniyat o'zlashtirgan eng qadimgi kimyoviy reaksiya. Yonish bizga issiqlik, yorug'lik va energiya beradi, lekin nazoratdan chiqsa, yong'inga aylanadi. Keling, yonish qanday sodir bo'lishini va uni qanday to'xtatishni bilib olaylik.","blocks":[{"h":"Yonish nima","p":"Moddaning kislorod bilan reaksiyaga kirishib, ko'p issiqlik va yorug'lik chiqarishi yonish deyiladi. Toza kislorodda moddalar havodagidan ancha tez va shiddatli yonadi, chunki issiqlik havodagi azotni isitishga sarflanmaydi. Masalan, havoda zo'rg'a cho'g'lanib turgan cho'p toza kislorodda darhol alangalanadi."},{"h":"Yonish shartlari va alanga","p":"Yonish boshlanishi uchun uchta shart kerak: yonuvchi modda, kislorod va yetarli harorat. Modda havoda alangalanib ketishi uchun kerak bo'lgan eng past harorat alangalanish harorati deyiladi. Alanga – yonayotgan qizigan gaz va bug'lar aralashmasi.","items":["Yonuvchi modda (yoqilg'i)","Kislorod (havo)","Alangalanish haroratigacha qizdirish"],"visual":{"type":"diagram","kind":"flame"}},{"h":"Yong'inni o'chirish","p":"Yong'in – nazoratdan chiqqan yonish. Uni o'chirish uchun yonish shartlaridan kamida bittasini yo'qotish kifoya: moddani alangalanish haroratidan past darajaga sovitish yoki unga havo kirishini to'xtatish. Buning uchun suv, qum, o't o'chirgichdagi ko'pik yoki qalin mato ishlatiladi.","items":["Suv yonayotgan narsani sovitadi","Qum, qalin adyol yoki brezent havoni to'sadi","Karbonat angidridli o't o'chirgich alangani kisloroddan ajratadi","Yonayotgan neft mahsulotlari va tokdagi asboblarni suv bilan o'chirib bo'lmaydi!"]},{"h":"Yoqilg'ining turlari","p":"Yonganda foydali issiqlik beradigan moddalar yoqilg'i deyiladi. Yoqilg'i qattiq, suyuq va gazsimon bo'ladi. Qattiq yoqilg'i yonganda kul qoladi, suyuq va gazsimon yoqilg'ida bu kamchilik yo'q. O'zbekistonda ko'mir (masalan, Angren koni), neft va tabiiy gaz (masalan, Sho'rtan va Muborak konlari) qazib olinadi.","table":{"head":["Turi","Misollar"],"rows":[["Qattiq","ko'mir, torf, yog'och, slanes"],["Suyuq","neft, benzin, mazut, spirt"],["Gazsimon","tabiiy gaz, vodorod, is gazi CO"]]}},{"h":"Tabiiy gazning yonishi","p":"Uylardagi gaz plitalarida asosan metan CH₄ yonadi. Yetarli havo bo'lganda u ko'k alanga bilan to'liq yonib, karbonat angidrid va suv hosil qiladi. Gazlar uchun hajmlar nisbati tenglamadagi koeffitsientlar nisbatiga teng: masalan, 10 l metanni yoqish uchun 20 l kislorod kerak.","formula":"CH₄ + 2O₂ → CO₂ + 2H₂O","visual":{"type":"reaction","id":"ch4_o2"}},{"h":"Esda tuting","items":["Yonish – issiqlik va yorug'lik chiqishi bilan boradigan oksidlanish","Yonish uchun yoqilg'i, kislorod va alangalanish haroratigacha qizdirish kerak","Yong'inni o'chirish uchun sovitish yoki havoni to'sish kerak","Yoqilg'i qattiq, suyuq va gazsimon bo'ladi"]}],"quiz":[{"q":"Alangalanish harorati nima?","options":["Alanganing eng yuqori harorati","Modda havoda yona boshlaydigan eng past harorat","Suvning qaynash harorati","Modda suyuqlanadigan harorat"],"correct":1,"explain":"Bu modda havoda o'z-o'zidan alangalanishi uchun zarur bo'lgan eng past harorat."},{"q":"Nima uchun yonayotgan narsani qum bilan ko'mish uni o'chiradi?","options":["Qum kislorod chiqaradi","Qum yonuvchi moddani qizdiradi","Qum havo kirishini to'xtatadi","Qum alangalanish haroratini oshiradi"],"correct":2,"explain":"Kislorodsiz yonish davom eta olmaydi."},{"q":"Quyidagilardan qaysi biri gazsimon yoqilg'i?","options":["Torf","Mazut","Ko'mir","Tabiiy gaz"],"correct":3,"explain":"Tabiiy gaz (asosan metan) – gazsimon yoqilg'i."}]},"en":{"title":"Combustion. Types of fuel","intro":"Fire is the oldest chemical reaction that people learned to use. Burning gives us heat, light and energy, but when it gets out of control it becomes a dangerous fire. Let's find out how combustion happens and how to stop it.","blocks":[{"h":"What combustion is","p":"Combustion is a reaction of a substance with oxygen that releases a lot of heat and light. Substances burn much faster and more fiercely in pure oxygen than in air, because no heat is wasted on warming up nitrogen. For example, a splint that barely glows in air bursts into flame in pure oxygen."},{"h":"Conditions for burning and the flame","p":"Three conditions are needed for burning to start: a combustible substance, oxygen and a high enough temperature. The lowest temperature at which a substance catches fire in air is called its ignition temperature. A flame is a mixture of hot, burning gases and vapours.","items":["A combustible substance (fuel)","Oxygen (air)","Heating to the ignition temperature"],"visual":{"type":"diagram","kind":"flame"}},{"h":"Putting out a fire","p":"A fire is combustion that has got out of control. To put it out, it is enough to remove at least one of the conditions: cool the substance below its ignition temperature or stop air from reaching it. Water, sand, foam from an extinguisher or a thick blanket can be used.","items":["Water cools the burning material","Sand, a thick blanket or a tarpaulin block the air","A carbon dioxide extinguisher cuts the flame off from oxygen","Never use water on burning oil products or on electrical devices that are switched on!"]},{"h":"Types of fuel","p":"Substances that give useful heat when they burn are called fuels. Fuels can be solid, liquid or gaseous. Solid fuels leave ash after burning, while liquid and gaseous fuels do not. Uzbekistan produces coal (for example at the Angren deposit), oil and natural gas (for example at the Shurtan and Mubarek fields).","table":{"head":["Type","Examples"],"rows":[["Solid","coal, peat, wood, oil shale"],["Liquid","crude oil, petrol, fuel oil, alcohol"],["Gaseous","natural gas, hydrogen, carbon monoxide CO"]]}},{"h":"Burning natural gas","p":"Gas cookers at home mainly burn methane CH₄. With enough air it burns completely with a blue flame, forming carbon dioxide and water. For gases, the ratio of volumes equals the ratio of the coefficients in the equation: for example, burning 10 L of methane needs 20 L of oxygen.","formula":"CH₄ + 2O₂ → CO₂ + 2H₂O","visual":{"type":"reaction","id":"ch4_o2"}},{"h":"Remember","items":["Combustion is oxidation that releases heat and light","Burning needs fuel, oxygen and heating to the ignition temperature","To put out a fire, cool it or cut off the air","Fuels are solid, liquid or gaseous"]}],"quiz":[{"q":"What is the ignition temperature?","options":["The highest temperature of a flame","The lowest temperature at which a substance catches fire in air","The boiling point of water","The melting point of a substance"],"correct":1,"explain":"It is the minimum temperature needed for a substance to catch fire in air."},{"q":"Why does covering a burning object with sand put it out?","options":["Sand releases oxygen","Sand heats the fuel","Sand stops air from reaching it","Sand raises the ignition temperature"],"correct":2,"explain":"Without oxygen burning cannot continue."},{"q":"Which of these is a gaseous fuel?","options":["Peat","Fuel oil","Coal","Natural gas"],"correct":3,"explain":"Natural gas (mostly methane) is a gaseous fuel."}]},"ru":{"title":"Горение. Виды топлива","intro":"Огонь – самая древняя химическая реакция, которую освоил человек. Горение даёт нам тепло, свет и энергию, но, выйдя из-под контроля, превращается в пожар. Давайте разберёмся, как происходит горение и как его остановить.","blocks":[{"h":"Что такое горение","p":"Горение – это реакция вещества с кислородом, при которой выделяется много тепла и света. В чистом кислороде вещества горят намного быстрее и интенсивнее, чем на воздухе, ведь тепло не тратится на нагревание азота. Например, лучинка, едва тлеющая на воздухе, в чистом кислороде сразу вспыхивает."},{"h":"Условия горения и пламя","p":"Для начала горения нужны три условия: горючее вещество, кислород и достаточно высокая температура. Самая низкая температура, при которой вещество загорается на воздухе, называется температурой воспламенения. Пламя – это смесь раскалённых горящих газов и паров.","items":["Горючее вещество (топливо)","Кислород (воздух)","Нагревание до температуры воспламенения"],"visual":{"type":"diagram","kind":"flame"}},{"h":"Тушение пожара","p":"Пожар – это горение, вышедшее из-под контроля. Чтобы его потушить, достаточно устранить хотя бы одно из условий: охладить вещество ниже температуры воспламенения или прекратить доступ воздуха. Для этого используют воду, песок, пену огнетушителя или плотную ткань.","items":["Вода охлаждает горящий предмет","Песок, плотное одеяло или брезент перекрывают доступ воздуха","Углекислотный огнетушитель отделяет пламя от кислорода","Горящие нефтепродукты и включённые электроприборы нельзя тушить водой!"]},{"h":"Виды топлива","p":"Вещества, которые при сгорании дают полезное тепло, называются топливом. Топливо бывает твёрдым, жидким и газообразным. Твёрдое топливо оставляет золу, а жидкое и газообразное лишены этого недостатка. В Узбекистане добывают уголь (например, на Ангренском месторождении), нефть и природный газ (например, на Шуртанском и Мубарекском месторождениях).","table":{"head":["Вид","Примеры"],"rows":[["Твёрдое","уголь, торф, древесина, сланцы"],["Жидкое","нефть, бензин, мазут, спирт"],["Газообразное","природный газ, водород, угарный газ CO"]]}},{"h":"Горение природного газа","p":"В домашних газовых плитах горит в основном метан CH₄. При достатке воздуха он сгорает полностью голубым пламенем, образуя углекислый газ и воду. Для газов отношение объёмов равно отношению коэффициентов в уравнении: например, для сжигания 10 л метана нужно 20 л кислорода.","formula":"CH₄ + 2O₂ → CO₂ + 2H₂O","visual":{"type":"reaction","id":"ch4_o2"}},{"h":"Запомните","items":["Горение – окисление, сопровождающееся выделением тепла и света","Для горения нужны топливо, кислород и нагрев до температуры воспламенения","Чтобы потушить пожар, надо охладить вещество или перекрыть доступ воздуха","Топливо бывает твёрдым, жидким и газообразным"]}],"quiz":[{"q":"Что такое температура воспламенения?","options":["Самая высокая температура пламени","Самая низкая температура, при которой вещество загорается на воздухе","Температура кипения воды","Температура плавления вещества"],"correct":1,"explain":"Это минимальная температура, при которой вещество загорается на воздухе."},{"q":"Почему засыпание горящего предмета песком тушит огонь?","options":["Песок выделяет кислород","Песок нагревает топливо","Песок прекращает доступ воздуха","Песок повышает температуру воспламенения"],"correct":2,"explain":"Без кислорода горение продолжаться не может."},{"q":"Какое из веществ – газообразное топливо?","options":["Торф","Мазут","Уголь","Природный газ"],"correct":3,"explain":"Природный газ (в основном метан) – газообразное топливо."}]}}]},{"title":{"uz":"3-bob. Vodorod","en":"Chapter 3. Hydrogen","ru":"Глава 3. Водород"},"topics":[{"id":"t22","num":22,"icon":"🎈","uz":{"title":"Vodorod","intro":"Vodorod – davriy sistemaning birinchi va eng yengil elementi. Yulduzlar uning hisobiga porlaydi, suv esa usiz mavjud bo'lmasdi. Bu darsda vodorod elementi bilan tanishamiz.","blocks":[{"h":"Kashf etilishi va nomi","p":"1766-yilda ingliz olimi G. Kavendish metallarga kislota ta'sir ettirib, havoda yonadigan gazni ajratib olgan va uni «yonuvchi havo» deb atagan. Keyinroq A. Lavuazye bu gaz yonganda suv hosil bo'lishini isbotlab, unga «hydrogenium» – «suv hosil qiluvchi» nomini bergan. Kimyoviy belgisi H shu so'zning bosh harfidan olingan. Ko'p o'tmay vodorod bilan to'ldirilgan havo sharlari osmonga ko'tarila boshlagan."},{"h":"Vodorod atomi","p":"Vodorod davriy sistemada 1-o'rinda turadi: yadrosining zaryadi +1, atomida bitta elektron bor. Uning nisbiy atom massasi taxminan 1 ga teng va birikmalarida vodorod doimo bir valentli. Oddiy modda sifatida vodorod ikki atomli H₂ molekulalaridan iborat, Mr(H₂) = 2.","formula":"H: tartib raqami 1, Ar(H) = 1, valentligi I","visual":{"type":"atom3d","el":"H"}},{"h":"Vodorodning izotoplari","p":"Vodorod atomlarining yadrolari bir xil zaryadga ega, lekin massasi har xil bo'lishi mumkin – bunday atomlar izotoplar deyiladi. Tabiiy vodorodning deyarli hammasi protiydan iborat.","items":["Protiy ¹H – nisbiy massasi 1, eng ko'p tarqalgan","Deyteriy ²H (D) – nisbiy massasi 2, «og'ir suv» D₂O tarkibida","Tritiy ³H (T) – nisbiy massasi 3, radioaktiv va juda kam uchraydi"]},{"h":"Tabiatda tarqalishi","p":"Vodorod – koinotda eng ko'p tarqalgan element: Quyosh va boshqa yulduzlar asosan undan tashkil topgan. Yulduzlar qa'rida vodorod yadrolari qo'shilib geliyga aylanadi va bunda juda katta energiya ajraladi. Yerda erkin vodorod juda kam, lekin u suv, tabiiy gaz (metan CH₄), neft, minerallar va barcha tirik organizmlar tarkibida bog'langan holda keng tarqalgan."},{"h":"Namuna: suvdagi vodorodning massa ulushi","p":"Suv massasining qancha qismi vodorodga to'g'ri kelishini hisoblaymiz.","formula":"ω(H) = 2 · Ar(H) / Mr(H₂O)","items":["Mr(H₂O) = 2 · 1 + 16 = 18","Vodorod atomlari massasi: 2 · 1 = 2","ω(H) = 2 / 18 ≈ 0,111","Javob: suv massasining taxminan 11,1% i (ya'ni 1/9 qismi) vodorod"]},{"h":"Esda tuting","items":["Vodorod – eng yengil va koinotda eng ko'p tarqalgan element","Belgisi H, Ar = 1, birikmalarida doimo I valentli","Oddiy modda – H₂ (Mr = 2)","Yerda vodorod asosan suv va organik moddalar tarkibida uchraydi"]}],"quiz":[{"q":"Koinotda eng ko'p tarqalgan element qaysi?","options":["Kislorod","Vodorod","Geliy","Uglerod"],"correct":1,"explain":"Yulduzlar va yulduzlararo gaz asosan vodoroddan iborat."},{"q":"«Hydrogenium» so'zi nimani anglatadi?","options":["Suv hosil qiluvchi","Kislota hosil qiluvchi","Yengil gaz","Yonuvchi havo"],"correct":0,"explain":"Lavuazye bu nomni vodorod yonganda suv hosil bo'lgani uchun bergan."},{"q":"Vodorod birikmalarida qanday valentlik namoyon qiladi?","options":["II","III","IV","I"],"correct":3,"explain":"Vodorod doimo bir valentli."}]},"en":{"title":"Hydrogen","intro":"Hydrogen is the first and lightest element of the periodic table. Stars shine thanks to it, and water could not exist without it. In this lesson we get to know the element hydrogen.","blocks":[{"h":"Discovery and name","p":"In 1766 the English scientist H. Cavendish obtained a gas that burns in air by treating metals with acids, and called it 'inflammable air'. Later A. Lavoisier proved that water forms when this gas burns and named it 'hydrogenium', meaning 'water-former'. The symbol H comes from the first letter of this word. Soon afterwards balloons filled with hydrogen began to rise into the sky."},{"h":"The hydrogen atom","p":"Hydrogen is number 1 in the periodic table: its nuclear charge is +1 and its atom has one electron. Its relative atomic mass is about 1, and in compounds hydrogen is always monovalent. As a simple substance hydrogen consists of two-atom H₂ molecules, Mr(H₂) = 2.","formula":"H: atomic number 1, Ar(H) = 1, valency I","visual":{"type":"atom3d","el":"H"}},{"h":"Isotopes of hydrogen","p":"Hydrogen atoms all have the same nuclear charge, but their masses can differ; such atoms are called isotopes. Almost all natural hydrogen is protium.","items":["Protium ¹H: relative mass 1, by far the most common","Deuterium ²H (D): relative mass 2, found in 'heavy water' D₂O","Tritium ³H (T): relative mass 3, radioactive and very rare"]},{"h":"Occurrence in nature","p":"Hydrogen is the most abundant element in the universe: the Sun and other stars are made mostly of it. Deep inside stars hydrogen nuclei fuse into helium, releasing enormous amounts of energy. On Earth there is very little free hydrogen, but it is widespread in bound form in water, natural gas (methane CH₄), oil, minerals and all living things."},{"h":"Worked example: hydrogen in water","p":"Let's calculate what fraction of the mass of water is hydrogen.","formula":"ω(H) = 2 · Ar(H) / Mr(H₂O)","items":["Mr(H₂O) = 2 × 1 + 16 = 18","Mass of hydrogen atoms: 2 × 1 = 2","ω(H) = 2 / 18 ≈ 0.111","Answer: about 11.1% (one ninth) of the mass of water is hydrogen"]},{"h":"Remember","items":["Hydrogen is the lightest element and the most abundant in the universe","Symbol H, Ar = 1, always valency I in compounds","The simple substance is H₂ (Mr = 2)","On Earth hydrogen is found mainly in water and organic substances"]}],"quiz":[{"q":"Which element is the most abundant in the universe?","options":["Oxygen","Hydrogen","Helium","Carbon"],"correct":1,"explain":"Stars and interstellar gas consist mainly of hydrogen."},{"q":"What does the word 'hydrogenium' mean?","options":["Water-former","Acid-former","Light gas","Inflammable air"],"correct":0,"explain":"Lavoisier chose this name because burning hydrogen forms water."},{"q":"What valency does hydrogen show in its compounds?","options":["II","III","IV","I"],"correct":3,"explain":"Hydrogen is always monovalent."}]},"ru":{"title":"Водород","intro":"Водород – первый и самый лёгкий элемент периодической системы. Благодаря ему светят звёзды, а без него не было бы воды. На этом уроке мы познакомимся с элементом водородом.","blocks":[{"h":"Открытие и название","p":"В 1766 году английский учёный Г. Кавендиш, действуя кислотами на металлы, получил газ, горящий на воздухе, и назвал его «горючим воздухом». Позже А. Лавуазье доказал, что при сгорании этого газа образуется вода, и назвал его «hydrogenium» – «рождающий воду». Символ H взят по первой букве этого слова. Вскоре в небо стали подниматься воздушные шары, наполненные водородом."},{"h":"Атом водорода","p":"Водород стоит в периодической системе под номером 1: заряд ядра +1, в атоме один электрон. Его относительная атомная масса примерно равна 1, а в соединениях водород всегда одновалентен. Как простое вещество водород состоит из двухатомных молекул H₂, Mr(H₂) = 2.","formula":"H: порядковый номер 1, Ar(H) = 1, валентность I","visual":{"type":"atom3d","el":"H"}},{"h":"Изотопы водорода","p":"Ядра всех атомов водорода имеют одинаковый заряд, но масса атомов может различаться – такие атомы называются изотопами. Почти весь природный водород – это протий.","items":["Протий ¹H – относительная масса 1, самый распространённый","Дейтерий ²H (D) – относительная масса 2, входит в «тяжёлую воду» D₂O","Тритий ³H (T) – относительная масса 3, радиоактивен и очень редок"]},{"h":"Распространение в природе","p":"Водород – самый распространённый элемент во Вселенной: Солнце и другие звёзды состоят в основном из него. В недрах звёзд ядра водорода сливаются в гелий, выделяя огромную энергию. На Земле свободного водорода очень мало, зато в связанном виде он широко распространён: в воде, природном газе (метан CH₄), нефти, минералах и всех живых организмах."},{"h":"Пример: водород в воде","p":"Рассчитаем, какую часть массы воды составляет водород.","formula":"ω(H) = 2 · Ar(H) / Mr(H₂O)","items":["Mr(H₂O) = 2 · 1 + 16 = 18","Масса атомов водорода: 2 · 1 = 2","ω(H) = 2 / 18 ≈ 0,111","Ответ: около 11,1% (одна девятая) массы воды приходится на водород"]},{"h":"Запомните","items":["Водород – самый лёгкий и самый распространённый во Вселенной элемент","Символ H, Ar = 1, в соединениях всегда валентность I","Простое вещество – H₂ (Mr = 2)","На Земле водород встречается в основном в составе воды и органических веществ"]}],"quiz":[{"q":"Какой элемент самый распространённый во Вселенной?","options":["Кислород","Водород","Гелий","Углерод"],"correct":1,"explain":"Звёзды и межзвёздный газ состоят в основном из водорода."},{"q":"Что означает слово «hydrogenium»?","options":["Рождающий воду","Рождающий кислоты","Лёгкий газ","Горючий воздух"],"correct":0,"explain":"Лавуазье дал это название, потому что при горении водорода образуется вода."},{"q":"Какую валентность проявляет водород в соединениях?","options":["II","III","IV","I"],"correct":3,"explain":"Водород всегда одновалентен."}]}},{"id":"t23","num":23,"icon":"🍋","uz":{"title":"Kislotalar haqida dastlabki tushunchalar","intro":"Limon, olma yoki qatiqning nordon ta'mi qayerdan keladi? Bu ta'mni kislotalar beradi – vodorodning muhim birikmalari. Bu darsda kislotalarni qanday tanib olish va ular qanday umumiy xossalarga ega ekanini bilib olamiz.","blocks":[{"h":"Tabiatdagi kislotalar","p":"Ko'plab meva va o'simliklar tarkibida tabiiy kislotalar bor, ular nordon ta'm beradi. Bu kislotalarning barchasi tarkibida vodorod bor.","table":{"head":["Qayerda uchraydi","Kislota"],"rows":[["Limon, apelsin, mandarin","limon kislota"],["Olma, behi, anor","olma kislota"],["Otquloq (shovul) barglari","shovul kislota"],["Chumoli, qichitqi o't","chumoli kislota"],["Gazli mineral suv","karbonat kislota"],["Sirka","sirka kislota"]]}},{"h":"Sanoatda olinadigan kislotalar","p":"Kimyo zavodlarida ko'plab kislotalar ishlab chiqariladi va ular ham vodorod birikmalaridir. Masalan, xlorid kislota HCl oshqozon shirasida ham oz miqdorda bo'ladi, sulfat kislota H₂SO₄ esa avtomobil akkumulyatorlarida ishlatiladi.","items":["Xlorid kislota – HCl","Sulfat kislota – H₂SO₄","Nitrat kislota – HNO₃","Fosfat kislota – H₃PO₄"]},{"h":"Indikatorlar","p":"Muhitga qarab rangini o'zgartiradigan sinov moddalari indikatorlar deyiladi. Kislota eritmalari indikatorlar rangini o'ziga xos tarzda o'zgartiradi, shuning uchun ularni ta'mini totib ko'rmasdan aniqlash mumkin.","items":["Binafsha lakmus kislotada qizaradi","To'q sariq metilzarg'aldoq kislotada pushti-qizil rangga kiradi","Fenolftalein kislotada rangsizligicha qoladi","Universal indikator kislotada qizil rangga o'tadi"],"visual":{"type":"diagram","kind":"indicators"}},{"h":"Kislotalarning metallar bilan ta'siri","p":"Faol metallar kislota eritmasiga tushirilganda undan vodorod gazini siqib chiqaradi. Magniy bu reaksiyani juda shiddatli, rux va temir sekinroq beradi, mis esa umuman vodorod ajratmaydi.","formula":"Mg + 2HCl → MgCl₂ + H₂↑","items":["Mg – tez, ko'p pufakchalar","Zn, Fe – sekinroq","Cu – reaksiya bormaydi"]},{"h":"Kislotalarning umumiy xossalari va xavfsizlik","p":"Kislotalarni umumiy belgilari bo'yicha tanib olish mumkin. Lekin laboratoriyadagi kislotalarni hech qachon tatib ko'rmang: ular teri va shilliq qavatlarni kuydiradi. Kislota teriga tushsa, darhol ko'p suv bilan yuving.","items":["Eritmalari nordon ta'mga ega (faqat oziq-ovqatdagi tabiiy kislotalar misolida!)","Indikatorlar rangini o'zgartiradi","Faol metallar ta'sirida vodorod ajratadi"]},{"h":"Esda tuting","items":["Kislotalar – tarkibida vodorod bo'lgan va nordon ta'mli moddalar","Indikatorlar kislota borligini rang o'zgarishi orqali ko'rsatadi","Faol metallar kislotalardan vodorodni siqib chiqaradi, mis esa yo'q","Laboratoriya kislotalarini hech qachon tatib ko'rmang"]}],"quiz":[{"q":"Kislota eritmasida binafsha lakmus qanday rangga kiradi?","options":["Ko'k","Qizil","Rangsiz","Yashil"],"correct":1,"explain":"Kislotali muhitda lakmus qizaradi."},{"q":"Qaysi metall xlorid kislotadan vodorodni siqib chiqarmaydi?","options":["Magniy","Rux","Temir","Mis"],"correct":3,"explain":"Mis faolligi past metall bo'lib, kislotadan vodorod ajratmaydi."},{"q":"Chumoli kislota tabiatda qayerda uchraydi?","options":["Chumolilar va qichitqi o'tda","Limonda","Olmada","Gazli suvda"],"correct":0,"explain":"Chumoli chaqqanda va qichitqi o't kuydirganda aynan shu kislota ta'sir qiladi."}]},"en":{"title":"First ideas about acids","intro":"Where does the sour taste of lemons, apples or yoghurt come from? It comes from acids, which are important compounds of hydrogen. In this lesson we learn how to recognise acids and what properties they share.","blocks":[{"h":"Acids in nature","p":"Many fruits and plants contain natural acids that give them a sour taste. All these acids contain hydrogen.","table":{"head":["Where it is found","Acid"],"rows":[["Lemons, oranges, tangerines","citric acid"],["Apples, quinces, pomegranates","malic acid"],["Sorrel leaves","oxalic acid"],["Ants, stinging nettles","formic acid"],["Sparkling mineral water","carbonic acid"],["Vinegar","acetic acid"]]}},{"h":"Acids made in industry","p":"Chemical plants produce many acids, and these are also compounds of hydrogen. For example, hydrochloric acid HCl is present in small amounts in stomach juice, and sulfuric acid H₂SO₄ is used in car batteries.","items":["Hydrochloric acid: HCl","Sulfuric acid: H₂SO₄","Nitric acid: HNO₃","Phosphoric acid: H₃PO₄"]},{"h":"Indicators","p":"Test substances that change colour depending on the medium are called indicators. Acid solutions change the colour of indicators in a characteristic way, so acids can be detected without tasting them.","items":["Purple litmus turns red in acid","Orange methyl orange turns pinkish red in acid","Phenolphthalein stays colourless in acid","Universal indicator turns red in acid"],"visual":{"type":"diagram","kind":"indicators"}},{"h":"Acids and metals","p":"When an active metal is placed in an acid solution, it drives out hydrogen gas. Magnesium reacts very vigorously, zinc and iron more slowly, and copper releases no hydrogen at all.","formula":"Mg + 2HCl → MgCl₂ + H₂↑","items":["Mg: fast, lots of bubbles","Zn, Fe: slower","Cu: no reaction"]},{"h":"General properties and safety","p":"Acids can be recognised by their shared properties. But never taste laboratory acids: they burn the skin and mucous membranes. If acid gets on your skin, wash it at once with plenty of water.","items":["Their solutions taste sour (judge this only from natural food acids!)","They change the colour of indicators","With active metals they release hydrogen"]},{"h":"Remember","items":["Acids are sour-tasting substances that contain hydrogen","Indicators reveal acids by changing colour","Active metals drive hydrogen out of acids, but copper does not","Never taste laboratory acids"]}],"quiz":[{"q":"What colour does purple litmus turn in an acid solution?","options":["Blue","Red","Colourless","Green"],"correct":1,"explain":"Litmus turns red in an acidic medium."},{"q":"Which metal does not drive hydrogen out of hydrochloric acid?","options":["Magnesium","Zinc","Iron","Copper"],"correct":3,"explain":"Copper is an unreactive metal and releases no hydrogen from acids."},{"q":"Where is formic acid found in nature?","options":["In ants and stinging nettles","In lemons","In apples","In sparkling water"],"correct":0,"explain":"This acid is responsible for the sting of ants and nettles."}]},"ru":{"title":"Первые представления о кислотах","intro":"Откуда берётся кислый вкус лимона, яблока или кефира? Его дают кислоты – важные соединения водорода. На этом уроке мы узнаем, как распознать кислоты и какие общие свойства у них есть.","blocks":[{"h":"Кислоты в природе","p":"Многие фрукты и растения содержат природные кислоты, придающие им кислый вкус. Все эти кислоты содержат водород.","table":{"head":["Где встречается","Кислота"],"rows":[["Лимон, апельсин, мандарин","лимонная кислота"],["Яблоко, айва, гранат","яблочная кислота"],["Листья щавеля","щавелевая кислота"],["Муравьи, крапива","муравьиная кислота"],["Газированная минеральная вода","угольная кислота"],["Уксус","уксусная кислота"]]}},{"h":"Кислоты, получаемые в промышленности","p":"Химические заводы выпускают множество кислот, и все они тоже соединения водорода. Например, соляная кислота HCl в небольшом количестве содержится в желудочном соке, а серная кислота H₂SO₄ используется в автомобильных аккумуляторах.","items":["Соляная (хлороводородная) кислота – HCl","Серная кислота – H₂SO₄","Азотная кислота – HNO₃","Фосфорная кислота – H₃PO₄"]},{"h":"Индикаторы","p":"Вещества, меняющие цвет в зависимости от среды, называются индикаторами. Растворы кислот изменяют окраску индикаторов характерным образом, поэтому кислоты можно обнаружить, не пробуя их на вкус.","items":["Фиолетовый лакмус в кислоте краснеет","Оранжевый метиловый оранжевый в кислоте становится розово-красным","Фенолфталеин в кислоте остаётся бесцветным","Универсальный индикатор в кислоте краснеет"],"visual":{"type":"diagram","kind":"indicators"}},{"h":"Действие кислот на металлы","p":"Активный металл, опущенный в раствор кислоты, вытесняет из неё газ водород. Магний реагирует очень бурно, цинк и железо – медленнее, а медь водород не вытесняет совсем.","formula":"Mg + 2HCl → MgCl₂ + H₂↑","items":["Mg – быстро, много пузырьков","Zn, Fe – медленнее","Cu – реакция не идёт"]},{"h":"Общие свойства кислот и безопасность","p":"Кислоты можно узнать по общим признакам. Но лабораторные кислоты нельзя пробовать на вкус: они разъедают кожу и слизистые оболочки. Если кислота попала на кожу, сразу промойте это место большим количеством воды.","items":["Растворы имеют кислый вкус (судить об этом можно только по пищевым природным кислотам!)","Изменяют окраску индикаторов","При действии активных металлов выделяют водород"]},{"h":"Запомните","items":["Кислоты – вещества с кислым вкусом, содержащие водород","Индикаторы обнаруживают кислоты по изменению цвета","Активные металлы вытесняют водород из кислот, а медь – нет","Лабораторные кислоты никогда не пробуют на вкус"]}],"quiz":[{"q":"Какой цвет приобретает фиолетовый лакмус в растворе кислоты?","options":["Синий","Красный","Бесцветный","Зелёный"],"correct":1,"explain":"В кислой среде лакмус краснеет."},{"q":"Какой металл не вытесняет водород из соляной кислоты?","options":["Магний","Цинк","Железо","Медь"],"correct":3,"explain":"Медь – малоактивный металл и не вытесняет водород из кислот."},{"q":"Где в природе встречается муравьиная кислота?","options":["В муравьях и крапиве","В лимоне","В яблоке","В газированной воде"],"correct":0,"explain":"Именно эта кислота вызывает жжение от укуса муравья и крапивы."}]}},{"id":"t24","num":24,"icon":"⚗️","uz":{"title":"Vodorodning olinishi","intro":"Erkin vodorod tabiatda deyarli uchramaydi, shuning uchun uni birikmalardan ajratib olish kerak. Bu darsda vodorodni laboratoriyada va sanoatda qanday olish mumkinligini ko'ramiz. Avval esa vodorod yordamida valentlikni aniqlashni o'rganamiz.","blocks":[{"h":"Vodorod bo'yicha valentlikni aniqlash","p":"Vodorodning valentligi doimo I ga teng. Shuning uchun vodorod va boshqa bir elementdan iborat birikmada vodorod atomlari soni ikkinchi elementning valentligini bevosita ko'rsatadi.","items":["HCl – xlor I valentli","H₂O – kislorod II valentli","NH₃ – azot III valentli","CH₄ – uglerod IV valentli"]},{"h":"Laboratoriyada olinishi","p":"Laboratoriyada vodorod odatda rux bo'lakchalariga xlorid kislota ta'sir ettirib olinadi. Probirkada ko'plab gaz pufakchalari hosil bo'ladi, rux esa asta-sekin eriydi. Rux o'rniga temir yoki magniy, xlorid kislota o'rniga suyultirilgan sulfat kislota ham ishlatilishi mumkin.","formula":"Zn + 2HCl → ZnCl₂ + H₂↑","items":["Zn + H₂SO₄ → ZnSO₄ + H₂↑","Fe + 2HCl → FeCl₂ + H₂↑"],"visual":{"type":"reaction","id":"zn_hcl"}},{"h":"Kipp apparati va vodorodni yig'ish","p":"Gazni kerak bo'lganda olib, kerak bo'lmaganda to'xtatish uchun Kipp apparatidan foydalaniladi. Unda o'rta qismga rux, yuqoridagi voronkaga kislota solinadi; jo'mrak ochiq bo'lsa, kislota ruxga yetib boradi va vodorod chiqadi. Jo'mrak yopilsa, to'plangan gaz kislotani yuqoriga siqib chiqaradi, kislota ruxdan ajraladi va reaksiya to'xtaydi. Vodorod havodan yengil, shuning uchun u og'zi pastga qaratilgan probirkaga yoki suvni siqib chiqarish usulida yig'iladi.","items":["Vodorod tozaligini tekshirish: probirka og'zini alangaga yaqinlashtiring","Bo'g'iq «puf» ovozi – vodorod toza","Qattiq hushtaksimon ovoz – havo aralashgan, yondirish xavfli!"]},{"h":"Sanoatda olinishi","p":"Sanoatda vodorod arzon va ko'p tarqalgan xomashyolar – suv va tabiiy gazdan olinadi. Metan suv bug'i bilan yuqori haroratda nikel katalizatori ishtirokida qayta ishlanadi, hosil bo'lgan is gazi esa yana suv bug'i bilan qo'shimcha vodorod beradi. Suvni elektroliz qilish usuli juda toza vodorod beradi, lekin ko'p elektr energiyasi talab qiladi.","items":["CH₄ + H₂O → CO + 3H₂ (yuqori harorat, Ni katalizator)","CO + H₂O → CO₂ + H₂ (katalizator ishtirokida)","2H₂O → 2H₂ + O₂ (elektr toki)"]},{"h":"Namuna: ruxdan qancha vodorod olinadi","p":"6,5 g rux mo'l miqdordagi xlorid kislota bilan reaksiyaga kirishganda normal sharoitda qancha hajm vodorod ajralishini hisoblaymiz.","formula":"Zn + 2HCl → ZnCl₂ + H₂","items":["n(Zn) = 6,5 g / 65 g/mol = 0,1 mol","Tenglamaga ko'ra n(H₂) = n(Zn) = 0,1 mol","V(H₂) = 0,1 · 22,4 = 2,24 l","Javob: 2,24 l vodorod"]},{"h":"Esda tuting","items":["Vodorod doimo I valentli, shuning uchun u bo'yicha boshqa elementlar valentligini topish oson","Laboratoriyada: faol metall + kislota, masalan Zn + 2HCl → ZnCl₂ + H₂","Sanoatda: metan va suv bug'idan hamda suv elektrolizidan","Vodorodni yoqishdan oldin uning tozaligini albatta tekshiring"]}],"quiz":[{"q":"NH₃ birikmasida azotning valentligi nechaga teng?","options":["I","II","III","IV"],"correct":2,"explain":"Uchta I valentli vodorod atomi azotning III valentli ekanini ko'rsatadi."},{"q":"Nima uchun vodorod og'zi pastga qaratilgan probirkaga yig'iladi?","options":["U havodan yengil","U havodan og'ir","U suvda yaxshi eriydi","U rangli gaz"],"correct":0,"explain":"Yengil vodorod yuqoriga ko'tariladi va to'ntarilgan idishda qoladi."},{"q":"13 g rux xlorid kislota bilan to'liq reaksiyaga kirishsa, n.sh. da necha litr H₂ ajraladi?","options":["2,24 l","22,4 l","11,2 l","4,48 l"],"correct":3,"explain":"13 g Zn = 0,2 mol, demak 0,2 mol H₂ = 4,48 l."}]},"en":{"title":"How hydrogen is obtained","intro":"Free hydrogen is almost never found in nature, so it has to be extracted from compounds. In this lesson we see how hydrogen is made in the laboratory and in industry. First, though, we learn how hydrogen helps us find valency.","blocks":[{"h":"Finding valency from hydrogen","p":"The valency of hydrogen is always I. So in a compound of hydrogen with one other element, the number of hydrogen atoms directly shows the valency of the other element.","items":["HCl: chlorine has valency I","H₂O: oxygen has valency II","NH₃: nitrogen has valency III","CH₄: carbon has valency IV"]},{"h":"Laboratory preparation","p":"In the laboratory hydrogen is usually made by adding hydrochloric acid to pieces of zinc. Many gas bubbles appear in the test tube while the zinc slowly dissolves. Iron or magnesium can replace zinc, and dilute sulfuric acid can replace hydrochloric acid.","formula":"Zn + 2HCl → ZnCl₂ + H₂↑","items":["Zn + H₂SO₄ → ZnSO₄ + H₂↑","Fe + 2HCl → FeCl₂ + H₂↑"],"visual":{"type":"reaction","id":"zn_hcl"}},{"h":"The Kipp apparatus and collecting hydrogen","p":"A Kipp apparatus lets you get gas when you need it and stop it when you do not. Zinc is placed in the middle part and acid is poured into the funnel at the top; with the tap open, the acid reaches the zinc and hydrogen comes out. When the tap is closed, the collecting gas pushes the acid up away from the zinc and the reaction stops. Hydrogen is lighter than air, so it is collected in an upside-down test tube or by displacing water.","items":["Purity test: bring the mouth of the tube to a flame","A soft 'pop' means the hydrogen is pure","A loud squeaky bang means air is mixed in, and lighting it is dangerous!"]},{"h":"Industrial production","p":"In industry hydrogen is made from cheap, plentiful raw materials: water and natural gas. Methane is treated with steam at high temperature over a nickel catalyst, and the carbon monoxide formed reacts with more steam to give extra hydrogen. Electrolysis of water gives very pure hydrogen but uses a lot of electricity.","items":["CH₄ + H₂O → CO + 3H₂ (high temperature, Ni catalyst)","CO + H₂O → CO₂ + H₂ (with a catalyst)","2H₂O → 2H₂ + O₂ (electric current)"]},{"h":"Worked example: hydrogen from zinc","p":"Let's find the volume of hydrogen at STP released when 6.5 g of zinc reacts with excess hydrochloric acid.","formula":"Zn + 2HCl → ZnCl₂ + H₂","items":["n(Zn) = 6.5 g / 65 g/mol = 0.1 mol","From the equation n(H₂) = n(Zn) = 0.1 mol","V(H₂) = 0.1 × 22.4 = 2.24 L","Answer: 2.24 L of hydrogen"]},{"h":"Remember","items":["Hydrogen always has valency I, so it is easy to find other elements' valency from it","In the lab: active metal + acid, e.g. Zn + 2HCl → ZnCl₂ + H₂","In industry: from methane and steam, and by electrolysis of water","Always test hydrogen for purity before lighting it"]}],"quiz":[{"q":"What is the valency of nitrogen in NH₃?","options":["I","II","III","IV"],"correct":2,"explain":"Three monovalent hydrogen atoms show that nitrogen has valency III."},{"q":"Why is hydrogen collected in an upside-down test tube?","options":["It is lighter than air","It is heavier than air","It dissolves well in water","It is a coloured gas"],"correct":0,"explain":"Light hydrogen rises and stays in the inverted tube."},{"q":"How many litres of H₂ (STP) form when 13 g of zinc reacts completely with hydrochloric acid?","options":["2.24 L","22.4 L","11.2 L","4.48 L"],"correct":3,"explain":"13 g of Zn is 0.2 mol, so 0.2 mol of H₂ = 4.48 L."}]},"ru":{"title":"Получение водорода","intro":"Свободный водород в природе почти не встречается, поэтому его приходится выделять из соединений. На этом уроке мы узнаем, как получают водород в лаборатории и в промышленности. Но сначала научимся определять валентность с помощью водорода.","blocks":[{"h":"Определение валентности по водороду","p":"Валентность водорода всегда равна I. Поэтому в соединении водорода с другим элементом число атомов водорода прямо указывает валентность второго элемента.","items":["HCl – хлор одновалентен","H₂O – кислород двухвалентен","NH₃ – азот трёхвалентен","CH₄ – углерод четырёхвалентен"]},{"h":"Получение в лаборатории","p":"В лаборатории водород обычно получают действием соляной кислоты на кусочки цинка. В пробирке появляется много пузырьков газа, а цинк постепенно растворяется. Вместо цинка можно взять железо или магний, а вместо соляной кислоты – разбавленную серную.","formula":"Zn + 2HCl → ZnCl₂ + H₂↑","items":["Zn + H₂SO₄ → ZnSO₄ + H₂↑","Fe + 2HCl → FeCl₂ + H₂↑"],"visual":{"type":"reaction","id":"zn_hcl"}},{"h":"Аппарат Киппа и собирание водорода","p":"Аппарат Киппа позволяет получать газ, когда он нужен, и останавливать реакцию, когда нет. Цинк помещают в среднюю часть, а кислоту наливают в верхнюю воронку; при открытом кране кислота доходит до цинка и выделяется водород. Если кран закрыть, скапливающийся газ вытесняет кислоту вверх, она отходит от цинка, и реакция прекращается. Водород легче воздуха, поэтому его собирают в пробирку, перевёрнутую вверх дном, или методом вытеснения воды.","items":["Проверка на чистоту: поднесите отверстие пробирки к пламени","Глухой хлопок – водород чистый","Резкий лающий звук – есть примесь воздуха, поджигать опасно!"]},{"h":"Получение в промышленности","p":"В промышленности водород получают из дешёвого и доступного сырья – воды и природного газа. Метан обрабатывают водяным паром при высокой температуре на никелевом катализаторе, а образовавшийся угарный газ с паром даёт дополнительный водород. Электролиз воды даёт очень чистый водород, но требует много электроэнергии.","items":["CH₄ + H₂O → CO + 3H₂ (высокая температура, катализатор Ni)","CO + H₂O → CO₂ + H₂ (в присутствии катализатора)","2H₂O → 2H₂ + O₂ (электрический ток)"]},{"h":"Пример: сколько водорода даёт цинк","p":"Найдём объём водорода (н. у.), который выделится при реакции 6,5 г цинка с избытком соляной кислоты.","formula":"Zn + 2HCl → ZnCl₂ + H₂","items":["n(Zn) = 6,5 г / 65 г/моль = 0,1 моль","По уравнению n(H₂) = n(Zn) = 0,1 моль","V(H₂) = 0,1 · 22,4 = 2,24 л","Ответ: 2,24 л водорода"]},{"h":"Запомните","items":["Водород всегда одновалентен, поэтому по нему легко найти валентность других элементов","В лаборатории: активный металл + кислота, например Zn + 2HCl → ZnCl₂ + H₂","В промышленности: из метана и водяного пара, а также электролизом воды","Перед поджиганием водород обязательно проверяют на чистоту"]}],"quiz":[{"q":"Чему равна валентность азота в NH₃?","options":["I","II","III","IV"],"correct":2,"explain":"Три одновалентных атома водорода показывают, что азот трёхвалентен."},{"q":"Почему водород собирают в пробирку, перевёрнутую вверх дном?","options":["Он легче воздуха","Он тяжелее воздуха","Он хорошо растворяется в воде","Это окрашенный газ"],"correct":0,"explain":"Лёгкий водород поднимается вверх и остаётся в перевёрнутой пробирке."},{"q":"Сколько литров H₂ (н. у.) выделится при полной реакции 13 г цинка с соляной кислотой?","options":["2,24 л","22,4 л","11,2 л","4,48 л"],"correct":3,"explain":"13 г Zn – это 0,2 моль, значит 0,2 моль H₂ = 4,48 л."}]}},{"id":"t25","num":25,"icon":"💧","uz":{"title":"Vodorod – oddiy modda. Fizik va kimyoviy xossalari","intro":"Vodorod – eng yengil gaz, u bilan to'ldirilgan shar havoga o'zi ko'tariladi. Kimyoviy jihatdan esa u kislorod bilan portlovchi aralashma hosil qiladi va metallarni oksidlaridan ajratib oladi. Keling, bu ajoyib moddaning xossalarini o'rganamiz.","blocks":[{"h":"Fizik xossalari","p":"Vodorod H₂ – rangsiz, hidsiz va ta'msiz gaz. U barcha gazlarning eng yengili: havodan taxminan 14,5 marta yengil. Molekulalari juda kichik va yengil bo'lgani uchun vodorod boshqa gazlarga qaraganda tez tarqaladi (diffuziyalanadi) va mayda tirqishlardan oson o'tadi.","items":["1 l vodorodning massasi (n.sh.) ≈ 0,09 g","Qaynash harorati −253 °C","Suvda juda kam eriydi","Palladiy, nikel, platina kabi metallarda yaxshi eriydi","Issiqlikni yaxshi o'tkazadi"],"visual":{"type":"molecule3d","mol":"H2"}},{"h":"Metallmaslar bilan reaksiyalari","p":"Oddiy sharoitda H₂ molekulasi uncha faol emas, lekin metallmaslar bilan birikib uchuvchan birikmalar hosil qiladi. Reaksiya tezligi metallmasning faolligiga bog'liq: ftor bilan sovuqda va qorong'ida ham portlab birikadi, azot bilan esa faqat yuqori harorat, bosim va katalizator ishtirokida reaksiyaga kirishadi.","items":["H₂ + F₂ → 2HF","H₂ + Cl₂ → 2HCl (yorug'likda yoki qizdirilganda)","H₂ + S → H₂S (qizdirilganda)","N₂ + 3H₂ → 2NH₃ (yuqori harorat, bosim, katalizator)"]},{"h":"Kislorod bilan reaksiyasi","p":"Toza vodorod havoda och-ko'kimtir, deyarli ko'rinmas alanga bilan tinch yonadi va suv hosil qiladi; bunda juda ko'p issiqlik ajraladi. Ikki hajm vodorod va bir hajm kislorod aralashmasi «qaldiroq gaz» deyiladi – u uchqun yoki alangadan kuchli portlaydi. Shuning uchun vodorodni yondirishdan oldin uning tozaligi tekshiriladi.","formula":"2H₂ + O₂ → 2H₂O","visual":{"type":"reaction","id":"h2_o2"}},{"h":"Metallarni oksidlardan qaytarish va gidridlar","p":"Qizdirilganda vodorod ko'plab metall oksidlaridan kislorodni tortib olib, sof metallni ajratadi – bu jarayon qaytarilish deyiladi. Masalan, qora mis(II) oksid ustidan vodorod o'tkazilsa, qizil mis va suv tomchilari hosil bo'ladi. Natriy, kalsiy kabi juda faol metallar bilan esa vodorod tuzsimon birikmalar – gidridlarni hosil qiladi.","items":["CuO + H₂ → Cu + H₂O (qizdirilganda)","2Na + H₂ → 2NaH (natriy gidrid)","Ca + H₂ → CaH₂ (kalsiy gidrid)"]},{"h":"Namuna: mis oksidini qaytarish","p":"8 g mis(II) oksidni to'liq qaytarish uchun normal sharoitda qancha vodorod kerak va qancha mis hosil bo'lishini hisoblaymiz.","formula":"CuO + H₂ → Cu + H₂O","items":["M(CuO) = 64 + 16 = 80 g/mol; n(CuO) = 8 / 80 = 0,1 mol","n(H₂) = n(CuO) = 0,1 mol; V(H₂) = 0,1 · 22,4 = 2,24 l","n(Cu) = 0,1 mol; m(Cu) = 0,1 · 64 = 6,4 g","Javob: 2,24 l vodorod, 6,4 g mis"]},{"h":"Esda tuting","items":["H₂ – rangsiz, hidsiz, eng yengil gaz","Vodorod metallmaslar bilan birikadi, kislorodda yonib suv hosil qiladi","2:1 hajmdagi H₂ va O₂ aralashmasi – portlovchi «qaldiroq gaz»","Qizdirilganda vodorod metallarni oksidlaridan qaytaradi, shuning uchun metallurgiyada ishlatiladi"]}],"quiz":[{"q":"Vodorod havodan taxminan necha marta yengil?","options":["2 marta","14,5 marta","29 marta","1,5 marta"],"correct":1,"explain":"M(havo) ≈ 29, M(H₂) = 2, 29 / 2 ≈ 14,5."},{"q":"Qizdirilgan CuO ustidan vodorod o'tkazilganda nima hosil bo'ladi?","options":["Cu va H₂O","CuH₂ va O₂","Cu(OH)₂","CuO₂ va H₂"],"correct":0,"explain":"Vodorod oksiddan kislorodni tortib olib, mis va suv hosil qiladi."},{"q":"«Qaldiroq gaz» qanday aralashma?","options":["N₂ va H₂ (1:3)","H₂ va Cl₂ (1:1)","CO va O₂ (2:1)","H₂ va O₂ (2:1)"],"correct":3,"explain":"Ikki hajm vodorod va bir hajm kislorod aralashmasi kuchli portlaydi."}]},"en":{"title":"Hydrogen as a simple substance. Physical and chemical properties","intro":"Hydrogen is the lightest gas: a balloon filled with it rises on its own. Chemically, it forms an explosive mixture with oxygen and can pull metals out of their oxides. Let's study the properties of this remarkable substance.","blocks":[{"h":"Physical properties","p":"Hydrogen H₂ is a colourless, odourless and tasteless gas. It is the lightest of all gases, about 14.5 times lighter than air. Because its molecules are so small and light, hydrogen spreads (diffuses) faster than other gases and easily passes through tiny gaps.","items":["Mass of 1 L at STP ≈ 0.09 g","Boiling point −253 °C","Very poorly soluble in water","Dissolves well in metals such as palladium, nickel and platinum","A good conductor of heat"],"visual":{"type":"molecule3d","mol":"H2"}},{"h":"Reactions with non-metals","p":"Under ordinary conditions the H₂ molecule is not very reactive, but it combines with non-metals to form volatile compounds. The rate depends on how active the non-metal is: with fluorine it reacts explosively even in the cold and dark, while with nitrogen it reacts only at high temperature and pressure with a catalyst.","items":["H₂ + F₂ → 2HF","H₂ + Cl₂ → 2HCl (in light or on heating)","H₂ + S → H₂S (on heating)","N₂ + 3H₂ → 2NH₃ (high temperature, pressure, catalyst)"]},{"h":"Reaction with oxygen","p":"Pure hydrogen burns quietly in air with a pale bluish, almost invisible flame, forming water and releasing a great deal of heat. A mixture of two volumes of hydrogen and one volume of oxygen is called 'detonating gas' (oxyhydrogen) and explodes violently from a spark or flame. That is why hydrogen is always tested for purity before it is lit.","formula":"2H₂ + O₂ → 2H₂O","visual":{"type":"reaction","id":"h2_o2"}},{"h":"Reducing metal oxides; hydrides","p":"When heated, hydrogen takes oxygen away from many metal oxides and leaves the pure metal; this is called reduction. For example, when hydrogen is passed over black copper(II) oxide, red copper and droplets of water form. With very active metals such as sodium and calcium, hydrogen forms salt-like compounds called hydrides.","items":["CuO + H₂ → Cu + H₂O (on heating)","2Na + H₂ → 2NaH (sodium hydride)","Ca + H₂ → CaH₂ (calcium hydride)"]},{"h":"Worked example: reducing copper oxide","p":"Let's find the volume of hydrogen at STP needed to reduce 8 g of copper(II) oxide completely, and the mass of copper formed.","formula":"CuO + H₂ → Cu + H₂O","items":["M(CuO) = 64 + 16 = 80 g/mol; n(CuO) = 8 / 80 = 0.1 mol","n(H₂) = n(CuO) = 0.1 mol; V(H₂) = 0.1 × 22.4 = 2.24 L","n(Cu) = 0.1 mol; m(Cu) = 0.1 × 64 = 6.4 g","Answer: 2.24 L of hydrogen, 6.4 g of copper"]},{"h":"Remember","items":["H₂ is a colourless, odourless gas, the lightest of all","Hydrogen combines with non-metals and burns in oxygen to form water","A 2:1 mixture of H₂ and O₂ is explosive 'detonating gas'","On heating, hydrogen reduces metals from their oxides, so it is used in metallurgy"]}],"quiz":[{"q":"About how many times lighter than air is hydrogen?","options":["2 times","14.5 times","29 times","1.5 times"],"correct":1,"explain":"M(air) ≈ 29, M(H₂) = 2, and 29 / 2 ≈ 14.5."},{"q":"What forms when hydrogen is passed over heated CuO?","options":["Cu and H₂O","CuH₂ and O₂","Cu(OH)₂","CuO₂ and H₂"],"correct":0,"explain":"Hydrogen removes oxygen from the oxide, forming copper and water."},{"q":"What is 'detonating gas'?","options":["N₂ and H₂ (1:3)","H₂ and Cl₂ (1:1)","CO and O₂ (2:1)","H₂ and O₂ (2:1)"],"correct":3,"explain":"Two volumes of hydrogen with one volume of oxygen explode violently."}]},"ru":{"title":"Водород – простое вещество. Физические и химические свойства","intro":"Водород – самый лёгкий газ: наполненный им шар сам поднимается в воздух. Химически он образует с кислородом взрывчатую смесь и умеет отнимать кислород у оксидов металлов. Давайте изучим свойства этого удивительного вещества.","blocks":[{"h":"Физические свойства","p":"Водород H₂ – бесцветный газ без запаха и вкуса. Это самый лёгкий из всех газов, примерно в 14,5 раза легче воздуха. Его молекулы очень малы и легки, поэтому водород распространяется (диффундирует) быстрее других газов и легко проходит через мельчайшие щели.","items":["Масса 1 л при н. у. ≈ 0,09 г","Температура кипения −253 °C","Очень плохо растворяется в воде","Хорошо растворяется в металлах – палладии, никеле, платине","Хорошо проводит тепло"],"visual":{"type":"molecule3d","mol":"H2"}},{"h":"Реакции с неметаллами","p":"При обычных условиях молекула H₂ не очень активна, но с неметаллами она образует летучие соединения. Скорость реакции зависит от активности неметалла: со фтором водород реагирует со взрывом даже на холоде и в темноте, а с азотом – только при высокой температуре, давлении и с катализатором.","items":["H₂ + F₂ → 2HF","H₂ + Cl₂ → 2HCl (на свету или при нагревании)","H₂ + S → H₂S (при нагревании)","N₂ + 3H₂ → 2NH₃ (высокая температура, давление, катализатор)"]},{"h":"Реакция с кислородом","p":"Чистый водород спокойно горит на воздухе бледно-голубым, почти невидимым пламенем, образуя воду и выделяя очень много тепла. Смесь двух объёмов водорода и одного объёма кислорода называется «гремучим газом» – от искры или пламени она сильно взрывается. Поэтому перед поджиганием водород всегда проверяют на чистоту.","formula":"2H₂ + O₂ → 2H₂O","visual":{"type":"reaction","id":"h2_o2"}},{"h":"Восстановление металлов из оксидов; гидриды","p":"При нагревании водород отнимает кислород у многих оксидов металлов, оставляя чистый металл, – этот процесс называется восстановлением. Например, если пропускать водород над чёрным оксидом меди(II), образуются красная медь и капельки воды. С очень активными металлами, такими как натрий и кальций, водород образует солеобразные соединения – гидриды.","items":["CuO + H₂ → Cu + H₂O (при нагревании)","2Na + H₂ → 2NaH (гидрид натрия)","Ca + H₂ → CaH₂ (гидрид кальция)"]},{"h":"Пример: восстановление оксида меди","p":"Найдём объём водорода (н. у.), необходимый для полного восстановления 8 г оксида меди(II), и массу образовавшейся меди.","formula":"CuO + H₂ → Cu + H₂O","items":["M(CuO) = 64 + 16 = 80 г/моль; n(CuO) = 8 / 80 = 0,1 моль","n(H₂) = n(CuO) = 0,1 моль; V(H₂) = 0,1 · 22,4 = 2,24 л","n(Cu) = 0,1 моль; m(Cu) = 0,1 · 64 = 6,4 г","Ответ: 2,24 л водорода, 6,4 г меди"]},{"h":"Запомните","items":["H₂ – бесцветный газ без запаха, самый лёгкий из всех","Водород соединяется с неметаллами и горит в кислороде с образованием воды","Смесь H₂ и O₂ в объёмном отношении 2:1 – взрывчатый «гремучий газ»","При нагревании водород восстанавливает металлы из оксидов, поэтому его применяют в металлургии"]}],"quiz":[{"q":"Примерно во сколько раз водород легче воздуха?","options":["В 2 раза","В 14,5 раза","В 29 раз","В 1,5 раза"],"correct":1,"explain":"M(воздуха) ≈ 29, M(H₂) = 2, 29 / 2 ≈ 14,5."},{"q":"Что образуется при пропускании водорода над нагретым CuO?","options":["Cu и H₂O","CuH₂ и O₂","Cu(OH)₂","CuO₂ и H₂"],"correct":0,"explain":"Водород отнимает у оксида кислород, образуя медь и воду."},{"q":"Что такое «гремучий газ»?","options":["N₂ и H₂ (1:3)","H₂ и Cl₂ (1:1)","CO и O₂ (2:1)","H₂ и O₂ (2:1)"],"correct":3,"explain":"Два объёма водорода с одним объёмом кислорода сильно взрываются."}]}},{"id":"t26","num":26,"icon":"🚀","uz":{"title":"Vodorod – ekologik toza yoqilg'i. Ishlatilishi","intro":"Ko'mir, benzin va gaz yonganda havoga karbonat angidrid va zararli moddalar chiqadi. Vodorod yonganda esa faqat suv hosil bo'ladi. Shuning uchun olimlar vodorodni kelajak yoqilg'isi deb atashadi.","blocks":[{"h":"Nima uchun vodorod toza yoqilg'i","p":"Vodorod yonganda yagona mahsulot – suv bug'i, u havoni ifloslantirmaydi va karbonat angidrid chiqarmaydi. Bundan tashqari, 1 kg vodorod yonganda 1 kg benzinga qaraganda taxminan uch marta ko'p issiqlik ajraladi. Vodorod uchun xomashyo – suv – Yerda juda ko'p.","formula":"2H₂ + O₂ → 2H₂O + issiqlik","items":["Ko'mir, neft mahsulotlari: CO₂, SO₂, qurum, kul","Vodorod: faqat H₂O"]},{"h":"Vodorod energetikasining muammolari","p":"Vodorodni keng qo'llash uchun hali bir necha muammoni hal qilish kerak. Uni suvdan olish ko'p elektr energiyasi talab qiladi, shuning uchun bu energiyani quyosh va shamol stansiyalaridan olish istiqbolli. Vodorod juda yengil va ko'p joy egallaydi, uni siqib yoki −253 °C gacha sovitib saqlash kerak, havo bilan aralashmasi esa portlovchi.","items":["Arzon va toza usulda olish","Xavfsiz saqlash va tashish","Yoqilg'i elementlari: vodoroddan to'g'ridan-to'g'ri elektr toki olinadi, avtomobil va avtobuslarda sinab ko'rilmoqda"],"visual":{"type":"diagram","kind":"electrolysis"}},{"h":"Yulduzlar energiyasi","p":"Quyosh va boshqa yulduzlar qa'rida vodorod yadrolari qo'shilib geliyga aylanadi – bu termoyadro reaksiyasi bo'lib, juda katta energiya beradi. Agar olimlar bu jarayonni Yerda boshqariladigan tarzda amalga oshirishni o'rgansalar, insoniyat deyarli tuganmas energiya manbaiga ega bo'ladi."},{"h":"Vodorodning ishlatilishi","p":"Vodorod kimyo sanoati va texnikada juda ko'p ishlatiladi. Uning eng katta qismi ammiak ishlab chiqarishga sarflanadi, ammiakdan esa o'g'itlar va nitrat kislota olinadi.","items":["Ammiak sintezi (N₂ + 3H₂ → 2NH₃) – o'g'itlar uchun","Xlorid kislota va metil spirti ishlab chiqarish","Suyuq o'simlik moylarini vodorod bilan to'yintirib (gidrogenlab) qattiq yog' – margarin olish","Vodorod-kislorod alangasida qiyin suyuqlanadigan metallarni kesish va payvandlash","Metallurgiyada oksidlardan toza metallar olish","Suyuq vodorod – raketa yoqilg'isi"]},{"h":"Namuna: vodorod yonganda qancha suv hosil bo'ladi","p":"4 g vodorod to'liq yonganda qancha suv hosil bo'lishini hisoblaymiz.","formula":"2H₂ + O₂ → 2H₂O","items":["n(H₂) = 4 g / 2 g/mol = 2 mol","Tenglamaga ko'ra n(H₂O) = n(H₂) = 2 mol","m(H₂O) = 2 mol · 18 g/mol = 36 g","Javob: 36 g suv – boshqa hech qanday mahsulot hosil bo'lmaydi"]},{"h":"Esda tuting","items":["Vodorod yonganda faqat suv hosil bo'ladi – bu ekologik toza yoqilg'i","Massa birligiga vodorod benzinga qaraganda ancha ko'p issiqlik beradi","Vodorodning asosiy qismi ammiak ishlab chiqarishga sarflanadi","Vodoroddan margarin olishda, metallarni payvandlashda va raketa yoqilg'isi sifatida foydalaniladi"]}],"quiz":[{"q":"Vodorod yonganda qanday mahsulot hosil bo'ladi?","options":["Karbonat angidrid","Suv","Is gazi","Oltingugurt dioksidi"],"correct":1,"explain":"2H₂ + O₂ → 2H₂O, boshqa mahsulot yo'q."},{"q":"Sanoatda vodorodning eng ko'p qismi nimaga sarflanadi?","options":["Havo sharlarini to'ldirishga","Ichimlik suvini tozalashga","Ammiak ishlab chiqarishga","Shisha ishlab chiqarishga"],"correct":2,"explain":"Ammiakdan o'g'itlar va nitrat kislota olinadi."},{"q":"Suyuq o'simlik moyidan margarin olish jarayoni qanday ataladi?","options":["Gidrogenlash","Elektroliz","Filtrlash","Distillash"],"correct":0,"explain":"Moylarni vodorod bilan to'yintirish gidrogenlash deyiladi."}]},"en":{"title":"Hydrogen as a clean fuel. Uses","intro":"When coal, petrol and gas burn, carbon dioxide and harmful substances enter the air. When hydrogen burns, only water is formed. That is why scientists call hydrogen the fuel of the future.","blocks":[{"h":"Why hydrogen is a clean fuel","p":"The only product of burning hydrogen is water vapour, which does not pollute the air and adds no carbon dioxide. In addition, burning 1 kg of hydrogen releases about three times more heat than burning 1 kg of petrol. The raw material for hydrogen, water, is extremely plentiful on Earth.","formula":"2H₂ + O₂ → 2H₂O + heat","items":["Coal and oil products: CO₂, SO₂, soot, ash","Hydrogen: only H₂O"]},{"h":"Challenges of hydrogen energy","p":"Several problems still need to be solved before hydrogen can be used widely. Making it from water needs a lot of electricity, so getting that electricity from solar and wind power is a promising approach. Hydrogen is very light and takes up a lot of space, so it must be compressed or cooled to −253 °C for storage, and its mixtures with air are explosive.","items":["Producing it cheaply and cleanly","Storing and transporting it safely","Fuel cells turn hydrogen directly into electric current and are being tested in cars and buses"],"visual":{"type":"diagram","kind":"electrolysis"}},{"h":"The energy of the stars","p":"Deep inside the Sun and other stars, hydrogen nuclei fuse to form helium; this thermonuclear reaction releases enormous energy. If scientists learn to carry out this process on Earth in a controlled way, humanity will gain an almost inexhaustible source of energy."},{"h":"Uses of hydrogen","p":"Hydrogen is used in large amounts in the chemical industry and in technology. The biggest share goes into making ammonia, from which fertilisers and nitric acid are produced.","items":["Ammonia synthesis (N₂ + 3H₂ → 2NH₃) for fertilisers","Making hydrochloric acid and methanol","Hydrogenating liquid vegetable oils to make solid fat (margarine)","Cutting and welding high-melting metals with an oxyhydrogen flame","Obtaining pure metals from their oxides in metallurgy","Liquid hydrogen as rocket fuel"]},{"h":"Worked example: water from burning hydrogen","p":"Let's calculate the mass of water formed when 4 g of hydrogen burns completely.","formula":"2H₂ + O₂ → 2H₂O","items":["n(H₂) = 4 g / 2 g/mol = 2 mol","From the equation n(H₂O) = n(H₂) = 2 mol","m(H₂O) = 2 mol × 18 g/mol = 36 g","Answer: 36 g of water, and no other product forms"]},{"h":"Remember","items":["Burning hydrogen produces only water, so it is an environmentally clean fuel","Per kilogram, hydrogen gives much more heat than petrol","Most hydrogen is used to make ammonia","Hydrogen is used to make margarine, to weld metals and as rocket fuel"]}],"quiz":[{"q":"What product forms when hydrogen burns?","options":["Carbon dioxide","Water","Carbon monoxide","Sulfur dioxide"],"correct":1,"explain":"2H₂ + O₂ → 2H₂O, with no other product."},{"q":"What is most industrial hydrogen used for?","options":["Filling balloons","Purifying drinking water","Making ammonia","Making glass"],"correct":2,"explain":"Ammonia is used to produce fertilisers and nitric acid."},{"q":"What is the process of turning liquid vegetable oil into margarine called?","options":["Hydrogenation","Electrolysis","Filtration","Distillation"],"correct":0,"explain":"Saturating oils with hydrogen is called hydrogenation."}]},"ru":{"title":"Водород – экологически чистое топливо. Применение","intro":"При сгорании угля, бензина и газа в воздух попадают углекислый газ и вредные вещества. А при сгорании водорода образуется только вода. Поэтому учёные называют водород топливом будущего.","blocks":[{"h":"Почему водород – чистое топливо","p":"Единственный продукт сгорания водорода – водяной пар, он не загрязняет воздух и не добавляет углекислого газа. Кроме того, при сгорании 1 кг водорода выделяется примерно в три раза больше тепла, чем при сгорании 1 кг бензина. Сырья для получения водорода – воды – на Земле очень много.","formula":"2H₂ + O₂ → 2H₂O + тепло","items":["Уголь и нефтепродукты: CO₂, SO₂, сажа, зола","Водород: только H₂O"]},{"h":"Проблемы водородной энергетики","p":"Чтобы водород применялся широко, нужно решить ещё несколько задач. Получение его из воды требует много электроэнергии, поэтому перспективно брать её от солнечных и ветровых станций. Водород очень лёгкий и занимает много места, его хранят сжатым или охлаждённым до −253 °C, а его смеси с воздухом взрывоопасны.","items":["Дешёвое и чистое получение","Безопасное хранение и перевозка","Топливные элементы превращают водород прямо в электрический ток и уже испытываются в автомобилях и автобусах"],"visual":{"type":"diagram","kind":"electrolysis"}},{"h":"Энергия звёзд","p":"В недрах Солнца и других звёзд ядра водорода сливаются, образуя гелий; эта термоядерная реакция даёт огромную энергию. Если учёные научатся проводить этот процесс на Земле управляемо, человечество получит практически неисчерпаемый источник энергии."},{"h":"Применение водорода","p":"Водород в больших количествах используется в химической промышленности и технике. Больше всего его расходуется на производство аммиака, из которого получают удобрения и азотную кислоту.","items":["Синтез аммиака (N₂ + 3H₂ → 2NH₃) для удобрений","Производство соляной кислоты и метилового спирта","Гидрогенизация жидких растительных масел с получением твёрдого жира – маргарина","Резка и сварка тугоплавких металлов водородно-кислородным пламенем","Получение чистых металлов из оксидов в металлургии","Жидкий водород – ракетное топливо"]},{"h":"Пример: сколько воды даёт сгорание водорода","p":"Рассчитаем массу воды, которая образуется при полном сгорании 4 г водорода.","formula":"2H₂ + O₂ → 2H₂O","items":["n(H₂) = 4 г / 2 г/моль = 2 моль","По уравнению n(H₂O) = n(H₂) = 2 моль","m(H₂O) = 2 моль · 18 г/моль = 36 г","Ответ: 36 г воды, и никаких других продуктов"]},{"h":"Запомните","items":["При сгорании водорода образуется только вода – это экологически чистое топливо","На единицу массы водород даёт намного больше тепла, чем бензин","Больше всего водорода идёт на производство аммиака","Водород применяют для получения маргарина, сварки металлов и как ракетное топливо"]}],"quiz":[{"q":"Какой продукт образуется при сгорании водорода?","options":["Углекислый газ","Вода","Угарный газ","Сернистый газ"],"correct":1,"explain":"2H₂ + O₂ → 2H₂O, других продуктов нет."},{"q":"На что расходуется больше всего промышленного водорода?","options":["На наполнение воздушных шаров","На очистку питьевой воды","На производство аммиака","На производство стекла"],"correct":2,"explain":"Из аммиака получают удобрения и азотную кислоту."},{"q":"Как называется процесс получения маргарина из жидкого растительного масла?","options":["Гидрогенизация","Электролиз","Фильтрование","Перегонка"],"correct":0,"explain":"Насыщение масел водородом называется гидрогенизацией."}]}}]},{"title":{"uz":"4-bob. Suv va eritmalar","en":"Chapter 4. Water and solutions","ru":"Глава 4. Вода и растворы"},"topics":[{"id":"t27","num":27,"icon":"💧","uz":{"title":"Suv – murakkab modda. Fizik va kimyoviy xossalari","intro":"Har kuni ichadigan va yuvinadigan suvimiz aslida juda qiziq modda. Uning molekulasi bor-yo'g'i uchta atomdan iborat, ammo xossalari boshqa moddalarnikiga ko'p jihatdan o'xshamaydi. Keling, suvni kimyogar ko'zi bilan ko'rib chiqamiz.","blocks":[{"h":"Suv molekulasining tarkibi va shakli","p":"Suv ikki xil element – vodorod va kisloroddan hosil bo'lgan murakkab modda. Har bir molekulada ikkita vodorod atomi bitta kislorod atomiga birikkan. Molekula to'g'ri chiziq emas, balki burchak shaklida: H–O–H burchagi taxminan 104,5° ga teng. Suyuq suvda molekulalar bir-biriga tortilib, kichik guruhlar hosil qilib turadi.","formula":"H₂O","visual":{"type":"molecule3d","mol":"H2O"}},{"h":"Suvning molar massasi","p":"Molekulaning nisbiy massasi uni tashkil etgan barcha atomlar nisbiy massalarining yig'indisiga teng. Shu qiymatdan suvning molar massasi kelib chiqadi.","formula":"M(H₂O) = 18 g/mol","items":["Mr(H₂O) = 2·Ar(H) + Ar(O)","Mr(H₂O) = 2·1 + 16 = 18","Demak, 1 mol suvning massasi 18 g","18 g suvda 6,02·10²³ ta molekula bor"]},{"h":"Fizik xossalari","p":"Toza suv rangsiz, hidsiz va ta'msiz tiniq suyuqlik; unga ta'm va hidni erigan moddalar beradi. Odatdagi bosimda suv 0 °C da muzlaydi va 100 °C da qaynaydi. Suvning bir qancha xossalari boshqa moddalarnikiga o'xshamagani uchun anomal deb ataladi.","items":["Zichligi +4 °C da eng katta: 1 g/ml","Muzning zichligi taxminan 0,92 g/sm³, shuning uchun muz suvda suzadi","Issiqlik sig'imi juda katta (4,18 kJ/(kg·K)): suv sekin isiydi va sekin soviydi","Juda ko'p moddalarni erita oladi"],"table":{"head":["Harorat (101,3 kPa)","Suvning holati"],"rows":[["0 °C dan past","qattiq (muz)"],["0 °C dan 100 °C gacha","suyuq"],["100 °C dan yuqori","gaz (bug')"]]}},{"h":"Suvni elektr toki bilan parchalash","p":"Suv issiqlikka juda chidamli: u faqat juda yuqori haroratda sezilarli darajada parchalana boshlaydi. Ammo suv orqali o'zgarmas elektr toki o'tkazilsa, u vodorod va kislorodga ajraladi – bu jarayon elektroliz deyiladi. Bunda vodorod hajmi kislorod hajmidan ikki marta ko'p chiqadi, bu esa H₂O formulasini tasdiqlaydi.","formula":"2H₂O → 2H₂ + O₂","visual":{"type":"diagram","kind":"electrolysis"}},{"h":"Kimyoviy xossalari","p":"Suv faol modda va ko'plab moddalar bilan reaksiyaga kirishadi. Faol metallar suvdan vodorodni siqib chiqarib asos hosil qiladi, ba'zi oksidlar suv bilan asos yoki kislota beradi. Bundan tashqari, suv ko'p reaksiyalarning borishini tezlashtiradi.","items":["2Na + 2H₂O → 2NaOH + H₂↑","Ca + 2H₂O → Ca(OH)₂ + H₂↑","CaO + H₂O → Ca(OH)₂ (asos hosil bo'ladi)","SO₃ + H₂O → H₂SO₄ (kislota hosil bo'ladi)","Cho'g'langan temir suv bug'i bilan: 3Fe + 4H₂O → Fe₃O₄ + 4H₂","Oq CuSO₄ suvni biriktirib ko'k kristallogidratga aylanadi: CuSO₄ + 5H₂O → CuSO₄·5H₂O"]},{"h":"Esda tuting","items":["Suv – vodorod va kisloroddan iborat murakkab modda, formulasi H₂O, M = 18 g/mol","Suv +4 °C da eng zich, muz esa suvdan yengil","Elektrolizda vodorod va kislorod 2:1 hajmiy nisbatda ajraladi","Faol metallar va ko'p oksidlar suv bilan reaksiyaga kirishib, asos yoki kislota hosil qiladi"]}],"quiz":[{"q":"Suvning molar massasi qancha?","options":["16 g/mol","18 g/mol","20 g/mol","34 g/mol"],"correct":1,"explain":"2·1 + 16 = 18, demak M(H₂O) = 18 g/mol."},{"q":"Nima uchun muz suv yuzasida suzib yuradi?","options":["Muzning tarkibi boshqacha","Muz suvdan og'irroq","Muzning zichligi suyuq suvnikidan kichik","Muz suvda tez eriydi"],"correct":2,"explain":"Muzning zichligi taxminan 0,92 g/sm³, suvniki esa 1 g/ml atrofida, shuning uchun muz suzadi."},{"q":"Suv elektrolizida 10 ml kislorod ajraldi. Shu vaqtda qancha vodorod ajraladi?","options":["5 ml","10 ml","30 ml","20 ml"],"correct":3,"explain":"Reaksiya tenglamasiga ko'ra vodorod hajmi kisloroddan ikki marta ko'p."}]},"en":{"title":"Water – a compound. Physical and chemical properties","intro":"The water we drink and wash with every day is actually a remarkable substance. Its molecule contains only three atoms, yet in many ways it behaves unlike other substances. Let us look at water through the eyes of a chemist.","blocks":[{"h":"Composition and shape of the water molecule","p":"Water is a compound made of two elements – hydrogen and oxygen. In each molecule two hydrogen atoms are bonded to one oxygen atom. The molecule is not straight but bent: the H–O–H angle is about 104.5°. In liquid water the molecules attract one another and keep forming small clusters.","formula":"H₂O","visual":{"type":"molecule3d","mol":"H2O"}},{"h":"Molar mass of water","p":"The relative mass of a molecule equals the sum of the relative masses of all its atoms. The molar mass of water follows directly from this value.","formula":"M(H₂O) = 18 g/mol","items":["Mr(H₂O) = 2·Ar(H) + Ar(O)","Mr(H₂O) = 2·1 + 16 = 18","So 1 mol of water has a mass of 18 g","18 g of water contain 6.02×10²³ molecules"]},{"h":"Physical properties","p":"Pure water is a clear liquid with no colour, smell or taste; any taste or smell comes from dissolved substances. At normal pressure water freezes at 0 °C and boils at 100 °C. Several of its properties are called anomalous because they differ from those of most other substances.","items":["Its density is greatest at +4 °C: 1 g/mL","Ice has a density of about 0.92 g/cm³, so ice floats on water","Its heat capacity is very high (4.18 kJ/(kg·K)): water warms up and cools down slowly","It can dissolve a great many substances"],"table":{"head":["Temperature (101.3 kPa)","State of water"],"rows":[["below 0 °C","solid (ice)"],["from 0 °C to 100 °C","liquid"],["above 100 °C","gas (steam)"]]}},{"h":"Splitting water with electric current","p":"Water is very stable to heat: it only starts to break down noticeably at very high temperatures. But when a direct electric current passes through water, it splits into hydrogen and oxygen – this process is called electrolysis. The volume of hydrogen collected is twice the volume of oxygen, which confirms the formula H₂O.","formula":"2H₂O → 2H₂ + O₂","visual":{"type":"diagram","kind":"electrolysis"}},{"h":"Chemical properties","p":"Water is a reactive substance and reacts with many others. Active metals push hydrogen out of water and form bases, while some oxides react with water to give bases or acids. Water also speeds up many reactions.","items":["2Na + 2H₂O → 2NaOH + H₂↑","Ca + 2H₂O → Ca(OH)₂ + H₂↑","CaO + H₂O → Ca(OH)₂ (a base forms)","SO₃ + H₂O → H₂SO₄ (an acid forms)","Red-hot iron with steam: 3Fe + 4H₂O → Fe₃O₄ + 4H₂","White CuSO₄ takes up water and becomes a blue crystalline hydrate: CuSO₄ + 5H₂O → CuSO₄·5H₂O"]},{"h":"Remember","items":["Water is a compound of hydrogen and oxygen, formula H₂O, M = 18 g/mol","Water is densest at +4 °C, and ice is lighter than water","Electrolysis gives hydrogen and oxygen in a 2:1 volume ratio","Active metals and many oxides react with water to form bases or acids"]}],"quiz":[{"q":"What is the molar mass of water?","options":["16 g/mol","18 g/mol","20 g/mol","34 g/mol"],"correct":1,"explain":"2·1 + 16 = 18, so M(H₂O) = 18 g/mol."},{"q":"Why does ice float on water?","options":["Ice has a different composition","Ice is heavier than water","Ice is less dense than liquid water","Ice dissolves quickly in water"],"correct":2,"explain":"Ice has a density of about 0.92 g/cm³ while water is about 1 g/mL, so ice floats."},{"q":"During electrolysis of water 10 mL of oxygen were collected. How much hydrogen is collected at the same time?","options":["5 mL","10 mL","30 mL","20 mL"],"correct":3,"explain":"By the equation, the volume of hydrogen is twice that of oxygen."}]},"ru":{"title":"Вода – сложное вещество. Физические и химические свойства","intro":"Вода, которую мы каждый день пьём и которой умываемся, на самом деле удивительное вещество. Её молекула состоит всего из трёх атомов, но по многим свойствам вода не похожа на другие вещества. Давайте посмотрим на воду глазами химика.","blocks":[{"h":"Состав и форма молекулы воды","p":"Вода – сложное вещество, образованное двумя элементами: водородом и кислородом. В каждой молекуле два атома водорода связаны с одним атомом кислорода. Молекула не линейная, а угловая: угол H–O–H составляет примерно 104,5°. В жидкой воде молекулы притягиваются друг к другу и постоянно образуют небольшие группы.","formula":"H₂O","visual":{"type":"molecule3d","mol":"H2O"}},{"h":"Молярная масса воды","p":"Относительная масса молекулы равна сумме относительных масс всех входящих в неё атомов. Из этого значения сразу получается молярная масса воды.","formula":"M(H₂O) = 18 г/моль","items":["Mr(H₂O) = 2·Ar(H) + Ar(O)","Mr(H₂O) = 2·1 + 16 = 18","Значит, масса 1 моль воды равна 18 г","В 18 г воды содержится 6,02·10²³ молекул"]},{"h":"Физические свойства","p":"Чистая вода – прозрачная жидкость без цвета, запаха и вкуса; вкус и запах ей придают растворённые вещества. При обычном давлении вода замерзает при 0 °C и кипит при 100 °C. Некоторые её свойства называют аномальными, потому что они отличаются от свойств большинства веществ.","items":["Наибольшая плотность – при +4 °C: 1 г/мл","Плотность льда около 0,92 г/см³, поэтому лёд плавает на воде","Очень большая теплоёмкость (4,18 кДж/(кг·К)): вода медленно нагревается и медленно остывает","Растворяет очень многие вещества"],"table":{"head":["Температура (101,3 кПа)","Состояние воды"],"rows":[["ниже 0 °C","твёрдое (лёд)"],["от 0 °C до 100 °C","жидкое"],["выше 100 °C","газ (пар)"]]}},{"h":"Разложение воды электрическим током","p":"Вода очень устойчива к нагреванию: заметно разлагаться она начинает лишь при очень высокой температуре. Но если пропустить через воду постоянный электрический ток, она разлагается на водород и кислород – этот процесс называется электролизом. Объём водорода получается вдвое больше объёма кислорода, что подтверждает формулу H₂O.","formula":"2H₂O → 2H₂ + O₂","visual":{"type":"diagram","kind":"electrolysis"}},{"h":"Химические свойства","p":"Вода – активное вещество и реагирует со многими другими. Активные металлы вытесняют из воды водород и образуют основания, а некоторые оксиды с водой дают основания или кислоты. Кроме того, вода ускоряет многие реакции.","items":["2Na + 2H₂O → 2NaOH + H₂↑","Ca + 2H₂O → Ca(OH)₂ + H₂↑","CaO + H₂O → Ca(OH)₂ (образуется основание)","SO₃ + H₂O → H₂SO₄ (образуется кислота)","Раскалённое железо с водяным паром: 3Fe + 4H₂O → Fe₃O₄ + 4H₂","Белый CuSO₄ присоединяет воду и превращается в синий кристаллогидрат: CuSO₄ + 5H₂O → CuSO₄·5H₂O"]},{"h":"Запомните","items":["Вода – сложное вещество из водорода и кислорода, формула H₂O, M = 18 г/моль","Вода плотнее всего при +4 °C, а лёд легче воды","При электролизе водород и кислород выделяются в объёмном отношении 2:1","Активные металлы и многие оксиды реагируют с водой, образуя основания или кислоты"]}],"quiz":[{"q":"Чему равна молярная масса воды?","options":["16 г/моль","18 г/моль","20 г/моль","34 г/моль"],"correct":1,"explain":"2·1 + 16 = 18, значит M(H₂O) = 18 г/моль."},{"q":"Почему лёд плавает на поверхности воды?","options":["У льда другой состав","Лёд тяжелее воды","Плотность льда меньше плотности жидкой воды","Лёд быстро растворяется в воде"],"correct":2,"explain":"Плотность льда около 0,92 г/см³, а воды – около 1 г/мл, поэтому лёд плавает."},{"q":"При электролизе воды выделилось 10 мл кислорода. Сколько водорода выделится за то же время?","options":["5 мл","10 мл","30 мл","20 мл"],"correct":3,"explain":"По уравнению реакции объём водорода вдвое больше объёма кислорода."}]}},{"id":"t28","num":28,"icon":"🌍","uz":{"title":"Suvning tabiatda tarqalishi, tirik organizmlar uchun ahamiyati va ishlatilishi","intro":"Kosmosdan qaraganda Yer moviy sayyoraga o'xshaydi, chunki uning katta qismini suv qoplagan. Shunday bo'lsa-da, ichish uchun yaroqli suv juda kam. Bu darsda suv qayerda uchrashi, nima uchun hayot usiz mumkin emasligi va odamlar uni qanday ishlatishini bilib olamiz.","blocks":[{"h":"Yerdagi suv zaxiralari","p":"Yer yuzasining qariyb to'rtdan uch qismi suv bilan qoplangan. Sayyoradagi barcha suvning taxminan 97% i okean va dengizlarda bo'lib, u sho'r. Chuchuk suv bor-yo'g'i 3% atrofida, uning ham katta qismi qutb va tog' muzliklarida qotib yotadi.","visual":{"type":"chart","kind":"water"}},{"h":"Suv qayerlarda uchraydi","items":["Okean va dengizlar – sho'r suvning asosiy qismi","Muzliklar va qor – chuchuk suvning eng katta zaxirasi","Daryo, ko'l va yer osti suvlari","Atmosferada – bug', bulut va tuman ko'rinishida","Tuproq, tog' jinslari va tirik organizmlar tarkibida"]},{"h":"Tirik organizmlar uchun ahamiyati","p":"Katta yoshli odam tanasining taxminan 60–65% i suvdan iborat, ba'zi meduzalarda esa bu ko'rsatkich 95% dan oshadi. Suv tanada oziq moddalarni tashiydi, harorat me'yorini saqlaydi va keraksiz moddalarni chiqarib yuboradi. Organizm suvni ko'p yo'qotsa, hayot uchun xavfli holat yuzaga keladi, shuning uchun kun davomida yetarli suv ichish muhim."},{"h":"Suvning g'ayrioddiy xossalari hayotni qanday asraydi","p":"Qishda ko'l yuzasida hosil bo'lgan muz cho'kmaydi, balki suv ustida qatlam bo'lib qoladi. Bu qatlam pastdagi suvni sovuqdan to'sib turadi, tubda esa +4 °C li eng zich suv yig'iladi – baliqlar va boshqa jonzotlar shu yerda qishlaydi. Suvning katta issiqlik sig'imi tufayli okeanlar yozda issiqlikni yig'ib, qishda asta-sekin beradi va iqlimni yumshatadi."},{"h":"Odamlar suvni qanday ishlatadi","p":"Chuchuk suvning eng ko'p qismi qishloq xo'jaligida – ekinlarni sug'orishga sarflanadi. Uy-ro'zg'or ehtiyojlari kichikroq ulushni tashkil qiladi, lekin har bir oila uchun juda muhim. Oziq-ovqat yetishtirish va buyumlar ishlab chiqarishga ko'zga ko'rinmas tarzda juda ko'p suv ketadi.","items":["Ichish, ovqat tayyorlash, gigiyena","Ekin maydonlarini sug'orish va chorvachilik","Sanoatda sovituvchi, erituvchi va yuvuvchi vosita sifatida","Energetikada: gidroelektrostansiyalar va bug' turbinalari"]},{"h":"Esda tuting","items":["Yerdagi suvning taxminan 97% i sho'r, chuchuk suv atigi 3% atrofida","Inson tanasining taxminan 60–65% i suv","Muzning suv ustida qolishi va suvning katta issiqlik sig'imi Yerdagi hayotni himoya qiladi","Chuchuk suvning eng ko'p qismi sug'orishga sarflanadi – suvni tejash kerak"]}],"quiz":[{"q":"Yerdagi suvning taxminan qancha qismi okean va dengizlarda?","options":["50%","75%","97%","3%"],"correct":2,"explain":"Suvning qariyb 97% i okean va dengizlardagi sho'r suvdir."},{"q":"Nima uchun ko'llar qishda tubigacha muzlab qolmaydi?","options":["Muz suv yuzasida qolib, pastki qatlamlarni sovuqdan to'sadi","Ko'l tubida doim issiq manbalar bo'ladi","Baliqlar suvni isitib turadi","Ko'l suvi hech qachon muzlamaydi"],"correct":0,"explain":"Muz suvdan yengil bo'lgani uchun yuzada qatlam hosil qilib, pastdagi suvni sovuqdan saqlaydi."},{"q":"Chuchuk suvning eng katta qismi nimaga sarflanadi?","options":["Uy-ro'zg'or ehtiyojlariga","Qishloq xo'jaligida sug'orishga","Transportga","Faqat ichishga"],"correct":1,"explain":"Dunyo bo'yicha chuchuk suvning eng ko'p qismi ekinlarni sug'orishga ketadi."}]},"en":{"title":"Water in nature, its importance for living things and its uses","intro":"Seen from space, Earth looks like a blue planet because water covers most of it. Even so, water fit for drinking is surprisingly scarce. In this lesson we find out where water is found, why life is impossible without it and how people use it.","blocks":[{"h":"Earth's water reserves","p":"About three quarters of Earth's surface is covered with water. Roughly 97% of all the water on the planet is in the oceans and seas, and it is salty. Fresh water makes up only about 3%, and most of it is frozen in polar and mountain glaciers.","visual":{"type":"chart","kind":"water"}},{"h":"Where water is found","items":["Oceans and seas – most of the salt water","Glaciers and snow – the largest store of fresh water","Rivers, lakes and groundwater","In the atmosphere – as vapour, clouds and fog","In soil, rocks and living organisms"]},{"h":"Importance for living things","p":"About 60–65% of an adult human body is water, and in some jellyfish the figure is above 95%. In the body water carries nutrients, keeps the temperature steady and removes waste substances. Losing a lot of water is dangerous for life, so it is important to drink enough during the day."},{"h":"How water's unusual properties protect life","p":"In winter the ice that forms on a lake does not sink but stays on top as a layer. This layer shields the water below from the cold, while the densest water at +4 °C collects at the bottom – fish and other creatures spend the winter there. Thanks to water's high heat capacity, oceans store heat in summer, release it slowly in winter and make the climate milder."},{"h":"How people use water","p":"The largest share of fresh water goes to agriculture – watering crops. Household needs take a smaller share, but they matter to every family. Growing food and making goods quietly uses enormous amounts of water.","items":["Drinking, cooking and hygiene","Irrigating fields and raising livestock","In industry as a coolant, a solvent and a cleaning agent","In energy: hydroelectric power stations and steam turbines"]},{"h":"Remember","items":["About 97% of Earth's water is salty; fresh water is only about 3%","About 60–65% of the human body is water","Floating ice and water's high heat capacity protect life on Earth","Most fresh water is used for irrigation – water should be saved"]}],"quiz":[{"q":"Roughly what share of Earth's water is in the oceans and seas?","options":["50%","75%","97%","3%"],"correct":2,"explain":"About 97% of the water is salt water in oceans and seas."},{"q":"Why do lakes not freeze all the way to the bottom in winter?","options":["Ice stays on top and shields the lower layers from the cold","There are always hot springs at the bottom","Fish keep the water warm","Lake water never freezes"],"correct":0,"explain":"Ice is lighter than water, so it forms a layer on top and protects the water below from the cold."},{"q":"What is the largest share of fresh water used for?","options":["Household needs","Irrigation in agriculture","Transport","Drinking only"],"correct":1,"explain":"Worldwide, most fresh water goes to watering crops."}]},"ru":{"title":"Вода в природе, её значение для живых организмов и применение","intro":"Из космоса Земля выглядит голубой планетой, потому что большую её часть покрывает вода. И всё же пригодной для питья воды удивительно мало. На этом уроке мы узнаем, где встречается вода, почему без неё невозможна жизнь и как люди её используют.","blocks":[{"h":"Запасы воды на Земле","p":"Около трёх четвертей поверхности Земли покрыто водой. Примерно 97% всей воды планеты находится в океанах и морях, и она солёная. На пресную воду приходится лишь около 3%, причём большая её часть заморожена в полярных и горных ледниках.","visual":{"type":"chart","kind":"water"}},{"h":"Где встречается вода","items":["Океаны и моря – основная часть солёной воды","Ледники и снег – самый большой запас пресной воды","Реки, озёра и подземные воды","В атмосфере – в виде пара, облаков и тумана","В почве, горных породах и живых организмах"]},{"h":"Значение для живых организмов","p":"Тело взрослого человека примерно на 60–65% состоит из воды, а у некоторых медуз эта доля превышает 95%. В организме вода переносит питательные вещества, поддерживает постоянную температуру и выводит ненужные вещества. Большая потеря воды опасна для жизни, поэтому важно пить достаточно воды в течение дня."},{"h":"Как необычные свойства воды берегут жизнь","p":"Зимой лёд, образовавшийся на озере, не тонет, а остаётся сверху слоем. Этот слой защищает нижнюю воду от холода, а у дна собирается самая плотная вода с температурой +4 °C – там зимуют рыбы и другие обитатели. Благодаря большой теплоёмкости воды океаны летом накапливают тепло, зимой медленно его отдают и смягчают климат."},{"h":"Как люди используют воду","p":"Больше всего пресной воды расходуется в сельском хозяйстве – на полив посевов. Бытовые нужды занимают меньшую долю, но важны для каждой семьи. На выращивание продуктов и производство вещей незаметно уходит огромное количество воды.","items":["Питьё, приготовление пищи, гигиена","Полив полей и животноводство","В промышленности – как охладитель, растворитель и моющее средство","В энергетике: гидроэлектростанции и паровые турбины"]},{"h":"Запомните","items":["Около 97% воды на Земле солёная, пресной – лишь около 3%","Тело человека примерно на 60–65% состоит из воды","Плавающий лёд и большая теплоёмкость воды защищают жизнь на Земле","Больше всего пресной воды уходит на полив – воду нужно беречь"]}],"quiz":[{"q":"Какая примерно доля воды Земли находится в океанах и морях?","options":["50%","75%","97%","3%"],"correct":2,"explain":"Около 97% воды – это солёная вода океанов и морей."},{"q":"Почему озёра зимой не промерзают до дна?","options":["Лёд остаётся сверху и защищает нижние слои от холода","На дне всегда есть горячие источники","Рыбы согревают воду","Озёрная вода никогда не замерзает"],"correct":0,"explain":"Лёд легче воды, поэтому он образует слой сверху и защищает воду внизу от холода."},{"q":"На что расходуется наибольшая часть пресной воды?","options":["На бытовые нужды","На полив в сельском хозяйстве","На транспорт","Только на питьё"],"correct":1,"explain":"В мире больше всего пресной воды уходит на полив посевов."}]}},{"id":"t29","num":29,"icon":"🚰","uz":{"title":"Suv havzalarini ifloslanishdan saqlash. Suvni tozalash usullari","intro":"Jo'mrakdan oqayotgan toza suv o'z-o'zidan paydo bo'lmaydi – u uzoq yo'l bosib, bir necha bosqichda tozalanadi. Daryo va ko'llarni ifloslantirsak, bu ish yanada qiyinlashadi. Keling, suv qanday ifloslanishi va qanday tozalanishini ko'rib chiqamiz.","blocks":[{"h":"Toza suv – qimmatli boylik","p":"Yerda suv ko'p bo'lsa ham, ichishga yaroqli chuchuk suv uning juda kichik qismini tashkil etadi. Aholi soni va sanoat o'sib borgani sari suvga ehtiyoj ortmoqda. Mutaxassislar kelajakda ko'plab mintaqalar toza suv tanqisligiga duch kelishi mumkinligini ogohlantirmoqda."},{"h":"Suvni nimalar ifloslantiradi","items":["Shahar va qishloqlardan chiqadigan maishiy oqova suvlar","Sanoat chiqindilari: neft mahsulotlari, og'ir metallar, bo'yoqlar","Dalalardan yuvilib tushadigan o'g'itlar va zararkunandalarga qarshi vositalar","Suvga tashlangan plastik va boshqa maishiy chiqindilar"]},{"h":"Suv havzalarini qanday asraymiz","items":["Oqova suvlarni tozalash inshootlaridan o'tkazib, keyin tabiatga qaytarish","O'g'it va kimyoviy vositalarni me'yorida ishlatish","Daryo va ko'l bo'ylarida muhofaza mintaqalari va daraxtzorlar barpo etish","Chiqindini suvga tashlamaslik, xazonni yoqmaslik va suvni tejash"]},{"h":"Ichimlik suvi qanday tozalanadi","p":"Ochiq manbadan olingan suvda loyqa, erigan tuzlar, gazlar va mikroblar bo'ladi. Shahar suv tozalash inshootlarida u ketma-ket bir necha bosqichdan o'tkaziladi.","items":["1) Tindirish va koagulyatsiya: maxsus moddalar qo'shiladi, mayda loyqa zarrachalar bir-biriga yopishib cho'kadi","2) Qum filtridan o'tkazish: qolgan mayda zarrachalar va mikroblarning katta qismi ushlanadi","3) Zararsizlantirish: suv xlorlanadi yoki ozonlanadi, qolgan mikroblar halok bo'ladi","4) Toza suv quvurlar orqali aholiga yetkaziladi"],"visual":{"type":"diagram","kind":"filtration"}},{"h":"Eng toza suv: distillash","p":"Filtr erigan moddalarni ushlab qola olmaydi. Erigan tuzlardan qutulish uchun suv qaynatiladi, bug'i esa sovitkichda yana suyuqlikka aylantiriladi. Tuzlar kolbada qoladi, idishga esa distillangan suv yig'iladi – u laboratoriyada, tibbiyotda va avtomobil akkumulyatorlarida ishlatiladi. Uy sharoitida suvni qaynatish va maishiy filtrlar ham foydali.","visual":{"type":"diagram","kind":"distillation"}},{"h":"Esda tuting","items":["Ichishga yaroqli chuchuk suv juda kam, uni ifloslantirmaslik kerak","Asosiy ifloslantiruvchilar – oqova suvlar, sanoat chiqindilari va o'g'itlar","Ichimlik suvi tindirish, qum filtri va xlorlash (ozonlash) orqali tozalanadi","Distillash erigan tuzlardan ham tozalaydi"]}],"quiz":[{"q":"Suv tozalash inshootida mikroblarni yo'q qilish uchun odatda nima qilinadi?","options":["Suv bo'yaladi","Suv xlorlanadi yoki ozonlanadi","Suvga qand qo'shiladi","Suv muzlatiladi"],"correct":1,"explain":"Xlor yoki ozon mikroblarni halok qiladi va suvni zararsizlantiradi."},{"q":"Filtrlashda suvdan nima ajraladi?","options":["Erigan osh tuzi","Erigan qand","Erigan gazlar","Erimagan qattiq zarrachalar"],"correct":3,"explain":"Filtr faqat erimagan zarrachalarni ushlaydi, erigan moddalar u orqali o'tib ketadi."},{"q":"Sho'r suv distillanganda tuz qayerda qoladi?","options":["Sovitkichda","Qabul qiluvchi idishda","Qizdirilayotgan kolbada","Bug' bilan birga chiqib ketadi"],"correct":2,"explain":"Bug'ga faqat suv aylanadi, tuz esa qizdirilayotgan kolbada qoladi."}]},"en":{"title":"Protecting water bodies from pollution. Methods of water purification","intro":"The clean water coming out of the tap does not appear by itself – it travels a long way and is purified in several stages. If we pollute rivers and lakes, this job becomes even harder. Let us see how water gets polluted and how it is cleaned.","blocks":[{"h":"Clean water is a precious resource","p":"Although Earth has a lot of water, fresh water fit for drinking is only a very small part of it. As the population and industry grow, the demand for water keeps rising. Experts warn that in the future many regions may face a shortage of clean water."},{"h":"What pollutes water","items":["Household wastewater from towns and villages","Industrial waste: oil products, heavy metals, dyes","Fertilisers and pest-control chemicals washed off fields","Plastic and other household rubbish thrown into water"]},{"h":"How we can protect water bodies","items":["Passing wastewater through treatment plants before returning it to nature","Using fertilisers and chemicals only in proper amounts","Creating protected zones and planting trees along rivers and lakes","Not throwing rubbish into water, not burning fallen leaves, and saving water"]},{"h":"How drinking water is purified","p":"Water taken from an open source contains mud, dissolved salts, gases and microbes. At a city water treatment plant it passes through several stages one after another.","items":["1) Settling and coagulation: special substances are added, and tiny mud particles stick together and sink","2) Sand filtration: the remaining fine particles and most microbes are trapped","3) Disinfection: the water is chlorinated or ozonated, and the remaining microbes are killed","4) The clean water is delivered to homes through pipes"],"visual":{"type":"diagram","kind":"filtration"}},{"h":"The purest water: distillation","p":"A filter cannot hold back dissolved substances. To get rid of dissolved salts, water is boiled and its vapour is turned back into liquid in a condenser. The salts stay in the flask, and distilled water collects in the receiver – it is used in laboratories, medicine and car batteries. At home, boiling water and household filters are also helpful.","visual":{"type":"diagram","kind":"distillation"}},{"h":"Remember","items":["Fresh drinking water is scarce, so it must not be polluted","The main pollutants are wastewater, industrial waste and fertilisers","Drinking water is purified by settling, sand filtration and chlorination (ozonation)","Distillation also removes dissolved salts"]}],"quiz":[{"q":"What is usually done at a treatment plant to kill microbes in water?","options":["The water is dyed","The water is chlorinated or ozonated","Sugar is added to the water","The water is frozen"],"correct":1,"explain":"Chlorine or ozone kills microbes and makes the water safe."},{"q":"What does filtration remove from water?","options":["Dissolved table salt","Dissolved sugar","Dissolved gases","Undissolved solid particles"],"correct":3,"explain":"A filter traps only undissolved particles; dissolved substances pass through it."},{"q":"When salty water is distilled, where does the salt stay?","options":["In the condenser","In the receiving vessel","In the heated flask","It leaves with the vapour"],"correct":2,"explain":"Only water turns into vapour, so the salt remains in the heated flask."}]},"ru":{"title":"Охрана водоёмов от загрязнения. Способы очистки воды","intro":"Чистая вода из крана не появляется сама собой – она проходит долгий путь и очищается в несколько этапов. Если загрязнять реки и озёра, эта работа становится ещё сложнее. Давайте разберёмся, как вода загрязняется и как её очищают.","blocks":[{"h":"Чистая вода – ценное богатство","p":"Хотя воды на Земле много, пресная вода, пригодная для питья, составляет лишь очень малую её часть. С ростом населения и промышленности потребность в воде постоянно растёт. Специалисты предупреждают, что в будущем многие регионы могут столкнуться с нехваткой чистой воды."},{"h":"Что загрязняет воду","items":["Бытовые сточные воды городов и сёл","Промышленные отходы: нефтепродукты, тяжёлые металлы, красители","Удобрения и средства от вредителей, смываемые с полей","Пластик и другой бытовой мусор, выброшенный в воду"]},{"h":"Как мы можем беречь водоёмы","items":["Пропускать сточные воды через очистные сооружения, прежде чем вернуть их в природу","Применять удобрения и химические средства только в нужных количествах","Создавать охранные зоны и сажать деревья вдоль рек и озёр","Не бросать мусор в воду, не сжигать опавшие листья и экономить воду"]},{"h":"Как очищают питьевую воду","p":"Вода из открытого источника содержит муть, растворённые соли, газы и микробы. На городской водоочистной станции она последовательно проходит несколько этапов.","items":["1) Отстаивание и коагуляция: добавляют специальные вещества, мелкие частицы мути слипаются и оседают","2) Фильтрование через песок: задерживаются оставшиеся мелкие частицы и большая часть микробов","3) Обеззараживание: воду хлорируют или озонируют, оставшиеся микробы погибают","4) Чистая вода по трубам поступает к жителям"],"visual":{"type":"diagram","kind":"filtration"}},{"h":"Самая чистая вода: перегонка","p":"Фильтр не задерживает растворённые вещества. Чтобы избавиться от растворённых солей, воду кипятят, а её пар в холодильнике снова превращают в жидкость. Соли остаются в колбе, а в приёмнике собирается дистиллированная вода – её используют в лабораториях, медицине и автомобильных аккумуляторах. В домашних условиях полезны кипячение и бытовые фильтры.","visual":{"type":"diagram","kind":"distillation"}},{"h":"Запомните","items":["Пресной питьевой воды мало, поэтому её нельзя загрязнять","Главные загрязнители – сточные воды, промышленные отходы и удобрения","Питьевую воду очищают отстаиванием, песчаным фильтром и хлорированием (озонированием)","Перегонка очищает воду и от растворённых солей"]}],"quiz":[{"q":"Что обычно делают на очистной станции, чтобы уничтожить микробы в воде?","options":["Воду окрашивают","Воду хлорируют или озонируют","В воду добавляют сахар","Воду замораживают"],"correct":1,"explain":"Хлор или озон убивают микробы и обеззараживают воду."},{"q":"Что удаляется из воды при фильтровании?","options":["Растворённая поваренная соль","Растворённый сахар","Растворённые газы","Нерастворимые твёрдые частицы"],"correct":3,"explain":"Фильтр задерживает только нерастворённые частицы, а растворённые вещества проходят сквозь него."},{"q":"Где остаётся соль при перегонке солёной воды?","options":["В холодильнике","В приёмнике","В нагреваемой колбе","Уходит вместе с паром"],"correct":2,"explain":"В пар превращается только вода, поэтому соль остаётся в нагреваемой колбе."}]}},{"id":"t30","num":30,"icon":"🥄","uz":{"title":"Suv – eng yaxshi erituvchi. Eruvchanlik","intro":"Choyga solingan qand bir zumda ko'zdan g'oyib bo'ladi, qum esa idish tubida yotaveradi. Nima uchun moddalar suvda turlicha eriydi va bir stakan suvga qancha qand sig'adi? Bu savollarga eruvchanlik tushunchasi javob beradi.","blocks":[{"h":"Suv – universal erituvchi","p":"Suv qattiq moddalarni (tuz, qand), suyuqliklarni (spirt, kislotalar) va gazlarni (kislorod, karbonat angidrid) erita oladi. Qon, limfa va hujayra suyuqliklari – suvli eritmalar, ovqat hazm bo'lishi ham oziq moddalarning erishi bilan bog'liq. Tabiatda mutlaqo toza suv deyarli uchramaydi: hatto yomg'ir tomchilari ham havodan turli moddalarni eritib oladi."},{"h":"Eruvchanlik nima","p":"Eruvchanlik – moddaning ma'lum haroratda 100 g erituvchida eng ko'pi bilan necha gramm erishini ko'rsatuvchi kattalik. Masalan, 20 °C da 100 g suvda taxminan 36 g osh tuzi eriydi. Eruvchanligiga ko'ra moddalar shartli ravishda uch guruhga bo'linadi.","formula":"S = m(modda) / m(suv) · 100 g","items":["Yaxshi eriydigan: qand, osh tuzi NaCl, kaliy nitrat KNO₃","Kam eriydigan: gips CaSO₄","Amalda erimaydigan (100 g suvda 0,01 g dan kam): bo'r CaCO₃, qum"]},{"h":"To'yingan va to'yinmagan eritma","p":"Agar eritma shu haroratda moddaning qo'shimcha ulushini endi erita olmasa, u to'yingan eritma deyiladi; idish tubida erimay qolgan modda ko'rinadi. Hali yana erita oladigan eritma to'yinmagan eritma deyiladi. Ko'pincha to'yingan eritmani isitsak, u to'yinmagan holga o'tadi, sovitsak esa ortiqcha modda kristall bo'lib cho'kadi."},{"h":"Harorat va bosimning ta'siri","p":"Ko'pchilik qattiq moddalarning eruvchanligi harorat ortishi bilan oshadi. KNO₃ ning eruvchanligi keskin ortadi: 20 °C da taxminan 32 g, 60 °C da esa 110 g atrofida. NaCl ning eruvchanligi esa harorat bilan deyarli o'zgarmaydi. Gazlar boshqacha: ular sovuq suvda yaxshiroq eriydi.","items":["Harorat ortsa, gaz eruvchanligi kamayadi – suv isitilganda pufakchalar chiqadi","Bosim ortsa, gaz eruvchanligi oshadi – gazli ichimlik ochilganda CO₂ shiddat bilan ajraladi","Issiq suvda kislorod kam bo'lgani uchun baliqlarga havo yetishmay qolishi mumkin"],"visual":{"type":"chart","kind":"solubility"}},{"h":"Namuna masala","p":"Biror haroratda olingan 40 g to'yingan eritma bug'latilganda 8 g quruq tuz qoldi. Shu haroratda tuzning eruvchanligini topamiz.","items":["Suvning massasi: 40 − 8 = 32 g","32 g suvda 8 g tuz erigan, 100 g suvda esa x g eriydi","x = 8 · 100 / 32 = 25 g","Javob: eruvchanlik 100 g suvda 25 g"]},{"h":"Esda tuting","items":["Suv qattiq, suyuq va gazsimon moddalarni erita oladi","Eruvchanlik 100 g erituvchida eriydigan moddaning eng katta massasi bilan o'lchanadi","Qattiq moddalar odatda issiq suvda yaxshiroq eriydi, gazlar esa sovuq suvda va yuqori bosimda","To'yingan eritma shu haroratda moddani boshqa erita olmaydi"]}],"quiz":[{"q":"Eruvchanlik erituvchining qancha massasiga nisbatan ko'rsatiladi?","options":["1 g","10 g","100 g","1000 g"],"correct":2,"explain":"Eruvchanlik 100 g erituvchida eriydigan modda massasi bilan ifodalanadi."},{"q":"Gazning suvda eruvchanligi qachon ortadi?","options":["Harorat ortganda","Bosim ortganda","Suv qaynaganda","Bosim kamayganda"],"correct":1,"explain":"Yuqori bosim gaz molekulalarini suvga ko'proq 'siqadi', shuning uchun eruvchanlik ortadi."},{"q":"20 °C da NaCl ning eruvchanligi 36 g. Shu haroratda 50 g suvda ko'pi bilan qancha tuz eriydi?","options":["18 g","36 g","72 g","14 g"],"correct":0,"explain":"Suv ikki marta kam, demak tuz ham ikki marta kam: 36 / 2 = 18 g."}]},"en":{"title":"Water – the best solvent. Solubility","intro":"Sugar put into tea disappears in a moment, while sand just lies at the bottom of the glass. Why do substances dissolve in water so differently, and how much sugar can a glass of water hold? The idea of solubility answers these questions.","blocks":[{"h":"Water – a universal solvent","p":"Water can dissolve solids (salt, sugar), liquids (alcohol, acids) and gases (oxygen, carbon dioxide). Blood, lymph and cell fluids are aqueous solutions, and digestion also depends on nutrients dissolving. Perfectly pure water hardly exists in nature: even raindrops dissolve various substances from the air."},{"h":"What solubility is","p":"Solubility is the greatest mass of a substance, in grams, that can dissolve in 100 g of solvent at a given temperature. For example, at 20 °C about 36 g of table salt dissolve in 100 g of water. By solubility, substances are roughly divided into three groups.","formula":"S = m(substance) / m(water) × 100 g","items":["Highly soluble: sugar, table salt NaCl, potassium nitrate KNO₃","Slightly soluble: gypsum CaSO₄","Practically insoluble (less than 0.01 g per 100 g of water): chalk CaCO₃, sand"]},{"h":"Saturated and unsaturated solutions","p":"If a solution can no longer dissolve any more of a substance at that temperature, it is called a saturated solution; undissolved substance can be seen at the bottom. A solution that can still dissolve more is called unsaturated. Usually, heating a saturated solution makes it unsaturated, while cooling it makes the excess substance settle out as crystals."},{"h":"The effect of temperature and pressure","p":"For most solids, solubility increases as temperature rises. The solubility of KNO₃ rises steeply: about 32 g at 20 °C and around 110 g at 60 °C. The solubility of NaCl, by contrast, hardly changes with temperature. Gases behave differently: they dissolve better in cold water.","items":["When temperature rises, gas solubility falls – bubbles appear as water is heated","When pressure rises, gas solubility increases – CO₂ rushes out when a fizzy drink is opened","Warm water holds little oxygen, so fish may run short of it"],"visual":{"type":"chart","kind":"solubility"}},{"h":"Worked example","p":"When 40 g of a saturated solution at a certain temperature were evaporated, 8 g of dry salt remained. Let us find the solubility of the salt at that temperature.","items":["Mass of water: 40 − 8 = 32 g","8 g of salt dissolved in 32 g of water, so x g dissolve in 100 g of water","x = 8 × 100 / 32 = 25 g","Answer: the solubility is 25 g per 100 g of water"]},{"h":"Remember","items":["Water can dissolve solids, liquids and gases","Solubility is the greatest mass of substance that dissolves in 100 g of solvent","Solids usually dissolve better in hot water, gases in cold water and under high pressure","A saturated solution cannot dissolve any more of the substance at that temperature"]}],"quiz":[{"q":"Solubility is given per what mass of solvent?","options":["1 g","10 g","100 g","1000 g"],"correct":2,"explain":"Solubility is the mass of substance that dissolves in 100 g of solvent."},{"q":"When does the solubility of a gas in water increase?","options":["When temperature rises","When pressure rises","When the water boils","When pressure falls"],"correct":1,"explain":"Higher pressure pushes more gas molecules into the water, so solubility increases."},{"q":"At 20 °C the solubility of NaCl is 36 g. What is the most salt that dissolves in 50 g of water at this temperature?","options":["18 g","36 g","72 g","14 g"],"correct":0,"explain":"There is half as much water, so half as much salt dissolves: 36 / 2 = 18 g."}]},"ru":{"title":"Вода – лучший растворитель. Растворимость","intro":"Сахар, брошенный в чай, исчезает за мгновение, а песок так и лежит на дне стакана. Почему вещества растворяются в воде по-разному и сколько сахара может вместить стакан воды? На эти вопросы отвечает понятие растворимости.","blocks":[{"h":"Вода – универсальный растворитель","p":"Вода растворяет твёрдые вещества (соль, сахар), жидкости (спирт, кислоты) и газы (кислород, углекислый газ). Кровь, лимфа и клеточные жидкости – водные растворы, и пищеварение тоже связано с растворением питательных веществ. Абсолютно чистая вода в природе почти не встречается: даже капли дождя растворяют вещества из воздуха."},{"h":"Что такое растворимость","p":"Растворимость – наибольшая масса вещества в граммах, которая может раствориться в 100 г растворителя при данной температуре. Например, при 20 °C в 100 г воды растворяется около 36 г поваренной соли. По растворимости вещества условно делят на три группы.","formula":"S = m(вещества) / m(воды) · 100 г","items":["Хорошо растворимые: сахар, поваренная соль NaCl, нитрат калия KNO₃","Малорастворимые: гипс CaSO₄","Практически нерастворимые (меньше 0,01 г на 100 г воды): мел CaCO₃, песок"]},{"h":"Насыщенный и ненасыщенный раствор","p":"Если раствор при данной температуре больше не может растворить добавленное вещество, его называют насыщенным; на дне видно нерастворившееся вещество. Раствор, который ещё способен растворять вещество, называют ненасыщенным. Обычно при нагревании насыщенный раствор становится ненасыщенным, а при охлаждении избыток вещества выпадает в виде кристаллов."},{"h":"Влияние температуры и давления","p":"Растворимость большинства твёрдых веществ растёт с повышением температуры. Растворимость KNO₃ увеличивается резко: около 32 г при 20 °C и около 110 г при 60 °C. Растворимость NaCl, напротив, почти не зависит от температуры. Газы ведут себя иначе: они лучше растворяются в холодной воде.","items":["При повышении температуры растворимость газа уменьшается – при нагревании воды появляются пузырьки","При повышении давления растворимость газа растёт – при открывании газировки CO₂ бурно выделяется","В тёплой воде мало кислорода, поэтому рыбам может его не хватать"],"visual":{"type":"chart","kind":"solubility"}},{"h":"Пример решения задачи","p":"При выпаривании 40 г насыщенного при некоторой температуре раствора осталось 8 г сухой соли. Найдём растворимость соли при этой температуре.","items":["Масса воды: 40 − 8 = 32 г","В 32 г воды растворилось 8 г соли, а в 100 г воды растворится x г","x = 8 · 100 / 32 = 25 г","Ответ: растворимость 25 г на 100 г воды"]},{"h":"Запомните","items":["Вода растворяет твёрдые, жидкие и газообразные вещества","Растворимость – наибольшая масса вещества, растворяющаяся в 100 г растворителя","Твёрдые вещества обычно лучше растворяются в горячей воде, газы – в холодной и при высоком давлении","Насыщенный раствор при данной температуре больше не растворяет вещество"]}],"quiz":[{"q":"На какую массу растворителя указывают растворимость?","options":["1 г","10 г","100 г","1000 г"],"correct":2,"explain":"Растворимость – это масса вещества, растворяющаяся в 100 г растворителя."},{"q":"Когда растворимость газа в воде увеличивается?","options":["При повышении температуры","При повышении давления","При кипении воды","При понижении давления"],"correct":1,"explain":"Высокое давление «вталкивает» в воду больше молекул газа, поэтому растворимость растёт."},{"q":"При 20 °C растворимость NaCl равна 36 г. Какая наибольшая масса соли растворится при этой температуре в 50 г воды?","options":["18 г","36 г","72 г","14 г"],"correct":0,"explain":"Воды вдвое меньше, значит и соли растворится вдвое меньше: 36 / 2 = 18 г."}]}},{"id":"t31","num":31,"icon":"🧪","uz":{"title":"Eritmalar","intro":"Choy, dengiz suvi, havo va hatto tilla uzuk – bularning barchasi eritmalardir. Eritmalar hamma joyda bor, ular kimyo va hayotda juda katta o'rin tutadi. Bu darsda eritma nima ekanini va uni oddiy aralashmadan qanday ajratishni o'rganamiz.","blocks":[{"h":"Eritma nima","p":"Eritma – erituvchi va unda erigan moddadan tashkil topgan bir jinsli (gomogen) sistema. Erigan modda alohida molekulalar yoki ionlar darajasigacha maydalanib, erituvchi zarrachalari orasida bir tekis tarqaladi. Shuning uchun haqiqiy eritma tiniq bo'ladi, tindirilganda cho'kma bermaydi va filtrdan to'liq o'tadi."},{"h":"Erituvchi va erigan modda","p":"Eritmada ko'proq miqdorda bo'lgan komponent odatda erituvchi, kamrog'i esa erigan modda deb olinadi. Qattiq modda suyuqlikda eritilsa, suyuqlik erituvchi hisoblanadi. Eritmaning massasi uning tarkibiy qismlari massalari yig'indisiga teng.","formula":"m(eritma) = m(erigan modda) + m(erituvchi)","items":["Sho'r suv: erituvchi – suv, erigan modda – osh tuzi","Yod damlamasi: erituvchi – spirt, erigan modda – yod","Gazli ichimlik: erituvchi – suv, erigan modda – karbonat angidrid va qand"]},{"h":"Eritmalarning turlari","p":"Eritmalar faqat suyuq bo'lmaydi: ular agregat holatiga ko'ra uch xil bo'ladi.","table":{"head":["Eritma holati","Misollar"],"rows":[["Suyuq","tuzli suv, qandli choy, sirka"],["Qattiq","qotishmalar: latun (mis + rux), bronza, duralyuminiy, tilla taqinchoqlar"],["Gazsimon","havo – azot, kislorod va boshqa gazlar eritmasi"]]}},{"h":"Erish jarayonida nimalar sodir bo'ladi","p":"Erish faqat moddaning maydalanishi emas: erigan modda zarrachalari erituvchi molekulalari bilan o'zaro ta'sirlashadi. Shuning uchun erish ko'pincha issiqlik chiqishi yoki yutilishi bilan boradi. Ba'zi eritmalar elektr tokini o'tkazadi, boshqalari esa deyarli o'tkazmaydi.","items":["NaOH yoki sulfat kislota suvda eritilsa, idish qiziydi (issiqlik chiqadi)","Ammoniy nitrat suvda eritilsa, idish soviydi (issiqlik yutiladi)","Xavfsizlik qoidasi: kislotani suvga oz-ozdan quyiladi, aksincha emas","Osh tuzi eritmasi tokni o'tkazadi, qand eritmasi esa deyarli o'tkazmaydi"]},{"h":"Eritma, mexanik aralashma va kimyoviy birikma","p":"Eritma ba'zi belgilari bilan aralashmaga, boshqalari bilan esa kimyoviy birikmaga o'xshaydi.","table":{"head":["Belgi","Mexanik aralashma","Eritma","Kimyoviy birikma"],"rows":[["Tarkib","o'zgaruvchan","o'zgaruvchan","doimiy"],["Bir jinslilik","ko'pincha bir jinsli emas","bir jinsli","bir jinsli"],["Hosil bo'lishda issiqlik","odatda kuzatilmaydi","ko'pincha kuzatiladi","kuzatiladi"],["Tarkibiy qismlarni ajratish","fizik usullar bilan","fizik usullar bilan (bug'latish, distillash)","faqat kimyoviy reaksiya bilan"]]}},{"h":"Esda tuting","items":["Eritma – erituvchi va erigan moddadan iborat bir jinsli sistema","Eritma massasi erigan modda va erituvchi massalarining yig'indisiga teng","Eritmalar suyuq, qattiq va gazsimon bo'ladi","Erish issiqlik chiqishi yoki yutilishi bilan borishi mumkin"]}],"quiz":[{"q":"Quyidagilardan qaysi biri eritma?","options":["Loyqa suv","Suv bilan qum aralashmasi","Tiniq qandli choy","Suv va o'simlik moyi"],"correct":2,"explain":"Qandli choy tiniq va bir jinsli, qolganlari bir jinsli bo'lmagan aralashmalar."},{"q":"Latun (mis va rux qotishmasi) qanday eritma?","options":["Qattiq","Suyuq","Gazsimon","Bu eritma emas"],"correct":0,"explain":"Qotishmalar – qattiq eritmalarning eng ko'p uchraydigan misoli."},{"q":"25 g tuz 100 g suvda eritildi. Hosil bo'lgan eritmaning massasi qancha?","options":["75 g","100 g","25 g","125 g"],"correct":3,"explain":"Eritma massasi = 25 + 100 = 125 g."}]},"en":{"title":"Solutions","intro":"Tea, sea water, air and even a gold ring – all of these are solutions. Solutions are everywhere and play a huge role in chemistry and in everyday life. In this lesson we learn what a solution is and how to tell it apart from an ordinary mixture.","blocks":[{"h":"What a solution is","p":"A solution is a uniform (homogeneous) system made of a solvent and a substance dissolved in it. The dissolved substance breaks down into separate molecules or ions and spreads evenly among the solvent particles. That is why a true solution is clear, forms no sediment on standing and passes completely through a filter."},{"h":"Solvent and solute","p":"The component present in the larger amount is usually taken as the solvent, and the smaller one as the solute. When a solid is dissolved in a liquid, the liquid is the solvent. The mass of a solution equals the sum of the masses of its components.","formula":"m(solution) = m(solute) + m(solvent)","items":["Salt water: solvent – water, solute – table salt","Iodine tincture: solvent – alcohol, solute – iodine","Fizzy drink: solvent – water, solutes – carbon dioxide and sugar"]},{"h":"Types of solutions","p":"Solutions are not only liquids: by their physical state they come in three kinds.","table":{"head":["State of solution","Examples"],"rows":[["Liquid","salt water, sweet tea, vinegar"],["Solid","alloys: brass (copper + zinc), bronze, duralumin, gold jewellery"],["Gaseous","air – a solution of nitrogen, oxygen and other gases"]]}},{"h":"What happens during dissolving","p":"Dissolving is not just the breaking up of a substance: the solute particles interact with the solvent molecules. That is why dissolving is often accompanied by the release or absorption of heat. Some solutions conduct electric current, while others hardly do.","items":["When NaOH or sulfuric acid is dissolved in water, the vessel gets hot (heat is released)","When ammonium nitrate is dissolved in water, the vessel gets cold (heat is absorbed)","Safety rule: pour acid into water little by little, never the other way round","Table salt solution conducts current, while sugar solution hardly does"]},{"h":"Solution, mechanical mixture and compound","p":"In some features a solution resembles a mixture, and in others a chemical compound.","table":{"head":["Feature","Mechanical mixture","Solution","Chemical compound"],"rows":[["Composition","variable","variable","constant"],["Uniformity","often not uniform","uniform","uniform"],["Heat on formation","usually none","often observed","observed"],["Separating the components","by physical methods","by physical methods (evaporation, distillation)","only by a chemical reaction"]]}},{"h":"Remember","items":["A solution is a uniform system made of a solvent and a solute","The mass of a solution equals the mass of solute plus the mass of solvent","Solutions can be liquid, solid or gaseous","Dissolving can release or absorb heat"]}],"quiz":[{"q":"Which of the following is a solution?","options":["Muddy water","A mixture of water and sand","Clear sweet tea","Water and vegetable oil"],"correct":2,"explain":"Sweet tea is clear and uniform; the others are non-uniform mixtures."},{"q":"What kind of solution is brass (an alloy of copper and zinc)?","options":["Solid","Liquid","Gaseous","It is not a solution"],"correct":0,"explain":"Alloys are the most common example of solid solutions."},{"q":"25 g of salt were dissolved in 100 g of water. What is the mass of the solution?","options":["75 g","100 g","25 g","125 g"],"correct":3,"explain":"Mass of solution = 25 + 100 = 125 g."}]},"ru":{"title":"Растворы","intro":"Чай, морская вода, воздух и даже золотое кольцо – всё это растворы. Растворы встречаются повсюду и играют огромную роль в химии и в жизни. На этом уроке мы узнаем, что такое раствор и как отличить его от обычной смеси.","blocks":[{"h":"Что такое раствор","p":"Раствор – однородная (гомогенная) система, состоящая из растворителя и растворённого в нём вещества. Растворённое вещество дробится до отдельных молекул или ионов и равномерно распределяется между частицами растворителя. Поэтому истинный раствор прозрачен, при отстаивании не даёт осадка и полностью проходит через фильтр."},{"h":"Растворитель и растворённое вещество","p":"Компонент, которого больше, обычно считают растворителем, а того, которого меньше, – растворённым веществом. Если твёрдое вещество растворяют в жидкости, растворителем считается жидкость. Масса раствора равна сумме масс его составных частей.","formula":"m(раствора) = m(растворённого вещества) + m(растворителя)","items":["Солёная вода: растворитель – вода, растворённое вещество – поваренная соль","Йодная настойка: растворитель – спирт, растворённое вещество – йод","Газированный напиток: растворитель – вода, растворённые вещества – углекислый газ и сахар"]},{"h":"Виды растворов","p":"Растворы бывают не только жидкими: по агрегатному состоянию их три вида.","table":{"head":["Состояние раствора","Примеры"],"rows":[["Жидкие","солёная вода, сладкий чай, уксус"],["Твёрдые","сплавы: латунь (медь + цинк), бронза, дюралюминий, золотые украшения"],["Газообразные","воздух – раствор азота, кислорода и других газов"]]}},{"h":"Что происходит при растворении","p":"Растворение – это не только измельчение вещества: частицы растворённого вещества взаимодействуют с молекулами растворителя. Поэтому растворение часто сопровождается выделением или поглощением теплоты. Одни растворы проводят электрический ток, другие почти не проводят.","items":["При растворении NaOH или серной кислоты в воде сосуд нагревается (теплота выделяется)","При растворении нитрата аммония в воде сосуд охлаждается (теплота поглощается)","Правило безопасности: кислоту понемногу вливают в воду, а не наоборот","Раствор поваренной соли проводит ток, а раствор сахара почти не проводит"]},{"h":"Раствор, механическая смесь и химическое соединение","p":"По одним признакам раствор похож на смесь, по другим – на химическое соединение.","table":{"head":["Признак","Механическая смесь","Раствор","Химическое соединение"],"rows":[["Состав","переменный","переменный","постоянный"],["Однородность","часто неоднородна","однороден","однородно"],["Теплота при образовании","обычно не наблюдается","часто наблюдается","наблюдается"],["Разделение на составные части","физическими методами","физическими методами (выпаривание, перегонка)","только химической реакцией"]]}},{"h":"Запомните","items":["Раствор – однородная система из растворителя и растворённого вещества","Масса раствора равна сумме масс растворённого вещества и растворителя","Растворы бывают жидкими, твёрдыми и газообразными","Растворение может сопровождаться выделением или поглощением теплоты"]}],"quiz":[{"q":"Что из перечисленного является раствором?","options":["Мутная вода","Смесь воды с песком","Прозрачный сладкий чай","Вода с растительным маслом"],"correct":2,"explain":"Сладкий чай прозрачен и однороден, остальное – неоднородные смеси."},{"q":"Каким раствором является латунь (сплав меди и цинка)?","options":["Твёрдым","Жидким","Газообразным","Это не раствор"],"correct":0,"explain":"Сплавы – самый распространённый пример твёрдых растворов."},{"q":"25 г соли растворили в 100 г воды. Какова масса раствора?","options":["75 г","100 г","25 г","125 г"],"correct":3,"explain":"Масса раствора = 25 + 100 = 125 г."}]}},{"id":"t32","num":32,"icon":"⚖️","uz":{"title":"Erigan moddaning massa ulushi, foiz va molar konsentratsiyasi. Eritmalarning ahamiyati","intro":"Eritmada erigan modda oz bo'lsa – suyultirilgan, ko'p bo'lsa – konsentrlangan eritma deyiladi. Ammo dorixonada ham, laboratoriyada ham 'oz' yoki 'ko'p' degan so'z yetarli emas – aniq son kerak. Bu darsda eritma tarkibini qanday hisoblashni va eritmani o'z qo'limiz bilan tayyorlashni o'rganamiz.","blocks":[{"h":"Massa ulushi va foiz konsentratsiya","p":"Massa ulushi (ω) – erigan modda massasining butun eritma massasiga nisbati. U 0 dan 1 gacha bo'lgan son bilan ifodalanadi; uni 100% ga ko'paytirsak, foiz konsentratsiya hosil bo'ladi. Suyuq eritmaning massasini uning hajmi va zichligidan ham topish mumkin: m = V·ρ.","formula":"ω = m(erigan modda) / m(eritma);  C% = ω · 100%","items":["Misol: 15 g qand 135 g suvda eritildi","m(eritma) = 15 + 135 = 150 g","ω = 15 / 150 = 0,1","C% = 0,1 · 100% = 10%"],"visual":{"type":"calc","kind":"fraction"}},{"h":"Molar konsentratsiya","p":"Molar konsentratsiya (c) 1 litr eritmada erigan moddaning necha moli borligini ko'rsatadi va mol/l bilan o'lchanadi. 1 litrida 1 mol modda bo'lgan eritma bir molarli (1 M) eritma deyiladi.","formula":"c = n / V = m / (M · V)","items":["Misol: 500 ml eritmada 20 g NaOH erigan","M(NaOH) = 23 + 16 + 1 = 40 g/mol","n = 20 / 40 = 0,5 mol;  V = 0,5 l","c = 0,5 / 0,5 = 1 mol/l (1 M eritma)"]},{"h":"Amaliy ish 1: berilgan konsentratsiyali eritma tayyorlash","p":"Vazifa: massa ulushi 0,05 (5%) bo'lgan 80 g osh tuzi eritmasini tayyorlash. Avval hisoblaymiz, keyin o'lchaymiz va aralashtiramiz.","items":["m(NaCl) = 80 · 0,05 = 4 g","m(suv) = 80 − 4 = 76 g; suvning zichligi 1 g/ml bo'lgani uchun bu 76 ml","Tuzni tarozida tortib kolbaga soling, suvni o'lchov silindrida o'lchab ustiga quying va tuz to'liq eriguncha aralashtiring","Eritmani idishga quyib, unga modda formulasi, konsentratsiyasi va tayyorlangan sanasi yozilgan yorliq yopishtiring"]},{"h":"Amaliy ish 2: tuproq eritmasida ishqorni aniqlash","p":"Tuproq ko'pincha biroz kislotali bo'ladi va dehqonlar uni ohak bilan neytrallaydi; ohak ortiqcha solinsa, tuproq ishqoriy bo'lib qolishi mumkin. Buni oddiy tajriba bilan tekshirish mumkin.","items":["Bir necha gramm tuproqni probirkaga solib, ustiga suv quying, tiqin bilan berkitib yaxshilab chayqating","Aralashmani tindiring, so'ng filtr qog'oz orqali filtrlang – tiniq filtrat tuproq eritmasidir","Filtratga fenolftalein tomizing: to'q pushti rang paydo bo'lsa, muhit ishqoriy","Qizil lakmus qog'ozi ko'karsa ham, tuproqda ishqor borligini bildiradi"],"visual":{"type":"diagram","kind":"indicators"}},{"h":"Eritmalarning inson hayotidagi ahamiyati","p":"Hayotimiz eritmalarsiz tasavvur qilib bo'lmaydi: tanamizdagi suvning deyarli hammasi turli eritmalar ko'rinishida. O'simliklar ham mineral moddalarni tuproqdan faqat eritma holida o'zlashtiradi.","items":["Tibbiyot: fiziologik eritma (0,9% li NaCl), yodning spirtdagi eritmasi, mineral suvlar","Oshxona: sirka – sirka kislotaning suyultirilgan eritmasi, tuzlamalar uchun sho'r suv","Texnika: avtomobil akkumulyatoridagi sulfat kislota eritmasi, sovutish uchun antifriz","Maishiy kimyo: bo'yoqlar, loklar, dog' ketkazgichlar va pardoz vositalari"]},{"h":"Esda tuting","items":["ω = m(erigan modda) / m(eritma), C% = ω · 100%","m(eritma) = m(erigan modda) + m(erituvchi) = V · ρ","Molar konsentratsiya c = n / V, birligi mol/l","Fenolftalein ishqoriy muhitda to'q pushti rangga kiradi"]}],"quiz":[{"q":"20 g tuz 180 g suvda eritildi. Tuzning massa ulushi qancha?","options":["0,2 (20%)","0,1 (10%)","0,11 (11%)","0,9 (90%)"],"correct":1,"explain":"Eritma massasi 200 g, demak ω = 20 / 200 = 0,1, ya'ni 10%."},{"q":"0,5 l eritmada 0,25 mol modda erigan. Molar konsentratsiya qancha?","options":["0,125 mol/l","2 mol/l","0,5 mol/l","0,75 mol/l"],"correct":2,"explain":"c = n / V = 0,25 / 0,5 = 0,5 mol/l."},{"q":"Tuproq filtratiga fenolftalein qo'shilganda to'q pushti rang paydo bo'ldi. Bu nimani bildiradi?","options":["Muhit kislotali","Muhit neytral","Eritmada hech qanday modda yo'q","Muhit ishqoriy"],"correct":3,"explain":"Fenolftalein faqat ishqoriy muhitda pushti rangga kiradi."}]},"en":{"title":"Mass fraction, percentage and molar concentration of a solute. The importance of solutions","intro":"A solution with little solute is called dilute, and one with a lot of solute is called concentrated. But in a pharmacy or a laboratory, 'little' or 'a lot' is not enough – an exact number is needed. In this lesson we learn how to calculate the composition of a solution and how to prepare one ourselves.","blocks":[{"h":"Mass fraction and percentage concentration","p":"The mass fraction (ω) is the ratio of the mass of solute to the mass of the whole solution. It is a number from 0 to 1; multiplying it by 100% gives the percentage concentration. The mass of a liquid solution can also be found from its volume and density: m = V·ρ.","formula":"ω = m(solute) / m(solution);  C% = ω × 100%","items":["Example: 15 g of sugar were dissolved in 135 g of water","m(solution) = 15 + 135 = 150 g","ω = 15 / 150 = 0.1","C% = 0.1 × 100% = 10%"],"visual":{"type":"calc","kind":"fraction"}},{"h":"Molar concentration","p":"Molar concentration (c) shows how many moles of solute are in 1 litre of solution and is measured in mol/L. A solution containing 1 mol of substance per litre is called a one-molar (1 M) solution.","formula":"c = n / V = m / (M × V)","items":["Example: 20 g of NaOH are dissolved in 500 mL of solution","M(NaOH) = 23 + 16 + 1 = 40 g/mol","n = 20 / 40 = 0.5 mol;  V = 0.5 L","c = 0.5 / 0.5 = 1 mol/L (a 1 M solution)"]},{"h":"Practical work 1: preparing a solution of known concentration","p":"Task: prepare 80 g of table salt solution with a mass fraction of 0.05 (5%). First we calculate, then we measure and mix.","items":["m(NaCl) = 80 × 0.05 = 4 g","m(water) = 80 − 4 = 76 g; since the density of water is 1 g/mL, this is 76 mL","Weigh the salt on a balance and put it into a flask, measure the water with a measuring cylinder, pour it in and stir until the salt has fully dissolved","Pour the solution into a bottle and stick on a label with the formula, the concentration and the date of preparation"]},{"h":"Practical work 2: detecting alkali in a soil extract","p":"Soil is often slightly acidic, and farmers neutralise it with lime; if too much lime is added, the soil may become alkaline. This can be checked with a simple experiment.","items":["Put a few grams of soil into a test tube, add water, close it with a stopper and shake well","Let the mixture settle, then filter it through filter paper – the clear filtrate is the soil extract","Add phenolphthalein to the filtrate: a crimson colour means the medium is alkaline","If red litmus paper turns blue, this also shows that the soil contains alkali"],"visual":{"type":"diagram","kind":"indicators"}},{"h":"The importance of solutions in human life","p":"Our life is unthinkable without solutions: almost all the water in our body is in the form of various solutions. Plants, too, can take mineral substances from the soil only as solutions.","items":["Medicine: saline solution (0.9% NaCl), iodine solution in alcohol, mineral waters","Kitchen: vinegar is a dilute solution of acetic acid; brine for pickling","Technology: sulfuric acid solution in car batteries, antifreeze for cooling","Household chemicals: paints, varnishes, stain removers and cosmetics"]},{"h":"Remember","items":["ω = m(solute) / m(solution), C% = ω × 100%","m(solution) = m(solute) + m(solvent) = V × ρ","Molar concentration c = n / V, unit mol/L","Phenolphthalein turns crimson in an alkaline medium"]}],"quiz":[{"q":"20 g of salt were dissolved in 180 g of water. What is the mass fraction of salt?","options":["0.2 (20%)","0.1 (10%)","0.11 (11%)","0.9 (90%)"],"correct":1,"explain":"The solution has a mass of 200 g, so ω = 20 / 200 = 0.1, i.e. 10%."},{"q":"0.25 mol of a substance are dissolved in 0.5 L of solution. What is the molar concentration?","options":["0.125 mol/L","2 mol/L","0.5 mol/L","0.75 mol/L"],"correct":2,"explain":"c = n / V = 0.25 / 0.5 = 0.5 mol/L."},{"q":"Phenolphthalein added to a soil filtrate turned crimson. What does this mean?","options":["The medium is acidic","The medium is neutral","The solution contains no substances","The medium is alkaline"],"correct":3,"explain":"Phenolphthalein turns crimson only in an alkaline medium."}]},"ru":{"title":"Массовая доля, процентная и молярная концентрация растворённого вещества. Значение растворов","intro":"Если растворённого вещества мало, раствор называют разбавленным, если много – концентрированным. Но в аптеке или лаборатории слов «мало» и «много» недостаточно – нужно точное число. На этом уроке мы научимся рассчитывать состав раствора и готовить его своими руками.","blocks":[{"h":"Массовая доля и процентная концентрация","p":"Массовая доля (ω) – отношение массы растворённого вещества к массе всего раствора. Она выражается числом от 0 до 1; умножив её на 100%, получают процентную концентрацию. Массу жидкого раствора можно найти и через его объём и плотность: m = V·ρ.","formula":"ω = m(вещества) / m(раствора);  C% = ω · 100%","items":["Пример: 15 г сахара растворили в 135 г воды","m(раствора) = 15 + 135 = 150 г","ω = 15 / 150 = 0,1","C% = 0,1 · 100% = 10%"],"visual":{"type":"calc","kind":"fraction"}},{"h":"Молярная концентрация","p":"Молярная концентрация (c) показывает, сколько моль растворённого вещества содержится в 1 литре раствора, и измеряется в моль/л. Раствор, в 1 литре которого 1 моль вещества, называют одномолярным (1 М).","formula":"c = n / V = m / (M · V)","items":["Пример: в 500 мл раствора содержится 20 г NaOH","M(NaOH) = 23 + 16 + 1 = 40 г/моль","n = 20 / 40 = 0,5 моль;  V = 0,5 л","c = 0,5 / 0,5 = 1 моль/л (1 М раствор)"]},{"h":"Практическая работа 1: приготовление раствора заданной концентрации","p":"Задача: приготовить 80 г раствора поваренной соли с массовой долей 0,05 (5%). Сначала считаем, потом отмеряем и смешиваем.","items":["m(NaCl) = 80 · 0,05 = 4 г","m(воды) = 80 − 4 = 76 г; так как плотность воды 1 г/мл, это 76 мл","Взвесьте соль на весах и поместите в колбу, отмерьте воду мерным цилиндром, влейте её и перемешайте до полного растворения соли","Перелейте раствор в склянку и наклейте этикетку с формулой вещества, концентрацией и датой приготовления"]},{"h":"Практическая работа 2: обнаружение щёлочи в почвенной вытяжке","p":"Почва часто бывает слабокислой, и её нейтрализуют известью; если извести внести слишком много, почва может стать щелочной. Это можно проверить простым опытом.","items":["Поместите несколько граммов почвы в пробирку, прилейте воду, закройте пробкой и хорошо встряхните","Дайте смеси отстояться, затем отфильтруйте через фильтровальную бумагу – прозрачный фильтрат и есть почвенная вытяжка","Добавьте к фильтрату фенолфталеин: малиновая окраска означает щелочную среду","Если красная лакмусовая бумажка синеет, это тоже говорит о наличии щёлочи в почве"],"visual":{"type":"diagram","kind":"indicators"}},{"h":"Значение растворов в жизни человека","p":"Нашу жизнь невозможно представить без растворов: почти вся вода в организме находится в виде различных растворов. Растения тоже усваивают минеральные вещества из почвы только в виде растворов.","items":["Медицина: физиологический раствор (0,9% NaCl), спиртовой раствор йода, минеральные воды","Кухня: уксус – разбавленный раствор уксусной кислоты, рассол для засолки","Техника: раствор серной кислоты в автомобильных аккумуляторах, антифриз для охлаждения","Бытовая химия: краски, лаки, пятновыводители и косметика"]},{"h":"Запомните","items":["ω = m(вещества) / m(раствора), C% = ω · 100%","m(раствора) = m(вещества) + m(растворителя) = V · ρ","Молярная концентрация c = n / V, единица – моль/л","Фенолфталеин в щелочной среде становится малиновым"]}],"quiz":[{"q":"20 г соли растворили в 180 г воды. Какова массовая доля соли?","options":["0,2 (20%)","0,1 (10%)","0,11 (11%)","0,9 (90%)"],"correct":1,"explain":"Масса раствора 200 г, значит ω = 20 / 200 = 0,1, то есть 10%."},{"q":"В 0,5 л раствора растворено 0,25 моль вещества. Какова молярная концентрация?","options":["0,125 моль/л","2 моль/л","0,5 моль/л","0,75 моль/л"],"correct":2,"explain":"c = n / V = 0,25 / 0,5 = 0,5 моль/л."},{"q":"При добавлении фенолфталеина к почвенному фильтрату появилась малиновая окраска. Что это означает?","options":["Среда кислая","Среда нейтральная","В растворе нет никаких веществ","Среда щелочная"],"correct":3,"explain":"Фенолфталеин становится малиновым только в щелочной среде."}]}}]},{"title":{"uz":"5-bob. Anorganik moddalarning eng muhim sinflari","en":"Chapter 5. The main classes of inorganic substances","ru":"Глава 5. Важнейшие классы неорганических веществ"},"topics":[{"id":"t33","num":33,"icon":"🔩","uz":{"title":"Metallmaslar va metallar. Murakkab moddalarning sinflanishi","intro":"Kimyoda ma'lum moddalar soni millionlab, ularni tartibga solmasdan o'rganib bo'lmaydi. Kutubxonadagi kitoblar javonlarga ajratilgani kabi, moddalar ham tarkibi va xossalariga ko'ra sinflarga bo'linadi. Bu darsda shu 'kimyoviy javonlar' bilan tanishamiz.","blocks":[{"h":"Oddiy moddalar: metallar va metallmaslar","p":"Oddiy modda faqat bitta element atomlaridan tashkil topadi. Xossalariga ko'ra oddiy moddalar ikki katta guruhga – metallar va metallmaslarga bo'linadi. Ularning xossalari ko'p jihatdan qarama-qarshi, bu esa atomlarining tuzilishi turlicha ekani bilan bog'liq.","items":["Metallar: temir Fe, mis Cu, natriy Na, magniy Mg, alyuminiy Al, kumush Ag","Metallmaslar: vodorod H₂, kislorod O₂, ozon O₃, azot N₂, xlor Cl₂, oltingugurt S, fosfor P, uglerod C"]},{"h":"Metallar va metallmaslarni taqqoslash","table":{"head":["Xossa","Metallar","Metallmaslar"],"rows":[["Agregat holati (odatdagi sharoitda)","simobdan (Hg) tashqari hammasi qattiq","gazlar (O₂, N₂, Cl₂), suyuq (Br₂), qattiq (S, P, C, I₂)"],["Yaltiroqlik","o'ziga xos metall yaltiroqligi bor","odatda yo'q (yod va grafit bundan mustasno)"],["Issiqlik va elektr o'tkazuvchanlik","yaxshi","yomon (grafit bundan mustasno)"],["Mexanik xossalar","bolg'alanadi, cho'ziladi","qattiq metallmaslar mo'rt"]]}},{"h":"Murakkab moddalar: anorganik va organik","p":"Murakkab modda turli elementlar atomlaridan tashkil topadi va uni oddiy moddalarga parchalash mumkin. Murakkab moddalar organik va anorganik moddalarga bo'linadi. Organik moddalar – uglerod birikmalari; biroq CO, CO₂, karbonat kislota va karbonatlar kabi oddiyroq uglerod birikmalari anorganik moddalar qatoriga kiritiladi."},{"h":"Anorganik murakkab moddalarning to'rt sinfi","p":"Anorganik murakkab moddalar tarkibi va kimyoviy xossalariga ko'ra to'rt asosiy sinfga bo'linadi. Bu sinflar o'zaro bog'langan: biridan ikkinchisini olish mumkin.","items":["Oksidlar – ikki elementdan iborat, ulardan biri kislorod: Na₂O, CaO, CO₂, P₂O₅","Asoslar – metall va bir yoki bir necha OH guruhi: NaOH, Ca(OH)₂, Cu(OH)₂","Kislotalar – vodorod atomlari va kislota qoldig'i: HCl, H₂SO₄, H₃PO₄","Tuzlar – metall va kislota qoldig'i: NaCl, CaCO₃, CuSO₄"],"visual":{"type":"diagram","kind":"classification"}},{"h":"Sinfni formulaga qarab aniqlash","p":"Moddaning formulasiga diqqat bilan qarab, uning qaysi sinfga tegishli ekanini aniqlash mumkin.","items":["SO₂ – ikki element, biri kislorod → oksid","KOH – metall va OH guruhi → asos","HNO₃ – vodorod va kislota qoldig'i NO₃ → kislota","Na₂SO₄ – metall va kislota qoldig'i SO₄ → tuz"]},{"h":"Esda tuting","items":["Oddiy moddalar metallar va metallmaslarga bo'linadi","Metallar yaltiroq, tok va issiqlikni yaxshi o'tkazadi; odatdagi sharoitda faqat simob suyuq","Anorganik murakkab moddalarning asosiy sinflari: oksidlar, asoslar, kislotalar, tuzlar","Sinfni formuladagi atomlar va guruhlarga qarab aniqlash mumkin"]}],"quiz":[{"q":"Quyidagilardan qaysi biri metallmas?","options":["Mis","Oltingugurt","Temir","Natriy"],"correct":1,"explain":"Oltingugurt – sariq, mo'rt, tokni o'tkazmaydigan metallmas."},{"q":"Odatdagi sharoitda suyuq bo'lgan metall qaysi?","options":["Simob","Brom","Natriy","Alyuminiy"],"correct":0,"explain":"Simob – odatdagi sharoitda suyuq metall; brom ham suyuq, lekin u metallmas."},{"q":"Ca(OH)₂ qaysi sinfga kiradi?","options":["Oksid","Kislota","Tuz","Asos"],"correct":3,"explain":"Tarkibida metall va OH guruhlari bor, demak bu asos."}]},"en":{"title":"Non-metals and metals. Classification of complex substances","intro":"Chemists know millions of substances, and studying them without some order would be impossible. Just as books in a library are sorted onto shelves, substances are divided into classes by their composition and properties. In this lesson we get to know these 'chemical shelves'.","blocks":[{"h":"Simple substances: metals and non-metals","p":"A simple substance consists of atoms of only one element. By their properties, simple substances fall into two large groups – metals and non-metals. Their properties are largely opposite, which is linked to the different structure of their atoms.","items":["Metals: iron Fe, copper Cu, sodium Na, magnesium Mg, aluminium Al, silver Ag","Non-metals: hydrogen H₂, oxygen O₂, ozone O₃, nitrogen N₂, chlorine Cl₂, sulfur S, phosphorus P, carbon C"]},{"h":"Comparing metals and non-metals","table":{"head":["Property","Metals","Non-metals"],"rows":[["Physical state (normal conditions)","all solid except mercury (Hg)","gases (O₂, N₂, Cl₂), liquid (Br₂), solids (S, P, C, I₂)"],["Lustre","typical metallic lustre","usually none (iodine and graphite are exceptions)"],["Heat and electrical conductivity","good","poor (graphite is an exception)"],["Mechanical properties","can be hammered and drawn into wire","solid non-metals are brittle"]]}},{"h":"Complex substances: inorganic and organic","p":"A complex substance consists of atoms of different elements and can be broken down into simple substances. Complex substances are divided into organic and inorganic. Organic substances are compounds of carbon; however, simpler carbon compounds such as CO, CO₂, carbonic acid and carbonates are counted as inorganic."},{"h":"The four classes of inorganic compounds","p":"By their composition and chemical properties, inorganic complex substances fall into four main classes. These classes are connected: one can be obtained from another.","items":["Oxides – made of two elements, one of which is oxygen: Na₂O, CaO, CO₂, P₂O₅","Bases – a metal and one or more OH groups: NaOH, Ca(OH)₂, Cu(OH)₂","Acids – hydrogen atoms and an acid residue: HCl, H₂SO₄, H₃PO₄","Salts – a metal and an acid residue: NaCl, CaCO₃, CuSO₄"],"visual":{"type":"diagram","kind":"classification"}},{"h":"Identifying the class from the formula","p":"By looking carefully at a substance's formula, you can tell which class it belongs to.","items":["SO₂ – two elements, one is oxygen → oxide","KOH – a metal and an OH group → base","HNO₃ – hydrogen and the acid residue NO₃ → acid","Na₂SO₄ – a metal and the acid residue SO₄ → salt"]},{"h":"Remember","items":["Simple substances are divided into metals and non-metals","Metals are shiny and conduct heat and electricity well; under normal conditions only mercury is liquid","The main classes of inorganic compounds are oxides, bases, acids and salts","The class can be identified from the atoms and groups in the formula"]}],"quiz":[{"q":"Which of these is a non-metal?","options":["Copper","Sulfur","Iron","Sodium"],"correct":1,"explain":"Sulfur is a yellow, brittle non-metal that does not conduct current."},{"q":"Which metal is liquid under normal conditions?","options":["Mercury","Bromine","Sodium","Aluminium"],"correct":0,"explain":"Mercury is a liquid metal; bromine is also liquid, but it is a non-metal."},{"q":"Which class does Ca(OH)₂ belong to?","options":["Oxide","Acid","Salt","Base"],"correct":3,"explain":"It contains a metal and OH groups, so it is a base."}]},"ru":{"title":"Неметаллы и металлы. Классификация сложных веществ","intro":"Химикам известны миллионы веществ, и изучать их без порядка было бы невозможно. Как книги в библиотеке расставлены по полкам, так и вещества делят на классы по составу и свойствам. На этом уроке мы познакомимся с этими «химическими полками».","blocks":[{"h":"Простые вещества: металлы и неметаллы","p":"Простое вещество состоит из атомов только одного элемента. По свойствам простые вещества делятся на две большие группы – металлы и неметаллы. Их свойства во многом противоположны, что связано с разным строением их атомов.","items":["Металлы: железо Fe, медь Cu, натрий Na, магний Mg, алюминий Al, серебро Ag","Неметаллы: водород H₂, кислород O₂, озон O₃, азот N₂, хлор Cl₂, сера S, фосфор P, углерод C"]},{"h":"Сравнение металлов и неметаллов","table":{"head":["Свойство","Металлы","Неметаллы"],"rows":[["Агрегатное состояние (при обычных условиях)","все твёрдые, кроме ртути (Hg)","газы (O₂, N₂, Cl₂), жидкость (Br₂), твёрдые (S, P, C, I₂)"],["Блеск","характерный металлический блеск","обычно нет (исключения – йод и графит)"],["Тепло- и электропроводность","хорошая","плохая (исключение – графит)"],["Механические свойства","куются, вытягиваются в проволоку","твёрдые неметаллы хрупкие"]]}},{"h":"Сложные вещества: неорганические и органические","p":"Сложное вещество состоит из атомов разных элементов, и его можно разложить на простые вещества. Сложные вещества делят на органические и неорганические. Органические вещества – это соединения углерода; однако более простые соединения углерода, такие как CO, CO₂, угольная кислота и карбонаты, относят к неорганическим."},{"h":"Четыре класса неорганических соединений","p":"По составу и химическим свойствам неорганические сложные вещества делят на четыре основных класса. Эти классы связаны между собой: одни можно получить из других.","items":["Оксиды – состоят из двух элементов, один из которых кислород: Na₂O, CaO, CO₂, P₂O₅","Основания – металл и одна или несколько групп OH: NaOH, Ca(OH)₂, Cu(OH)₂","Кислоты – атомы водорода и кислотный остаток: HCl, H₂SO₄, H₃PO₄","Соли – металл и кислотный остаток: NaCl, CaCO₃, CuSO₄"],"visual":{"type":"diagram","kind":"classification"}},{"h":"Определяем класс по формуле","p":"Внимательно посмотрев на формулу вещества, можно определить, к какому классу оно относится.","items":["SO₂ – два элемента, один из них кислород → оксид","KOH – металл и группа OH → основание","HNO₃ – водород и кислотный остаток NO₃ → кислота","Na₂SO₄ – металл и кислотный остаток SO₄ → соль"]},{"h":"Запомните","items":["Простые вещества делятся на металлы и неметаллы","Металлы блестят, хорошо проводят тепло и ток; при обычных условиях жидкая только ртуть","Основные классы неорганических соединений: оксиды, основания, кислоты, соли","Класс вещества можно определить по атомам и группам в формуле"]}],"quiz":[{"q":"Какое из веществ является неметаллом?","options":["Медь","Сера","Железо","Натрий"],"correct":1,"explain":"Сера – жёлтый хрупкий неметалл, не проводящий ток."},{"q":"Какой металл при обычных условиях жидкий?","options":["Ртуть","Бром","Натрий","Алюминий"],"correct":0,"explain":"Ртуть – жидкий металл; бром тоже жидкий, но это неметалл."},{"q":"К какому классу относится Ca(OH)₂?","options":["Оксид","Кислота","Соль","Основание"],"correct":3,"explain":"В его составе металл и группы OH, значит это основание."}]}},{"id":"t34","num":34,"icon":"💨","uz":{"title":"Oksidlarning tarkibi, tuzilishi va nomlanishi","intro":"Zanglagan mix, qum, karbonat angidrid gazi va hatto suv — bularning barchasi bitta oilaga mansub. Ularning har birida kislorod boshqa bitta element bilan birikkan. Bu darsda shunday moddalar — oksidlar bilan tanishamiz.","blocks":[{"h":"Oksid nima?","p":"Oksid — faqat ikki elementdan iborat, ulardan biri kislorod bo'lgan murakkab modda. Oksidlarda kislorod doim II valentli bo'ladi. Shuning uchun har qanday oksidning formulasini umumiy ko'rinishda yozish mumkin.","formula":"EₓOᵧ, umumiy holda E₂Oₙ (n — E elementning valentligi)","items":["MgO — magniy oksid","Al₂O₃ — aluminiy oksid","CO₂ — uglerod (IV)-oksid","P₂O₅ — fosfor (V)-oksid"]},{"h":"Oksidlarning tuzilishi","p":"Oksid molekulasida kislorod atomlari bir-biri bilan emas, balki boshqa element atomi bilan bog'langan. Grafik formulada har bir chiziqcha bitta valentlikni bildiradi: kislorod atomidan ikkita chiziq, element atomidan esa uning valentligiga teng chiziq chiqadi. Masalan, CO₂ da uglerod o'rtada turadi va ikkala kislorod atomi bilan qo'shbog' hosil qiladi.","formula":"Mg=O     O=C=O","visual":{"type":"molecule3d","mol":"CO2"}},{"h":"Misol: oksid formulasini tuzamiz","p":"Element valentligini bilsak, oksid formulasini oson tuzish mumkin. Aluminiy (III) oksidi uchun qadamlarni ko'rib chiqamiz.","items":["1) Valentliklarni yozamiz: Al — III, O — II.","2) Ularning eng kichik umumiy karralisini topamiz: 6.","3) 6 : 3 = 2 — aluminiy atomlari soni; 6 : 2 = 3 — kislorod atomlari soni.","4) Javob: Al₂O₃. Tekshiruv: 2·3 = 3·2 = 6."]},{"h":"Oksidlarni nomlash","p":"Valentligi doimiy element uchun nom «element nomi + oksid» tarzida tuziladi. Valentligi o'zgaruvchan element bir necha oksid hosil qilgani uchun uning valentligi qavs ichida rim raqami bilan ko'rsatiladi. Kislorod atomlari sonini yunoncha qo'shimchalar (di-, tri-, tetra-) bilan ifodalash ham mumkin. Ba'zi oksidlarning tarixiy, kundalik nomlari ham bor.","table":{"head":["Formula","Valentlik bo'yicha nom","Boshqa nomi"],"rows":[["CO","uglerod (II)-oksid","is gazi"],["CO₂","uglerod (IV)-oksid","uglerod dioksid, karbonat angidrid"],["SO₃","oltingugurt (VI)-oksid","oltingugurt trioksid"],["CaO","kalsiy oksid","so'ndirilmagan ohak"],["SiO₂","kremniy (IV)-oksid","qum, kvars"],["Fe₂O₃","temir (III)-oksid","qizil temirtosh"]]}},{"h":"Esda tuting","items":["Oksid — ikki elementdan iborat, biri kislorod bo'lgan murakkab modda.","Oksidlarda kislorod II valentli, umumiy formula E₂Oₙ.","O'zgaruvchan valentli element oksidining nomida valentlik rim raqami bilan yoziladi: FeO — temir (II)-oksid.","Kislorod atomlari oksidda bir-biri bilan bog'lanmaydi."]}],"quiz":[{"q":"Quyidagilardan qaysi biri oksid?","options":["KOH","CaO","H₂SO₄","NaCl"],"correct":1,"explain":"CaO faqat ikki elementdan — kalsiy va kisloroddan tuzilgan."},{"q":"Fosfor (V)-oksidning formulasi qaysi?","options":["P₂O₃","PO₅","P₂O₅","P₅O₂"],"correct":2,"explain":"Valentliklar V va II, ularning eng kichik umumiy karralisi 10, demak P₂O₅."},{"q":"SO₃ yunoncha qo'shimcha yordamida qanday nomlanadi?","options":["Oltingugurt dioksid","Oltingugurt trioksid","Oltingugurt (IV)-oksid","Oltingugurt monooksid"],"correct":1,"explain":"Molekulada uchta kislorod atomi bor, «tri» qo'shimchasi uchtani bildiradi."}]},"en":{"title":"Oxides: composition, structure and naming","intro":"A rusty nail, sand, carbon dioxide gas and even water all belong to one family. In each of them oxygen is joined to exactly one other element. In this lesson we meet these substances: the oxides.","blocks":[{"h":"What is an oxide?","p":"An oxide is a compound made of only two elements, one of which is oxygen. In oxides oxygen always has a valency of II. That is why the formula of any oxide can be written in one general form.","formula":"EₓOᵧ, in general E₂Oₙ (n is the valency of element E)","items":["MgO — magnesium oxide","Al₂O₃ — aluminium oxide","CO₂ — carbon(IV) oxide","P₂O₅ — phosphorus(V) oxide"]},{"h":"Structure of oxides","p":"In an oxide, oxygen atoms are not bonded to each other; they are bonded to atoms of the other element. In a structural (graphic) formula each dash stands for one unit of valency: two dashes leave every oxygen atom, and the other atom has as many dashes as its valency. In CO₂, for example, carbon sits in the middle and forms a double bond with each oxygen atom.","formula":"Mg=O     O=C=O","visual":{"type":"molecule3d","mol":"CO2"}},{"h":"Example: building an oxide formula","p":"If you know the valency of the element, writing the oxide formula is easy. Let us follow the steps for aluminium (valency III).","items":["1) Write the valencies: Al — III, O — II.","2) Find their lowest common multiple: 6.","3) 6 ÷ 3 = 2 aluminium atoms; 6 ÷ 2 = 3 oxygen atoms.","4) Answer: Al₂O₃. Check: 2·3 = 3·2 = 6."]},{"h":"Naming oxides","p":"For an element with a fixed valency the name is simply \"element name + oxide\". An element with variable valency can form several oxides, so its valency is shown as a Roman numeral in brackets. You can also show the number of oxygen atoms with Greek prefixes (di-, tri-, tetra-). Some oxides also have traditional everyday names.","table":{"head":["Formula","Name by valency","Other name"],"rows":[["CO","carbon(II) oxide","carbon monoxide"],["CO₂","carbon(IV) oxide","carbon dioxide"],["SO₃","sulfur(VI) oxide","sulfur trioxide"],["CaO","calcium oxide","quicklime"],["SiO₂","silicon(IV) oxide","sand, quartz"],["Fe₂O₃","iron(III) oxide","red iron ore (haematite)"]]}},{"h":"Remember","items":["An oxide is a compound of two elements, one of which is oxygen.","Oxygen in oxides has valency II; the general formula is E₂Oₙ.","For elements with variable valency the name includes a Roman numeral: FeO is iron(II) oxide.","Oxygen atoms in an oxide are not bonded to each other."]}],"quiz":[{"q":"Which of these substances is an oxide?","options":["KOH","CaO","H₂SO₄","NaCl"],"correct":1,"explain":"CaO is made of only two elements, calcium and oxygen."},{"q":"What is the formula of phosphorus(V) oxide?","options":["P₂O₃","PO₅","P₂O₅","P₅O₂"],"correct":2,"explain":"The valencies are V and II, their lowest common multiple is 10, so the formula is P₂O₅."},{"q":"What is the name of SO₃ using a Greek prefix?","options":["Sulfur dioxide","Sulfur trioxide","Sulfur(IV) oxide","Sulfur monoxide"],"correct":1,"explain":"There are three oxygen atoms, and the prefix \"tri\" means three."}]},"ru":{"title":"Оксиды: состав, строение и названия","intro":"Ржавый гвоздь, песок, углекислый газ и даже вода принадлежат к одному семейству. В каждом из этих веществ кислород соединён ровно с одним другим элементом. На этом уроке мы познакомимся с такими веществами — оксидами.","blocks":[{"h":"Что такое оксид?","p":"Оксид — сложное вещество, состоящее только из двух элементов, один из которых кислород. В оксидах кислород всегда двухвалентен. Поэтому формулу любого оксида можно записать в общем виде.","formula":"EₓOᵧ, в общем виде E₂Oₙ (n — валентность элемента E)","items":["MgO — оксид магния","Al₂O₃ — оксид алюминия","CO₂ — оксид углерода(IV)","P₂O₅ — оксид фосфора(V)"]},{"h":"Строение оксидов","p":"В оксиде атомы кислорода связаны не друг с другом, а с атомами другого элемента. В графической формуле каждая чёрточка обозначает одну единицу валентности: от атома кислорода отходят две чёрточки, от атома элемента — столько, какова его валентность. Например, в CO₂ углерод находится в центре и образует двойную связь с каждым атомом кислорода.","formula":"Mg=O     O=C=O","visual":{"type":"molecule3d","mol":"CO2"}},{"h":"Пример: составляем формулу оксида","p":"Зная валентность элемента, формулу оксида составить легко. Разберём шаги для алюминия (валентность III).","items":["1) Записываем валентности: Al — III, O — II.","2) Находим их наименьшее общее кратное: 6.","3) 6 : 3 = 2 атома алюминия; 6 : 2 = 3 атома кислорода.","4) Ответ: Al₂O₃. Проверка: 2·3 = 3·2 = 6."]},{"h":"Названия оксидов","p":"Для элемента с постоянной валентностью название строится так: «оксид + название элемента в родительном падеже». Элемент с переменной валентностью может образовывать несколько оксидов, поэтому его валентность указывают римской цифрой в скобках. Число атомов кислорода можно показать и греческими приставками (ди-, три-, тетра-). У некоторых оксидов есть и традиционные, бытовые названия.","table":{"head":["Формула","Название по валентности","Другое название"],"rows":[["CO","оксид углерода(II)","угарный газ"],["CO₂","оксид углерода(IV)","диоксид углерода, углекислый газ"],["SO₃","оксид серы(VI)","триоксид серы"],["CaO","оксид кальция","негашёная известь"],["SiO₂","оксид кремния(IV)","песок, кварц"],["Fe₂O₃","оксид железа(III)","красный железняк"]]}},{"h":"Запомните","items":["Оксид — сложное вещество из двух элементов, один из которых кислород.","Кислород в оксидах двухвалентен; общая формула E₂Oₙ.","Для элементов с переменной валентностью в названии указывают римскую цифру: FeO — оксид железа(II).","Атомы кислорода в оксиде не связаны друг с другом."]}],"quiz":[{"q":"Какое из веществ является оксидом?","options":["KOH","CaO","H₂SO₄","NaCl"],"correct":1,"explain":"CaO состоит только из двух элементов — кальция и кислорода."},{"q":"Какова формула оксида фосфора(V)?","options":["P₂O₃","PO₅","P₂O₅","P₅O₂"],"correct":2,"explain":"Валентности V и II, их наименьшее общее кратное 10, значит формула P₂O₅."},{"q":"Как называется SO₃ с греческой приставкой?","options":["Диоксид серы","Триоксид серы","Оксид серы(IV)","Монооксид серы"],"correct":1,"explain":"В молекуле три атома кислорода, а приставка «три» означает три."}]}},{"id":"t35","num":35,"icon":"🗂️","uz":{"title":"Oksidlarning toifalanishi","intro":"Oksidlar ko'p, lekin ular kimyoviy reaksiyalarda turlicha «xulq» ko'rsatadi. Biri kislota bilan, boshqasi asos bilan, uchinchisi ikkalasi bilan ham reaksiyaga kirishadi, to'rtinchisi esa umuman tuz hosil qilmaydi. Shu xususiyatlarga qarab oksidlar guruhlarga ajratiladi.","blocks":[{"h":"Ikki katta guruh","p":"Kimyoviy xossalariga ko'ra oksidlar avvalo tuz hosil qiluvchi va tuz hosil qilmaydigan oksidlarga bo'linadi. Tuz hosil qilmaydigan oksidlar befarq oksidlar ham deyiladi, ular na kislota, na asos bilan tuz bermaydi. Tuz hosil qiluvchi oksidlar esa asosli, kislotali va amfoter oksidlarga bo'linadi.","items":["Befarq oksidlar: CO, NO, N₂O","Tuz hosil qiluvchi: asosli, kislotali, amfoter"],"visual":{"type":"diagram","kind":"classification"}},{"h":"Asosli oksidlar","p":"Asosli oksidlar — metallarning oksidlari bo'lib, ularga asoslar mos keladi. Ular kislotalar yoki kislotali oksidlar bilan reaksiyaga kirishib tuz hosil qiladi. Ko'pincha bunday oksidlarda metall I yoki II valentli bo'ladi.","formula":"MgO + 2HCl → MgCl₂ + H₂O","items":["Misollar: Na₂O, K₂O, CaO, MgO, FeO, CuO"]},{"h":"Kislotali oksidlar","p":"Kislotali oksidlarning aksariyati metallmaslarning oksidlaridir, ularga kislotalar mos keladi. Ular asoslar yoki asosli oksidlar bilan reaksiyaga kirishib tuz hosil qiladi. Ba'zi metallarning yuqori valentli oksidlari ham kislotali bo'ladi, masalan, Mn₂O₇.","formula":"CO₂ + 2NaOH → Na₂CO₃ + H₂O","items":["Misollar: CO₂, SO₂, SO₃, P₂O₅, SiO₂"]},{"h":"Amfoter oksidlar","p":"«Amfoter» so'zi «ikki tomonlama» degan ma'noni beradi. Amfoter oksidlar sharoitga qarab ham asosli, ham kislotali xossa ko'rsatadi: kislotalar bilan ham, ishqorlar bilan ham tuz hosil qiladi. Ularning xossalari yuqori sinflarda batafsil o'rganiladi.","formula":"ZnO + 2HCl → ZnCl₂ + H₂O","items":["Misollar: ZnO, Al₂O₃, Cr₂O₃","Ishqor bilan suyuqlantirilganda: ZnO + 2NaOH → Na₂ZnO₂ + H₂O"]},{"h":"Taqqoslash jadvali","table":{"head":["Oksid turi","Misol","Kislota bilan","Ishqor bilan","Mos gidroksid"],"rows":[["Asosli","CaO","tuz hosil qiladi","ta'sirlashmaydi","asos Ca(OH)₂"],["Kislotali","SO₃","ta'sirlashmaydi","tuz hosil qiladi","kislota H₂SO₄"],["Amfoter","ZnO","tuz hosil qiladi","tuz hosil qiladi","Zn(OH)₂"],["Befarq","CO","tuz bermaydi","tuz bermaydi","yo'q"]]}},{"h":"Esda tuting","items":["Oksidlar tuz hosil qiluvchi va tuz hosil qilmaydigan (befarq) oksidlarga bo'linadi.","Asosli oksidlar kislotalar bilan, kislotali oksidlar asoslar bilan tuz hosil qiladi.","Amfoter oksidlar (ZnO, Al₂O₃) ham kislota, ham ishqor bilan reaksiyaga kirishadi.","CO, NO, N₂O — befarq oksidlar."]}],"quiz":[{"q":"Qaysi oksid tuz hosil qilmaydi?","options":["CO₂","CO","CaO","SO₃"],"correct":1,"explain":"CO befarq oksid: u kislota bilan ham, asos bilan ham tuz bermaydi."},{"q":"Qaysi oksid amfoter?","options":["Na₂O","P₂O₅","ZnO","N₂O"],"correct":2,"explain":"ZnO kislotalar bilan ham, ishqorlar bilan ham tuz hosil qiladi."},{"q":"Kislotali oksid qaysi moddalar bilan tuz hosil qiladi?","options":["Kislotalar bilan","Asoslar bilan","Faqat suv bilan","Hech narsa bilan"],"correct":1,"explain":"Kislotali oksidlar asoslar yoki asosli oksidlar bilan tuz beradi."}]},"en":{"title":"Classification of oxides","intro":"There are many oxides, but they behave differently in reactions. One reacts with acids, another with bases, a third with both, and a fourth forms no salt at all. Oxides are sorted into groups according to this behaviour.","blocks":[{"h":"Two large groups","p":"By their chemical properties oxides are first divided into salt-forming and non-salt-forming oxides. Non-salt-forming oxides are also called indifferent oxides: they give no salt with either acids or bases. Salt-forming oxides are further divided into basic, acidic and amphoteric oxides.","items":["Non-salt-forming (indifferent): CO, NO, N₂O","Salt-forming: basic, acidic, amphoteric"],"visual":{"type":"diagram","kind":"classification"}},{"h":"Basic oxides","p":"Basic oxides are oxides of metals, and each of them corresponds to a base. They react with acids or acidic oxides to form salts. In these oxides the metal usually has a valency of I or II.","formula":"MgO + 2HCl → MgCl₂ + H₂O","items":["Examples: Na₂O, K₂O, CaO, MgO, FeO, CuO"]},{"h":"Acidic oxides","p":"Most acidic oxides are oxides of non-metals, and each corresponds to an acid. They react with bases or basic oxides to form salts. Some metal oxides in which the metal has a high valency are also acidic, for example Mn₂O₇.","formula":"CO₂ + 2NaOH → Na₂CO₃ + H₂O","items":["Examples: CO₂, SO₂, SO₃, P₂O₅, SiO₂"]},{"h":"Amphoteric oxides","p":"The word \"amphoteric\" means \"acting both ways\". Depending on conditions, amphoteric oxides show both basic and acidic properties: they form salts with acids and with alkalis. You will study them in more detail in later courses.","formula":"ZnO + 2HCl → ZnCl₂ + H₂O","items":["Examples: ZnO, Al₂O₃, Cr₂O₃","When fused with an alkali: ZnO + 2NaOH → Na₂ZnO₂ + H₂O"]},{"h":"Comparison table","table":{"head":["Oxide type","Example","With an acid","With an alkali","Related hydroxide"],"rows":[["Basic","CaO","forms a salt","no reaction","base Ca(OH)₂"],["Acidic","SO₃","no reaction","forms a salt","acid H₂SO₄"],["Amphoteric","ZnO","forms a salt","forms a salt","Zn(OH)₂"],["Indifferent","CO","no salt","no salt","none"]]}},{"h":"Remember","items":["Oxides are divided into salt-forming and non-salt-forming (indifferent) oxides.","Basic oxides form salts with acids; acidic oxides form salts with bases.","Amphoteric oxides (ZnO, Al₂O₃) react with both acids and alkalis.","CO, NO and N₂O are indifferent oxides."]}],"quiz":[{"q":"Which oxide does not form salts?","options":["CO₂","CO","CaO","SO₃"],"correct":1,"explain":"CO is an indifferent oxide: it gives no salt with acids or with bases."},{"q":"Which oxide is amphoteric?","options":["Na₂O","P₂O₅","ZnO","N₂O"],"correct":2,"explain":"ZnO forms salts both with acids and with alkalis."},{"q":"An acidic oxide forms a salt when it reacts with…","options":["acids","bases","only water","nothing"],"correct":1,"explain":"Acidic oxides form salts with bases or basic oxides."}]},"ru":{"title":"Классификация оксидов","intro":"Оксидов много, но в реакциях они ведут себя по-разному. Один реагирует с кислотами, другой — с основаниями, третий — и с теми и с другими, а четвёртый вообще не образует солей. По этому поведению оксиды делят на группы.","blocks":[{"h":"Две большие группы","p":"По химическим свойствам оксиды прежде всего делят на солеобразующие и несолеобразующие. Несолеобразующие оксиды называют также безразличными: они не дают солей ни с кислотами, ни с основаниями. Солеобразующие оксиды, в свою очередь, бывают основными, кислотными и амфотерными.","items":["Несолеобразующие (безразличные): CO, NO, N₂O","Солеобразующие: основные, кислотные, амфотерные"],"visual":{"type":"diagram","kind":"classification"}},{"h":"Основные оксиды","p":"Основные оксиды — это оксиды металлов, каждому из них соответствует основание. Они реагируют с кислотами или кислотными оксидами, образуя соли. Металл в таких оксидах обычно имеет валентность I или II.","formula":"MgO + 2HCl → MgCl₂ + H₂O","items":["Примеры: Na₂O, K₂O, CaO, MgO, FeO, CuO"]},{"h":"Кислотные оксиды","p":"Большинство кислотных оксидов — оксиды неметаллов, каждому из них соответствует кислота. Они реагируют с основаниями или основными оксидами, образуя соли. Кислотными бывают и некоторые оксиды металлов с высокой валентностью, например Mn₂O₇.","formula":"CO₂ + 2NaOH → Na₂CO₃ + H₂O","items":["Примеры: CO₂, SO₂, SO₃, P₂O₅, SiO₂"]},{"h":"Амфотерные оксиды","p":"Слово «амфотерный» означает «двойственный». В зависимости от условий амфотерные оксиды проявляют и основные, и кислотные свойства: образуют соли и с кислотами, и со щелочами. Подробнее их изучают в старших классах.","formula":"ZnO + 2HCl → ZnCl₂ + H₂O","items":["Примеры: ZnO, Al₂O₃, Cr₂O₃","При сплавлении со щёлочью: ZnO + 2NaOH → Na₂ZnO₂ + H₂O"]},{"h":"Сравнительная таблица","table":{"head":["Тип оксида","Пример","С кислотой","Со щёлочью","Соответствующий гидроксид"],"rows":[["Основный","CaO","образует соль","не реагирует","основание Ca(OH)₂"],["Кислотный","SO₃","не реагирует","образует соль","кислота H₂SO₄"],["Амфотерный","ZnO","образует соль","образует соль","Zn(OH)₂"],["Безразличный","CO","соли не даёт","соли не даёт","нет"]]}},{"h":"Запомните","items":["Оксиды делят на солеобразующие и несолеобразующие (безразличные).","Основные оксиды образуют соли с кислотами, кислотные — с основаниями.","Амфотерные оксиды (ZnO, Al₂O₃) реагируют и с кислотами, и со щелочами.","CO, NO и N₂O — безразличные оксиды."]}],"quiz":[{"q":"Какой оксид не образует солей?","options":["CO₂","CO","CaO","SO₃"],"correct":1,"explain":"CO — безразличный оксид: он не даёт солей ни с кислотами, ни с основаниями."},{"q":"Какой оксид амфотерный?","options":["Na₂O","P₂O₅","ZnO","N₂O"],"correct":2,"explain":"ZnO образует соли и с кислотами, и со щелочами."},{"q":"С какими веществами кислотный оксид образует соль?","options":["С кислотами","С основаниями","Только с водой","Ни с чем"],"correct":1,"explain":"Кислотные оксиды образуют соли с основаниями или основными оксидами."}]}},{"id":"t36","num":36,"icon":"🔥","uz":{"title":"Oksidlarning olinishi va xossalari","intro":"Gaz plitasida metan yonganda, gugurt chaqilganda yoki ohaktosh qizdirilganda oksidlar hosil bo'ladi. Endi oksidlar qanday olinishini va ular boshqa moddalar bilan qanday reaksiyalarga kirishishini bilib olamiz.","blocks":[{"h":"Oddiy moddalarning yonishi","p":"Ko'pchilik metallar va metallmaslar kislorodda yonib yoki oksidlanib oksidlar hosil qiladi. Bu oksid olishning eng oddiy usuli.","items":["C + O₂ → CO₂","4P + 5O₂ → 2P₂O₅","4Al + 3O₂ → 2Al₂O₃","2Mg + O₂ → 2MgO"]},{"h":"Murakkab moddalarning yonishi va parchalanishi","p":"Murakkab moddalar yonganda tarkibidagi har bir element o'z oksidiga aylanadi. Bundan tashqari, ba'zi asoslar, kislotalar va tuzlar qizdirilganda parchalanib, oksidlar hosil qiladi.","items":["Yonish: CH₄ + 2O₂ → CO₂ + 2H₂O","Yonish: 2H₂S + 3O₂ → 2SO₂ + 2H₂O","Asosning parchalanishi: Cu(OH)₂ → CuO + H₂O","Tuzning parchalanishi: CaCO₃ → CaO + CO₂","Malaxitning parchalanishi: Cu₂(OH)₂CO₃ → 2CuO + CO₂ + H₂O"]},{"h":"Oksidlarning suv bilan reaksiyasi","p":"Ishqoriy va ishqoriy-yer metallarning oksidlari suv bilan birikib ishqorlar hosil qiladi. Ko'pchilik metallmas oksidlari esa suv bilan kislotalar beradi. Hamma oksidlar ham suv bilan reaksiyaga kirishmaydi: masalan, CuO va SiO₂ suvda erimaydi. Asosli oksidlar odatda qattiq moddalar, kislotali oksidlar esa qattiq, suyuq yoki gaz holatida bo'lishi mumkin.","formula":"CaO + H₂O → Ca(OH)₂","items":["Na₂O + H₂O → 2NaOH","SO₂ + H₂O → H₂SO₃","P₂O₅ + 3H₂O → 2H₃PO₄"],"visual":{"type":"reaction","id":"cao_h2o"}},{"h":"Kislotalar va asoslar bilan reaksiyalar","p":"Asosli oksid kislota bilan reaksiyaga kirishganda tuz va suv hosil bo'ladi. Kislotali oksid esa asos bilan reaksiyaga kirishib, xuddi shunday tuz va suv beradi.","items":["CaO + 2HCl → CaCl₂ + H₂O","CuO + H₂SO₄ → CuSO₄ + H₂O","SO₂ + 2NaOH → Na₂SO₃ + H₂O","P₂O₅ + 3Ca(OH)₂ → Ca₃(PO₄)₂ + 3H₂O"]},{"h":"Asosli va kislotali oksidlar o'zaro","p":"Qarama-qarshi xossali oksidlar bir-biri bilan bevosita birikib tuz hosil qiladi, bunda suv ajralmaydi. Bu reaksiya ko'pincha qizdirilganda boradi.","items":["CaO + CO₂ → CaCO₃","MgO + SO₂ → MgSO₃","BaO + CO₂ → BaCO₃"]},{"h":"Esda tuting","items":["Oksidlar moddalarning yonishidan va murakkab moddalarning parchalanishidan hosil bo'ladi.","Faol metallarning oksidlari suv bilan ishqor, ko'p metallmas oksidlari suv bilan kislota beradi.","Asosli oksid + kislota → tuz + suv; kislotali oksid + asos → tuz + suv.","Asosli oksid + kislotali oksid → tuz."]}],"quiz":[{"q":"CaO suv bilan reaksiyaga kirishganda nima hosil bo'ladi?","options":["CaCO₃","Ca(OH)₂","CaH₂","CaO₂"],"correct":1,"explain":"Kalsiy oksid suv bilan birikib kalsiy gidroksidni hosil qiladi."},{"q":"Qaysi oksid suv bilan reaksiyaga kirishmaydi?","options":["Na₂O","SO₃","SiO₂","P₂O₅"],"correct":2,"explain":"SiO₂ (qum) suvda erimaydi va u bilan reaksiyaga kirishmaydi."},{"q":"CaO + CO₂ reaksiyasi mahsuloti qaysi?","options":["CaCO₃","Ca(OH)₂","CaC₂","CO"],"correct":0,"explain":"Asosli oksid kislotali oksid bilan birikib kalsiy karbonat tuzini beradi."}]},"en":{"title":"How oxides are obtained, and their properties","intro":"Oxides form when methane burns on a gas stove, when a match is struck or when limestone is heated. Now we will learn how oxides are made and how they react with other substances.","blocks":[{"h":"Burning simple substances","p":"Most metals and non-metals burn or oxidise in oxygen to give oxides. This is the simplest way to obtain an oxide.","items":["C + O₂ → CO₂","4P + 5O₂ → 2P₂O₅","4Al + 3O₂ → 2Al₂O₃","2Mg + O₂ → 2MgO"]},{"h":"Burning and decomposing compounds","p":"When a compound burns, each of its elements turns into its own oxide. In addition, some bases, acids and salts break down into oxides when heated.","items":["Burning: CH₄ + 2O₂ → CO₂ + 2H₂O","Burning: 2H₂S + 3O₂ → 2SO₂ + 2H₂O","Decomposing a base: Cu(OH)₂ → CuO + H₂O","Decomposing a salt: CaCO₃ → CaO + CO₂","Decomposing malachite: Cu₂(OH)₂CO₃ → 2CuO + CO₂ + H₂O"]},{"h":"Reaction of oxides with water","p":"Oxides of alkali and alkaline-earth metals combine with water to give alkalis. Many non-metal oxides give acids with water. Not every oxide reacts with water: CuO and SiO₂, for example, do not dissolve in it. Basic oxides are usually solids, while acidic oxides can be solids, liquids or gases.","formula":"CaO + H₂O → Ca(OH)₂","items":["Na₂O + H₂O → 2NaOH","SO₂ + H₂O → H₂SO₃","P₂O₅ + 3H₂O → 2H₃PO₄"],"visual":{"type":"reaction","id":"cao_h2o"}},{"h":"Reactions with acids and bases","p":"When a basic oxide reacts with an acid, a salt and water form. An acidic oxide reacts with a base and also gives a salt and water.","items":["CaO + 2HCl → CaCl₂ + H₂O","CuO + H₂SO₄ → CuSO₄ + H₂O","SO₂ + 2NaOH → Na₂SO₃ + H₂O","P₂O₅ + 3Ca(OH)₂ → Ca₃(PO₄)₂ + 3H₂O"]},{"h":"Basic and acidic oxides together","p":"Oxides with opposite properties can combine directly to form a salt, and no water is released. This reaction often needs heating.","items":["CaO + CO₂ → CaCO₃","MgO + SO₂ → MgSO₃","BaO + CO₂ → BaCO₃"]},{"h":"Remember","items":["Oxides form when substances burn and when some compounds decompose.","Oxides of active metals give alkalis with water; many non-metal oxides give acids.","Basic oxide + acid → salt + water; acidic oxide + base → salt + water.","Basic oxide + acidic oxide → salt."]}],"quiz":[{"q":"What forms when CaO reacts with water?","options":["CaCO₃","Ca(OH)₂","CaH₂","CaO₂"],"correct":1,"explain":"Calcium oxide combines with water to form calcium hydroxide."},{"q":"Which oxide does not react with water?","options":["Na₂O","SO₃","SiO₂","P₂O₅"],"correct":2,"explain":"SiO₂ (sand) does not dissolve in water or react with it."},{"q":"What is the product of CaO + CO₂?","options":["CaCO₃","Ca(OH)₂","CaC₂","CO"],"correct":0,"explain":"A basic oxide combines with an acidic oxide to form the salt calcium carbonate."}]},"ru":{"title":"Получение и свойства оксидов","intro":"Оксиды образуются, когда на газовой плите горит метан, когда зажигают спичку или нагревают известняк. Теперь узнаем, как получают оксиды и в какие реакции они вступают.","blocks":[{"h":"Горение простых веществ","p":"Большинство металлов и неметаллов горят или окисляются в кислороде с образованием оксидов. Это самый простой способ получить оксид.","items":["C + O₂ → CO₂","4P + 5O₂ → 2P₂O₅","4Al + 3O₂ → 2Al₂O₃","2Mg + O₂ → 2MgO"]},{"h":"Горение и разложение сложных веществ","p":"При горении сложного вещества каждый входящий в него элемент превращается в свой оксид. Кроме того, некоторые основания, кислоты и соли при нагревании разлагаются с образованием оксидов.","items":["Горение: CH₄ + 2O₂ → CO₂ + 2H₂O","Горение: 2H₂S + 3O₂ → 2SO₂ + 2H₂O","Разложение основания: Cu(OH)₂ → CuO + H₂O","Разложение соли: CaCO₃ → CaO + CO₂","Разложение малахита: Cu₂(OH)₂CO₃ → 2CuO + CO₂ + H₂O"]},{"h":"Реакция оксидов с водой","p":"Оксиды щелочных и щёлочноземельных металлов соединяются с водой, образуя щёлочи. Многие оксиды неметаллов дают с водой кислоты. Не все оксиды реагируют с водой: например, CuO и SiO₂ в ней не растворяются. Основные оксиды обычно твёрдые, а кислотные могут быть твёрдыми, жидкими или газообразными.","formula":"CaO + H₂O → Ca(OH)₂","items":["Na₂O + H₂O → 2NaOH","SO₂ + H₂O → H₂SO₃","P₂O₅ + 3H₂O → 2H₃PO₄"],"visual":{"type":"reaction","id":"cao_h2o"}},{"h":"Реакции с кислотами и основаниями","p":"При взаимодействии основного оксида с кислотой образуются соль и вода. Кислотный оксид реагирует с основанием и тоже даёт соль и воду.","items":["CaO + 2HCl → CaCl₂ + H₂O","CuO + H₂SO₄ → CuSO₄ + H₂O","SO₂ + 2NaOH → Na₂SO₃ + H₂O","P₂O₅ + 3Ca(OH)₂ → Ca₃(PO₄)₂ + 3H₂O"]},{"h":"Основные и кислотные оксиды между собой","p":"Оксиды с противоположными свойствами могут напрямую соединяться в соль, причём вода не выделяется. Такая реакция часто идёт при нагревании.","items":["CaO + CO₂ → CaCO₃","MgO + SO₂ → MgSO₃","BaO + CO₂ → BaCO₃"]},{"h":"Запомните","items":["Оксиды образуются при горении веществ и при разложении некоторых сложных веществ.","Оксиды активных металлов дают с водой щёлочи, многие оксиды неметаллов — кислоты.","Основный оксид + кислота → соль + вода; кислотный оксид + основание → соль + вода.","Основный оксид + кислотный оксид → соль."]}],"quiz":[{"q":"Что образуется при реакции CaO с водой?","options":["CaCO₃","Ca(OH)₂","CaH₂","CaO₂"],"correct":1,"explain":"Оксид кальция соединяется с водой и образует гидроксид кальция."},{"q":"Какой оксид не реагирует с водой?","options":["Na₂O","SO₃","SiO₂","P₂O₅"],"correct":2,"explain":"SiO₂ (песок) не растворяется в воде и не реагирует с ней."},{"q":"Какой продукт реакции CaO + CO₂?","options":["CaCO₃","Ca(OH)₂","CaC₂","CO"],"correct":0,"explain":"Основный оксид соединяется с кислотным и образует соль — карбонат кальция."}]}},{"id":"t37","num":37,"icon":"🏗️","uz":{"title":"Eng muhim oksidlarning ishlatilishi","intro":"Gazli suvdagi pufakchalar, uy qurishdagi qum va ohak, avtomobil akkumulyatoridagi kislota — bularning barchasi oksidlar bilan bog'liq. Keling, kundalik hayot va sanoatda eng ko'p qo'llanadigan oksidlarni ko'rib chiqamiz.","blocks":[{"h":"Uglerod (IV)-oksid — CO₂","p":"Karbonat angidrid havoning doimiy, lekin juda kichik qismini tashkil etadi (taxminan 0,04%). Yashil o'simliklar uni barglari orqali yutadi va quyosh nuri ta'sirida suv bilan birga qandga aylantirib, havoga kislorod chiqaradi — bu jarayon fotosintez deyiladi. CO₂ ichimliklarni gazlashda, o't o'chirgichlarda, soda ishlab chiqarishda ishlatiladi, uning qattiq holi «quruq muz» esa sovitish uchun qo'llanadi.","formula":"6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ (yorug'lik ta'sirida)","visual":{"type":"chart","kind":"air"}},{"h":"Kremniy (IV)-oksid — SiO₂","p":"Tabiatda asosan qum va kvars ko'rinishida keng tarqalgan. Qum — muhim qurilish materiali va shisha ishlab chiqarishning asosiy xomashyosi. Kvars juda yuqori haroratda suyuqlanadi va ultrabinafsha nurlarni o'tkazadi, shuning uchun undan issiqqa chidamli laboratoriya idishlari va ultrabinafsha lampalar yasaladi. SiO₂ dan elektronikada ishlatiladigan sof kremniy ham olinadi, ametist va agat kabi bezak toshlari ham kvarsning turlaridir."},{"h":"Kalsiy oksid — CaO","p":"Kalsiy oksid so'ndirilmagan ohak deb ataladi va ohaktoshni kuchli qizdirib olinadi. U qurilishda qorishmalar va sement tayyorlashda, kislotali tuproqlarni neytrallashda, kimyo sanoatida ishlatiladi. Uning suv bilan hosil qilgan mahsuloti bog'larda daraxtlarni zararkunandalardan himoyalashda qo'llanadi.","formula":"CaCO₃ → CaO + CO₂ (qizdirilganda)"},{"h":"Oltingugurt (VI)-oksid va azot (IV)-oksid","p":"SO₃ tabiatda erkin holda deyarli uchramaydi: u oltingugurt (IV)-oksidni katalizator ishtirokida oksidlab olinadi. Undan sulfat kislota ishlab chiqariladi, sulfat kislota esa o'g'itlar, dori-darmonlar olishda va akkumulyatorlarda ishlatiladi. Qo'ng'ir rangli NO₂ gazi asosan nitrat kislota olish uchun sintez qilinadi, nitrat kislotadan esa azotli o'g'itlar va dorilar tayyorlanadi.","formula":"2SO₂ + O₂ → 2SO₃ (katalizator)"},{"h":"Qisqacha jadval","table":{"head":["Oksid","Kundalik nomi","Asosiy qo'llanilishi"],"rows":[["CO₂","karbonat angidrid, quruq muz","gazli ichimliklar, sovitish, o't o'chirish"],["SiO₂","qum, kvars","qurilish, shisha, laboratoriya idishlari"],["CaO","so'ndirilmagan ohak","qurilish, sement, tuproqni neytrallash"],["SO₃","sulfat angidrid","sulfat kislota olish"],["NO₂","—","nitrat kislota olish"]]}},{"h":"Esda tuting","items":["CO₂ — fotosintez uchun zarur, gazli ichimliklarda va «quruq muz» sifatida ishlatiladi.","SiO₂ (qum, kvars) — qurilish va shisha ishlab chiqarish xomashyosi.","CaO (so'ndirilmagan ohak) ohaktoshni qizdirib olinadi va qurilishda qo'llanadi.","SO₃ va NO₂ — mos ravishda sulfat va nitrat kislotalar olish uchun xomashyo."]}],"quiz":[{"q":"«Quruq muz» qaysi moddaning qattiq holati?","options":["H₂O","CO₂","SO₂","N₂"],"correct":1,"explain":"Quruq muz — qattiq uglerod (IV)-oksid."},{"q":"So'ndirilmagan ohakning formulasi qaysi?","options":["CaCO₃","Ca(OH)₂","CaO","CaSO₄"],"correct":2,"explain":"So'ndirilmagan ohak — kalsiy oksid CaO."},{"q":"SO₃ asosan nima olish uchun ishlatiladi?","options":["Nitrat kislota","Sulfat kislota","Shisha","Sement"],"correct":1,"explain":"SO₃ suv bilan birikib sulfat kislotani hosil qiladi."}]},"en":{"title":"Uses of the most important oxides","intro":"The bubbles in fizzy water, the sand and lime used to build houses, the acid in a car battery — all of these are linked to oxides. Let us look at the oxides that matter most in everyday life and industry.","blocks":[{"h":"Carbon(IV) oxide — CO₂","p":"Carbon dioxide is a permanent but very small part of the air (about 0.04%). Green plants take it in through their leaves and, using sunlight, turn it together with water into sugar while releasing oxygen — this process is called photosynthesis. CO₂ is used to make drinks fizzy, in fire extinguishers and in making soda, and its solid form, \"dry ice\", is used for cooling.","formula":"6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ (in light)","visual":{"type":"chart","kind":"air"}},{"h":"Silicon(IV) oxide — SiO₂","p":"In nature it is widespread, mainly as sand and quartz. Sand is an important building material and the main raw material for making glass. Quartz melts only at very high temperatures and lets ultraviolet light pass through, so it is used for heat-resistant laboratory ware and ultraviolet lamps. Pure silicon for electronics is also obtained from SiO₂, and decorative stones such as amethyst and agate are forms of quartz."},{"h":"Calcium oxide — CaO","p":"Calcium oxide is called quicklime and is made by strongly heating limestone. It is used in building to make mortars and cement, to neutralise acidic soils and in the chemical industry. The product it forms with water is used in orchards to protect trees from pests.","formula":"CaCO₃ → CaO + CO₂ (on heating)"},{"h":"Sulfur(VI) oxide and nitrogen(IV) oxide","p":"SO₃ is hardly ever found free in nature: it is made by oxidising sulfur(IV) oxide with the help of a catalyst. It is used to produce sulfuric acid, which in turn is needed for fertilisers, medicines and car batteries. The brown gas NO₂ is made mainly to produce nitric acid, from which nitrogen fertilisers and medicines are prepared.","formula":"2SO₂ + O₂ → 2SO₃ (catalyst)"},{"h":"Summary table","table":{"head":["Oxide","Common name","Main use"],"rows":[["CO₂","carbon dioxide, dry ice","fizzy drinks, cooling, fire fighting"],["SiO₂","sand, quartz","building, glass, lab ware"],["CaO","quicklime","building, cement, soil neutralisation"],["SO₃","sulfur trioxide","making sulfuric acid"],["NO₂","nitrogen dioxide","making nitric acid"]]}},{"h":"Remember","items":["CO₂ is needed for photosynthesis and is used in fizzy drinks and as dry ice.","SiO₂ (sand, quartz) is a raw material for building and glass making.","CaO (quicklime) is made by heating limestone and is used in building.","SO₃ and NO₂ are raw materials for sulfuric and nitric acid respectively."]}],"quiz":[{"q":"\"Dry ice\" is the solid form of which substance?","options":["H₂O","CO₂","SO₂","N₂"],"correct":1,"explain":"Dry ice is solid carbon(IV) oxide."},{"q":"What is the formula of quicklime?","options":["CaCO₃","Ca(OH)₂","CaO","CaSO₄"],"correct":2,"explain":"Quicklime is calcium oxide, CaO."},{"q":"SO₃ is mainly used to make…","options":["nitric acid","sulfuric acid","glass","cement"],"correct":1,"explain":"SO₃ combines with water to form sulfuric acid."}]},"ru":{"title":"Применение важнейших оксидов","intro":"Пузырьки в газировке, песок и известь для строительства домов, кислота в автомобильном аккумуляторе — всё это связано с оксидами. Рассмотрим оксиды, которые важнее всего в быту и промышленности.","blocks":[{"h":"Оксид углерода(IV) — CO₂","p":"Углекислый газ — постоянная, но очень малая часть воздуха (около 0,04%). Зелёные растения поглощают его листьями и под действием солнечного света вместе с водой превращают в сахар, выделяя кислород, — этот процесс называется фотосинтезом. CO₂ используют для газирования напитков, в огнетушителях и в производстве соды, а его твёрдую форму — «сухой лёд» — для охлаждения.","formula":"6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ (на свету)","visual":{"type":"chart","kind":"air"}},{"h":"Оксид кремния(IV) — SiO₂","p":"В природе широко распространён, главным образом в виде песка и кварца. Песок — важный строительный материал и основное сырьё для производства стекла. Кварц плавится только при очень высокой температуре и пропускает ультрафиолетовые лучи, поэтому из него делают термостойкую лабораторную посуду и ультрафиолетовые лампы. Из SiO₂ получают и чистый кремний для электроники, а такие поделочные камни, как аметист и агат, — разновидности кварца."},{"h":"Оксид кальция — CaO","p":"Оксид кальция называют негашёной известью; его получают сильным нагреванием известняка. Его используют в строительстве для приготовления растворов и цемента, для нейтрализации кислых почв и в химической промышленности. Продукт его реакции с водой применяют в садах для защиты деревьев от вредителей.","formula":"CaCO₃ → CaO + CO₂ (при нагревании)"},{"h":"Оксид серы(VI) и оксид азота(IV)","p":"SO₃ почти не встречается в природе в свободном виде: его получают окислением оксида серы(IV) в присутствии катализатора. Из него производят серную кислоту, которая нужна для удобрений, лекарств и автомобильных аккумуляторов. Бурый газ NO₂ получают в основном для производства азотной кислоты, из которой делают азотные удобрения и лекарства.","formula":"2SO₂ + O₂ → 2SO₃ (катализатор)"},{"h":"Краткая таблица","table":{"head":["Оксид","Бытовое название","Главное применение"],"rows":[["CO₂","углекислый газ, сухой лёд","газированные напитки, охлаждение, тушение пожаров"],["SiO₂","песок, кварц","строительство, стекло, лабораторная посуда"],["CaO","негашёная известь","строительство, цемент, нейтрализация почв"],["SO₃","серный ангидрид","производство серной кислоты"],["NO₂","бурый газ","производство азотной кислоты"]]}},{"h":"Запомните","items":["CO₂ нужен для фотосинтеза, его используют в газировке и в виде сухого льда.","SiO₂ (песок, кварц) — сырьё для строительства и производства стекла.","CaO (негашёную известь) получают нагреванием известняка и применяют в строительстве.","SO₃ и NO₂ — сырьё для получения серной и азотной кислот соответственно."]}],"quiz":[{"q":"«Сухой лёд» — это твёрдая форма какого вещества?","options":["H₂O","CO₂","SO₂","N₂"],"correct":1,"explain":"Сухой лёд — твёрдый оксид углерода(IV)."},{"q":"Какова формула негашёной извести?","options":["CaCO₃","Ca(OH)₂","CaO","CaSO₄"],"correct":2,"explain":"Негашёная известь — оксид кальция CaO."},{"q":"Для чего в основном используют SO₃?","options":["Для получения азотной кислоты","Для получения серной кислоты","Для производства стекла","Для производства цемента"],"correct":1,"explain":"SO₃ соединяется с водой и образует серную кислоту."}]}},{"id":"t38","num":38,"icon":"🧼","uz":{"title":"Asoslarning tarkibi, tuzilishi va nomlanishi","intro":"Sovun ishlab chiqarishda ishlatiladigan o'yuvchi natriy va devorlarni oqlashda qo'llanadigan so'ndirilgan ohak bitta sinfga — asoslarga kiradi. Ularning barchasida bitta umumiy «bo'lak» bor: gidroksoguruh OH. Shu darsda asoslar qanday tuzilganini va qanday nomlanishini o'rganamiz.","blocks":[{"h":"Asos nima?","p":"Asos — metall atomi va bir yoki bir nechta gidroksoguruh (OH) dan tashkil topgan murakkab modda. Gidroksoguruh bir valentli, shuning uchun asosdagi OH guruhlar soni metallning valentligiga teng. Ammoniy gidroksid NH₄OH ham asoslarga kiritiladi.","formula":"M(OH)ₙ (M — metall, n — metallning valentligi)","items":["NaOH — natriy I valentli, bitta OH","Ca(OH)₂ — kalsiy II valentli, ikkita OH","Al(OH)₃ — aluminiy III valentli, uchta OH"],"visual":{"type":"diagram","kind":"classification"}},{"h":"Asoslarning tuzilishi","p":"Asos tarkibida kislorod atomi metall atomi bilan vodorod atomi o'rtasida joylashadi va ularning har biri bilan bog' hosil qiladi. Grafik formulada buni chiziqchalar bilan ko'rsatamiz. Metall atomidan nechta chiziq chiqsa, shuncha O–H guruhi bog'langan bo'ladi.","formula":"Na–O–H     H–O–Ca–O–H"},{"h":"Misol: asos formulasini tuzamiz","p":"Temir (III) gidroksidining formulasini tuzib ko'raylik.","items":["1) Temirning valentligi — III.","2) OH guruh bir valentli, demak, temir atomiga uchta OH birikadi.","3) Bir nechta OH guruhni qavsga olib, indeksni qavsdan keyin yozamiz.","4) Javob: Fe(OH)₃."]},{"h":"Asoslarni nomlash","p":"Valentligi doimiy metall uchun nom «metall nomi + gidroksid» tarzida tuziladi. Metall valentligi o'zgaruvchan bo'lsa, valentlik qavs ichida rim raqami bilan yoziladi. OH guruhlar sonini yunoncha qo'shimcha bilan ham ko'rsatish mumkin: Ca(OH)₂ — kalsiy digidroksid. Har bir asosga valentligi bir xil bo'lgan asosli oksid mos keladi.","table":{"head":["Asos","Nomi","Mos oksid"],"rows":[["KOH","kaliy gidroksid","K₂O"],["Ba(OH)₂","bariy gidroksid","BaO"],["Fe(OH)₂","temir (II)-gidroksid","FeO"],["Fe(OH)₃","temir (III)-gidroksid","Fe₂O₃"],["Cu(OH)₂","mis (II)-gidroksid","CuO"]]}},{"h":"Esda tuting","items":["Asos — metall atomi va gidroksoguruhlardan iborat murakkab modda, umumiy formula M(OH)ₙ.","OH guruhlar soni metallning valentligiga teng.","Asosda kislorod metall va vodorod atomlari orasida turadi.","O'zgaruvchan valentli metall gidroksidining nomida rim raqami yoziladi: Cu(OH)₂ — mis (II)-gidroksid."]}],"quiz":[{"q":"Quyidagilardan qaysi biri asos?","options":["H₂SO₄","NaOH","Na₂O","NaCl"],"correct":1,"explain":"NaOH metall atomi va gidroksoguruhdan iborat."},{"q":"Temir (III)-gidroksidda nechta OH guruh bor?","options":["1","2","3","6"],"correct":2,"explain":"OH guruhlar soni metall valentligiga teng, temir bu yerda III valentli."},{"q":"Cu(OH)₂ qanday nomlanadi?","options":["Mis (I)-gidroksid","Mis (II)-gidroksid","Mis oksid","Mis digidrid"],"correct":1,"explain":"Ikkita OH guruh misning II valentli ekanini ko'rsatadi."}]},"en":{"title":"Bases: composition, structure and naming","intro":"Caustic soda, used for making soap, and slaked lime, used for whitewashing walls, belong to the same class: bases. All of them contain one shared \"piece\" — the hydroxide group OH. In this lesson we learn how bases are built and how they are named.","blocks":[{"h":"What is a base?","p":"A base is a compound made of a metal atom and one or more hydroxide groups (OH). The hydroxide group has a valency of I, so the number of OH groups in a base equals the valency of the metal. Ammonium hydroxide NH₄OH is also counted as a base.","formula":"M(OH)ₙ (M is a metal, n is its valency)","items":["NaOH — sodium has valency I, one OH","Ca(OH)₂ — calcium has valency II, two OH","Al(OH)₃ — aluminium has valency III, three OH"],"visual":{"type":"diagram","kind":"classification"}},{"h":"Structure of bases","p":"In a base the oxygen atom sits between the metal atom and the hydrogen atom and is bonded to each of them. In a structural formula we show this with dashes. The metal atom has as many O–H groups attached as it has dashes.","formula":"Na–O–H     H–O–Ca–O–H"},{"h":"Example: building a base formula","p":"Let us write the formula of iron(III) hydroxide.","items":["1) The valency of iron here is III.","2) The OH group has valency I, so three OH groups join one iron atom.","3) When there is more than one OH group, put OH in brackets and write the subscript after the bracket.","4) Answer: Fe(OH)₃."]},{"h":"Naming bases","p":"For a metal with a fixed valency the name is \"metal name + hydroxide\". If the metal has a variable valency, the valency is written as a Roman numeral in brackets. The number of OH groups can also be shown with a Greek prefix: Ca(OH)₂ is calcium dihydroxide. Every base corresponds to a basic oxide in which the metal has the same valency.","table":{"head":["Base","Name","Related oxide"],"rows":[["KOH","potassium hydroxide","K₂O"],["Ba(OH)₂","barium hydroxide","BaO"],["Fe(OH)₂","iron(II) hydroxide","FeO"],["Fe(OH)₃","iron(III) hydroxide","Fe₂O₃"],["Cu(OH)₂","copper(II) hydroxide","CuO"]]}},{"h":"Remember","items":["A base is a compound of a metal atom and hydroxide groups; general formula M(OH)ₙ.","The number of OH groups equals the valency of the metal.","In a base oxygen sits between the metal and hydrogen atoms.","For metals with variable valency the name includes a Roman numeral: Cu(OH)₂ is copper(II) hydroxide."]}],"quiz":[{"q":"Which of these is a base?","options":["H₂SO₄","NaOH","Na₂O","NaCl"],"correct":1,"explain":"NaOH is made of a metal atom and a hydroxide group."},{"q":"How many OH groups are in iron(III) hydroxide?","options":["1","2","3","6"],"correct":2,"explain":"The number of OH groups equals the metal's valency, and iron here has valency III."},{"q":"What is the name of Cu(OH)₂?","options":["Copper(I) hydroxide","Copper(II) hydroxide","Copper oxide","Copper dihydride"],"correct":1,"explain":"Two OH groups show that copper has valency II."}]},"ru":{"title":"Основания: состав, строение и названия","intro":"Едкий натр, из которого делают мыло, и гашёная известь, которой белят стены, относятся к одному классу — основаниям. Во всех них есть общая «деталь» — гидроксогруппа OH. На этом уроке узнаем, как устроены основания и как их называют.","blocks":[{"h":"Что такое основание?","p":"Основание — сложное вещество, состоящее из атома металла и одной или нескольких гидроксогрупп (OH). Гидроксогруппа одновалентна, поэтому число групп OH в основании равно валентности металла. К основаниям относят и гидроксид аммония NH₄OH.","formula":"M(OH)ₙ (M — металл, n — его валентность)","items":["NaOH — натрий одновалентен, одна группа OH","Ca(OH)₂ — кальций двухвалентен, две группы OH","Al(OH)₃ — алюминий трёхвалентен, три группы OH"],"visual":{"type":"diagram","kind":"classification"}},{"h":"Строение оснований","p":"В основании атом кислорода находится между атомом металла и атомом водорода и связан с каждым из них. В графической формуле это показывают чёрточками. Сколько чёрточек отходит от атома металла, столько групп O–H к нему присоединено.","formula":"Na–O–H     H–O–Ca–O–H"},{"h":"Пример: составляем формулу основания","p":"Составим формулу гидроксида железа(III).","items":["1) Валентность железа здесь — III.","2) Группа OH одновалентна, значит, к атому железа присоединяются три группы OH.","3) Если групп OH несколько, их заключают в скобки, а индекс пишут после скобки.","4) Ответ: Fe(OH)₃."]},{"h":"Названия оснований","p":"Для металла с постоянной валентностью название строится так: «гидроксид + название металла в родительном падеже». Если валентность металла переменная, её указывают римской цифрой в скобках. Число групп OH можно показать и греческой приставкой: Ca(OH)₂ — дигидроксид кальция. Каждому основанию соответствует основный оксид с той же валентностью металла.","table":{"head":["Основание","Название","Соответствующий оксид"],"rows":[["KOH","гидроксид калия","K₂O"],["Ba(OH)₂","гидроксид бария","BaO"],["Fe(OH)₂","гидроксид железа(II)","FeO"],["Fe(OH)₃","гидроксид железа(III)","Fe₂O₃"],["Cu(OH)₂","гидроксид меди(II)","CuO"]]}},{"h":"Запомните","items":["Основание — сложное вещество из атома металла и гидроксогрупп; общая формула M(OH)ₙ.","Число групп OH равно валентности металла.","В основании кислород находится между атомами металла и водорода.","Для металлов с переменной валентностью в названии пишут римскую цифру: Cu(OH)₂ — гидроксид меди(II)."]}],"quiz":[{"q":"Какое из веществ является основанием?","options":["H₂SO₄","NaOH","Na₂O","NaCl"],"correct":1,"explain":"NaOH состоит из атома металла и гидроксогруппы."},{"q":"Сколько групп OH в гидроксиде железа(III)?","options":["1","2","3","6"],"correct":2,"explain":"Число групп OH равно валентности металла, а железо здесь трёхвалентно."},{"q":"Как называется Cu(OH)₂?","options":["Гидроксид меди(I)","Гидроксид меди(II)","Оксид меди","Дигидрид меди"],"correct":1,"explain":"Две группы OH показывают, что медь двухвалентна."}]}},{"id":"t39","num":39,"icon":"🧪","uz":{"title":"Asoslarning toifalanishi","intro":"Ba'zi asoslar suvda shakardek oson eriydi, boshqalari esa probirka tubiga cho'kma bo'lib tushadi. Asoslar eruvchanligiga, kimyoviy xossalariga va tarkibidagi OH guruhlar soniga qarab guruhlarga ajratiladi.","blocks":[{"h":"Eruvchanligiga ko'ra: ishqorlar va erimaydigan asoslar","p":"Suvda eriydigan asoslar ishqorlar deb ataladi. Ishqoriy metallarning hamda ishqoriy-yer metallarning (berilliy va magniydan tashqari) gidroksidlari ishqorlardir, Ca(OH)₂ esa suvda kam eriydi. Qolgan asoslar suvda deyarli erimaydi.","items":["Ishqorlar: LiOH, NaOH, KOH, Ba(OH)₂, Ca(OH)₂ (kam eriydi)","Suvda erimaydigan asoslar: Cu(OH)₂, Fe(OH)₂, Fe(OH)₃, Mg(OH)₂"]},{"h":"O'yuvchi ishqorlar — ehtiyot bo'ling!","p":"Kuchli ishqorlar teri, ko'z va to'qimalarni yemiradi, shuning uchun ularni o'yuvchi ishqorlar deyishadi. NaOH — o'yuvchi natriy, KOH — o'yuvchi kaliy. Ular bilan ishlaganda xavfsizlik qoidalariga qat'iy amal qilish kerak.","items":["Himoya ko'zoynagi va qo'lqop kiying.","Ishqorni qo'l bilan ushlamang, kurakcha bilan oling.","Teriga tegsa, darhol ko'p miqdordagi suv bilan yuving va o'qituvchiga ayting."]},{"h":"Amfoter gidroksidlar","p":"Ba'zi gidroksidlar ikki tomonlama xossaga ega: ular kislotalar bilan ham, ishqorlar bilan ham reaksiyaga kirishadi. Bunday moddalar amfoter gidroksidlar deyiladi, ular suvda erimaydi. Ularga Zn(OH)₂, Al(OH)₃, Cr(OH)₃ misol bo'ladi.","formula":"Zn(OH)₂ + 2HCl → ZnCl₂ + 2H₂O"},{"h":"Kislotaliligiga ko'ra","p":"Asosning kislotaliligi uning tarkibidagi OH guruhlar soni bilan aniqlanadi. Bu son asos bitta molekulasi kislota bilan reaksiyada nechta OH guruhini almashtira olishini ko'rsatadi.","table":{"head":["Turi","OH soni","Misollar"],"rows":[["Bir kislotali","1","NaOH, KOH, LiOH"],["Ikki kislotali","2","Ca(OH)₂, Ba(OH)₂, Cu(OH)₂"],["Uch kislotali","3","Al(OH)₃, Fe(OH)₃"]]}},{"h":"Ishqorlarni indikatorlar bilan aniqlash","p":"Indikatorlar — muhitga qarab rangini o'zgartiradigan moddalar. Ishqor eritmasida lakmus ko'k, fenolftalein to'q pushti (moviy-qizil), metilzarg'aldog'i sariq rangga kiradi. Suvda erimaydigan asoslar indikator rangini o'zgartirmaydi.","table":{"head":["Indikator","Neytral muhitda","Ishqoriy muhitda"],"rows":[["Lakmus","binafsha","ko'k"],["Fenolftalein","rangsiz","to'q pushti"],["Metilzarg'aldog'i","to'q sariq","sariq"]]},"visual":{"type":"diagram","kind":"indicators"}},{"h":"Esda tuting","items":["Suvda eriydigan asoslar ishqorlar deyiladi: NaOH, KOH, Ba(OH)₂.","Amfoter gidroksidlar (Zn(OH)₂, Al(OH)₃) kislota bilan ham, ishqor bilan ham reaksiyaga kirishadi.","Asosning kislotaliligi OH guruhlar soniga teng.","Ishqor fenolftaleinni to'q pushti, lakmusni ko'k rangga bo'yaydi."]}],"quiz":[{"q":"Qaysi modda ishqor?","options":["Cu(OH)₂","Fe(OH)₃","KOH","Mg(OH)₂"],"correct":2,"explain":"KOH suvda yaxshi eriydi, qolganlari erimaydigan asoslar."},{"q":"Fenolftalein ishqor eritmasida qanday rangga kiradi?","options":["Rangsiz qoladi","Ko'k","To'q pushti","Sariq"],"correct":2,"explain":"Ishqoriy muhitda fenolftalein to'q pushti tusga kiradi."},{"q":"Ca(OH)₂ necha kislotali asos?","options":["Bir","Ikki","Uch","Nol"],"correct":1,"explain":"Ca(OH)₂ tarkibida ikkita OH guruh bor."}]},"en":{"title":"Classification of bases","intro":"Some bases dissolve in water as easily as sugar, while others settle to the bottom of a test tube as a precipitate. Bases are grouped by their solubility, their chemical behaviour and the number of OH groups they contain.","blocks":[{"h":"By solubility: alkalis and insoluble bases","p":"Bases that dissolve in water are called alkalis. The hydroxides of the alkali metals and of the alkaline-earth metals (except beryllium and magnesium) are alkalis, although Ca(OH)₂ is only slightly soluble. The remaining bases hardly dissolve in water at all.","items":["Alkalis: LiOH, NaOH, KOH, Ba(OH)₂, Ca(OH)₂ (slightly soluble)","Insoluble bases: Cu(OH)₂, Fe(OH)₂, Fe(OH)₃, Mg(OH)₂"]},{"h":"Caustic alkalis — take care!","p":"Strong alkalis eat away skin, eyes and tissue, so they are called caustic alkalis. NaOH is caustic soda and KOH is caustic potash. Safety rules must be followed strictly when working with them.","items":["Wear safety goggles and gloves.","Never touch an alkali with your hands; use a spatula.","If it gets on your skin, wash at once with plenty of water and tell the teacher."]},{"h":"Amphoteric hydroxides","p":"Some hydroxides behave both ways: they react with acids and with alkalis. Such substances are called amphoteric hydroxides, and they are insoluble in water. Examples are Zn(OH)₂, Al(OH)₃ and Cr(OH)₃.","formula":"Zn(OH)₂ + 2HCl → ZnCl₂ + 2H₂O"},{"h":"By acidity","p":"The acidity of a base is set by the number of OH groups it contains. This number shows how many OH groups one formula unit of the base can exchange when it reacts with an acid.","table":{"head":["Type","Number of OH","Examples"],"rows":[["Monoacidic","1","NaOH, KOH, LiOH"],["Diacidic","2","Ca(OH)₂, Ba(OH)₂, Cu(OH)₂"],["Triacidic","3","Al(OH)₃, Fe(OH)₃"]]}},{"h":"Detecting alkalis with indicators","p":"Indicators are substances that change colour depending on the medium. In an alkali solution litmus turns blue, phenolphthalein turns crimson (pink) and methyl orange turns yellow. Insoluble bases do not change the colour of indicators.","table":{"head":["Indicator","In a neutral medium","In an alkaline medium"],"rows":[["Litmus","violet","blue"],["Phenolphthalein","colourless","crimson"],["Methyl orange","orange","yellow"]]},"visual":{"type":"diagram","kind":"indicators"}},{"h":"Remember","items":["Bases that dissolve in water are called alkalis: NaOH, KOH, Ba(OH)₂.","Amphoteric hydroxides (Zn(OH)₂, Al(OH)₃) react with both acids and alkalis.","The acidity of a base equals the number of its OH groups.","An alkali turns phenolphthalein crimson and litmus blue."]}],"quiz":[{"q":"Which substance is an alkali?","options":["Cu(OH)₂","Fe(OH)₃","KOH","Mg(OH)₂"],"correct":2,"explain":"KOH dissolves well in water; the others are insoluble bases."},{"q":"What colour does phenolphthalein turn in an alkali solution?","options":["Stays colourless","Blue","Crimson","Yellow"],"correct":2,"explain":"In an alkaline medium phenolphthalein turns crimson."},{"q":"What is the acidity of Ca(OH)₂?","options":["One","Two","Three","Zero"],"correct":1,"explain":"Ca(OH)₂ contains two OH groups."}]},"ru":{"title":"Классификация оснований","intro":"Одни основания растворяются в воде так же легко, как сахар, а другие оседают на дно пробирки в виде осадка. Основания делят на группы по растворимости, по химическому поведению и по числу групп OH в их составе.","blocks":[{"h":"По растворимости: щёлочи и нерастворимые основания","p":"Растворимые в воде основания называют щелочами. Щелочами являются гидроксиды щелочных и щёлочноземельных металлов (кроме бериллия и магния), хотя Ca(OH)₂ растворяется лишь немного. Остальные основания в воде практически не растворяются.","items":["Щёлочи: LiOH, NaOH, KOH, Ba(OH)₂, Ca(OH)₂ (малорастворим)","Нерастворимые основания: Cu(OH)₂, Fe(OH)₂, Fe(OH)₃, Mg(OH)₂"]},{"h":"Едкие щёлочи — осторожно!","p":"Сильные щёлочи разъедают кожу, глаза и ткани, поэтому их называют едкими щелочами. NaOH — едкий натр, KOH — едкое кали. При работе с ними нужно строго соблюдать правила безопасности.","items":["Надевайте защитные очки и перчатки.","Не берите щёлочь руками, пользуйтесь шпателем.","Если щёлочь попала на кожу, сразу промойте большим количеством воды и сообщите учителю."]},{"h":"Амфотерные гидроксиды","p":"Некоторые гидроксиды обладают двойственными свойствами: реагируют и с кислотами, и со щелочами. Такие вещества называют амфотерными гидроксидами, в воде они нерастворимы. Примеры: Zn(OH)₂, Al(OH)₃, Cr(OH)₃.","formula":"Zn(OH)₂ + 2HCl → ZnCl₂ + 2H₂O"},{"h":"По кислотности","p":"Кислотность основания определяется числом групп OH в его составе. Это число показывает, сколько групп OH одна формульная единица основания может обменять при реакции с кислотой.","table":{"head":["Тип","Число OH","Примеры"],"rows":[["Однокислотные","1","NaOH, KOH, LiOH"],["Двухкислотные","2","Ca(OH)₂, Ba(OH)₂, Cu(OH)₂"],["Трёхкислотные","3","Al(OH)₃, Fe(OH)₃"]]}},{"h":"Обнаружение щелочей индикаторами","p":"Индикаторы — вещества, меняющие цвет в зависимости от среды. В растворе щёлочи лакмус синеет, фенолфталеин становится малиновым, а метиловый оранжевый — жёлтым. Нерастворимые основания цвет индикаторов не изменяют.","table":{"head":["Индикатор","В нейтральной среде","В щелочной среде"],"rows":[["Лакмус","фиолетовый","синий"],["Фенолфталеин","бесцветный","малиновый"],["Метиловый оранжевый","оранжевый","жёлтый"]]},"visual":{"type":"diagram","kind":"indicators"}},{"h":"Запомните","items":["Растворимые в воде основания называют щелочами: NaOH, KOH, Ba(OH)₂.","Амфотерные гидроксиды (Zn(OH)₂, Al(OH)₃) реагируют и с кислотами, и со щелочами.","Кислотность основания равна числу его групп OH.","Щёлочь окрашивает фенолфталеин в малиновый цвет, а лакмус — в синий."]}],"quiz":[{"q":"Какое вещество является щёлочью?","options":["Cu(OH)₂","Fe(OH)₃","KOH","Mg(OH)₂"],"correct":2,"explain":"KOH хорошо растворяется в воде, остальные — нерастворимые основания."},{"q":"Какой цвет приобретает фенолфталеин в растворе щёлочи?","options":["Остаётся бесцветным","Синий","Малиновый","Жёлтый"],"correct":2,"explain":"В щелочной среде фенолфталеин становится малиновым."},{"q":"Какова кислотность Ca(OH)₂?","options":["Однокислотное","Двухкислотное","Трёхкислотное","Нулевая"],"correct":1,"explain":"В Ca(OH)₂ две группы OH."}]}},{"id":"t40","num":40,"icon":"⚗️","uz":{"title":"Asoslarning olinishi va xossalari","intro":"Natriy bo'lakchasi suvga tashlansa, u suv yuzasida vishillab yugura boshlaydi va eritma ishqorga aylanadi. Mis tuzi eritmasiga ishqor qo'shilsa, ko'k cho'kma paydo bo'ladi. Bu tajribalar asoslarni qanday olish va ular qanday xossalarga ega ekanini ko'rsatadi.","blocks":[{"h":"Ishqorlarning olinishi","p":"Ishqoriy va ishqoriy-yer metallar suv bilan shiddatli reaksiyaga kirishib, ishqor va vodorod hosil qiladi. Shu metallarning oksidlari ham suv bilan birikib ishqor beradi.","items":["2Na + 2H₂O → 2NaOH + H₂↑","Ca + 2H₂O → Ca(OH)₂ + H₂↑","Na₂O + H₂O → 2NaOH","CaO + H₂O → Ca(OH)₂"]},{"h":"Erimaydigan asoslarning olinishi","p":"Suvda erimaydigan asoslar shu metall tuzining eritmasiga ishqor qo'shib olinadi. Bunda asos cho'kma (↓) holida ajraladi. Ko'p asoslarning rangi xarakterli: Cu(OH)₂ — ko'k, Fe(OH)₃ — qo'ng'ir, Ni(OH)₂ — yashil, ishqorlar esa oq qattiq moddalar.","items":["CuSO₄ + 2NaOH → Cu(OH)₂↓ + Na₂SO₄","FeCl₃ + 3KOH → Fe(OH)₃↓ + 3KCl"]},{"h":"Neytrallanish reaksiyasi","p":"Asoslarning eng muhim xossasi — kislotalar bilan reaksiyaga kirishib tuz va suv hosil qilishi. Bu reaksiya neytrallanish deyiladi, chunki ishqoriy va kislotali muhit bir-birini yo'qqa chiqaradi. Bunday reaksiyaga erimaydigan asoslar ham kirishadi.","formula":"NaOH + HCl → NaCl + H₂O","items":["Cu(OH)₂ + H₂SO₄ → CuSO₄ + 2H₂O","Ca(OH)₂ + 2HNO₃ → Ca(NO₃)₂ + 2H₂O"],"visual":{"type":"reaction","id":"naoh_hcl"}},{"h":"Misol: neytrallanishda qancha tuz hosil bo'ladi?","p":"4 g natriy gidroksid xlorid kislota bilan to'liq reaksiyaga kirishsa, necha gramm osh tuzi hosil bo'ladi?","items":["1) M(NaOH) = 23 + 16 + 1 = 40 g/mol; n(NaOH) = 4 : 40 = 0,1 mol.","2) Tenglama bo'yicha 1 mol NaOH dan 1 mol NaCl hosil bo'ladi, demak n(NaCl) = 0,1 mol.","3) M(NaCl) = 23 + 35,5 = 58,5 g/mol.","4) m(NaCl) = 0,1 · 58,5 = 5,85 g."]},{"h":"Boshqa kimyoviy xossalar","p":"Ishqorlar indikatorlar rangini o'zgartiradi, kislotali oksidlar va tuzlar bilan reaksiyaga kirishadi. Ohakli suvdan CO₂ o'tkazilsa, u loyqalanadi — bu karbonat angidridni aniqlash usuli. Erimaydigan asoslar qizdirilganda oksid va suvga parchalanadi.","items":["Kislotali oksid bilan: Ca(OH)₂ + CO₂ → CaCO₃↓ + H₂O","Tuz bilan: NiCl₂ + 2NaOH → Ni(OH)₂↓ + 2NaCl","Qizdirilganda: Cu(OH)₂ → CuO + H₂O"]},{"h":"Esda tuting","items":["Ishqorlar faol metall yoki uning oksidini suvga ta'sir ettirib olinadi.","Erimaydigan asoslar tuz eritmasiga ishqor qo'shib olinadi.","Asos + kislota → tuz + suv (neytrallanish reaksiyasi).","Erimaydigan asoslar qizdirilganda metall oksidi va suvga parchalanadi."]}],"quiz":[{"q":"Neytrallanish reaksiyasida nima hosil bo'ladi?","options":["Tuz va vodorod","Tuz va suv","Oksid va suv","Asos va tuz"],"correct":1,"explain":"Asos kislota bilan reaksiyaga kirishib tuz va suv beradi."},{"q":"Qaysi asos qizdirilganda oksid va suvga parchalanadi?","options":["NaOH","KOH","Cu(OH)₂","Ba(OH)₂"],"correct":2,"explain":"Erimaydigan Cu(OH)₂ qizdirilganda CuO va suvga ajraladi."},{"q":"Ohakli suvdan CO₂ o'tkazilganda qaysi modda loyqa hosil qiladi?","options":["CaCO₃","CaO","Ca(OH)₂","CaCl₂"],"correct":0,"explain":"Suvda erimaydigan kalsiy karbonat cho'kmaga tushib eritmani loyqalatadi."}]},"en":{"title":"How bases are obtained, and their properties","intro":"Drop a small piece of sodium into water and it rushes across the surface with a hiss, turning the water into an alkali. Add an alkali to a copper salt solution and a blue precipitate appears. These experiments show how bases are made and what properties they have.","blocks":[{"h":"Obtaining alkalis","p":"Alkali and alkaline-earth metals react vigorously with water to give an alkali and hydrogen. The oxides of these metals also combine with water to give alkalis.","items":["2Na + 2H₂O → 2NaOH + H₂↑","Ca + 2H₂O → Ca(OH)₂ + H₂↑","Na₂O + H₂O → 2NaOH","CaO + H₂O → Ca(OH)₂"]},{"h":"Obtaining insoluble bases","p":"Insoluble bases are made by adding an alkali to a solution of a salt of that metal. The base separates out as a precipitate (↓). Many bases have typical colours: Cu(OH)₂ is blue, Fe(OH)₃ is brown, Ni(OH)₂ is green, while alkalis are white solids.","items":["CuSO₄ + 2NaOH → Cu(OH)₂↓ + Na₂SO₄","FeCl₃ + 3KOH → Fe(OH)₃↓ + 3KCl"]},{"h":"The neutralisation reaction","p":"The most important property of bases is that they react with acids to give a salt and water. This reaction is called neutralisation, because the alkaline and acidic media cancel each other out. Insoluble bases take part in this reaction too.","formula":"NaOH + HCl → NaCl + H₂O","items":["Cu(OH)₂ + H₂SO₄ → CuSO₄ + 2H₂O","Ca(OH)₂ + 2HNO₃ → Ca(NO₃)₂ + 2H₂O"],"visual":{"type":"reaction","id":"naoh_hcl"}},{"h":"Example: how much salt does neutralisation give?","p":"4 g of sodium hydroxide reacts completely with hydrochloric acid. How many grams of table salt form?","items":["1) M(NaOH) = 23 + 16 + 1 = 40 g/mol; n(NaOH) = 4 ÷ 40 = 0.1 mol.","2) By the equation 1 mol NaOH gives 1 mol NaCl, so n(NaCl) = 0.1 mol.","3) M(NaCl) = 23 + 35.5 = 58.5 g/mol.","4) m(NaCl) = 0.1 × 58.5 = 5.85 g."]},{"h":"Other chemical properties","p":"Alkalis change the colour of indicators and react with acidic oxides and with salts. When CO₂ is bubbled through limewater, it turns cloudy — this is a way to detect carbon dioxide. Insoluble bases break down into an oxide and water when heated.","items":["With an acidic oxide: Ca(OH)₂ + CO₂ → CaCO₃↓ + H₂O","With a salt: NiCl₂ + 2NaOH → Ni(OH)₂↓ + 2NaCl","On heating: Cu(OH)₂ → CuO + H₂O"]},{"h":"Remember","items":["Alkalis are made by reacting an active metal or its oxide with water.","Insoluble bases are made by adding an alkali to a salt solution.","Base + acid → salt + water (the neutralisation reaction).","Insoluble bases decompose on heating into a metal oxide and water."]}],"quiz":[{"q":"What forms in a neutralisation reaction?","options":["A salt and hydrogen","A salt and water","An oxide and water","A base and a salt"],"correct":1,"explain":"A base reacts with an acid to give a salt and water."},{"q":"Which base decomposes into an oxide and water on heating?","options":["NaOH","KOH","Cu(OH)₂","Ba(OH)₂"],"correct":2,"explain":"Insoluble Cu(OH)₂ breaks down into CuO and water when heated."},{"q":"Which substance makes limewater cloudy when CO₂ is passed through it?","options":["CaCO₃","CaO","Ca(OH)₂","CaCl₂"],"correct":0,"explain":"Insoluble calcium carbonate precipitates and makes the solution cloudy."}]},"ru":{"title":"Получение и свойства оснований","intro":"Если бросить в воду кусочек натрия, он с шипением бегает по поверхности, а вода превращается в раствор щёлочи. Если добавить щёлочь к раствору соли меди, выпадает голубой осадок. Эти опыты показывают, как получают основания и какими свойствами они обладают.","blocks":[{"h":"Получение щелочей","p":"Щелочные и щёлочноземельные металлы бурно реагируют с водой, образуя щёлочь и водород. Оксиды этих металлов тоже соединяются с водой и дают щёлочи.","items":["2Na + 2H₂O → 2NaOH + H₂↑","Ca + 2H₂O → Ca(OH)₂ + H₂↑","Na₂O + H₂O → 2NaOH","CaO + H₂O → Ca(OH)₂"]},{"h":"Получение нерастворимых оснований","p":"Нерастворимые основания получают, добавляя щёлочь к раствору соли соответствующего металла. Основание выделяется в виде осадка (↓). Многие основания имеют характерный цвет: Cu(OH)₂ — голубой, Fe(OH)₃ — бурый, Ni(OH)₂ — зелёный, а щёлочи — белые твёрдые вещества.","items":["CuSO₄ + 2NaOH → Cu(OH)₂↓ + Na₂SO₄","FeCl₃ + 3KOH → Fe(OH)₃↓ + 3KCl"]},{"h":"Реакция нейтрализации","p":"Важнейшее свойство оснований — реагировать с кислотами с образованием соли и воды. Такую реакцию называют нейтрализацией, потому что щелочная и кислотная среды взаимно уничтожаются. В эту реакцию вступают и нерастворимые основания.","formula":"NaOH + HCl → NaCl + H₂O","items":["Cu(OH)₂ + H₂SO₄ → CuSO₄ + 2H₂O","Ca(OH)₂ + 2HNO₃ → Ca(NO₃)₂ + 2H₂O"],"visual":{"type":"reaction","id":"naoh_hcl"}},{"h":"Пример: сколько соли даёт нейтрализация?","p":"4 г гидроксида натрия полностью прореагировали с соляной кислотой. Сколько граммов поваренной соли образовалось?","items":["1) M(NaOH) = 23 + 16 + 1 = 40 г/моль; n(NaOH) = 4 : 40 = 0,1 моль.","2) По уравнению из 1 моль NaOH получается 1 моль NaCl, значит n(NaCl) = 0,1 моль.","3) M(NaCl) = 23 + 35,5 = 58,5 г/моль.","4) m(NaCl) = 0,1 · 58,5 = 5,85 г."]},{"h":"Другие химические свойства","p":"Щёлочи изменяют окраску индикаторов, реагируют с кислотными оксидами и с солями. Если пропускать CO₂ через известковую воду, она мутнеет — так обнаруживают углекислый газ. Нерастворимые основания при нагревании разлагаются на оксид и воду.","items":["С кислотным оксидом: Ca(OH)₂ + CO₂ → CaCO₃↓ + H₂O","С солью: NiCl₂ + 2NaOH → Ni(OH)₂↓ + 2NaCl","При нагревании: Cu(OH)₂ → CuO + H₂O"]},{"h":"Запомните","items":["Щёлочи получают действием воды на активный металл или его оксид.","Нерастворимые основания получают, добавляя щёлочь к раствору соли.","Основание + кислота → соль + вода (реакция нейтрализации).","Нерастворимые основания при нагревании разлагаются на оксид металла и воду."]}],"quiz":[{"q":"Что образуется в реакции нейтрализации?","options":["Соль и водород","Соль и вода","Оксид и вода","Основание и соль"],"correct":1,"explain":"Основание реагирует с кислотой с образованием соли и воды."},{"q":"Какое основание при нагревании разлагается на оксид и воду?","options":["NaOH","KOH","Cu(OH)₂","Ba(OH)₂"],"correct":2,"explain":"Нерастворимый Cu(OH)₂ при нагревании распадается на CuO и воду."},{"q":"Какое вещество вызывает помутнение известковой воды при пропускании CO₂?","options":["CaCO₃","CaO","Ca(OH)₂","CaCl₂"],"correct":0,"explain":"Нерастворимый карбонат кальция выпадает в осадок и делает раствор мутным."}]}},{"id":"t41","num":41,"icon":"🏭","uz":{"title":"Eng muhim asoslarning ishlatilishi","intro":"Siz ishlatadigan sovun, daftaringizdagi qog'oz va uy devoridagi oq bo'yoq — bularni tayyorlashda asoslar qatnashgan. Bu darsda sanoat va turmushda eng ko'p qo'llanadigan uchta asos bilan tanishamiz.","blocks":[{"h":"Natriy gidroksid — NaOH","p":"O'yuvchi natriy (kaustik soda) — oq, suvda juda yaxshi eriydigan qattiq modda. U gigroskopik, ya'ni havodagi namlikni yutib, asta-sekin suyuqlanib qoladi. Eritmasi qo'lga sovundek sirpanchiq tuyuladi, lekin terini kuydiradi, shuning uchun u bilan juda ehtiyot bo'lib ishlash kerak. Sanoatda NaOH osh tuzi eritmasini elektroliz qilib olinadi.","formula":"2NaCl + 2H₂O → 2NaOH + H₂↑ + Cl₂↑ (elektroliz)","visual":{"type":"molecule3d","mol":"NaCl"}},{"h":"NaOH qayerda ishlatiladi?","p":"Natriy gidroksid kimyo sanoatining eng muhim xomashyolaridan biri.","items":["Qattiq sovun tayyorlashda","Qog'oz ishlab chiqarishda","To'qimachilik va sun'iy tolalar ishlab chiqarishda","Neft mahsulotlarini tozalashda"]},{"h":"Kaliy gidroksid — KOH","p":"O'yuvchi kaliy ham oq, suvda yaxshi eriydigan qattiq modda bo'lib, xossalari NaOH ga juda o'xshaydi. U kaliy xlorid eritmasini elektroliz qilib olinadi. Narxi qimmatroq bo'lgani uchun kamroq ishlatiladi: asosan suyuq sovun tayyorlashda va ishqoriy batareyalarda qo'llanadi."},{"h":"Kalsiy gidroksid — Ca(OH)₂","p":"So'ndirilgan ohak — oq kukunsimon modda, suvda kam eriydi. Uning tiniq eritmasi «ohakli suv», suv bilan loyqa aralashmasi esa «ohak suti» deyiladi. Ca(OH)₂ ohaktoshni qizdirib olingan so'ndirilmagan ohakka suv qo'shib olinadi, bu jarayon «ohakni so'ndirish» deyiladi va ko'p issiqlik ajraladi. U qurilish qorishmalarida, devorlarni oqlashda, kislotali tuproqlarni neytrallashda va zararkunandalarga qarshi kurashda ishlatiladi.","formula":"CaCO₃ → CaO + CO₂;   CaO + H₂O → Ca(OH)₂","items":["Misol: 50 g CaCO₃ dan qancha Ca(OH)₂ olinadi?","M(CaCO₃) = 40 + 12 + 3·16 = 100 g/mol; n = 50 : 100 = 0,5 mol.","Sxema bo'yicha 1 mol CaCO₃ → 1 mol Ca(OH)₂, demak n(Ca(OH)₂) = 0,5 mol.","M(Ca(OH)₂) = 40 + 2·17 = 74 g/mol; m = 0,5 · 74 = 37 g."]},{"h":"Qisqacha jadval","table":{"head":["Asos","Kundalik nomi","Asosiy qo'llanilishi"],"rows":[["NaOH","o'yuvchi natriy, kaustik soda","sovun, qog'oz, to'qimachilik"],["KOH","o'yuvchi kaliy","suyuq sovun, ishqoriy batareyalar"],["Ca(OH)₂","so'ndirilgan ohak","qurilish, oqlash, tuproqni neytrallash"]]}},{"h":"Esda tuting","items":["NaOH (kaustik soda) — gigroskopik, o'yuvchi modda; osh tuzi eritmasini elektroliz qilib olinadi.","KOH xossalari NaOH ga o'xshaydi, lekin qimmatroq.","Ca(OH)₂ — so'ndirilgan ohak; uning tiniq eritmasi ohakli suv deyiladi.","So'ndirilgan ohak qurilishda va tuproq kislotaliligini kamaytirishda ishlatiladi."]}],"quiz":[{"q":"Kaustik sodaning formulasi qaysi?","options":["KOH","NaOH","Ca(OH)₂","Na₂CO₃"],"correct":1,"explain":"Kaustik soda yoki o'yuvchi natriy — NaOH."},{"q":"Sanoatda NaOH qanday olinadi?","options":["Natriyni yondirib","Osh tuzi eritmasini elektroliz qilib","Ohaktoshni qizdirib","Qumdan"],"correct":1,"explain":"NaCl eritmasidan elektr toki o'tkazilganda NaOH, vodorod va xlor hosil bo'ladi."},{"q":"So'ndirilgan ohak qaysi modda?","options":["CaO","CaCO₃","Ca(OH)₂","CaSO₄"],"correct":2,"explain":"So'ndirilgan ohak — kalsiy gidroksid Ca(OH)₂."}]},"en":{"title":"Uses of the most important bases","intro":"The soap you use, the paper in your notebook and the white coating on a house wall were all made with the help of bases. In this lesson we meet the three bases used most in industry and everyday life.","blocks":[{"h":"Sodium hydroxide — NaOH","p":"Caustic soda is a white solid that dissolves very well in water. It is hygroscopic: it absorbs moisture from the air and slowly turns liquid. Its solution feels slippery like soap but burns the skin, so it must be handled with great care. In industry NaOH is made by electrolysis of a sodium chloride solution.","formula":"2NaCl + 2H₂O → 2NaOH + H₂↑ + Cl₂↑ (electrolysis)","visual":{"type":"molecule3d","mol":"NaCl"}},{"h":"Where is NaOH used?","p":"Sodium hydroxide is one of the most important raw materials of the chemical industry.","items":["Making hard soap","Making paper","Textile and artificial fibre production","Purifying petroleum products"]},{"h":"Potassium hydroxide — KOH","p":"Caustic potash is also a white solid that dissolves well in water, and its properties are very similar to those of NaOH. It is made by electrolysis of a potassium chloride solution. Because it is more expensive, it is used less: mainly for liquid soap and in alkaline batteries."},{"h":"Calcium hydroxide — Ca(OH)₂","p":"Slaked lime is a white powder that dissolves only slightly in water. Its clear solution is called \"limewater\", and its cloudy mixture with water is called \"milk of lime\". Ca(OH)₂ is made by adding water to quicklime obtained by heating limestone; this is called slaking and gives off a lot of heat. It is used in building mortars, for whitewashing, for neutralising acidic soils and against pests.","formula":"CaCO₃ → CaO + CO₂;   CaO + H₂O → Ca(OH)₂","items":["Example: how much Ca(OH)₂ can be made from 50 g of CaCO₃?","M(CaCO₃) = 40 + 12 + 3·16 = 100 g/mol; n = 50 ÷ 100 = 0.5 mol.","By the scheme 1 mol CaCO₃ → 1 mol Ca(OH)₂, so n(Ca(OH)₂) = 0.5 mol.","M(Ca(OH)₂) = 40 + 2·17 = 74 g/mol; m = 0.5 × 74 = 37 g."]},{"h":"Summary table","table":{"head":["Base","Common name","Main use"],"rows":[["NaOH","caustic soda","soap, paper, textiles"],["KOH","caustic potash","liquid soap, alkaline batteries"],["Ca(OH)₂","slaked lime","building, whitewash, soil neutralisation"]]}},{"h":"Remember","items":["NaOH (caustic soda) is a hygroscopic, corrosive substance made by electrolysis of salt solution.","KOH is similar to NaOH but more expensive.","Ca(OH)₂ is slaked lime; its clear solution is called limewater.","Slaked lime is used in building and to reduce soil acidity."]}],"quiz":[{"q":"What is the formula of caustic soda?","options":["KOH","NaOH","Ca(OH)₂","Na₂CO₃"],"correct":1,"explain":"Caustic soda is sodium hydroxide, NaOH."},{"q":"How is NaOH made in industry?","options":["By burning sodium","By electrolysis of salt solution","By heating limestone","From sand"],"correct":1,"explain":"Passing electric current through NaCl solution gives NaOH, hydrogen and chlorine."},{"q":"Which substance is slaked lime?","options":["CaO","CaCO₃","Ca(OH)₂","CaSO₄"],"correct":2,"explain":"Slaked lime is calcium hydroxide, Ca(OH)₂."}]},"ru":{"title":"Применение важнейших оснований","intro":"Мыло, которым вы пользуетесь, бумага в вашей тетради и белая побелка на стене дома — всё это сделано с участием оснований. На этом уроке познакомимся с тремя основаниями, которые чаще всего применяют в промышленности и быту.","blocks":[{"h":"Гидроксид натрия — NaOH","p":"Едкий натр (каустическая сода) — белое твёрдое вещество, очень хорошо растворимое в воде. Он гигроскопичен: поглощает влагу из воздуха и постепенно расплывается. Его раствор на ощупь мылкий, но обжигает кожу, поэтому работать с ним нужно очень осторожно. В промышленности NaOH получают электролизом раствора поваренной соли.","formula":"2NaCl + 2H₂O → 2NaOH + H₂↑ + Cl₂↑ (электролиз)","visual":{"type":"molecule3d","mol":"NaCl"}},{"h":"Где применяют NaOH?","p":"Гидроксид натрия — одно из важнейших сырьевых веществ химической промышленности.","items":["Производство твёрдого мыла","Производство бумаги","Текстильная промышленность и производство искусственных волокон","Очистка нефтепродуктов"]},{"h":"Гидроксид калия — KOH","p":"Едкое кали — тоже белое, хорошо растворимое в воде твёрдое вещество, по свойствам очень похожее на NaOH. Его получают электролизом раствора хлорида калия. Поскольку он дороже, применяют его реже: в основном для жидкого мыла и в щелочных батарейках."},{"h":"Гидроксид кальция — Ca(OH)₂","p":"Гашёная известь — белое порошкообразное вещество, малорастворимое в воде. Её прозрачный раствор называют «известковой водой», а мутную смесь с водой — «известковым молоком». Ca(OH)₂ получают, добавляя воду к негашёной извести, полученной обжигом известняка; этот процесс называют гашением, и при нём выделяется много теплоты. Её используют в строительных растворах, для побелки, для нейтрализации кислых почв и против вредителей.","formula":"CaCO₃ → CaO + CO₂;   CaO + H₂O → Ca(OH)₂","items":["Пример: сколько Ca(OH)₂ можно получить из 50 г CaCO₃?","M(CaCO₃) = 40 + 12 + 3·16 = 100 г/моль; n = 50 : 100 = 0,5 моль.","По схеме 1 моль CaCO₃ → 1 моль Ca(OH)₂, значит n(Ca(OH)₂) = 0,5 моль.","M(Ca(OH)₂) = 40 + 2·17 = 74 г/моль; m = 0,5 · 74 = 37 г."]},{"h":"Краткая таблица","table":{"head":["Основание","Бытовое название","Главное применение"],"rows":[["NaOH","едкий натр, каустическая сода","мыло, бумага, текстиль"],["KOH","едкое кали","жидкое мыло, щелочные батарейки"],["Ca(OH)₂","гашёная известь","строительство, побелка, нейтрализация почв"]]}},{"h":"Запомните","items":["NaOH (каустическая сода) — гигроскопичное едкое вещество; его получают электролизом раствора соли.","KOH по свойствам похож на NaOH, но дороже.","Ca(OH)₂ — гашёная известь; её прозрачный раствор называют известковой водой.","Гашёную известь применяют в строительстве и для снижения кислотности почв."]}],"quiz":[{"q":"Какова формула каустической соды?","options":["KOH","NaOH","Ca(OH)₂","Na₂CO₃"],"correct":1,"explain":"Каустическая сода, или едкий натр, — это NaOH."},{"q":"Как получают NaOH в промышленности?","options":["Сжиганием натрия","Электролизом раствора поваренной соли","Обжигом известняка","Из песка"],"correct":1,"explain":"При пропускании тока через раствор NaCl образуются NaOH, водород и хлор."},{"q":"Какое вещество является гашёной известью?","options":["CaO","CaCO₃","Ca(OH)₂","CaSO₄"],"correct":2,"explain":"Гашёная известь — гидроксид кальция Ca(OH)₂."}]}},{"id":"t42","num":42,"icon":"🍋","uz":{"title":"Kislotalar: tarkibi, tuzilishi va nomlanishi","intro":"Limon, olma yoki qatiqning nordon ta'mi ulardagi kislotalarga bog'liq. Kimyoda kislotalar alohida sinfni tashkil qiladi va ularning hammasi bir xil «qolip» asosida tuzilgan. Bu darsda shu qolipni ochib, kislotalarni to'g'ri nomlashni o'rganamiz.","blocks":[{"h":"Kislota nima?","p":"Kislota – molekulasi vodorod atomlari va kislota qoldig'idan tashkil topgan murakkab modda. Undagi vodorod atomlari reaksiyalarda metall atomlariga almashinishi mumkin. Molekulaning vodoroddan qolgan qismi kislota qoldig'i deyiladi.","formula":"HₙA  (A – kislota qoldig'i, n – uning valentligi)"},{"h":"Vodorodlar soni va qoldiq valentligi","p":"Vodorod bir valentli bo'lgani uchun kislotadagi vodorod atomlari soni kislota qoldig'ining valentligiga teng. Demak, formulaga qarab qoldiq valentligini darhol aytish mumkin.","items":["HCl → qoldiq Cl, valentligi I","H₂SO₄ → qoldiq SO₄, valentligi II","H₃PO₄ → qoldiq PO₄, valentligi III"]},{"h":"Kislotalarning tuzilishi","p":"Kislorodsiz kislotalarda vodorod atomi qoldiqdagi metallmas atomiga bevosita bog'langan, masalan H–Cl. Kislorodli kislotalarda esa har bir vodorod atomi kislorod orqali markaziy atomga ulanadi: H–O–. Aylantirib ko'ring: HCl molekulasida bitta kichik vodorod va bitta katta xlor atomi bor.","items":["HCl: H–Cl","HNO₃: H–O– guruhi azot atomiga bog'langan","H₂SO₄: ikki H–O– guruhi va ikki kislorod oltingugurt atomiga bog'langan"],"visual":{"type":"molecule3d","mol":"HCl"}},{"h":"Kislotalarni nomlash","p":"O'zbek tilida kislota nomi kislota qoldig'i nomiga «kislota» so'zini qo'shish bilan yasaladi. Shuning uchun asosiy qoldiqlar nomini yodlab olish foydali.","table":{"head":["Formula","Kislota nomi","Qoldiq","Qoldiq nomi"],"rows":[["HCl","xlorid kislota","Cl (I)","xlorid"],["HF","ftorid kislota","F (I)","ftorid"],["H₂S","sulfid kislota","S (II)","sulfid"],["HNO₃","nitrat kislota","NO₃ (I)","nitrat"],["H₂SO₃","sulfit kislota","SO₃ (II)","sulfit"],["H₂SO₄","sulfat kislota","SO₄ (II)","sulfat"],["H₂CO₃","karbonat kislota","CO₃ (II)","karbonat"],["H₃PO₄","ortofosfat kislota","PO₄ (III)","ortofosfat"]]}},{"h":"Namuna: H₂SiO₃ ni tahlil qilamiz","p":"Formulani bosqichma-bosqich o'qib chiqamiz.","items":["1) Vodorodni ajratamiz: H₂ va SiO₃.","2) Vodorod atomlari 2 ta, demak SiO₃ qoldig'i ikki valentli.","3) SiO₃ qoldig'i silikat deb ataladi.","4) Kislota nomi: silikat kislota."]},{"h":"Esda tuting","items":["Kislota = vodorod atomlari + kislota qoldig'i.","Vodorod atomlari soni qoldiq valentligiga teng.","Kislorodli kislotalarda vodorod kislorod orqali bog'lanadi.","Nomi: qoldiq nomi + «kislota» (sulfat kislota, nitrat kislota)."]}],"quiz":[{"q":"Kislota qoldig'i PO₄ uch valentli. Kislota molekulasida nechta vodorod atomi bo'ladi?","options":["1","2","3","4"],"correct":2,"explain":"Vodorodlar soni qoldiq valentligiga teng, ya'ni 3 ta: H₃PO₄."},{"q":"HNO₃ dagi kislota qoldig'i qanday ataladi?","options":["sulfat","nitrat","nitrit","karbonat"],"correct":1,"explain":"NO₃ qoldig'i nitrat, shuning uchun HNO₃ nitrat kislota."},{"q":"Quyidagilardan qaysi biri kislota?","options":["H₂CO₃","NaOH","CaO","KCl"],"correct":0,"explain":"H₂CO₃ vodorod va CO₃ kislota qoldig'idan iborat, demak u kislota."}]},"en":{"title":"Acids: composition, structure and naming","intro":"The sour taste of lemons, apples and yogurt comes from acids. In chemistry, acids form a separate class, and all of them are built on the same pattern. In this lesson we uncover that pattern and learn to name acids correctly.","blocks":[{"h":"What is an acid?","p":"An acid is a complex substance whose molecule consists of hydrogen atoms and an acid residue. In reactions these hydrogen atoms can be replaced by metal atoms. The part of the molecule left after removing the hydrogen is called the acid residue.","formula":"HₙA  (A – acid residue, n – its valence)"},{"h":"Number of hydrogens and valence of the residue","p":"Hydrogen has a valence of one, so the number of hydrogen atoms in an acid equals the valence of its acid residue. This lets you read the valence of a residue straight from the formula.","items":["HCl → residue Cl, valence I","H₂SO₄ → residue SO₄, valence II","H₃PO₄ → residue PO₄, valence III"]},{"h":"Structure of acids","p":"In oxygen-free acids the hydrogen atom is bonded directly to the non-metal atom of the residue, for example H–Cl. In oxygen-containing acids each hydrogen atom is joined to the central atom through an oxygen atom: H–O–. Rotate the model: an HCl molecule has one small hydrogen atom and one large chlorine atom.","items":["HCl: H–Cl","HNO₃: an H–O– group is attached to the nitrogen atom","H₂SO₄: two H–O– groups and two oxygen atoms are attached to the sulfur atom"],"visual":{"type":"molecule3d","mol":"HCl"}},{"h":"Naming acids","p":"Acid names are linked to the names of their residues. Oxygen-free acids are called hydro…ic acids, while residues ending in -ate give acids ending in -ic and residues ending in -ite give acids ending in -ous.","table":{"head":["Formula","Acid name","Residue","Residue name"],"rows":[["HCl","hydrochloric acid","Cl (I)","chloride"],["HF","hydrofluoric acid","F (I)","fluoride"],["H₂S","hydrosulfuric acid","S (II)","sulfide"],["HNO₃","nitric acid","NO₃ (I)","nitrate"],["H₂SO₃","sulfurous acid","SO₃ (II)","sulfite"],["H₂SO₄","sulfuric acid","SO₄ (II)","sulfate"],["H₂CO₃","carbonic acid","CO₃ (II)","carbonate"],["H₃PO₄","phosphoric acid","PO₄ (III)","phosphate"]]}},{"h":"Example: analysing H₂SiO₃","p":"Let us read the formula step by step.","items":["1) Separate the hydrogen: H₂ and SiO₃.","2) There are 2 hydrogen atoms, so the SiO₃ residue has a valence of two.","3) The SiO₃ residue is called silicate.","4) The acid is silicic acid."]},{"h":"Remember","items":["Acid = hydrogen atoms + acid residue.","The number of hydrogen atoms equals the valence of the residue.","In oxygen-containing acids hydrogen is bonded through oxygen.","The acid name follows the residue name: sulfate → sulfuric acid, nitrate → nitric acid."]}],"quiz":[{"q":"The PO₄ residue has a valence of three. How many hydrogen atoms are in the acid molecule?","options":["1","2","3","4"],"correct":2,"explain":"The number of hydrogens equals the residue valence, so there are 3: H₃PO₄."},{"q":"What is the acid residue in HNO₃ called?","options":["sulfate","nitrate","nitrite","carbonate"],"correct":1,"explain":"The NO₃ residue is nitrate, so HNO₃ is nitric acid."},{"q":"Which of these substances is an acid?","options":["H₂CO₃","NaOH","CaO","KCl"],"correct":0,"explain":"H₂CO₃ consists of hydrogen and the CO₃ acid residue, so it is an acid."}]},"ru":{"title":"Кислоты: состав, строение и названия","intro":"Кислый вкус лимона, яблока и кефира объясняется кислотами. В химии кислоты образуют отдельный класс веществ, и все они построены по одному образцу. На этом уроке мы разберём этот образец и научимся правильно называть кислоты.","blocks":[{"h":"Что такое кислота?","p":"Кислота – сложное вещество, молекула которого состоит из атомов водорода и кислотного остатка. В реакциях эти атомы водорода могут замещаться атомами металла. Часть молекулы, оставшаяся без водорода, называется кислотным остатком.","formula":"HₙA  (A – кислотный остаток, n – его валентность)"},{"h":"Число атомов водорода и валентность остатка","p":"Водород одновалентен, поэтому число атомов водорода в кислоте равно валентности кислотного остатка. Значит, валентность остатка можно сразу определить по формуле.","items":["HCl → остаток Cl, валентность I","H₂SO₄ → остаток SO₄, валентность II","H₃PO₄ → остаток PO₄, валентность III"]},{"h":"Строение кислот","p":"В бескислородных кислотах атом водорода связан прямо с атомом неметалла, например H–Cl. В кислородсодержащих кислотах каждый атом водорода присоединён к центральному атому через атом кислорода: H–O–. Поверните модель: в молекуле HCl один маленький атом водорода и один большой атом хлора.","items":["HCl: H–Cl","HNO₃: группа H–O– присоединена к атому азота","H₂SO₄: две группы H–O– и два атома кислорода присоединены к атому серы"],"visual":{"type":"molecule3d","mol":"HCl"}},{"h":"Названия кислот","p":"Название кислоты связано с названием её остатка. Остатку на «-ат» соответствует кислота с окончанием «-ная» или «-вая», остатку на «-ит» – кислота на «-истая», а бескислородные кислоты называют по неметаллу с добавлением «-водородная».","table":{"head":["Формула","Название кислоты","Остаток","Название остатка"],"rows":[["HCl","хлороводородная (соляная)","Cl (I)","хлорид"],["HF","фтороводородная (плавиковая)","F (I)","фторид"],["H₂S","сероводородная","S (II)","сульфид"],["HNO₃","азотная","NO₃ (I)","нитрат"],["H₂SO₃","сернистая","SO₃ (II)","сульфит"],["H₂SO₄","серная","SO₄ (II)","сульфат"],["H₂CO₃","угольная","CO₃ (II)","карбонат"],["H₃PO₄","ортофосфорная","PO₄ (III)","ортофосфат"]]}},{"h":"Пример: разбираем H₂SiO₃","p":"Прочитаем формулу по шагам.","items":["1) Отделяем водород: H₂ и SiO₃.","2) Атомов водорода 2, значит остаток SiO₃ двухвалентен.","3) Остаток SiO₃ называется силикат.","4) Кислота называется кремниевой."]},{"h":"Запомните","items":["Кислота = атомы водорода + кислотный остаток.","Число атомов водорода равно валентности остатка.","В кислородсодержащих кислотах водород связан через кислород.","Название кислоты связано с названием остатка: сульфат → серная, нитрат → азотная."]}],"quiz":[{"q":"Остаток PO₄ трёхвалентен. Сколько атомов водорода в молекуле кислоты?","options":["1","2","3","4"],"correct":2,"explain":"Число атомов водорода равно валентности остатка, то есть 3: H₃PO₄."},{"q":"Как называется кислотный остаток в HNO₃?","options":["сульфат","нитрат","нитрит","карбонат"],"correct":1,"explain":"Остаток NO₃ – нитрат, поэтому HNO₃ – азотная кислота."},{"q":"Какое из веществ является кислотой?","options":["H₂CO₃","NaOH","CaO","KCl"],"correct":0,"explain":"H₂CO₃ состоит из водорода и кислотного остатка CO₃, значит это кислота."}]}},{"id":"t43","num":43,"icon":"🗂️","uz":{"title":"Kislotalarning toifalanishi","intro":"Kislotalar juda ko'p, ularni tartibga solish uchun bir necha belgidan foydalaniladi. Tarkibida kislorod borligi, vodorod atomlari soni va kuchiga qarab har bir kislotaga «pasport» yozish mumkin.","blocks":[{"h":"Kislorodli va kislorodsiz kislotalar","p":"Kislota qoldig'ida kislorod atomi bo'lsa, kislota kislorodli, bo'lmasa kislorodsiz deyiladi. Kislorodsiz kislotalar ko'pincha vodorodli gazlarning (HCl, H₂S) suvdagi eritmalaridir.","table":{"head":["Kislorodsiz","Kislorodli"],"rows":[["HCl, HBr, HI","HNO₃, H₂SO₄"],["HF","H₂CO₃, H₂SiO₃"],["H₂S, HCN","H₃PO₄, H₂SO₃"]]}},{"h":"Negizliligi bo'yicha","p":"Kislotaning negizliligi uning molekulasidagi metallga almashina oladigan vodorod atomlari soni bilan aniqlanadi. Bir negizli kislotada bitta, ikki negizlida ikkita, uch negizlida uchta shunday vodorod bo'ladi.","table":{"head":["Bir negizli","Ikki negizli","Uch negizli"],"rows":[["HCl","H₂SO₄","H₃PO₄"],["HNO₃","H₂CO₃","H₃BO₃"],["HF","H₂S","H₃AsO₄"]]}},{"h":"Kuchli va kuchsiz kislotalar","p":"Kuchli kislotalarning suvdagi eritmasida deyarli barcha molekulalar zarrachalarga (ionlarga) ajraladi, shuning uchun ular faol reaksiyaga kirishadi. Kuchsiz kislotalarda bu jarayon molekulalarning faqat kichik qismida boradi. H₃PO₄ o'rtacha kuchdagi kislota hisoblanadi.","items":["Kuchli: HCl, HBr, HI, HNO₃, H₂SO₄","Kuchsiz: H₂S, H₂CO₃, H₂SiO₃, HF, HNO₂"]},{"h":"Barqaror va beqaror kislotalar","p":"Ayrim kislotalar faqat eritmada mavjud bo'lib, oson parchalanadi. Gazli ichimlik ochilganda ko'piklanishi karbonat kislotaning parchalanib, karbonat angidrid ajralishi bilan bog'liq.","formula":"H₂CO₃ → H₂O + CO₂↑"},{"h":"Namuna: H₂SO₄ ga «pasport» yozamiz","items":["1) Qoldiq SO₄ tarkibida kislorod bor → kislorodli.","2) Almashinuvchi vodorodlar 2 ta → ikki negizli.","3) Eritmada deyarli to'liq ionlarga ajraladi → kuchli.","4) Xona sharoitida parchalanmaydi → barqaror."]},{"h":"Esda tuting","items":["Tarkibiga ko'ra kislotalar kislorodli va kislorodsiz bo'ladi.","Negizlilik – almashina oladigan vodorod atomlari soni.","HCl, HNO₃, H₂SO₄ – kuchli; H₂S, H₂CO₃, H₂SiO₃ – kuchsiz.","H₂CO₃ va H₂SO₃ beqaror, oson parchalanadi."]}],"quiz":[{"q":"Qaysi kislota kislorodsiz?","options":["H₂SO₄","HNO₃","H₂S","H₃PO₄"],"correct":2,"explain":"H₂S qoldig'ida faqat oltingugurt bor, kislorod yo'q."},{"q":"Qaysi kislota ikki negizli?","options":["HCl","H₂CO₃","H₃PO₄","HNO₃"],"correct":1,"explain":"H₂CO₃ da metallga almashina oladigan ikkita vodorod atomi bor."},{"q":"Qaysi kislota kuchli?","options":["H₂S","H₂CO₃","H₂SiO₃","HCl"],"correct":3,"explain":"Xlorid kislota eritmada deyarli to'liq ionlarga ajraladi, shuning uchun kuchli."}]},"en":{"title":"Classification of acids","intro":"There are very many acids, so chemists sort them using several features. By looking at whether an acid contains oxygen, how many hydrogen atoms it has and how strong it is, you can write a kind of passport for every acid.","blocks":[{"h":"Oxygen-containing and oxygen-free acids","p":"If the acid residue contains an oxygen atom, the acid is oxygen-containing; if not, it is oxygen-free. Oxygen-free acids are often solutions of hydrogen-containing gases such as HCl and H₂S in water.","table":{"head":["Oxygen-free","Oxygen-containing"],"rows":[["HCl, HBr, HI","HNO₃, H₂SO₄"],["HF","H₂CO₃, H₂SiO₃"],["H₂S, HCN","H₃PO₄, H₂SO₃"]]}},{"h":"By basicity","p":"The basicity of an acid is the number of hydrogen atoms in its molecule that can be replaced by a metal. A monobasic acid has one such hydrogen, a dibasic acid has two and a tribasic acid has three.","table":{"head":["Monobasic","Dibasic","Tribasic"],"rows":[["HCl","H₂SO₄","H₃PO₄"],["HNO₃","H₂CO₃","H₃BO₃"],["HF","H₂S","H₃AsO₄"]]}},{"h":"Strong and weak acids","p":"In a water solution of a strong acid almost all molecules split into charged particles (ions), so strong acids react vigorously. In weak acids this happens only to a small part of the molecules. H₃PO₄ is considered an acid of medium strength.","items":["Strong: HCl, HBr, HI, HNO₃, H₂SO₄","Weak: H₂S, H₂CO₃, H₂SiO₃, HF, HNO₂"]},{"h":"Stable and unstable acids","p":"Some acids exist only in solution and break down easily. When you open a fizzy drink, it foams because carbonic acid decomposes and releases carbon dioxide.","formula":"H₂CO₃ → H₂O + CO₂↑"},{"h":"Example: a passport for H₂SO₄","items":["1) The SO₄ residue contains oxygen → oxygen-containing.","2) It has 2 replaceable hydrogens → dibasic.","3) It splits into ions almost completely in solution → strong.","4) It does not decompose at room conditions → stable."]},{"h":"Remember","items":["By composition acids are oxygen-containing or oxygen-free.","Basicity is the number of replaceable hydrogen atoms.","HCl, HNO₃, H₂SO₄ are strong; H₂S, H₂CO₃, H₂SiO₃ are weak.","H₂CO₃ and H₂SO₃ are unstable and decompose easily."]}],"quiz":[{"q":"Which acid is oxygen-free?","options":["H₂SO₄","HNO₃","H₂S","H₃PO₄"],"correct":2,"explain":"The residue of H₂S contains only sulfur and no oxygen."},{"q":"Which acid is dibasic?","options":["HCl","H₂CO₃","H₃PO₄","HNO₃"],"correct":1,"explain":"H₂CO₃ has two hydrogen atoms that can be replaced by a metal."},{"q":"Which acid is strong?","options":["H₂S","H₂CO₃","H₂SiO₃","HCl"],"correct":3,"explain":"Hydrochloric acid splits into ions almost completely in solution, so it is strong."}]},"ru":{"title":"Классификация кислот","intro":"Кислот очень много, и для порядка их делят по нескольким признакам. По наличию кислорода, числу атомов водорода и силе можно составить для каждой кислоты своеобразный паспорт.","blocks":[{"h":"Кислородсодержащие и бескислородные кислоты","p":"Если в кислотном остатке есть атом кислорода, кислота кислородсодержащая, если нет – бескислородная. Бескислородные кислоты часто представляют собой растворы водородных соединений-газов (HCl, H₂S) в воде.","table":{"head":["Бескислородные","Кислородсодержащие"],"rows":[["HCl, HBr, HI","HNO₃, H₂SO₄"],["HF","H₂CO₃, H₂SiO₃"],["H₂S, HCN","H₃PO₄, H₂SO₃"]]}},{"h":"По основности","p":"Основность кислоты – это число атомов водорода в её молекуле, способных замещаться на металл. У одноосновной кислоты один такой атом, у двухосновной – два, у трёхосновной – три.","table":{"head":["Одноосновные","Двухосновные","Трёхосновные"],"rows":[["HCl","H₂SO₄","H₃PO₄"],["HNO₃","H₂CO₃","H₃BO₃"],["HF","H₂S","H₃AsO₄"]]}},{"h":"Сильные и слабые кислоты","p":"В водном растворе сильной кислоты почти все молекулы распадаются на заряженные частицы (ионы), поэтому такие кислоты реагируют энергично. У слабых кислот это происходит лишь с небольшой частью молекул. H₃PO₄ считается кислотой средней силы.","items":["Сильные: HCl, HBr, HI, HNO₃, H₂SO₄","Слабые: H₂S, H₂CO₃, H₂SiO₃, HF, HNO₂"]},{"h":"Устойчивые и неустойчивые кислоты","p":"Некоторые кислоты существуют только в растворе и легко разлагаются. Газированный напиток пенится при открывании, потому что угольная кислота разлагается с выделением углекислого газа.","formula":"H₂CO₃ → H₂O + CO₂↑"},{"h":"Пример: паспорт серной кислоты H₂SO₄","items":["1) В остатке SO₄ есть кислород → кислородсодержащая.","2) Замещаемых атомов водорода 2 → двухосновная.","3) В растворе почти полностью распадается на ионы → сильная.","4) При обычных условиях не разлагается → устойчивая."]},{"h":"Запомните","items":["По составу кислоты бывают кислородсодержащие и бескислородные.","Основность – число замещаемых атомов водорода.","HCl, HNO₃, H₂SO₄ – сильные; H₂S, H₂CO₃, H₂SiO₃ – слабые.","H₂CO₃ и H₂SO₃ неустойчивы и легко разлагаются."]}],"quiz":[{"q":"Какая кислота бескислородная?","options":["H₂SO₄","HNO₃","H₂S","H₃PO₄"],"correct":2,"explain":"В остатке H₂S есть только сера, кислорода нет."},{"q":"Какая кислота двухосновная?","options":["HCl","H₂CO₃","H₃PO₄","HNO₃"],"correct":1,"explain":"В H₂CO₃ два атома водорода, способных замещаться на металл."},{"q":"Какая кислота сильная?","options":["H₂S","H₂CO₃","H₂SiO₃","HCl"],"correct":3,"explain":"Соляная кислота почти полностью распадается на ионы в растворе, поэтому она сильная."}]}},{"id":"t44","num":44,"icon":"🧪","uz":{"title":"Kislotalarning olinishi va xossalari","intro":"Kislotalar kimyodagi eng faol moddalardan. Ular indikatorlar rangini o'zgartiradi, asoslarni neytrallaydi, metallar va oksidlarni eritadi. Bu darsda kislotalar qanday olinishini va qanday reaksiyalarga kirishishini ko'rib chiqamiz.","blocks":[{"h":"Kislotalarni olish usullari","p":"Kislotani qaysi usulda olish uning turiga bog'liq.","items":["Kislotali oksid + suv: SO₃ + H₂O → H₂SO₄; P₂O₅ + 3H₂O → 2H₃PO₄","Metallmas + vodorod, so'ng gazni suvda eritish: H₂ + Cl₂ → 2HCl","Tuz + boshqa kislota: Na₂SiO₃ + 2HCl → H₂SiO₃↓ + 2NaCl"]},{"h":"Fizik xossalari va indikatorlar","p":"Kislotalar qattiq (H₃PO₄, H₃BO₃) yoki suyuq (H₂SO₄, HNO₃) bo'ladi, HCl va H₂S esa gazlarning eritmasidir. Laboratoriyada kislotani ta'tib ko'rish qat'iyan man etiladi, uni indikator yordamida aniqlaymiz. Kislota lakmusni qizil, metilzarg'aldog'ini pushti rangga bo'yaydi, fenolftalein esa rangsizligicha qoladi.","table":{"head":["Indikator","Neytral muhitda","Kislotada"],"rows":[["Lakmus","binafsha","qizil"],["Metilzarg'aldog'i","to'q sariq","pushti"],["Fenolftalein","rangsiz","rangsiz"]]},"visual":{"type":"diagram","kind":"indicators"}},{"h":"Asoslar va asosli oksidlar bilan reaksiya","p":"Kislota asos bilan tuz va suv hosil qiladi – bu neytrallanish reaksiyasi. Ishqorga fenolftalein tomizib, ustiga kislota qo'shilsa, pushti rang yo'qoladi. Kislotalar asosli oksidlar bilan ham tuz va suv beradi.","formula":"NaOH + HCl → NaCl + H₂O","items":["H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O","2HNO₃ + CaO → Ca(NO₃)₂ + H₂O"],"visual":{"type":"reaction","id":"naoh_hcl"}},{"h":"Metallar va tuzlar bilan reaksiya","p":"Metallarning faollik qatorida vodoroddan chapda turgan metallar kislotadan vodorodni siqib chiqaradi, o'ngdagilar (Cu, Ag, Au) esa siqib chiqarmaydi. Kislotalar tuzlar bilan yangi tuz va yangi kislota hosil qiladi, ayniqsa cho'kma yoki gaz chiqsa.","items":["Zn + H₂SO₄ → ZnSO₄ + H₂↑","Cu + HCl → reaksiya bormaydi","BaCl₂ + H₂SO₄ → BaSO₄↓ + 2HCl","Qizdirilganda: H₂SiO₃ → SiO₂ + H₂O"]},{"h":"Amaliy mashg'ulot: oksidlarni sulfat kislotada eritish","p":"Mis (II)-oksid va temir (III)-oksidni suyultirilgan sulfat kislota bilan reaksiyaga kiritib, hosil bo'lgan tuzni eritmadan ajratib olamiz. Himoya ko'zoynagi taqing, kislotani ehtiyotkorlik bilan qizdiring.","items":["1) Probirkaga bir necha ml suyultirilgan H₂SO₄ quyib, qaynash darajasigacha ehtiyotlik bilan isitiladi.","2) Shisha tayoqcha bilan aralashtirib, qora CuO kukuni oz-ozdan, u erimay qolguncha qo'shiladi: CuO + H₂SO₄ → CuSO₄ + H₂O. Eritma ko'k rangga kiradi.","3) Eritma chinni kosachaga filtrlanadi va spirt lampasida bug'latiladi – ko'k mis sulfat kristallari hosil bo'ladi.","4) Shu tartibda qizil-qo'ng'ir Fe₂O₃ bilan: Fe₂O₃ + 3H₂SO₄ → Fe₂(SO₄)₃ + 3H₂O, eritma sarg'ish-qo'ng'ir tusda bo'ladi.","5) Hisobotga maqsad, jihozlar, bajarilish tartibi, tenglamalar va xulosa yoziladi."]},{"h":"Esda tuting","items":["Kislorodli kislotalar kislotali oksid va suvdan olinadi.","Kislota lakmusni qizil, metilzarg'aldog'ini pushti qiladi.","Kislota + asos (yoki asosli oksid) → tuz + suv.","Vodoroddan chapdagi metallar kislotadan H₂ ni siqib chiqaradi."]}],"quiz":[{"q":"Kislota eritmasida lakmus qanday rangga kiradi?","options":["ko'k","qizil","rangsiz","sariq"],"correct":1,"explain":"Kislotali muhitda lakmus qizil rangga bo'yaladi."},{"q":"Qaysi metall xlorid kislotadan vodorodni siqib chiqarmaydi?","options":["Zn","Mg","Cu","Fe"],"correct":2,"explain":"Mis faollik qatorida vodoroddan o'ngda turadi."},{"q":"CuO va H₂SO₄ reaksiyasi mahsulotlari qaysi?","options":["CuSO₄ + H₂O","CuSO₄ + H₂","Cu(OH)₂ + SO₃","CuS + H₂O"],"correct":0,"explain":"Asosli oksid kislota bilan tuz va suv hosil qiladi."}]},"en":{"title":"How acids are obtained, and their properties","intro":"Acids are among the most active substances in chemistry. They change the colour of indicators, neutralise bases and dissolve metals and oxides. In this lesson we see how acids are made and which reactions they take part in.","blocks":[{"h":"Ways of obtaining acids","p":"The method depends on the type of acid.","items":["Acidic oxide + water: SO₃ + H₂O → H₂SO₄; P₂O₅ + 3H₂O → 2H₃PO₄","Non-metal + hydrogen, then dissolving the gas in water: H₂ + Cl₂ → 2HCl","Salt + another acid: Na₂SiO₃ + 2HCl → H₂SiO₃↓ + 2NaCl"]},{"h":"Physical properties and indicators","p":"Acids can be solids (H₃PO₄, H₃BO₃) or liquids (H₂SO₄, HNO₃), while HCl and H₂S acids are solutions of gases. Tasting an acid in the lab is strictly forbidden, so we detect it with indicators. An acid turns litmus red and methyl orange pink, while phenolphthalein stays colourless.","table":{"head":["Indicator","Neutral","Acid"],"rows":[["Litmus","violet","red"],["Methyl orange","orange","pink"],["Phenolphthalein","colourless","colourless"]]},"visual":{"type":"diagram","kind":"indicators"}},{"h":"Reactions with bases and basic oxides","p":"An acid and a base form a salt and water; this is called a neutralisation reaction. If you add phenolphthalein to an alkali and then pour in acid, the pink colour disappears. Acids also give a salt and water with basic oxides.","formula":"NaOH + HCl → NaCl + H₂O","items":["H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O","2HNO₃ + CaO → Ca(NO₃)₂ + H₂O"],"visual":{"type":"reaction","id":"naoh_hcl"}},{"h":"Reactions with metals and salts","p":"Metals to the left of hydrogen in the activity series displace hydrogen from acids, while those to the right (Cu, Ag, Au) do not. Acids react with salts to form a new salt and a new acid, especially when a precipitate or a gas forms.","items":["Zn + H₂SO₄ → ZnSO₄ + H₂↑","Cu + HCl → no reaction","BaCl₂ + H₂SO₄ → BaSO₄↓ + 2HCl","On heating: H₂SiO₃ → SiO₂ + H₂O"]},{"h":"Practical work: dissolving oxides in sulfuric acid","p":"We react copper(II) oxide and iron(III) oxide with dilute sulfuric acid and then isolate the salt from the solution. Wear safety goggles and heat the acid carefully.","items":["1) Pour a few mL of dilute H₂SO₄ into a test tube and carefully heat it almost to boiling.","2) While stirring with a glass rod, add black CuO powder in small portions until it stops dissolving: CuO + H₂SO₄ → CuSO₄ + H₂O. The solution turns blue.","3) Filter the solution into a porcelain dish and evaporate it over a spirit lamp; blue crystals of copper sulfate appear.","4) Repeat with red-brown Fe₂O₃: Fe₂O₃ + 3H₂SO₄ → Fe₂(SO₄)₃ + 3H₂O; the solution becomes yellowish-brown.","5) The report includes the aim, equipment, procedure, equations and conclusion."]},{"h":"Remember","items":["Oxygen-containing acids are made from an acidic oxide and water.","An acid turns litmus red and methyl orange pink.","Acid + base (or basic oxide) → salt + water.","Metals to the left of hydrogen displace H₂ from acids."]}],"quiz":[{"q":"What colour does litmus turn in an acid solution?","options":["blue","red","colourless","yellow"],"correct":1,"explain":"In an acidic medium litmus turns red."},{"q":"Which metal does not displace hydrogen from hydrochloric acid?","options":["Zn","Mg","Cu","Fe"],"correct":2,"explain":"Copper stands to the right of hydrogen in the activity series."},{"q":"What are the products of CuO and H₂SO₄?","options":["CuSO₄ + H₂O","CuSO₄ + H₂","Cu(OH)₂ + SO₃","CuS + H₂O"],"correct":0,"explain":"A basic oxide and an acid form a salt and water."}]},"ru":{"title":"Получение и свойства кислот","intro":"Кислоты – одни из самых активных веществ в химии. Они меняют окраску индикаторов, нейтрализуют основания, растворяют металлы и оксиды. На этом уроке разберём, как получают кислоты и в какие реакции они вступают.","blocks":[{"h":"Способы получения кислот","p":"Способ получения зависит от типа кислоты.","items":["Кислотный оксид + вода: SO₃ + H₂O → H₂SO₄; P₂O₅ + 3H₂O → 2H₃PO₄","Неметалл + водород, затем растворение газа в воде: H₂ + Cl₂ → 2HCl","Соль + другая кислота: Na₂SiO₃ + 2HCl → H₂SiO₃↓ + 2NaCl"]},{"h":"Физические свойства и индикаторы","p":"Кислоты бывают твёрдыми (H₃PO₄, H₃BO₃) и жидкими (H₂SO₄, HNO₃), а соляная и сероводородная кислоты – это растворы газов. Пробовать кислоту на вкус в лаборатории строго запрещено, поэтому её обнаруживают индикаторами. Кислота окрашивает лакмус в красный цвет, метиловый оранжевый – в розовый, а фенолфталеин остаётся бесцветным.","table":{"head":["Индикатор","В нейтральной среде","В кислоте"],"rows":[["Лакмус","фиолетовый","красный"],["Метиловый оранжевый","оранжевый","розовый"],["Фенолфталеин","бесцветный","бесцветный"]]},"visual":{"type":"diagram","kind":"indicators"}},{"h":"Реакции с основаниями и основными оксидами","p":"Кислота с основанием образует соль и воду – это реакция нейтрализации. Если к щёлочи с фенолфталеином прилить кислоту, малиновая окраска исчезнет. С основными оксидами кислоты тоже дают соль и воду.","formula":"NaOH + HCl → NaCl + H₂O","items":["H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O","2HNO₃ + CaO → Ca(NO₃)₂ + H₂O"],"visual":{"type":"reaction","id":"naoh_hcl"}},{"h":"Реакции с металлами и солями","p":"Металлы, стоящие в ряду активности левее водорода, вытесняют водород из кислот, а стоящие правее (Cu, Ag, Au) – нет. С солями кислоты образуют новую соль и новую кислоту, особенно если выпадает осадок или выделяется газ.","items":["Zn + H₂SO₄ → ZnSO₄ + H₂↑","Cu + HCl → реакция не идёт","BaCl₂ + H₂SO₄ → BaSO₄↓ + 2HCl","При нагревании: H₂SiO₃ → SiO₂ + H₂O"]},{"h":"Практическое занятие: растворение оксидов в серной кислоте","p":"Проводим реакции оксида меди(II) и оксида железа(III) с разбавленной серной кислотой и выделяем соль из раствора. Наденьте защитные очки и нагревайте кислоту осторожно.","items":["1) В пробирку наливают несколько мл разбавленной H₂SO₄ и осторожно нагревают почти до кипения.","2) Помешивая стеклянной палочкой, небольшими порциями добавляют чёрный порошок CuO, пока он не перестанет растворяться: CuO + H₂SO₄ → CuSO₄ + H₂O. Раствор становится голубым.","3) Раствор фильтруют в фарфоровую чашку и выпаривают на спиртовке – появляются голубые кристаллы сульфата меди.","4) Так же поступают с красно-бурым Fe₂O₃: Fe₂O₃ + 3H₂SO₄ → Fe₂(SO₄)₃ + 3H₂O, раствор желтовато-бурый.","5) В отчёт записывают цель, оборудование, ход работы, уравнения и вывод."]},{"h":"Запомните","items":["Кислородсодержащие кислоты получают из кислотного оксида и воды.","Кислота окрашивает лакмус в красный, метиловый оранжевый – в розовый.","Кислота + основание (или основный оксид) → соль + вода.","Металлы левее водорода вытесняют H₂ из кислот."]}],"quiz":[{"q":"Какой цвет приобретает лакмус в растворе кислоты?","options":["синий","красный","бесцветный","жёлтый"],"correct":1,"explain":"В кислой среде лакмус становится красным."},{"q":"Какой металл не вытесняет водород из соляной кислоты?","options":["Zn","Mg","Cu","Fe"],"correct":2,"explain":"Медь стоит в ряду активности правее водорода."},{"q":"Какие продукты образуются из CuO и H₂SO₄?","options":["CuSO₄ + H₂O","CuSO₄ + H₂","Cu(OH)₂ + SO₃","CuS + H₂O"],"correct":0,"explain":"Основный оксид с кислотой образует соль и воду."}]}},{"id":"t45","num":45,"icon":"🏭","uz":{"title":"Eng muhim kislotalarning ishlatilishi","intro":"Sulfat, xlorid va nitrat kislotalar sanoatning «ishchi otlari» hisoblanadi: o'g'it, dori, bo'yoq va akkumulyatorlar ular yordamida tayyorlanadi. Shu bilan birga ular xavfli moddalar, shuning uchun ular bilan ishlash qoidalarini bilish shart.","blocks":[{"h":"Sulfat kislota – H₂SO₄","p":"Konsentrlangan sulfat kislota rangsiz, hidsiz, moysimon suyuqlik bo'lib, zichligi taxminan 1,84 g/sm³, ya'ni suvdan deyarli ikki marta og'ir. U suvni kuchli tortib oladi: shakar yoki yog'ochni ko'mirga aylantiradi, gazlarni quritishda ishlatiladi.","items":["mineral o'g'itlar ishlab chiqarish","neft mahsulotlarini tozalash","boshqa kislota va tuzlar, dori va bo'yoqlar olish","avtomobil akkumulyatorlari","metall yuzasini zangdan tozalash"]},{"h":"Kislotani to'g'ri suyultirish","p":"Sulfat kislota suv bilan aralashganda juda ko'p issiqlik ajraladi. Agar kislotaga suv quyilsa, suv birdan qaynab, kislota sachrab ketishi mumkin. Shuning uchun doimo kislotani ingichka oqim bilan, idish devori bo'ylab, aralashtirib turgan holda suvga quyish kerak.","formula":"Kislota → suvga, aksincha emas!"},{"h":"Xlorid kislota – HCl","p":"Vodorod xlorid gazining suvdagi eritmasi rangsiz, o'tkir hidli suyuqlikdir. Konsentrlangan eritmadan HCl gazi chiqib, havodagi namlik bilan tuman hosil qiladi, shuning uchun u «tutaydi». Oshqozon shirasida ham oz miqdorda xlorid kislota bo'lib, ovqat hazm bo'lishiga yordam beradi.","items":["metallarni zang va oksid pardadan tozalash","xloridlar (tuzlar) olish","dori-darmon va plastmassa ishlab chiqarish"]},{"h":"Nitrat kislota – HNO₃","p":"Toza nitrat kislota rangsiz suyuqlik, suvdan taxminan 1,5 marta og'ir. Yorug'likda sekin parchalanib, hosil bo'lgan qo'ng'ir NO₂ gazi uni sarg'aytiradi, shu sababli u qorong'i shishalarda saqlanadi. Sovuq konsentrlangan nitrat kislota temir va aluminiy sirtini passivlashtiradi, shuning uchun uni aluminiy sisternalarda tashish mumkin.","items":["azotli o'g'itlar (masalan, ammiakli selitra)","bo'yoqlar va dori-darmonlar","portlovchi moddalar"]},{"h":"Kundalik hayotdagi kislotalar","table":{"head":["Qayerda?","Kislota"],"rows":[["Limon, apelsin","limon kislota"],["Sirka","sirka kislota"],["Gazli ichimliklar","karbonat kislota H₂CO₃"],["Oshqozon shirasi","xlorid kislota HCl"],["Avtomobil akkumulyatori","sulfat kislota H₂SO₄"]]}},{"h":"Esda tuting","items":["H₂SO₄ – og'ir moysimon suyuqlik, suvni kuchli tortadi.","Suyultirishda kislota suvga quyiladi, aksincha emas.","HCl oshqozon shirasida bor va metallarni tozalashda ishlatiladi.","HNO₃ azotli o'g'itlar olishda ishlatiladi va qorong'ida saqlanadi."]}],"quiz":[{"q":"Sulfat kislotani qanday suyultirish to'g'ri?","options":["Kislotaga tez suv quyish","Ikkalasini birdan quyish","Kislotaga sekin suv quyish","Kislotani sekin suvga quyish"],"correct":3,"explain":"Issiqlik suvning katta hajmida tarqalishi uchun kislota suvga quyiladi."},{"q":"Oshqozon shirasida qaysi kislota bor?","options":["HCl","H₂SO₄","HNO₃","H₃PO₄"],"correct":0,"explain":"Oshqozon shirasidagi xlorid kislota ovqat hazm bo'lishiga yordam beradi."},{"q":"Azotli o'g'itlar olishda asosan qaysi kislota ishlatiladi?","options":["HCl","H₂CO₃","HNO₃","H₂S"],"correct":2,"explain":"Nitrat kislota tarkibida azot bor va undan azotli o'g'itlar olinadi."}]},"en":{"title":"Uses of the most important acids","intro":"Sulfuric, hydrochloric and nitric acids are the workhorses of industry: fertilisers, medicines, dyes and batteries are made with their help. At the same time they are dangerous, so knowing how to handle them is essential.","blocks":[{"h":"Sulfuric acid – H₂SO₄","p":"Concentrated sulfuric acid is a colourless, odourless, oily liquid with a density of about 1.84 g/cm³, almost twice as heavy as water. It strongly draws water out of other substances: it chars sugar and wood and is used to dry gases.","items":["making mineral fertilisers","refining petroleum products","producing other acids and salts, medicines and dyes","car batteries","cleaning rust from metal surfaces"]},{"h":"Diluting an acid correctly","p":"Mixing sulfuric acid with water releases a great deal of heat. If water is poured into the acid, it can boil instantly and spray acid around. That is why the acid is always poured into water in a thin stream, down the wall of the vessel, while stirring.","formula":"Acid → into water, never the other way round!"},{"h":"Hydrochloric acid – HCl","p":"A solution of hydrogen chloride gas in water is a colourless liquid with a sharp smell. HCl gas escapes from the concentrated solution and forms a mist with moisture in the air, so the acid fumes. Our gastric juice also contains a little hydrochloric acid, which helps digestion.","items":["removing rust and oxide films from metals","making chlorides (salts)","producing medicines and plastics"]},{"h":"Nitric acid – HNO₃","p":"Pure nitric acid is a colourless liquid about 1.5 times heavier than water. In light it slowly decomposes and the brown NO₂ gas formed turns it yellow, so it is stored in dark bottles. Cold concentrated nitric acid makes the surface of iron and aluminium passive, so it can be transported in aluminium tanks.","items":["nitrogen fertilisers (for example ammonium nitrate)","dyes and medicines","explosives"]},{"h":"Acids in everyday life","table":{"head":["Where?","Acid"],"rows":[["Lemons, oranges","citric acid"],["Vinegar","acetic acid"],["Fizzy drinks","carbonic acid H₂CO₃"],["Gastric juice","hydrochloric acid HCl"],["Car battery","sulfuric acid H₂SO₄"]]}},{"h":"Remember","items":["H₂SO₄ is a heavy oily liquid that strongly absorbs water.","When diluting, pour the acid into water, never the reverse.","HCl is found in gastric juice and is used to clean metals.","HNO₃ is used to make nitrogen fertilisers and is kept in the dark."]}],"quiz":[{"q":"What is the correct way to dilute sulfuric acid?","options":["Quickly pour water into the acid","Pour both in at once","Slowly pour water into the acid","Slowly pour the acid into water"],"correct":3,"explain":"The acid goes into water so the heat spreads through a large volume of water."},{"q":"Which acid is found in gastric juice?","options":["HCl","H₂SO₄","HNO₃","H₃PO₄"],"correct":0,"explain":"Hydrochloric acid in gastric juice helps digest food."},{"q":"Which acid is mainly used to make nitrogen fertilisers?","options":["HCl","H₂CO₃","HNO₃","H₂S"],"correct":2,"explain":"Nitric acid contains nitrogen, and nitrogen fertilisers are made from it."}]},"ru":{"title":"Применение важнейших кислот","intro":"Серная, соляная и азотная кислоты – рабочие лошадки промышленности: с их помощью получают удобрения, лекарства, красители и аккумуляторы. Вместе с тем они опасны, поэтому правила обращения с ними нужно знать обязательно.","blocks":[{"h":"Серная кислота – H₂SO₄","p":"Концентрированная серная кислота – бесцветная маслянистая жидкость без запаха плотностью около 1,84 г/см³, то есть почти вдвое тяжелее воды. Она сильно отнимает воду у других веществ: обугливает сахар и древесину, применяется для осушения газов.","items":["производство минеральных удобрений","очистка нефтепродуктов","получение других кислот и солей, лекарств и красителей","автомобильные аккумуляторы","очистка поверхности металлов от ржавчины"]},{"h":"Как правильно разбавлять кислоту","p":"При смешивании серной кислоты с водой выделяется очень много теплоты. Если лить воду в кислоту, вода может мгновенно вскипеть и разбрызгать кислоту. Поэтому кислоту всегда вливают в воду тонкой струйкой по стенке сосуда, перемешивая.","formula":"Кислоту – в воду, а не наоборот!"},{"h":"Соляная кислота – HCl","p":"Раствор хлороводорода в воде – бесцветная жидкость с резким запахом. Из концентрированного раствора выделяется газ HCl, который с влагой воздуха образует туман, поэтому кислота дымит. В желудочном соке тоже есть немного соляной кислоты, она помогает пищеварению.","items":["очистка металлов от ржавчины и оксидной плёнки","получение хлоридов (солей)","производство лекарств и пластмасс"]},{"h":"Азотная кислота – HNO₃","p":"Чистая азотная кислота – бесцветная жидкость, примерно в 1,5 раза тяжелее воды. На свету она медленно разлагается, и образующийся бурый газ NO₂ окрашивает её в жёлтый цвет, поэтому её хранят в тёмных склянках. Холодная концентрированная азотная кислота пассивирует поверхность железа и алюминия, поэтому её перевозят в алюминиевых цистернах.","items":["азотные удобрения (например, аммиачная селитра)","красители и лекарства","взрывчатые вещества"]},{"h":"Кислоты в повседневной жизни","table":{"head":["Где?","Кислота"],"rows":[["Лимон, апельсин","лимонная кислота"],["Уксус","уксусная кислота"],["Газированные напитки","угольная кислота H₂CO₃"],["Желудочный сок","соляная кислота HCl"],["Автомобильный аккумулятор","серная кислота H₂SO₄"]]}},{"h":"Запомните","items":["H₂SO₄ – тяжёлая маслянистая жидкость, сильно поглощает воду.","При разбавлении кислоту вливают в воду, а не наоборот.","HCl содержится в желудочном соке и служит для очистки металлов.","HNO₃ применяют для получения азотных удобрений и хранят в темноте."]}],"quiz":[{"q":"Как правильно разбавлять серную кислоту?","options":["Быстро влить воду в кислоту","Влить обе жидкости одновременно","Медленно влить воду в кислоту","Медленно влить кислоту в воду"],"correct":3,"explain":"Кислоту вливают в воду, чтобы теплота распределялась в большом объёме воды."},{"q":"Какая кислота содержится в желудочном соке?","options":["HCl","H₂SO₄","HNO₃","H₃PO₄"],"correct":0,"explain":"Соляная кислота желудочного сока помогает переваривать пищу."},{"q":"Какую кислоту в основном используют для получения азотных удобрений?","options":["HCl","H₂CO₃","HNO₃","H₂S"],"correct":2,"explain":"Азотная кислота содержит азот, из неё получают азотные удобрения."}]}},{"id":"t46","num":46,"icon":"🧂","uz":{"title":"Tuzlar: tarkibi, tuzilishi va nomlanishi","intro":"Har kuni ovqatga solinadigan osh tuzi tuzlar katta oilasining faqat bitta vakili. Bo'r, marmar, mis kuporosi, ichimlik sodasi ham tuzlardir. Keling, ular nimadan tuzilganini va qanday nomlanishini bilib olamiz.","blocks":[{"h":"Tuz nima?","p":"Tuz – metall atomlari (yoki ammoniy NH₄ guruhi) va kislota qoldig'idan tashkil topgan murakkab modda. Tuzni kislotadagi vodorod o'rnini metall egallagan modda deb ham tasavvur qilish mumkin.","formula":"MₓAᵧ  (M – metall, A – kislota qoldig'i)","items":["HCl → NaCl (H o'rniga Na)","H₂SO₄ → CuSO₄ (2 ta H o'rniga bitta Cu(II))"]},{"h":"Tuzlarning tuzilishi","p":"Ko'pchilik tuzlar qattiq kristall moddalardir. Osh tuzi kristallida natriy va xlor zarrachalari kub panjara bo'ylab navbatma-navbat joylashgan: har bir natriyni oltita xlor, har bir xlorni oltita natriy o'rab turadi. Modelni aylantirib, bu tartibni ko'ring.","visual":{"type":"molecule3d","mol":"NaCl"}},{"h":"O'rta tuzlarni nomlash","p":"Tuz nomi metall nomi va kislota qoldig'i nomidan iborat. Agar metall o'zgaruvchan valentli bo'lsa, uning valentligi qavs ichida rim raqami bilan ko'rsatiladi.","table":{"head":["Formula","Nomi"],"rows":[["NaCl","natriy xlorid"],["K₂CO₃","kaliy karbonat"],["CaSO₄","kalsiy sulfat"],["FeCl₂","temir (II)-xlorid"],["FeCl₃","temir (III)-xlorid"],["NH₄NO₃","ammoniy nitrat"]]}},{"h":"Nordon va asosli tuzlar nomi","p":"Tuzda kislotaning vodorodi qisman qolgan bo'lsa, qoldiq nomiga «gidro» qo'shiladi. Tuzda asosning OH guruhi qolgan bo'lsa, «gidrokso» qo'shimchasi ishlatiladi.","items":["NaHCO₃ – natriy gidrokarbonat","KHSO₄ – kaliy gidrosulfat","Mg(OH)Cl – magniy gidroksoxlorid","Al(OH)SO₄ – aluminiy gidroksosulfat"]},{"h":"Namuna: Fe₂(SO₄)₃ ni nomlaymiz","items":["1) Qoldiq SO₄ – sulfat, valentligi II.","2) Qoldiqlar valentliklari yig'indisi: 3 · 2 = 6.","3) Temir atomlari 2 ta, demak har biri 6 : 2 = 3 valentli.","4) Nomi: temir (III)-sulfat."]},{"h":"Esda tuting","items":["Tuz = metall (yoki NH₄) + kislota qoldig'i.","Ko'p tuzlar kristall panjarali qattiq moddalar.","O'zgaruvchan valentli metall uchun valentlik rim raqamida yoziladi.","«Gidro» – nordon tuz, «gidrokso» – asosli tuz belgisi."]}],"quiz":[{"q":"K₂CO₃ qanday nomlanadi?","options":["kaliy karbid","kaliy karbonat","kaliy gidrokarbonat","kaliy sulfat"],"correct":1,"explain":"K – kaliy, CO₃ – karbonat qoldig'i."},{"q":"FeCl₃ ning to'g'ri nomi qaysi?","options":["temir xlorat","temir (II)-xlorid","temir (III)-xlorid","temir gidroksoxlorid"],"correct":2,"explain":"Uchta bir valentli Cl ga bitta Fe to'g'ri keladi, demak temir III valentli."},{"q":"Quyidagilardan qaysi biri tuz?","options":["CaCO₃","H₂CO₃","CaO","Ca(OH)₂"],"correct":0,"explain":"CaCO₃ metall va kislota qoldig'idan iborat."}]},"en":{"title":"Salts: composition, structure and naming","intro":"The table salt you add to food is just one member of the big family of salts. Chalk, marble, blue vitriol and baking soda are salts too. Let us find out what they are made of and how they are named.","blocks":[{"h":"What is a salt?","p":"A salt is a complex substance made of metal atoms (or the ammonium group NH₄) and an acid residue. You can picture a salt as an acid in which the hydrogen has been replaced by a metal.","formula":"MₓAᵧ  (M – metal, A – acid residue)","items":["HCl → NaCl (Na in place of H)","H₂SO₄ → CuSO₄ (one Cu(II) in place of 2 H)"]},{"h":"Structure of salts","p":"Most salts are solid crystalline substances. In a crystal of table salt, sodium and chlorine particles alternate along a cubic lattice: each sodium is surrounded by six chlorines and each chlorine by six sodiums. Rotate the model to see this order.","visual":{"type":"molecule3d","mol":"NaCl"}},{"h":"Naming normal salts","p":"The name of a salt consists of the metal name and the name of the acid residue. If the metal has variable valence, its valence is shown in brackets with a Roman numeral.","table":{"head":["Formula","Name"],"rows":[["NaCl","sodium chloride"],["K₂CO₃","potassium carbonate"],["CaSO₄","calcium sulfate"],["FeCl₂","iron(II) chloride"],["FeCl₃","iron(III) chloride"],["NH₄NO₃","ammonium nitrate"]]}},{"h":"Names of acid and basic salts","p":"If part of the acid's hydrogen remains in the salt, the word hydrogen is added before the residue name. If an OH group from the base remains, the prefix hydroxy- (hydroxide) is used.","items":["NaHCO₃ – sodium hydrogen carbonate","KHSO₄ – potassium hydrogen sulfate","Mg(OH)Cl – magnesium hydroxychloride","Al(OH)SO₄ – aluminium hydroxysulfate"]},{"h":"Example: naming Fe₂(SO₄)₃","items":["1) The SO₄ residue is sulfate, valence II.","2) Total valence of the residues: 3 · 2 = 6.","3) There are 2 iron atoms, so each has a valence of 6 : 2 = 3.","4) Name: iron(III) sulfate."]},{"h":"Remember","items":["Salt = metal (or NH₄) + acid residue.","Many salts are solids with a crystal lattice.","For a metal with variable valence, the valence is written as a Roman numeral.","Hydrogen in the name marks an acid salt, hydroxy marks a basic salt."]}],"quiz":[{"q":"What is the name of K₂CO₃?","options":["potassium carbide","potassium carbonate","potassium hydrogen carbonate","potassium sulfate"],"correct":1,"explain":"K is potassium and CO₃ is the carbonate residue."},{"q":"Which is the correct name of FeCl₃?","options":["iron chlorate","iron(II) chloride","iron(III) chloride","iron hydroxychloride"],"correct":2,"explain":"One Fe is combined with three monovalent Cl, so iron has a valence of three."},{"q":"Which of these is a salt?","options":["CaCO₃","H₂CO₃","CaO","Ca(OH)₂"],"correct":0,"explain":"CaCO₃ consists of a metal and an acid residue."}]},"ru":{"title":"Соли: состав, строение и названия","intro":"Поваренная соль, которую мы добавляем в еду, – лишь один представитель большого семейства солей. Мел, мрамор, медный купорос и питьевая сода – тоже соли. Узнаем, из чего они состоят и как называются.","blocks":[{"h":"Что такое соль?","p":"Соль – сложное вещество, состоящее из атомов металла (или группы аммония NH₄) и кислотного остатка. Соль можно представить как кислоту, в которой водород замещён металлом.","formula":"MₓAᵧ  (M – металл, A – кислотный остаток)","items":["HCl → NaCl (Na вместо H)","H₂SO₄ → CuSO₄ (один Cu(II) вместо двух H)"]},{"h":"Строение солей","p":"Большинство солей – твёрдые кристаллические вещества. В кристалле поваренной соли частицы натрия и хлора чередуются по кубической решётке: каждый натрий окружён шестью хлорами, а каждый хлор – шестью натриями. Поверните модель и рассмотрите этот порядок.","visual":{"type":"molecule3d","mol":"NaCl"}},{"h":"Названия средних солей","p":"Название соли состоит из названия кислотного остатка и названия металла в родительном падеже. Если валентность металла переменная, её указывают римской цифрой в скобках.","table":{"head":["Формула","Название"],"rows":[["NaCl","хлорид натрия"],["K₂CO₃","карбонат калия"],["CaSO₄","сульфат кальция"],["FeCl₂","хлорид железа(II)"],["FeCl₃","хлорид железа(III)"],["NH₄NO₃","нитрат аммония"]]}},{"h":"Названия кислых и основных солей","p":"Если в соли сохранилась часть водорода кислоты, к названию остатка добавляют приставку «гидро». Если сохранилась группа OH основания, используют приставку «гидроксо».","items":["NaHCO₃ – гидрокарбонат натрия","KHSO₄ – гидросульфат калия","Mg(OH)Cl – гидроксохлорид магния","Al(OH)SO₄ – гидроксосульфат алюминия"]},{"h":"Пример: называем Fe₂(SO₄)₃","items":["1) Остаток SO₄ – сульфат, валентность II.","2) Суммарная валентность остатков: 3 · 2 = 6.","3) Атомов железа 2, значит каждый из них трёхвалентен: 6 : 2 = 3.","4) Название: сульфат железа(III)."]},{"h":"Запомните","items":["Соль = металл (или NH₄) + кислотный остаток.","Многие соли – твёрдые вещества с кристаллической решёткой.","Переменную валентность металла указывают римской цифрой.","«Гидро» – признак кислой соли, «гидроксо» – основной."]}],"quiz":[{"q":"Как называется K₂CO₃?","options":["карбид калия","карбонат калия","гидрокарбонат калия","сульфат калия"],"correct":1,"explain":"K – калий, CO₃ – карбонатный остаток."},{"q":"Какое название FeCl₃ правильное?","options":["хлорат железа","хлорид железа(II)","хлорид железа(III)","гидроксохлорид железа"],"correct":2,"explain":"Одному Fe соответствуют три одновалентных Cl, значит железо трёхвалентно."},{"q":"Какое из веществ является солью?","options":["CaCO₃","H₂CO₃","CaO","Ca(OH)₂"],"correct":0,"explain":"CaCO₃ состоит из металла и кислотного остатка."}]}},{"id":"t47","num":47,"icon":"✍️","uz":{"title":"Tuz formulalarini tuzish va tuzlarning toifalanishi","intro":"Tuz nomini bilsangiz, uning formulasini bitta oddiy qoida yordamida yozib chiqishingiz mumkin. Bu darsda shu qoidani o'rganamiz va tuzlarni o'rta, nordon va asosli turlarga ajratamiz.","blocks":[{"h":"Asosiy qoida","p":"Tuzdagi metall atomlari soni bilan uning valentligi ko'paytmasi kislota qoldiqlari soni bilan qoldiq valentligi ko'paytmasiga teng bo'lishi kerak.","formula":"MₓAᵧ:  m · x = n · y  (m, n – valentliklar; x, y – indekslar)"},{"h":"Namuna: aluminiy sulfat","items":["1) Aluminiy III valentli, sulfat qoldig'i SO₄ II valentli.","2) 3 va 2 ning eng kichik umumiy karralisi 6.","3) Al atomlari soni: 6 : 3 = 2; SO₄ qoldiqlari soni: 6 : 2 = 3.","4) Formula: Al₂(SO₄)₃ (bir nechta murakkab qoldiq qavsga olinadi)."]},{"h":"Yana bir nechta misol","table":{"head":["Tuz","Valentliklar","Formula"],"rows":[["kalsiy fosfat","Ca (II), PO₄ (III)","Ca₃(PO₄)₂"],["natriy sulfat","Na (I), SO₄ (II)","Na₂SO₄"],["temir (III)-xlorid","Fe (III), Cl (I)","FeCl₃"],["magniy nitrat","Mg (II), NO₃ (I)","Mg(NO₃)₂"]]}},{"h":"Tuzlarning toifalanishi","p":"Tarkibiga ko'ra tuzlar uch asosiy turga bo'linadi. O'rta tuzda kislotaning barcha vodorodi metallga almashgan, nordon tuzda vodorodning bir qismi qolgan, asosli tuzda esa asosning OH guruhi to'liq almashinmagan.","table":{"head":["Turi","Tarkibi","Misollar"],"rows":[["O'rta","metall + qoldiq","Na₂SO₄, KNO₃, CaCO₃"],["Nordon","metall + H + qoldiq","NaHSO₄, Ca(HCO₃)₂"],["Asosli","metall + OH + qoldiq","Mg(OH)Cl, (CuOH)₂CO₃"]]}},{"h":"Qo'sh va kompleks tuzlar","p":"Ba'zi tuzlarda ikki xil metall bo'ladi, ular qo'sh tuzlar deyiladi, masalan achchiqtosh KAl(SO₄)₂. Yana murakkab tuzilishli kompleks tuzlar ham uchraydi, masalan K₄[Fe(CN)₆]."},{"h":"Esda tuting","items":["Formula qoidasi: m · x = n · y.","Indekslarni topish uchun valentliklarning eng kichik umumiy karralisidan foydalaniladi.","O'rta, nordon va asosli tuzlar farqlanadi.","Nordon tuzda H, asosli tuzda OH qoladi."]}],"quiz":[{"q":"Aluminiy sulfatning to'g'ri formulasi qaysi?","options":["AlSO₄","Al₃(SO₄)₂","Al₂SO₄","Al₂(SO₄)₃"],"correct":3,"explain":"2 · 3 = 3 · 2 = 6, valentliklar muvozanatlashgan."},{"q":"NaHCO₃ qaysi turdagi tuz?","options":["o'rta","nordon","asosli","qo'sh"],"correct":1,"explain":"Tarkibida kislotaning almashinmagan vodorodi bor."},{"q":"Mg(OH)Cl qaysi turdagi tuz?","options":["asosli","nordon","o'rta","kompleks"],"correct":0,"explain":"Tarkibida asosning OH guruhi saqlangan."}]},"en":{"title":"Writing salt formulas; classification of salts","intro":"If you know the name of a salt, you can write its formula with one simple rule. In this lesson we learn that rule and sort salts into normal, acid and basic salts.","blocks":[{"h":"The main rule","p":"The number of metal atoms multiplied by their valence must equal the number of acid residues multiplied by the residue's valence.","formula":"MₓAᵧ:  m · x = n · y  (m, n – valences; x, y – subscripts)"},{"h":"Example: aluminium sulfate","items":["1) Aluminium has valence III, the sulfate residue SO₄ has valence II.","2) The least common multiple of 3 and 2 is 6.","3) Number of Al atoms: 6 : 3 = 2; number of SO₄ residues: 6 : 2 = 3.","4) Formula: Al₂(SO₄)₃ (several complex residues are put in brackets)."]},{"h":"A few more examples","table":{"head":["Salt","Valences","Formula"],"rows":[["calcium phosphate","Ca (II), PO₄ (III)","Ca₃(PO₄)₂"],["sodium sulfate","Na (I), SO₄ (II)","Na₂SO₄"],["iron(III) chloride","Fe (III), Cl (I)","FeCl₃"],["magnesium nitrate","Mg (II), NO₃ (I)","Mg(NO₃)₂"]]}},{"h":"Classification of salts","p":"By composition salts are divided into three main types. In a normal salt all the hydrogen of the acid is replaced by a metal, in an acid salt part of the hydrogen remains, and in a basic salt the OH groups of the base are not fully replaced.","table":{"head":["Type","Composition","Examples"],"rows":[["Normal","metal + residue","Na₂SO₄, KNO₃, CaCO₃"],["Acid","metal + H + residue","NaHSO₄, Ca(HCO₃)₂"],["Basic","metal + OH + residue","Mg(OH)Cl, (CuOH)₂CO₃"]]}},{"h":"Double and complex salts","p":"Some salts contain two different metals; they are called double salts, for example potassium alum KAl(SO₄)₂. There are also complex salts with a more intricate structure, such as K₄[Fe(CN)₆]."},{"h":"Remember","items":["Formula rule: m · x = n · y.","Use the least common multiple of the valences to find the subscripts.","Salts are normal, acid or basic.","An acid salt keeps H, a basic salt keeps OH."]}],"quiz":[{"q":"Which is the correct formula of aluminium sulfate?","options":["AlSO₄","Al₃(SO₄)₂","Al₂SO₄","Al₂(SO₄)₃"],"correct":3,"explain":"2 · 3 = 3 · 2 = 6, so the valences are balanced."},{"q":"What type of salt is NaHCO₃?","options":["normal","acid","basic","double"],"correct":1,"explain":"It still contains unreplaced hydrogen from the acid."},{"q":"What type of salt is Mg(OH)Cl?","options":["basic","acid","normal","complex"],"correct":0,"explain":"It still contains an OH group from the base."}]},"ru":{"title":"Составление формул солей; классификация солей","intro":"Зная название соли, можно записать её формулу с помощью одного простого правила. На этом уроке мы изучим это правило и разделим соли на средние, кислые и основные.","blocks":[{"h":"Главное правило","p":"Произведение числа атомов металла на его валентность должно равняться произведению числа кислотных остатков на валентность остатка.","formula":"MₓAᵧ:  m · x = n · y  (m, n – валентности; x, y – индексы)"},{"h":"Пример: сульфат алюминия","items":["1) Алюминий трёхвалентен, сульфатный остаток SO₄ двухвалентен.","2) Наименьшее общее кратное чисел 3 и 2 равно 6.","3) Число атомов Al: 6 : 3 = 2; число остатков SO₄: 6 : 2 = 3.","4) Формула: Al₂(SO₄)₃ (несколько сложных остатков берут в скобки)."]},{"h":"Ещё несколько примеров","table":{"head":["Соль","Валентности","Формула"],"rows":[["фосфат кальция","Ca (II), PO₄ (III)","Ca₃(PO₄)₂"],["сульфат натрия","Na (I), SO₄ (II)","Na₂SO₄"],["хлорид железа(III)","Fe (III), Cl (I)","FeCl₃"],["нитрат магния","Mg (II), NO₃ (I)","Mg(NO₃)₂"]]}},{"h":"Классификация солей","p":"По составу соли делят на три основных типа. В средней соли весь водород кислоты замещён металлом, в кислой соли часть водорода сохранилась, а в основной соли группы OH основания замещены не полностью.","table":{"head":["Тип","Состав","Примеры"],"rows":[["Средние","металл + остаток","Na₂SO₄, KNO₃, CaCO₃"],["Кислые","металл + H + остаток","NaHSO₄, Ca(HCO₃)₂"],["Основные","металл + OH + остаток","Mg(OH)Cl, (CuOH)₂CO₃"]]}},{"h":"Двойные и комплексные соли","p":"Некоторые соли содержат два разных металла – это двойные соли, например алюмокалиевые квасцы KAl(SO₄)₂. Встречаются и комплексные соли более сложного строения, например K₄[Fe(CN)₆]."},{"h":"Запомните","items":["Правило формулы: m · x = n · y.","Индексы находят через наименьшее общее кратное валентностей.","Соли бывают средние, кислые и основные.","В кислой соли остаётся H, в основной – OH."]}],"quiz":[{"q":"Какая формула сульфата алюминия правильная?","options":["AlSO₄","Al₃(SO₄)₂","Al₂SO₄","Al₂(SO₄)₃"],"correct":3,"explain":"2 · 3 = 3 · 2 = 6, валентности уравновешены."},{"q":"К какому типу относится NaHCO₃?","options":["средняя","кислая","основная","двойная"],"correct":1,"explain":"В ней остался незамещённый водород кислоты."},{"q":"К какому типу относится Mg(OH)Cl?","options":["основная","кислая","средняя","комплексная"],"correct":0,"explain":"В ней сохранилась группа OH основания."}]}},{"id":"t48","num":48,"icon":"⚗️","uz":{"title":"Tuzlarning olinishi va xossalari","intro":"Tuz hosil bo'ladigan reaksiyalar shunchalik ko'pki, deyarli har qanday ikki sinf moddasidan tuz olish mumkin. Bu darsda eng muhim usullarni va tuzlarning o'zi qanday reaksiyalarga kirishishini o'rganamiz.","blocks":[{"h":"Oddiy moddalardan","p":"Eng sodda usul – metallni metallmas bilan biriktirish. Temir kukuni va oltingugurt aralashmasi qizdirilganda temir (II)-sulfid hosil bo'ladi. Animatsiyada atomlar qanday birlashishini kuzating.","formula":"Fe + S → FeS","visual":{"type":"reaction","id":"fe_s"}},{"h":"Murakkab moddalardan","p":"Tuzlar ko'pincha ikki murakkab modda yoki metall va murakkab modda o'rtasidagi reaksiyada hosil bo'ladi.","items":["metall + kislota: Zn + 2HCl → ZnCl₂ + H₂↑","asosli oksid + kislota: CaO + 2HCl → CaCl₂ + H₂O","asos + kislota: 2KOH + H₂SO₄ → K₂SO₄ + 2H₂O","asosli oksid + kislotali oksid: CaO + CO₂ → CaCO₃","ishqor + kislotali oksid: 2NaOH + CO₂ → Na₂CO₃ + H₂O","tuz + tuz: BaCl₂ + Na₂SO₄ → BaSO₄↓ + 2NaCl"]},{"h":"Fizik xossalari","p":"Tuzlar odatda kristall tuzilishli qattiq moddalar. Ularning rangi turlicha: osh tuzi oq, mis kuporosi CuSO₄·5H₂O ko'k, kaliy permanganat to'q binafsha. Suvda eruvchanligi ham har xil: NaCl yaxshi eriydi, CaCO₃ va BaSO₄ deyarli erimaydi. Ayrim tuzlar kristallarida suv molekulalari bo'ladi (kristallizatsion suv)."},{"h":"Kimyoviy xossalari","p":"Tuzlar ishtirokidagi almashinish reaksiyalari, odatda, cho'kma, gaz yoki suv hosil bo'lganda oxirigacha boradi. Faolroq metall kamroq faol metallni uning tuzi eritmasidan siqib chiqaradi.","items":["tuz + ishqor: CuSO₄ + 2NaOH → Cu(OH)₂↓ + Na₂SO₄","tuz + kislota: BaCl₂ + H₂SO₄ → BaSO₄↓ + 2HCl","tuz + tuz: AgNO₃ + NaCl → AgCl↓ + NaNO₃","tuz + metall: CuSO₄ + Fe → FeSO₄ + Cu","qizdirilganda: CaCO₃ → CaO + CO₂↑"]},{"h":"Namuna: reaksiya boradimi?","items":["1) Temir mix CuSO₄ eritmasiga botiriladi. Fe faollik qatorida Cu dan chapda → reaksiya boradi, mix qizg'ish mis bilan qoplanadi.","2) Mis plastinka ZnSO₄ eritmasiga botiriladi. Cu Zn dan o'ngda → reaksiya bormaydi.","3) NaCl va KNO₃ eritmalari aralashtiriladi. Cho'kma, gaz, suv hosil bo'lmaydi → reaksiya oxirigacha bormaydi."]},{"h":"Esda tuting","items":["Tuzlar oddiy moddalardan ham, murakkab moddalardan ham olinadi.","Tuzlar kristall, turli rangli va turli eruvchanlikka ega.","Almashinish reaksiyalari cho'kma, gaz yoki suv hosil bo'lsa boradi.","Faol metall kam faol metallni tuzidan siqib chiqaradi."]}],"quiz":[{"q":"Qaysi reaksiya boradi?","options":["Fe + CuSO₄","Cu + ZnSO₄","Ag + FeSO₄","Cu + MgCl₂"],"correct":0,"explain":"Temir misdan faolroq, shuning uchun misni tuzidan siqib chiqaradi."},{"q":"AgNO₃ va NaCl eritmalari aralashtirilganda qanday oq cho'kma tushadi?","options":["NaNO₃","AgNO₃","AgCl","NaCl"],"correct":2,"explain":"Kumush xlorid suvda deyarli erimaydi va oq cho'kma hosil qiladi."},{"q":"CaCO₃ qizdirilganda nima hosil bo'ladi?","options":["Ca + CO₂","CaO + CO₂","CaO + CO","Ca(OH)₂ + CO₂"],"correct":1,"explain":"Kalsiy karbonat kalsiy oksid va karbonat angidridga parchalanadi."}]},"en":{"title":"How salts are obtained, and their properties","intro":"There are so many salt-forming reactions that a salt can be made from almost any two classes of substances. In this lesson we learn the most important methods and the reactions that salts themselves take part in.","blocks":[{"h":"From simple substances","p":"The simplest method is to combine a metal with a non-metal. When a mixture of iron powder and sulfur is heated, iron(II) sulfide forms. Watch how the atoms join in the animation.","formula":"Fe + S → FeS","visual":{"type":"reaction","id":"fe_s"}},{"h":"From complex substances","p":"Salts often form in reactions between two complex substances or between a metal and a complex substance.","items":["metal + acid: Zn + 2HCl → ZnCl₂ + H₂↑","basic oxide + acid: CaO + 2HCl → CaCl₂ + H₂O","base + acid: 2KOH + H₂SO₄ → K₂SO₄ + 2H₂O","basic oxide + acidic oxide: CaO + CO₂ → CaCO₃","alkali + acidic oxide: 2NaOH + CO₂ → Na₂CO₃ + H₂O","salt + salt: BaCl₂ + Na₂SO₄ → BaSO₄↓ + 2NaCl"]},{"h":"Physical properties","p":"Salts are usually solids with a crystalline structure. Their colours vary: table salt is white, blue vitriol CuSO₄·5H₂O is blue and potassium permanganate is dark violet. Their solubility in water also differs: NaCl dissolves well, while CaCO₃ and BaSO₄ are practically insoluble. Some salt crystals contain water molecules (water of crystallisation)."},{"h":"Chemical properties","p":"Exchange reactions involving salts usually go to completion when a precipitate, a gas or water forms. A more active metal displaces a less active metal from a solution of its salt.","items":["salt + alkali: CuSO₄ + 2NaOH → Cu(OH)₂↓ + Na₂SO₄","salt + acid: BaCl₂ + H₂SO₄ → BaSO₄↓ + 2HCl","salt + salt: AgNO₃ + NaCl → AgCl↓ + NaNO₃","salt + metal: CuSO₄ + Fe → FeSO₄ + Cu","on heating: CaCO₃ → CaO + CO₂↑"]},{"h":"Example: will the reaction happen?","items":["1) An iron nail is dipped into CuSO₄ solution. Fe is to the left of Cu in the activity series → the reaction happens and the nail is coated with reddish copper.","2) A copper plate is dipped into ZnSO₄ solution. Cu is to the right of Zn → no reaction.","3) Solutions of NaCl and KNO₃ are mixed. No precipitate, gas or water forms → the reaction does not go to completion."]},{"h":"Remember","items":["Salts can be obtained from both simple and complex substances.","Salts are crystalline, have various colours and different solubility.","Exchange reactions proceed if a precipitate, a gas or water forms.","An active metal displaces a less active metal from its salt."]}],"quiz":[{"q":"Which reaction takes place?","options":["Fe + CuSO₄","Cu + ZnSO₄","Ag + FeSO₄","Cu + MgCl₂"],"correct":0,"explain":"Iron is more active than copper, so it displaces copper from its salt."},{"q":"Which white precipitate forms when AgNO₃ and NaCl solutions are mixed?","options":["NaNO₃","AgNO₃","AgCl","NaCl"],"correct":2,"explain":"Silver chloride is practically insoluble in water and forms a white precipitate."},{"q":"What forms when CaCO₃ is heated?","options":["Ca + CO₂","CaO + CO₂","CaO + CO","Ca(OH)₂ + CO₂"],"correct":1,"explain":"Calcium carbonate decomposes into calcium oxide and carbon dioxide."}]},"ru":{"title":"Получение и свойства солей","intro":"Реакций, в которых образуются соли, так много, что соль можно получить почти из любых двух классов веществ. На этом уроке изучим главные способы получения солей и реакции, в которые вступают сами соли.","blocks":[{"h":"Из простых веществ","p":"Самый простой способ – соединение металла с неметаллом. При нагревании смеси железного порошка и серы образуется сульфид железа(II). Посмотрите в анимации, как соединяются атомы.","formula":"Fe + S → FeS","visual":{"type":"reaction","id":"fe_s"}},{"h":"Из сложных веществ","p":"Соли часто образуются в реакциях между двумя сложными веществами или между металлом и сложным веществом.","items":["металл + кислота: Zn + 2HCl → ZnCl₂ + H₂↑","основный оксид + кислота: CaO + 2HCl → CaCl₂ + H₂O","основание + кислота: 2KOH + H₂SO₄ → K₂SO₄ + 2H₂O","основный оксид + кислотный оксид: CaO + CO₂ → CaCO₃","щёлочь + кислотный оксид: 2NaOH + CO₂ → Na₂CO₃ + H₂O","соль + соль: BaCl₂ + Na₂SO₄ → BaSO₄↓ + 2NaCl"]},{"h":"Физические свойства","p":"Соли обычно твёрдые вещества кристаллического строения. Их окраска различна: поваренная соль белая, медный купорос CuSO₄·5H₂O синий, перманганат калия тёмно-фиолетовый. Растворимость в воде тоже разная: NaCl хорошо растворяется, а CaCO₃ и BaSO₄ практически нерастворимы. Кристаллы некоторых солей содержат молекулы воды (кристаллизационная вода)."},{"h":"Химические свойства","p":"Реакции обмена с участием солей обычно идут до конца, если образуется осадок, газ или вода. Более активный металл вытесняет менее активный из раствора его соли.","items":["соль + щёлочь: CuSO₄ + 2NaOH → Cu(OH)₂↓ + Na₂SO₄","соль + кислота: BaCl₂ + H₂SO₄ → BaSO₄↓ + 2HCl","соль + соль: AgNO₃ + NaCl → AgCl↓ + NaNO₃","соль + металл: CuSO₄ + Fe → FeSO₄ + Cu","при нагревании: CaCO₃ → CaO + CO₂↑"]},{"h":"Пример: пойдёт ли реакция?","items":["1) Железный гвоздь опускают в раствор CuSO₄. Fe стоит в ряду активности левее Cu → реакция идёт, гвоздь покрывается красноватой медью.","2) Медную пластинку опускают в раствор ZnSO₄. Cu правее Zn → реакции нет.","3) Смешивают растворы NaCl и KNO₃. Ни осадка, ни газа, ни воды → реакция до конца не идёт."]},{"h":"Запомните","items":["Соли получают как из простых, так и из сложных веществ.","Соли кристалличны, имеют разную окраску и растворимость.","Реакции обмена идут, если образуется осадок, газ или вода.","Активный металл вытесняет менее активный из его соли."]}],"quiz":[{"q":"Какая реакция протекает?","options":["Fe + CuSO₄","Cu + ZnSO₄","Ag + FeSO₄","Cu + MgCl₂"],"correct":0,"explain":"Железо активнее меди, поэтому вытесняет её из соли."},{"q":"Какой белый осадок образуется при смешивании растворов AgNO₃ и NaCl?","options":["NaNO₃","AgNO₃","AgCl","NaCl"],"correct":2,"explain":"Хлорид серебра практически нерастворим в воде и выпадает белым осадком."},{"q":"Что образуется при нагревании CaCO₃?","options":["Ca + CO₂","CaO + CO₂","CaO + CO","Ca(OH)₂ + CO₂"],"correct":1,"explain":"Карбонат кальция разлагается на оксид кальция и углекислый газ."}]}},{"id":"t49","num":49,"icon":"🌾","uz":{"title":"Eng muhim tuzlarning ishlatilishi","intro":"Tuzlar bizni har tomondan o'rab turadi: oshxonada, dalada, qurilishda va hatto organizmimizda. Ular tabiatda eng ko'p tarqalgan va xo'jalikda eng ko'p ishlatiladigan anorganik moddalardan hisoblanadi.","blocks":[{"h":"Tuzlar va inson organizmi","p":"Organizmda natriy, kaliy, kalsiy va boshqa elementlarning tuzlari doimo muayyan miqdorda bo'lishi kerak. Kalsiy tuzlari suyak va tishlarni mustahkamlaydi. Organizm ko'p suyuqlik yo'qotganda tibbiyotda 0,9% li osh tuzi eritmasi – fiziologik eritma ishlatiladi."},{"h":"Natriy xlorid – NaCl","p":"Osh tuzi oziq-ovqatga ta'm berish va mahsulotlarni konservalashda ishlatiladi. Kimyo sanoatida undan xlor, natriy gidroksid va metall natriy olinadi. O'zbekistonda osh tuzining yirik tabiiy konlari mavjud."},{"h":"Kalsiy karbonat – CaCO₃","p":"Bo'r, ohaktosh va marmar tarkibi jihatidan bir xil modda – kalsiy karbonatdir. Ohaktoshdan so'ndirilmagan ohak va sement olinadi, marmar binolarni bezashda ishlatiladi. Bo'r esa maktab doskasida yozish uchun xizmat qiladi."},{"h":"Tuzlar – o'g'itlar","p":"O'simliklarga azot, fosfor va kaliy zarur, ular tuzlar shaklida tuproqqa beriladi. Respublikamizdagi kimyo korxonalarida azotli va fosforli o'g'itlar ishlab chiqariladi.","items":["NH₄NO₃ – ammiakli selitra (azotli o'g'it)","KCl – kaliyli o'g'it","Ca(H₂PO₄)₂ – fosforli o'g'it (superfosfat tarkibida)"]},{"h":"Tuzlarning texnik nomlari","table":{"head":["Texnik nomi","Formula","Kimyoviy nomi"],"rows":[["osh tuzi","NaCl","natriy xlorid"],["ichimlik sodasi","NaHCO₃","natriy gidrokarbonat"],["kalsinatsiyalangan soda","Na₂CO₃","natriy karbonat"],["potash","K₂CO₃","kaliy karbonat"],["mis kuporosi","CuSO₄·5H₂O","mis (II)-sulfat kristallogidrati"],["marmar, bo'r","CaCO₃","kalsiy karbonat"]]}},{"h":"Esda tuting","items":["0,9% li NaCl eritmasi fiziologik eritma deyiladi.","NaCl dan xlor, ishqor va natriy olinadi.","CaCO₃ – bo'r, ohaktosh, marmar; qurilishda ishlatiladi.","NH₄NO₃, KCl va fosfatlar o'g'it sifatida qo'llanadi."]}],"quiz":[{"q":"Ichimlik sodasining formulasi qaysi?","options":["Na₂CO₃","NaCl","NaHCO₃","K₂CO₃"],"correct":2,"explain":"Ichimlik sodasi – natriy gidrokarbonat NaHCO₃."},{"q":"Fiziologik eritmada osh tuzining massa ulushi qancha?","options":["0,9%","9%","0,09%","90%"],"correct":0,"explain":"Tibbiyotda 0,9% li NaCl eritmasi ishlatiladi."},{"q":"Ammiakli selitra NH₄NO₃ asosan qayerda ishlatiladi?","options":["qurilishda","oziq-ovqatda","shisha olishda","qishloq xo'jaligida o'g'it sifatida"],"correct":3,"explain":"U tarkibida azot ko'p bo'lgan o'g'itdir."}]},"en":{"title":"Uses of the most important salts","intro":"Salts surround us everywhere: in the kitchen, in the field, on building sites and even inside our bodies. They are among the most widespread inorganic substances in nature and the most widely used in the economy.","blocks":[{"h":"Salts and the human body","p":"The body must always contain certain amounts of salts of sodium, potassium, calcium and other elements. Calcium salts make bones and teeth strong. When the body loses a lot of fluid, doctors use a 0.9% sodium chloride solution called physiological saline."},{"h":"Sodium chloride – NaCl","p":"Table salt is used to flavour food and to preserve products. In the chemical industry chlorine, sodium hydroxide and sodium metal are obtained from it. Uzbekistan has large natural deposits of rock salt."},{"h":"Calcium carbonate – CaCO₃","p":"Chalk, limestone and marble all have the same composition: calcium carbonate. Limestone is used to make quicklime and cement, and marble is used to decorate buildings. Chalk is used for writing on school boards."},{"h":"Salts as fertilisers","p":"Plants need nitrogen, phosphorus and potassium, and these are added to the soil in the form of salts. Chemical plants in Uzbekistan produce nitrogen and phosphorus fertilisers.","items":["NH₄NO₃ – ammonium nitrate (nitrogen fertiliser)","KCl – potassium fertiliser","Ca(H₂PO₄)₂ – phosphorus fertiliser (in superphosphate)"]},{"h":"Common names of salts","table":{"head":["Common name","Formula","Chemical name"],"rows":[["table salt","NaCl","sodium chloride"],["baking soda","NaHCO₃","sodium hydrogen carbonate"],["soda ash","Na₂CO₃","sodium carbonate"],["potash","K₂CO₃","potassium carbonate"],["blue vitriol","CuSO₄·5H₂O","copper(II) sulfate pentahydrate"],["marble, chalk","CaCO₃","calcium carbonate"]]}},{"h":"Remember","items":["A 0.9% NaCl solution is called physiological saline.","Chlorine, alkali and sodium are obtained from NaCl.","CaCO₃ is chalk, limestone and marble; it is used in construction.","NH₄NO₃, KCl and phosphates are used as fertilisers."]}],"quiz":[{"q":"What is the formula of baking soda?","options":["Na₂CO₃","NaCl","NaHCO₃","K₂CO₃"],"correct":2,"explain":"Baking soda is sodium hydrogen carbonate NaHCO₃."},{"q":"What is the mass fraction of table salt in physiological saline?","options":["0.9%","9%","0.09%","90%"],"correct":0,"explain":"Medicine uses a 0.9% NaCl solution."},{"q":"What is ammonium nitrate NH₄NO₃ mainly used for?","options":["construction","food","making glass","as a fertiliser in agriculture"],"correct":3,"explain":"It is a fertiliser rich in nitrogen."}]},"ru":{"title":"Применение важнейших солей","intro":"Соли окружают нас повсюду: на кухне, в поле, на стройке и даже в нашем организме. Это одни из самых распространённых в природе и самых используемых в хозяйстве неорганических веществ.","blocks":[{"h":"Соли и организм человека","p":"В организме всегда должно содержаться определённое количество солей натрия, калия, кальция и других элементов. Соли кальция делают прочными кости и зубы. При большой потере жидкости в медицине используют 0,9%-ный раствор хлорида натрия – физиологический раствор."},{"h":"Хлорид натрия – NaCl","p":"Поваренную соль используют для придания вкуса пище и для консервирования продуктов. В химической промышленности из неё получают хлор, гидроксид натрия и металлический натрий. В Узбекистане есть крупные природные месторождения поваренной соли."},{"h":"Карбонат кальция – CaCO₃","p":"Мел, известняк и мрамор имеют одинаковый состав – это карбонат кальция. Из известняка получают негашёную известь и цемент, мрамором украшают здания. Мелом пишут на школьной доске."},{"h":"Соли – удобрения","p":"Растениям нужны азот, фосфор и калий, их вносят в почву в виде солей. Химические предприятия Узбекистана выпускают азотные и фосфорные удобрения.","items":["NH₄NO₃ – аммиачная селитра (азотное удобрение)","KCl – калийное удобрение","Ca(H₂PO₄)₂ – фосфорное удобрение (в составе суперфосфата)"]},{"h":"Технические названия солей","table":{"head":["Техническое название","Формула","Химическое название"],"rows":[["поваренная соль","NaCl","хлорид натрия"],["питьевая сода","NaHCO₃","гидрокарбонат натрия"],["кальцинированная сода","Na₂CO₃","карбонат натрия"],["поташ","K₂CO₃","карбонат калия"],["медный купорос","CuSO₄·5H₂O","пентагидрат сульфата меди(II)"],["мрамор, мел","CaCO₃","карбонат кальция"]]}},{"h":"Запомните","items":["0,9%-ный раствор NaCl называют физиологическим раствором.","Из NaCl получают хлор, щёлочь и натрий.","CaCO₃ – это мел, известняк и мрамор; применяется в строительстве.","NH₄NO₃, KCl и фосфаты используют как удобрения."]}],"quiz":[{"q":"Какова формула питьевой соды?","options":["Na₂CO₃","NaCl","NaHCO₃","K₂CO₃"],"correct":2,"explain":"Питьевая сода – гидрокарбонат натрия NaHCO₃."},{"q":"Какова массовая доля поваренной соли в физиологическом растворе?","options":["0,9%","9%","0,09%","90%"],"correct":0,"explain":"В медицине используют 0,9%-ный раствор NaCl."},{"q":"Где в основном применяют аммиачную селитру NH₄NO₃?","options":["в строительстве","в пищевой промышленности","для получения стекла","в сельском хозяйстве как удобрение"],"correct":3,"explain":"Это удобрение с высоким содержанием азота."}]}},{"id":"t50","num":50,"icon":"⚖️","uz":{"title":"Ekvivalentlik qonuni","intro":"Moddalar reaksiyaga qanday nisbatda kirishishini oldindan bilish mumkinmi? Ha – buning uchun ekvivalent tushunchasi bor. «Ekvivalent» so'zi «teng qiymatli» degan ma'noni bildiradi.","blocks":[{"h":"Ekvivalent nima?","p":"Elementning ekvivalenti – uning 1 g vodorod (1 mol H atomi) bilan qoldiqsiz birikadigan yoki reaksiyada shuncha vodorod o'rnini oladigan miqdori. Bir ekvivalent massasi ekvivalent massa (E) deyiladi va g/mol da ifodalanadi. Taqqoslash uchun asos: E(H) = 1, E(O) = 8.","formula":"E(O) = 16 : 2 = 8 g/mol"},{"h":"Elementning ekvivalenti","p":"Element ekvivalentini topish uchun uning nisbiy atom massasi valentligiga bo'linadi. Valentligi o'zgaruvchan elementning ekvivalenti ham o'zgaradi.","formula":"E = Ar : V","items":["Al: 27 : 3 = 9","Ca: 40 : 2 = 20","Cu (I): 64 : 1 = 64; Cu (II): 64 : 2 = 32"]},{"h":"Murakkab moddalarning ekvivalenti","p":"Murakkab moddaning molar massasini hisoblab (kalkulyatordan foydalaning), uni tegishli songa bo'lamiz.","table":{"head":["Sinf","Formula","Misol"],"rows":[["Oksid","Mr : (atomlar soni · valentlik)","CuO: 80 : 2 = 40"],["Asos","Mr : OH soni","Cu(OH)₂: 98 : 2 = 49"],["Kislota","Mr : H soni","H₂SO₄: 98 : 2 = 49"],["Tuz","Mr : (metall atomlari soni · valentlik)","CuCl₂: 135 : 2 = 67,5"]]},"visual":{"type":"calc","kind":"molar"}},{"h":"Ekvivalentlik qonuni","p":"Moddalar bir-biri bilan o'z ekvivalentlariga proporsional massalarda reaksiyaga kirishadi. Gazlar uchun ekvivalent hajm ishlatiladi: normal sharoitda 1 ekvivalent vodorod 11,2 L, 1 ekvivalent kislorod 5,6 L hajm egallaydi.","formula":"m(A) : m(B) = E(A) : E(B)"},{"h":"Namuna: metallning ekvivalenti","p":"0,6 g ikki valentli metall kislotadan 0,05 g vodorod siqib chiqardi. Metallning ekvivalenti va atom massasini topamiz.","items":["1) Qonun: m(Me) : m(H₂) = E(Me) : E(H).","2) 0,6 : 0,05 = E(Me) : 1.","3) E(Me) = 0,6 · 1 : 0,05 = 12 g/mol.","4) Ar = E · V = 12 · 2 = 24 → bu magniy."]},{"h":"Esda tuting","items":["E(H) = 1, E(O) = 8.","Element uchun E = Ar : V.","Moddalar ekvivalentlariga proporsional massalarda reaksiyaga kirishadi.","Ekvivalent hajmlar: H₂ – 11,2 L, O₂ – 5,6 L."]}],"quiz":[{"q":"Kislorodning ekvivalent massasi nechaga teng?","options":["8 g/mol","16 g/mol","1 g/mol","32 g/mol"],"correct":0,"explain":"Kislorod ikki valentli: 16 : 2 = 8."},{"q":"Aluminiyning (Ar = 27, valentlik III) ekvivalenti qancha?","options":["27","13,5","3","9"],"correct":3,"explain":"E = 27 : 3 = 9."},{"q":"H₂SO₄ ning ekvivalent massasi qancha?","options":["98","49","32,7","24,5"],"correct":1,"explain":"Mr = 98, vodorodlar soni 2: 98 : 2 = 49."}]},"en":{"title":"Law of equivalents","intro":"Can we know in advance in what ratio substances will react? Yes – that is what the idea of an equivalent is for. The word equivalent means of equal value.","blocks":[{"h":"What is an equivalent?","p":"The equivalent of an element is the amount of it that combines without remainder with 1 g of hydrogen (1 mol of H atoms) or replaces that much hydrogen in a reaction. The mass of one equivalent is called the equivalent mass (E), expressed in g/mol. Reference values: E(H) = 1, E(O) = 8.","formula":"E(O) = 16 : 2 = 8 g/mol"},{"h":"Equivalent of an element","p":"To find the equivalent of an element, divide its relative atomic mass by its valence. If the valence changes, the equivalent changes too.","formula":"E = Ar : V","items":["Al: 27 : 3 = 9","Ca: 40 : 2 = 20","Cu (I): 64 : 1 = 64; Cu (II): 64 : 2 = 32"]},{"h":"Equivalents of compounds","p":"Calculate the molar mass of the compound (use the calculator) and divide it by the appropriate number.","table":{"head":["Class","Rule","Example"],"rows":[["Oxide","Mr : (number of atoms · valence)","CuO: 80 : 2 = 40"],["Base","Mr : number of OH","Cu(OH)₂: 98 : 2 = 49"],["Acid","Mr : number of H","H₂SO₄: 98 : 2 = 49"],["Salt","Mr : (number of metal atoms · valence)","CuCl₂: 135 : 2 = 67.5"]]},"visual":{"type":"calc","kind":"molar"}},{"h":"The law of equivalents","p":"Substances react with each other in masses proportional to their equivalents. For gases the equivalent volume is used: at normal conditions 1 equivalent of hydrogen occupies 11.2 L and 1 equivalent of oxygen occupies 5.6 L.","formula":"m(A) : m(B) = E(A) : E(B)"},{"h":"Example: equivalent of a metal","p":"0.6 g of a divalent metal displaced 0.05 g of hydrogen from an acid. Find the equivalent and the atomic mass of the metal.","items":["1) Law: m(Me) : m(H₂) = E(Me) : E(H).","2) 0.6 : 0.05 = E(Me) : 1.","3) E(Me) = 0.6 · 1 : 0.05 = 12 g/mol.","4) Ar = E · V = 12 · 2 = 24 → the metal is magnesium."]},{"h":"Remember","items":["E(H) = 1, E(O) = 8.","For an element E = Ar : V.","Substances react in masses proportional to their equivalents.","Equivalent volumes: H₂ – 11.2 L, O₂ – 5.6 L."]}],"quiz":[{"q":"What is the equivalent mass of oxygen?","options":["8 g/mol","16 g/mol","1 g/mol","32 g/mol"],"correct":0,"explain":"Oxygen is divalent: 16 : 2 = 8."},{"q":"What is the equivalent of aluminium (Ar = 27, valence III)?","options":["27","13.5","3","9"],"correct":3,"explain":"E = 27 : 3 = 9."},{"q":"What is the equivalent mass of H₂SO₄?","options":["98","49","32.7","24.5"],"correct":1,"explain":"Mr = 98 and there are 2 hydrogens: 98 : 2 = 49."}]},"ru":{"title":"Закон эквивалентов","intro":"Можно ли заранее узнать, в каком соотношении вещества вступят в реакцию? Да – для этого существует понятие эквивалента. Слово «эквивалент» означает «равноценный».","blocks":[{"h":"Что такое эквивалент?","p":"Эквивалент элемента – такое его количество, которое без остатка соединяется с 1 г водорода (1 моль атомов H) или замещает столько же водорода в реакции. Масса одного эквивалента называется эквивалентной массой (E) и выражается в г/моль. Опорные значения: E(H) = 1, E(O) = 8.","formula":"E(O) = 16 : 2 = 8 г/моль"},{"h":"Эквивалент элемента","p":"Чтобы найти эквивалент элемента, его относительную атомную массу делят на валентность. Если валентность меняется, меняется и эквивалент.","formula":"E = Ar : V","items":["Al: 27 : 3 = 9","Ca: 40 : 2 = 20","Cu (I): 64 : 1 = 64; Cu (II): 64 : 2 = 32"]},{"h":"Эквиваленты сложных веществ","p":"Вычислите молярную массу вещества (воспользуйтесь калькулятором) и разделите её на соответствующее число.","table":{"head":["Класс","Правило","Пример"],"rows":[["Оксид","Mr : (число атомов · валентность)","CuO: 80 : 2 = 40"],["Основание","Mr : число OH","Cu(OH)₂: 98 : 2 = 49"],["Кислота","Mr : число H","H₂SO₄: 98 : 2 = 49"],["Соль","Mr : (число атомов металла · валентность)","CuCl₂: 135 : 2 = 67,5"]]},"visual":{"type":"calc","kind":"molar"}},{"h":"Закон эквивалентов","p":"Вещества реагируют друг с другом в массах, пропорциональных их эквивалентам. Для газов используют эквивалентный объём: при нормальных условиях 1 эквивалент водорода занимает 11,2 л, 1 эквивалент кислорода – 5,6 л.","formula":"m(A) : m(B) = E(A) : E(B)"},{"h":"Пример: эквивалент металла","p":"0,6 г двухвалентного металла вытеснили из кислоты 0,05 г водорода. Найдём эквивалент и атомную массу металла.","items":["1) Закон: m(Me) : m(H₂) = E(Me) : E(H).","2) 0,6 : 0,05 = E(Me) : 1.","3) E(Me) = 0,6 · 1 : 0,05 = 12 г/моль.","4) Ar = E · V = 12 · 2 = 24 → это магний."]},{"h":"Запомните","items":["E(H) = 1, E(O) = 8.","Для элемента E = Ar : V.","Вещества реагируют в массах, пропорциональных их эквивалентам.","Эквивалентные объёмы: H₂ – 11,2 л, O₂ – 5,6 л."]}],"quiz":[{"q":"Чему равна эквивалентная масса кислорода?","options":["8 г/моль","16 г/моль","1 г/моль","32 г/моль"],"correct":0,"explain":"Кислород двухвалентен: 16 : 2 = 8."},{"q":"Чему равен эквивалент алюминия (Ar = 27, валентность III)?","options":["27","13,5","3","9"],"correct":3,"explain":"E = 27 : 3 = 9."},{"q":"Чему равна эквивалентная масса H₂SO₄?","options":["98","49","32,7","24,5"],"correct":1,"explain":"Mr = 98, атомов водорода 2: 98 : 2 = 49."}]}}]},{"title":{"uz":"6-bob. Moddalar sinflari orasidagi genetik bog'lanish","en":"Chapter 6. Genetic links between classes of substances","ru":"Глава 6. Генетическая связь между классами веществ"},"topics":[{"id":"t51","num":51,"icon":"🔗","uz":{"title":"Oksid, asos, kislota va tuzlar orasidagi genetik bog'lanish","intro":"Biz o'rgangan moddalar sinflari bir-biridan ajralgan emas – ular bitta katta «oila daraxti»ni tashkil qiladi. Metalldan tuzgacha, metallmasdan tuzgacha zanjir bo'ylab yurib, bir moddani boshqasiga aylantirish mumkin.","blocks":[{"h":"Genetik bog'lanish nima?","p":"Bir sinf moddasidan boshqa sinf moddasini olish mumkinligi genetik bog'lanish deyiladi. Metall asosli oksid va asosga, metallmas kislotali oksid va kislotaga aylanadi, ikki zanjir esa tuzda uchrashadi. Sxemada strelkalar bo'ylab yurib chiqing.","visual":{"type":"diagram","kind":"genetic"}},{"h":"Metall qatori: kalsiy","items":["2Ca + O₂ → 2CaO (metall → asosli oksid)","CaO + H₂O → Ca(OH)₂ (asosli oksid → asos)","Ca(OH)₂ + 2HCl → CaCl₂ + 2H₂O (asos → tuz)"]},{"h":"Metallmas qatori: uglerod","items":["C + O₂ → CO₂ (metallmas → kislotali oksid)","CO₂ + H₂O → H₂CO₃ (kislotali oksid → kislota)","H₂CO₃ + 2NaOH → Na₂CO₃ + 2H₂O (kislota → tuz)"]},{"h":"Ikki qator uchrashganda va teskari o'tishlar","p":"Asosli va kislotali qatorlar moddalari o'zaro reaksiyaga kirishib, tuz hosil qiladi. Ba'zi o'tishlarni teskari yo'nalishda ham amalga oshirish mumkin.","items":["CaO + CO₂ → CaCO₃","Ca(OH)₂ + CO₂ → CaCO₃↓ + H₂O","qizdirish: CaCO₃ → CaO + CO₂","qizdirish: Cu(OH)₂ → CuO + H₂O"]},{"h":"Amaliy mashg'ulot: tajribaviy masalalar","p":"Bilimlarni umumlashtirish uchun quyidagi masalalarni tajribada yeching, xavfsizlik qoidalariga rioya qiling.","items":["1) Temir va mis qirindilari aralashmasiga xlorid kislota qo'shing: temir eriydi (Fe + 2HCl → FeCl₂ + H₂↑), mis qoladi, uni filtrlab ajrating.","2) Qora kukun toza CuO ekanini tekshirish: uni suyultirilgan H₂SO₄ da isitib eriting; toza oksid butunlay erib, ko'k eritma beradi, erimagan qoldiq qo'shimcha borligini bildiradi.","3) Uchta raqamlangan probirkada NaCl, H₂SO₄ va NaOH eritmalari: lakmus kislotada qizil, ishqorda ko'k bo'ladi, NaCl da rang o'zgarmaydi.","4) O'zgarishlar zanjirini bajaring: CuO → CuSO₄ → Cu(OH)₂ → CuO va tenglamalarini yozing."]},{"h":"Esda tuting","items":["Metall → asosli oksid → asos → tuz.","Metallmas → kislotali oksid → kislota → tuz.","Ikki qator tuzda uchrashadi.","Genetik bog'lanish yordamida kerakli moddani rejali olish mumkin."]}],"quiz":[{"q":"Asosli oksid suv bilan reaksiyaga kirishsa, qaysi sinf moddasi hosil bo'ladi?","options":["kislota","asos","tuz","oksid"],"correct":1,"explain":"Masalan, CaO + H₂O → Ca(OH)₂ – asos."},{"q":"Temir va mis qirindilari aralashmasidan misni kimyoviy usulda qanday ajratish mumkin?","options":["Magnit bilan","Suvda eritib","Xlorid kislota qo'shib, so'ng filtrlab","Qizdirib"],"correct":2,"explain":"Temir xlorid kislotada eriydi, mis esa erimay qoladi."},{"q":"Lakmus NaOH eritmasida qanday rangga kiradi?","options":["ko'k","qizil","binafsha","rangsiz"],"correct":0,"explain":"Ishqoriy muhitda lakmus ko'k rangga kiradi."}]},"en":{"title":"The genetic relationship between oxides, bases, acids and salts","intro":"The classes of substances we have studied are not isolated from one another; they form one big family tree. By moving along a chain from a metal or a non-metal to a salt, one substance can be turned into another.","blocks":[{"h":"What is a genetic relationship?","p":"The possibility of obtaining a substance of one class from a substance of another class is called a genetic relationship. A metal turns into a basic oxide and a base, a non-metal into an acidic oxide and an acid, and the two chains meet at a salt. Follow the arrows in the diagram.","visual":{"type":"diagram","kind":"genetic"}},{"h":"Metal chain: calcium","items":["2Ca + O₂ → 2CaO (metal → basic oxide)","CaO + H₂O → Ca(OH)₂ (basic oxide → base)","Ca(OH)₂ + 2HCl → CaCl₂ + 2H₂O (base → salt)"]},{"h":"Non-metal chain: carbon","items":["C + O₂ → CO₂ (non-metal → acidic oxide)","CO₂ + H₂O → H₂CO₃ (acidic oxide → acid)","H₂CO₃ + 2NaOH → Na₂CO₃ + 2H₂O (acid → salt)"]},{"h":"Where the chains meet, and reverse steps","p":"Substances from the basic and acidic chains react with each other to form salts. Some steps can also be carried out in the reverse direction.","items":["CaO + CO₂ → CaCO₃","Ca(OH)₂ + CO₂ → CaCO₃↓ + H₂O","heating: CaCO₃ → CaO + CO₂","heating: Cu(OH)₂ → CuO + H₂O"]},{"h":"Practical work: experimental problems","p":"To pull your knowledge together, solve these problems by experiment, following the safety rules.","items":["1) Add hydrochloric acid to a mixture of iron and copper filings: iron dissolves (Fe + 2HCl → FeCl₂ + H₂↑), copper remains and is separated by filtering.","2) To check that a black powder is pure CuO, warm it in dilute H₂SO₄: pure oxide dissolves completely giving a blue solution, while an undissolved residue shows an impurity.","3) Three numbered test tubes contain NaCl, H₂SO₄ and NaOH solutions: litmus turns red in the acid, blue in the alkali and does not change in NaCl.","4) Carry out the chain CuO → CuSO₄ → Cu(OH)₂ → CuO and write the equations."]},{"h":"Remember","items":["Metal → basic oxide → base → salt.","Non-metal → acidic oxide → acid → salt.","The two chains meet at a salt.","The genetic relationship lets you plan how to obtain a required substance."]}],"quiz":[{"q":"Which class of substance forms when a basic oxide reacts with water?","options":["acid","base","salt","oxide"],"correct":1,"explain":"For example, CaO + H₂O → Ca(OH)₂, a base."},{"q":"How can copper be separated chemically from a mixture of iron and copper filings?","options":["With a magnet","By dissolving in water","By adding hydrochloric acid, then filtering","By heating"],"correct":2,"explain":"Iron dissolves in hydrochloric acid while copper does not."},{"q":"What colour does litmus turn in NaOH solution?","options":["blue","red","violet","colourless"],"correct":0,"explain":"In an alkaline medium litmus turns blue."}]},"ru":{"title":"Генетическая связь между оксидами, основаниями, кислотами и солями","intro":"Изученные нами классы веществ не оторваны друг от друга – они образуют одно большое родословное древо. Двигаясь по цепочке от металла или неметалла к соли, можно превращать одно вещество в другое.","blocks":[{"h":"Что такое генетическая связь?","p":"Возможность получить вещество одного класса из вещества другого класса называется генетической связью. Металл превращается в основный оксид и основание, неметалл – в кислотный оксид и кислоту, а обе цепочки сходятся на соли. Пройдите по стрелкам схемы.","visual":{"type":"diagram","kind":"genetic"}},{"h":"Цепочка металла: кальций","items":["2Ca + O₂ → 2CaO (металл → основный оксид)","CaO + H₂O → Ca(OH)₂ (основный оксид → основание)","Ca(OH)₂ + 2HCl → CaCl₂ + 2H₂O (основание → соль)"]},{"h":"Цепочка неметалла: углерод","items":["C + O₂ → CO₂ (неметалл → кислотный оксид)","CO₂ + H₂O → H₂CO₃ (кислотный оксид → кислота)","H₂CO₃ + 2NaOH → Na₂CO₃ + 2H₂O (кислота → соль)"]},{"h":"Где цепочки встречаются, и обратные переходы","p":"Вещества основной и кислотной цепочек реагируют друг с другом, образуя соли. Некоторые переходы можно осуществить и в обратном направлении.","items":["CaO + CO₂ → CaCO₃","Ca(OH)₂ + CO₂ → CaCO₃↓ + H₂O","нагревание: CaCO₃ → CaO + CO₂","нагревание: Cu(OH)₂ → CuO + H₂O"]},{"h":"Практическое занятие: экспериментальные задачи","p":"Чтобы обобщить знания, решите опытным путём следующие задачи, соблюдая правила безопасности.","items":["1) К смеси железных и медных опилок добавьте соляную кислоту: железо растворяется (Fe + 2HCl → FeCl₂ + H₂↑), медь остаётся, её отделяют фильтрованием.","2) Чтобы проверить, чистый ли чёрный порошок CuO, нагрейте его с разбавленной H₂SO₄: чистый оксид растворяется полностью с образованием голубого раствора, нерастворившийся остаток указывает на примесь.","3) В трёх пронумерованных пробирках растворы NaCl, H₂SO₄ и NaOH: лакмус в кислоте краснеет, в щёлочи синеет, в растворе NaCl не меняет цвет.","4) Осуществите цепочку CuO → CuSO₄ → Cu(OH)₂ → CuO и запишите уравнения."]},{"h":"Запомните","items":["Металл → основный оксид → основание → соль.","Неметалл → кислотный оксид → кислота → соль.","Обе цепочки сходятся на соли.","Генетическая связь позволяет спланировать получение нужного вещества."]}],"quiz":[{"q":"Вещество какого класса образуется при реакции основного оксида с водой?","options":["кислота","основание","соль","оксид"],"correct":1,"explain":"Например, CaO + H₂O → Ca(OH)₂ – основание."},{"q":"Как химическим способом отделить медь от смеси железных и медных опилок?","options":["Магнитом","Растворением в воде","Добавить соляную кислоту и отфильтровать","Нагреванием"],"correct":2,"explain":"Железо растворяется в соляной кислоте, а медь – нет."},{"q":"Какой цвет приобретает лакмус в растворе NaOH?","options":["синий","красный","фиолетовый","бесцветный"],"correct":0,"explain":"В щелочной среде лакмус синеет."}]}}]}]}]};
